'use strict';
/* Пояснення до офіційних питань ГСЦ: [простими словами, як запам’ятати]. Написані для тренажера (в офіційній базі
   пояснень немає), узгоджені з офіційним ключем; чисел, яких немає в питанні чи варіантах, не містять. */
window.EXPLAIN={
"o1-1":["Межі трамвайної колії по ширині задає або окреме вимощення трамвайної лінії, або дорожня розмітка. Тому правильні обидва варіанти.","Колію «обводять» двома способами: вимощенням або фарбою розмітки."],
"o1-2":["Частина дороги для трамваїв, межі якої задає окреме вимощення або розмітка, називається трамвайною колією. Смуга руху — для звичайних машин.","Рейки плюс свої межі — це трамвайна колія."],
"o1-3":["Машини без рейок їздять проїзною частиною, а в дозволених випадках — і трамвайною колією. Тротуар призначений для пішоходів.","Тротуар — для ніг, дорога й колія — для коліс."],
"o1-4":["Велосмуга — це смуга на самій дорозі, виділена для велосипедистів. Тому вона є частиною проїзної частини.","Велосмуга — це шматок дороги, просто відданий велосипедам."],
"o1-5":["Проїзна частина призначена для машин без рейок: авто, автобусів, мотоциклів. Для трамваїв є окремий елемент — трамвайна колія.","Немає рейок — їдеш проїзною частиною; є рейки — це трамвайна колія."],
"o1-6":["«Дати дорогу» означає: не рушати, не продовжувати рух і не маневрувати, якщо через це тому, хто має перевагу, доведеться гальмувати чи змінювати напрямок. Обидва формулювання правильні.","Дати дорогу — щоб тому, хто має перевагу, не довелося ні гальмувати, ні кермувати."],
"o1-7":["Поздовжня смуга на дорозі завширшки щонайменше 2,75 м для звичайних машин — це смуга руху, навіть без розмітки. На малюнку кожне авто їде своєю смугою.","Один ряд машин — одна смуга руху, від 2,75 м завширшки."],
"o1-8":["Учасники дорожнього руху — ті, хто рухається дорогою: пішоходи, водії, пасажири, погоничі тварин, велосипедисти й люди в кріслах колісних. Регулювальник на дорозі працює, тому до них не належить.","Регулювальник керує рухом, а не бере в ньому участь."],
"o1-9":["Пішохід перебуває на дорозі поза транспортом і нічого там не робить, лише пересувається. Пасажир їде в машині, а регулювальник на дорозі працює.","Не в машині й не на роботі — значить, пішохід."],
"o1-10":["Пасажир їде в транспорті, але не кермує ним. Пішохід і людина в кріслі колісному рухаються поза машиною.","Сидиш в авто, але не за кермом — ти пасажир."],
"o1-11":["Колона пішоходів — це організована група людей, які йдуть в одному напрямку саме проїзною частиною, а не тротуаром чи узбіччям.","Колона йде строєм по дорозі, як на параді."],
"o1-12":["Регульований перехід — той, де рух дозволяють і зупиняють світлофор або регулювальник. Знаки й розмітка лише показують, де перехід.","Регульований — значить, хтось регулює: світлофор або людина з жезлом."],
"o1-13":["Якщо немає регулювальника, а світлофора нема, він вимкнений або блимає жовтим, перехід вважається нерегульованим: ніхто не подає сигналів «стій» чи «йди».","Жовтий блимає — ніхто не регулює."],
"o1-14":["Синій круглий знак із дорослим і дитиною позначає пішохідну доріжку — доріжку з покриттям лише для тих, хто йде пішки.","Дорослий веде дитину за руку — тут ходять пішки."],
"o1-15":["Пішохідна доріжка — тільки для тих, хто йде пішки. Їхати нею на велосипеді не можна.","Пішохідна — для ніг, а не для педалей."],
"o1-16":["Людина в кріслі колісному без двигуна прирівнюється до пішохода, тому пішохідна доріжка призначена і для неї.","Крісло без мотора — як пішохід: на пішохідну доріжку можна."],
"o1-17":["Хто веде мопед поруч, а не їде на ньому, вважається пішоходом. Тому йому можна рухатися пішохідною доріжкою.","Мопед у руках, а не під тобою — ти пішохід."],
"o1-18":["Перехрестя — місце, де дороги перетинаються або примикають одна до одної. На другому малюнку саме таке місце, а на першому — в’їзд на прилеглу територію з будинками й стоянкою.","Дорога зустрічає дорогу — перехрестя; заїзд до дворів — ні."],
"o1-19":["На другому малюнку з’їзд веде до будинків і стоянки — це в’їзд на прилеглу територію, а не перехрестя. На першому зображено перехрестя з острівцем посередині.","Прилегла територія — туди заїжджають до дворів і стоянок, а не проїжджають наскрізь."],
"o1-20":["Автомагістраль ні з чим не перетинається на одному рівні: дороги, колії й доріжки проходять над нею або під нею. Тому там можна їхати швидко без зупинок.","На автомагістралі жодних «хрестиків» на землі: усе зверху або знизу."],
"o1-21":["Виїзд із двору чи іншої прилеглої території на дорогу перехрестям не вважається. Хто звідти виїжджає, той пропускає всіх на дорозі.","Із двору — не перехрестя, а «черга з подвір’я»: спершу пропусти всіх."],
"o1-22":["На малюнку дорога ховається за поворотом і деревами — погода ясна, але далі ти просто не бачиш. Це обмежена оглядовість: заважає рельєф чи перешкоди, а не туман чи темрява.","Оглядовість обмежує поворот і кущі, видимість — туман і темрява."],
"o1-23":["Жовте авто обганяє синє, не виїжджаючи на зустрічну частину дороги: обидва їдуть у свій бік по сусідніх смугах. Це випередження, а не обгін.","Швидше за сусіда без виїзду на зустрічку — це випередження."],
"o1-24":["Автомобільна дорога призначена і для машин, і для пішоходів: на ній є проїзна частина, тротуари або узбіччя. Тварин у цьому визначенні немає.","Автодорога — для коліс і для ніг."],
"o1-25":["Недостатня видимість — коли через туман, дощ, снігопад чи сутінки ти бачиш дорогу попереду менше ніж на 300 м. Як на малюнку: туман ховає все вдалині.","Видимість псує погода й сутінки, оглядовість — повороти й перешкоди."],
"o1-26":["Окрема доріжка поза дорогою, із синім знаком велосипеда й намальованими велосипедами на покритті, — це велосипедна доріжка.","Окремо від дороги й зі знаком велосипеда — велодоріжка."],
"o1-27":["На малюнку доріжка йде окремо від дороги, між газонами, і позначена синім знаком із велосипедом та розміткою. Це велосипедна доріжка.","Велосипед на синьому колі й доріжка серед газону — велодоріжка."],
"o1-28":["Синій круглий знак із велосипедом і велосипеди на покритті показують: ця доріжка призначена для руху на велосипедах.","Намальовано велосипед — значить, їдуть велосипеди."],
"o1-29":["Якщо місце для велосипедистів виділене розміткою прямо на проїзній частині дороги, це велосипедна смуга, як на малюнку. Окрема доріжка поза дорогою — це вже велодоріжка.","Смуга — на самій дорозі, доріжка — окремо від неї."],
"o1-30":["Велодоріжкою, крім велосипедистів, можуть рухатися люди в кріслах колісних, пішоходи й ті, хто везе візок, коли немає тротуару чи пішохідної доріжки. Тобто всі перелічені.","Велодоріжка гостинна: і для педалей, і для повільних коліс, і для ніг."],
"o1-31":["Небезпека для руху — будь-яка раптова зміна, через яку треба негайно гальмувати: щось вискочило на смугу або з машиною сталася несправність. Обидва випадки підходять.","Небезпека — і ззовні, і зсередини машини: в обох випадках гальмуєш."],
"o1-32":["Тротуар — частина дороги для пішоходів, яка йде поруч із проїзною частиною або відділена від неї газоном. Узбіччя й розділювальна смуга — інше.","Тротуар — пішохідна доріжка вздовж дороги, впритул або за газоном."],
"o1-33":["Так, тротуар входить до складу автомобільної дороги, як і проїзна частина та узбіччя.","Дорога — це не лише асфальт для машин, а й тротуар."],
"o1-34":["Тротуар є частиною дороги, але не проїзної частини: проїзна частина — для машин, а тротуар — для пішоходів.","Тротуар — у дорозі, але не в проїзній частині."],
"o1-35":["Велосипедистам на тротуарі їздити не можна. Виняток — діти до 7 років на дитячих велосипедах під наглядом дорослих.","На тротуар із велосипедом — лише малюки до 7 років під наглядом дорослих."],
"o1-36":["Видимість у напрямку руху — найбільша відстань, на якій з-за керма ти чітко бачиш межі дороги та інших учасників руху й можеш орієнтуватися.","Видимість — наскільки далеко ти чітко бачиш дорогу й людей на ній."],
"o1-37":["Автомобільна дорога — це не тільки асфальт. Ґрунтова дорога на першому малюнку й асфальтова на другому — обидві автомобільні дороги.","Ґрунт чи асфальт — дорога є дорога."],
"o1-38":["Проїзна частина призначена для машин без рейок. Трамваї їздять трамвайною колією.","Без рейок — на проїзну частину, з рейками — на колію."],
"o1-39":["Так, може: наприклад, на широкому проспекті дві проїзні частини розділені газоном чи бордюром.","Розділювальна смуга посередині — і ось уже дві проїзні частини."],
"o1-40":["Колію, яку просто накатали машини через поле чи ліс, дорогою не вважають: її ніхто не будував і не облаштовував для руху.","Накатали самі — це ще не дорога."],
"o1-41":["Обмежена оглядовість — коли дорогу попереду закривають повороти, підйоми, будівлі, дерева чи інші машини. Погода тут ні до чого: туман і дощ стосуються видимості.","Оглядовість заважають предмети й рельєф, видимість — погода."],
"o1-42":["Перевага — це твоє право проїхати першим щодо інших учасників руху. Решта варіантів описують «дати дорогу» і крайнє положення машини.","Перевага — право першим: ти їдеш, інші чекають."],
"o1-43":["Рейковий транспорт — це трамвай, а також платформа зі спеціальним обладнанням, що рухається трамвайними коліями.","Їде трамвайними рейками — значить, рейковий: і трамвай, і платформа."],
"o1-44":["Дозволена максимальна маса — це вага машини разом із вантажем, водієм і пасажирами, яку виробник у технічних даних вказав як найбільшу допустиму.","Максимум разом з усім і всіма — як написано в техпаспорті."],
"o1-45":["Вимушена зупинка — коли зупиняєшся не з власної волі, а через обставини: пробите колесо, засліплення фарами чи потребу допомогти пасажиру. Усі три випадки підходять.","Не хочеш, а мусиш стати — це вимушена зупинка."],
"o1-46":["Маршрутні транспортні засоби — автобуси, мікроавтобуси, тролейбуси, трамваї й таксі, які їздять встановленим маршрутом і мають визначені зупинки для посадки й висадки.","Є маршрут і є зупинки — значить, маршрутний."],
"o1-47":["Оглядовість — це реальна можливість бачити, що відбувається на дорозі навколо, з місця водія.","Оглядовість — що ти можеш оглянути зі свого крісла."],
"o1-48":["Обмежену оглядовість створюють форма дороги (повороти, підйоми), а також споруди, дерева, інші предмети й машини. Дощ, сніг і туман погіршують уже видимість.","Заважають поворот, будинок, дерево чи вантажівка — оглядовість обмежена."],
"o1-49":["Випереджати можна з будь-якого боку, якщо їдеш сусідньою смугою й тримаєш безпечний інтервал до машини поруч.","Випередження — і зліва, і справа, головне — сусідня смуга й безпечний проміжок."],
"o1-50":["Прилегла територія — ділянка біля дороги, куди заїжджають до дворів, на стоянки, АЗС, будмайданчики та звідти виїжджають. Проїжджати нею наскрізь не передбачено.","Прилегла територія — не для проїзду наскрізь: тільки в’їзд і виїзд."],
"o1-51":["Розділювальна смуга розділяє сусідні проїзні частини, як на малюнку. Якщо на ній є тротуар, по ній можуть ходити пішоходи. Стоянка й велорух там не передбачені.","Розділювальна смуга розділяє, а не паркує."],
"o1-52":["Зелена смуга посередині, що відділяє одну проїзну частину від іншої, — це розділювальна смуга.","Стоїть між двома дорогами й розділяє їх — розділювальна смуга."],
"o1-53":["Розділювальна смуга — не для руху й не для стоянки машин. Вона лише відділяє зустрічні потоки, навіть якщо позначена тільки розміткою, як на малюнку.","Розділювальна смуга — нічия земля: там не їздять і не стоять."],
"o1-54":["Засліплення — це коли світло б’є в очі так, що ти справді не можеш помітити перешкоду чи межі дороги навіть зблизька.","Засліплений — значить, на мить нічого не бачиш."],
"o1-55":["Так, водій має бути особливо уважним до велосипедистів: вони менш помітні, можуть раптово змінити напрямок і нічим не захищені.","Велосипедист без кузова — дивися на нього уважніше."],
"o1-56":["Хто котить мотоцикл поруч, а не їде на ньому, прирівнюється до пішохода — як хлопець на малюнку.","Мотоцикл котиш руками — ти пішохід."],
"o1-57":["Так, людина, яка веде мотоцикл поруч, а не їде на ньому, вважається пішоходом.","Ноги йдуть, мотор мовчить — пішохід."],
"o1-58":["Так, людина з дитячим візком прирівнюється до пішохода: вона йде пішки й просто штовхає візок.","Візок у руках — ти все одно пішохід."],
"o1-59":["Так, люди в кріслах колісних — повноправні учасники дорожнього руху.","Рухаєшся дорогою — ти учасник руху, на ногах чи на колесах крісла."],
"o1-60":["Так, мости, естакади та шляхопроводи для руху машин теж є елементами автомобільної дороги.","Міст — це та сама дорога, тільки над річкою чи іншою дорогою."],
"o1-61":["Естакада піднімає одну дорогу над іншою там, де вони перетинаються, і з’їзду з неї на нижню дорогу немає. Шляхопровід, навпаки, такий з’їзд дає.","Естакада — «проліт без виходу»: над дорогою, але з’їхати на неї не можна."],
"o1-62":["Причіп сам не їздить: у нього немає двигуна, і рухатися він може тільки причеплений до іншої машини.","Причіп — бо його причіплюють: сам нікуди не поїде."],
"o1-63":["Узбіччям пішоходам можна йти тоді, коли поруч немає тротуару чи пішохідної доріжки.","Немає тротуару — тоді узбіччя."],
"o1-64":["Узбіччя не призначене для руху машин. Виїжджати на нього можна лише у випадках, які прямо дозволяють Правила.","Узбіччя — не запасна смуга: лише коли Правила дозволяють."],
"o1-65":["Так, на малюнку суцільна біла лінія справа відділяє проїзну частину від узбіччя — вона позначає край дороги для машин.","Суцільна лінія з краю — тут закінчується проїзна частина."],
"o1-66":["Ні, на малюнку стрілка показує на тротуар: він піднятий над дорогою бордюром, і по ньому йдуть пішоходи. Узбіччя виглядає інакше.","Бордюр, плитка й пішоходи в місті — це тротуар, а не узбіччя."],
"o1-67":["Острівець безпеки — піднятий над дорогою майданчик посеред пішохідного переходу, де пішохід може зупинитися й перечекати машини.","Острівець — як острів посеред річки машин: стоїш і чекаєш у безпеці."],
"o1-68":["Ні, острівець безпеки потрібен пішоходам, щоб перечекати під час переходу дороги. Для посадки й висадки пасажирів є інші місця.","Острівець безпеки — для переходу, а не для зупинки автобуса."],
"o1-69":["Якщо машина зупиняється через несправність, небезпечний вантаж, погане самопочуття когось чи раптову перешкоду, це вимушена зупинка.","Зупинка не з власної волі — вимушена."],
"o1-70":["Місце, де дорога на одному рівні перетинає залізничні колії, називається залізничним переїздом.","Дорога й поїзд на одному рівні — це переїзд."],
"o1-71":["Уся смуга території з тротуарами, спорудами, знаками й світлофорами, де їздять машини й ходять пішоходи, — це автомобільна дорога або вулиця. Проїзна частина — лише її частина для машин.","Від тротуару до тротуару з усім, що є, — це вулиця, або дорога."],
"o1-72":["Пішохідний перехід призначений для того, щоб пішоходи переходили дорогу. Їхати ним на велосипеді не передбачено.","Перехід — щоб переходити ногами, а не переїжджати колесами."],
"o1-73":["Білі вогні спереду, які роблять машину помітнішою вдень, називаються денними ходовими вогнями.","Денні ходові — світять удень, щоб тебе бачили."],
"o1-74":["Людина на велосипеді — це велосипедист, а не пішохід. А той, хто везе візок чи їде в кріслі колісному без двигуна, прирівнюється до пішохода.","Крутиш педалі — ти велосипедист, а не пішохід."],
"o1-75":["Колона — це організована група з трьох і більше машин, які їдуть одна за одною в одному напрямку з увімкненим ближнім світлом.","Колона: від трьох машин і всі з ближнім світлом."],
"o1-76":["Дорожня обстановка — це все, що водій враховує в конкретний момент: стан дороги, перешкоди, кількість машин, знаки, розмітка, світлофори. Від неї залежать швидкість і смуга.","Обстановка — повна «картинка» навколо: дорога, машини, знаки."],
"o1-77":["Оглядовість — це реальна можливість бачити, що відбувається на дорозі, із місця водія.","Оглядовість — що ти фізично можеш побачити з крісла водія."],
"o1-78":["Трактори, самохідні шасі, дорожньо-будівельні й меліоративні машини Правила відносять до сільськогосподарської техніки.","Трактор і вся «важка робоча» техніка — у сільськогосподарській родині."],
"o1-79":["Безпечна швидкість — та, за якої ти впевнено керуєш машиною в конкретних умовах. На мокрій дорозі вона одна, на сухій — інша.","Безпечна швидкість — не цифра, а контроль над машиною тут і зараз."],
"o2-1":["Якщо допомогу на місці надати не можна, швидку не викликати й передати потерпілого нікому, вези його до лікарні своєю машиною. Спершу зафіксуй сліди ДТП, у лікарні назви себе й номер авто та повертайся на місце.","Сліди зафіксуй — у лікарню відвези — назад повернись."],
"o2-2":["Коли в ДТП є постраждалі, найперше — люди: надай домедичну допомогу, виклич швидку, а якщо не виходить — попроси допомоги в присутніх і відправ потерпілих до лікарні. Поліція й сліди — потім.","Спочатку люди, потім усе інше."],
"o2-3":["Учасник ДТП робить усе разом: зупиняється й лишається на місці, вмикає аварійку й ставить знак, допомагає потерпілим і викликає швидку, повідомляє поліцію. Як на малюнку.","Стоп — аварійка — знак — допомога — швидка — поліція."],
"o2-4":["Після аварійки й знака не переставляй машину й предмети, пов’язані з ДТП, допоможи постраждалим і виклич швидку, а якщо не можеш — попроси присутніх відправити їх до лікарні. Страхову Правила тут не згадують.","Нічого не чіпай, а людям допоможи."],
"o2-5":["Табличка під знаком знімає заборону для авто й мотоколясок зі знаком «Водій з інвалідністю». А таксі в зоні цього знака й так можуть зупинитися для посадки чи висадки пасажирів.","Під цим знаком можна двом: знаку «Водій з інвалідністю» і таксі з пасажирами."],
"o2-6":["Вимагати пройти огляд на алкоголь, наркотики чи інші речовини може лише поліцейський. Ні лікар швидкої, ні страховий агент такого права не мають.","Алкотестер подає поліцейський — і тільки він."],
"o2-7":["Керувати легковою машиною категорії В можна з 18 років.","Повноліття — 18 — і права на В."],
"o2-8":["Засоби пасивної безпеки — це підголівники й ремені безпеки, вони рятують у разі зіткнення. Підлокітник — просто для зручності.","Ремінь тримає тіло, підголівник — шию, підлокітник — лише лікоть."],
"o2-9":["Поліцейському показують посвідчення водія, реєстраційний документ на авто (можна електронні) і поліс страхування. Медична довідка в цьому переліку не потрібна.","Права, техпаспорт, страховка — трійка, яку завжди маєш при собі."],
"o2-10":["Якщо почуваєшся зле і це загрожує безпеці на дорозі, за кермо сідати не можна — жодні ліки цього не скасовують.","Погано почуваєшся — не кермуєш."],
"o2-11":["Водій має всі ці права: їздити й возити людей та вантажі, де рух дозволено, знати причину зупинки та ім’я й посаду того, хто зупинив, і оскаржити незаконні дії поліцейського.","Права водія: їхати, знати, оскаржити."],
"o2-12":["Кожен учасник руху має знати й точно виконувати Правила, а ще бути ввічливим до інших. Вимагати виконання Правил від інших — не його обов’язок.","Знай, виконуй і будь ввічливим."],
"o2-13":["Якщо тебе зупинили, ти маєш право знати причину зупинки, прізвище й посаду посадовця та вимагати показати посвідчення. Правильні обидва варіанти.","Зупинили — запитай: чому, хто ви і покажіть посвідчення."],
"o2-14":["Так, якщо поліцейський порушив закон, водій має право оскаржити його дії.","Поліцейський теж під законом — його дії можна оскаржити."],
"o2-15":["Передати кермо можна тільки людині, яка має при собі посвідчення водія потрібної категорії. Родинні зв’язки тут нічого не вирішують.","Кермо — лише тому, в кого права в кишені."],
"o2-16":["Перевіряти, чи машина справна, треба перед кожним виїздом, а не лише після довгої стоянки чи коли «розбираєшся» в техніці.","Кожен виїзд починається з перевірки."],
"o2-17":["Усі перелічені пункти — обов’язки водія: бути уважним, не смітити на дорозі, не створювати загроз і повідомляти дорожникам про перешкоди.","Уважний, охайний, безпечний і небайдужий — це все про водія."],
"o2-18":["Перед виїздом перевір і забезпеч, щоб машина була справна й укомплектована, а вантаж правильно розміщений і закріплений.","Перед дорогою — справність, комплект і надійно закріплений вантаж."],
"o2-19":["Легковий автомобіль — це категорія В. Тому передати кермо можна тільки людині, яка має при собі посвідчення водія саме категорії «В».","Легковик — категорія «В»: інша категорія не підходить."],
"o2-20":["У водія є всі три права: знати причину зупинки й хто зупинив, бачити посвідчення того, хто зупинив, і відступити від вимог закону, коли інакше не врятувати життя чи здоров’я.","Знати, перевірити посвідчення і рятувати життя — усі три права твої."],
"o2-21":["Затримувати тих, хто забруднює дорогу, — не справа водія. А не смітити самому й пристібатися, якщо є ремені, — його прямі обов’язки.","Водій не поліцейський: сам не смітить, але нікого не затримує."],
"o2-22":["Категорія В охоплює все перелічене: авто з дозволеною максимальною масою до 3500 кг, не більш як вісім пасажирських місць і такі авто з причепом до 750 кг.","В — це «звичайна легкова» з усіма своїми межами: маса, місця й легкий причіп."],
"o2-23":["Поза населеним пунктом пристібатися мусять усі, без винятків. Пільги для деяких водіїв і пасажирів діють лише в населених пунктах.","За містом швидкість вища — пристібаються всі."],
"o2-24":["Поліцейський може оглянути твою машину тільки тоді, коли для цього є законні підстави, а не за будь-яких обставин.","Огляд авто — лише за законом, а не за бажанням."],
"o2-25":["Не зобов’язані надавати свою машину водії авто дипломатичних представництв і міжнародних організацій, а також оперативних і спеціальних машин. Таксисти такої пільги не мають.","Дипломати й спецслужби машину не віддають, таксі — віддає."],
"o2-26":["Машину треба надати поліцейським і медикам, щоб довезти до лікарні людину, якій потрібна швидка допомога, а також поліцейським для перевезення пошкоджених авто — для цього залучають лише вантажівки.","Хворого — до лікарні, розбите авто — на вантажівці."],
"o2-27":["Машину надають поліцейським і медикам, щоб довезти людину до лікарні, а також поліцейським, коли вони переслідують правопорушників чи доставляють їх до поліції. Тому правильні всі відповіді.","Порятунок людини й погоня за порушником — у цих випадках машину надаєш."],
"o2-28":["Заборонено все перелічене: їздити п’яним чи під наркотиками, хворим, утомленим або під ліками, що гальмують реакцію, і передавати кермо людині в такому стані.","Сам не в формі — не кермуй; інший не в формі — не давай йому кермо."],
"o2-29":["Говорити телефоном за кермом можна лише так, щоб не тримати його в руці: через гарнітуру чи гучний зв’язок. Ні стаж, ні робота таксистом цього не змінюють.","Руки — на кермі, телефон — без рук."],
"o2-30":["Учасник ДТП до медичного огляду не має права пити алкоголь чи вживати наркотики або ліки на їх основі. Дозволені лише засоби зі складу аптечки.","Після ДТП — ні краплі до огляду."],
"o2-31":["При собі водій має мати реєстраційний документ на машину, посвідчення водія потрібної категорії та поліс обов’язкового страхування. Генеральна довіреність не обов’язкова.","Техпаспорт, права, страховка — і можна їхати."],
"o2-32":["Власник машини має всі ці права: на безпечні умови руху й інформацію про дороги, доручити машину іншій людині, отримати компенсацію, коли її взяли поліція чи медики, і за збитки через погану дорогу.","У власника прав багато — правильно «усе перелічене»."],
"o2-33":["Залишати машину можна, коли вона не покотиться сама і в неї не зможуть залізти чи викрасти. Потрібні обидві умови.","Не покотиться й не вкрадуть — тоді йди."],
"o2-34":["У населеному пункті можуть не пристібатися люди з інвалідністю, яким ремінь фізично не підходить, а також водії й пасажири оперативних і спеціальних машин. Таксисти й інструктори — пристібаються.","У місті без ременя — лише за станом здоров’я або на спецмашині."],
"o2-35":["Після ДТП машину й предмети, пов’язані з пригодою, переміщати не можна, навіть якщо вони заважають іншим. Сліди потрібні, щоб з’ясувати, що сталося.","ДТП — як місце події в детективі: нічого не чіпай."],
"o2-36":["На малюнку номер зсунутий убік і стоїть криво. Номерний знак треба кріпити на призначеному для нього місці так, щоб його було добре видно, тому так не можна.","Номер — на своє місце й рівно, а не де зручно."],
"o2-37":["Коли номер забруднений і його не прочитати, як на малюнку, їхати не можна — ні в місті, ні за ним.","Номер у болоті — машина не їде."],
"o3-1":["Навіть на головній дорозі ти пропускаєш машину з увімкненим синім маячком, як ця швидка справа. Головна дорога тут не допомагає.","Синій маячок сильніший за головну дорогу."],
"o3-2":["Машина з увімкненим синім маячком має перевагу, тож навіть на спуску у вузькому місці вона не зобов’язана пропускати тих, хто їде на підйом.","Синій маячок — перевага скрізь, навіть на вузькому спуску."],
"o3-3":["Біля машини з увімкненим синім маячком, що стоїть, як поліцейська на малюнку, скинь швидкість до 40 км/год і будь готовий зупинитися, якщо регулювальник дасть сигнал.","Бачиш маячок на місці — до 40 км/год і очі на регулювальника."],
"o3-4":["Ставати в колону, яку супроводжує машина з маячком, не можна — синьому авто доведеться їхати окремо.","Колона з супроводом — закритий клуб: чужим вхід заборонено."],
"o3-5":["Машина із зеленим маячком замикає колону з супроводом. Обганяти чи випереджати її не можна за жодної швидкості — синьому авто доведеться їхати позаду, доки колона не проїде.","Зелений маячок — хвіст колони: за ним чекаєш, а не обганяєш."],
"o3-6":["Коли ззаду наближається машина із синім маячком або сиреною, дай їй дорогу й зроби так, щоб вона проїхала без перешкод. Зупинятися не обов’язково — головне не заважати.","Синій маячок ззаду — звільни йому шлях."],
"o3-7":["На малюнку в поліцейського авто увімкнені червоний і синій маячки. У такому разі інші водії мусять зупинитися біля правого краю дороги або на узбіччі.","Червоний із синім — стань праворуч і стій."],
"o3-8":["Заборона обгону діє для машин із червоним (або червоним і синім) чи зеленим маячком і колон, які вони супроводжують. Одиночну машину лише із синім маячком обганяти дозволено.","Тільки синій і без колони — обгін можливий."],
"o3-9":["Якщо попереду колони машина з червоним і синім маячками, замикає колону машина із зеленим маячком або із синім і зеленим разом. Обидва варіанти правильні.","Хвіст колони завжди зелений: сам або в парі із синім."],
"o3-10":["Так, машинам з увімкненими синіми або червоними маячками та сиреною треба дати проїхати першими.","Маячок і сирена — пропусти першими."],
"o3-11":["Ні, навіть із синім чи червоним маячком водій не може їхати, коли регулювальник забороняє рух. Сигнали регулювальника обов’язкові для всіх.","Регулювальник головніший за маячок."],
"o3-12":["Із увімкненим маячком оперативна машина може відступати лише від правил маневрування й обгону — і тільки якщо це безпечно. Сигнали регулювальника й правила проїзду залізничних переїздів обов’язкові й для неї.","Маячок дає свободу маневру й обгону, але регулювальник і залізничний переїзд — закон для всіх."],
"o3-13":["Перевагу оперативна машина має тоді, коли в неї увімкнений синій або червоний маячок і водій забезпечує безпеку руху. Оранжевий маячок переваги не дає.","Синій чи червоний — перевага; оранжевий — лише увага."],
"o3-14":["Сирену з маячком можна вимкнути, якщо додатково привертати увагу інших учасників руху немає потреби. Маячок при цьому працює.","Маячок світить завжди, сирена — коли треба докричатися."],
"o3-15":["Сама по собі швидка переваги не має. Пропускати її треба тоді, коли в неї увімкнені маячки та/або сирена.","Швидка без маячка — звичайна машина, з маячком — пропускай."],
"o3-16":["Ні, оранжевий маячок на дорожній техніці, як на снігоочиснику з малюнка, переваги не дає — він лише попереджає про небезпеку й просить бути уважнішим.","Оранжевий маячок — «обережно», а не «пропусти»."],
"o4-1":["Якщо на зупинці немає посадкового майданчика, на дорогу до трамвая виходять тільки з боку його дверей і лише тоді, коли трамвай уже зупинився.","Спершу трамвай стоїть, потім ти йдеш — і тільки до дверей."],
"o4-2":["Якщо поруч є підземний або надземний перехід, як на знаках, переходити дорогу можна тільки ним — не поверху, навіть на перехресті.","Є підземний чи надземний — іди тільки ним."],
"o4-3":["По тротуарах і пішохідних доріжках пішоходи тримаються правого боку, так само як машини на дорозі. Так зустрічні потоки не заважають одне одному.","Пішки, як і за кермом, — тримайся правого боку."],
"o4-4":["Краєм проїзної частини пішохід може йти, коли немає тротуару, пішохідної доріжки, а також узбіччя або ним неможливо пройти.","Ні тротуару, ні узбіччя — тоді край дороги."],
"o4-5":["Так, пішохід має право вимагати від влади й власників доріг, вулиць і переїздів, щоб ті створювали безпечні умови для руху.","Безпечна дорога — право й пішохода теж."],
"o4-6":["На регульованому переході пішохід має перевагу лише тоді, коли світлофор чи регулювальник дозволяє йому йти.","Зелений чоловічок — твоя перевага; червоний — ні."],
"o4-7":["Пішохід може зупинитися на дорозі, якщо цього вимагає безпека, або коли перейти за свій сигнал не вдалося — тоді чекає на острівці безпеки, лінії між зустрічними потоками чи посередині дороги.","Зупинка на дорозі — лише заради безпеки або «на півдорозі», посередині."],
"o4-8":["Якщо є розділювальна смуга, огородження чи дорога має чотири і більше смуг в обох напрямках, переходити можна лише пішохідними переходами, зокрема підземними й надземними.","Широка дорога чи паркан посередині — тільки по переходу."],
"o4-9":["Навіть на переході пішохід не має права виходити на дорогу, не переконавшись, що це безпечно, і не може раптово вибігати. Заборонено і те, і те.","Перехід — не стартова лінія: спершу подивись, потім спокійно йди."],
"o4-10":["Чекати автобус чи трамвай треба на тротуарі або посадковому майданчику, а якщо їх немає — на узбіччі. Заїзна кишеня — для самого автобуса.","Чекаєш автобус там, де ходять люди, а не там, де він зупиняється."],
"o4-11":["Якщо, поки ти переходиш, загорівся сигнал, що забороняє рух, зупинись на розділювальній смузі й зачекай там. Далі йди лише на дозвільний сигнал світлофора.","Червоний на півдорозі — перечекай посередині."],
"o4-12":["Якщо перейти першу половину дороги не вдається, зупинись на острівці безпеки, лінії між зустрічними потоками чи посередині. Далі йди лише на дозвільний сигнал і переконавшись, що безпечно.","Не вдалося перейти — стань посередині й дочекайся свого сигналу."],
"o4-13":["Поза переходом і перехрестям дорогу можна переходити, коли їх не видно поблизу, а смуг в обох напрямках не більш як три. І лише переконавшись, що це безпечно.","Переходу не видно й смуг не більш як три — тоді можна, обережно."],
"o4-14":["На позначеному нерегульованому переході пішохід має перевагу завжди, водії мусять його пропустити.","Зебра без світлофора — пішохід головний."],
"o4-15":["Якщо немає тротуарів і пішохідних доріжок, організовану групу дітей водять тільки узбіччям, колоною в напрямку руху машин, лише вдень і в супроводі дорослих.","Діти — тільки узбіччям, удень, за потоком і з дорослими."],
"o4-16":["Водити організовані групи дітей проїзною частиною заборонено. Для них — тротуари, пішохідні доріжки або узбіччя.","Діти й проїзна частина — несумісні."],
"o4-17":["Група людей може йти проїзною частиною за рухом машин, не більш як по чотири в ряд і не ширше половини свого боку дороги. Попереду й позаду, за 10-15 м зліва, ідуть супровідники з червоними прапорцями, а в темряві — з ліхтарями.","Четвірками, за потоком, з прапорцями спереду й ззаду."],
"o4-18":["Організована група людей іде проїзною частиною тільки в напрямку руху машин, колоною не більш як по чотири в ряд.","Колона людей — за потоком машин, четвірками."],
"o4-19":["У темряві чи при поганій видимості пішохід на дорозі чи узбіччі має бути зі світлоповертальними елементами — стрічкою, наліпкою, жилетом, — щоб водії вчасно його помітили.","У темряві світись, щоб тебе не збили."],
"o4-20":["За містом людина в кріслі колісному без двигуна або з мотоциклом, мопедом чи велосипедом у руках рухається узбіччям чи краєм дороги в напрямку руху машин.","Котиш колеса поруч — іди за потоком, як вони."],
"o4-21":["Пішохід — учасник ДТП має допомогти потерпілим, записати очевидців і повідомити поліцію, назвати себе й дочекатися поліцейських. Правильні всі ці дії разом.","Допоможи, запиши свідків, виклич поліцію й чекай."],
"o4-22":["Так, на нерегульованому перехресті без розмітки переходу пішоходи можуть переходити дорогу — по лініях тротуарів або узбіч.","Перехрестя — сам собі перехід уздовж лінії тротуару."],
"o4-23":["На малюнку широка дорога з огородженням посередині. На такій ділянці переходити проїзну частину пішоходам заборонено — тільки пішохідним переходом.","Паркан посередині — не переходь."],
"o4-24":["На малюнку жінка йде краєм дороги в той самий бік, що й машини, тобто спиною до них. Краєм проїзної частини треба йти назустріч руху, щоб бачити машини.","Ідеш дорогою — дивись машинам в обличчя."],
"o4-25":["Так, пішохідка йде краєм дороги назустріч машинам: вона бачить авто, а водій бачить її.","Назустріч потоку — бачиш небезпеку заздалегідь."],
"o4-26":["Так, у випадках, які визначають Правила, — наприклад, коли немає тротуару чи пішохідної доріжки, — пішоходи можуть іти велосипедною доріжкою.","Немає тротуару — велодоріжка допоможе й пішоходу."],
"o5-1":["Сідати чи виходити з боку сусідньої смуги, де їдуть машини, пасажирам заборонено. Роби це з боку тротуару або узбіччя.","Двері — до тротуару, а не до потоку."],
"o5-2":["Пасажир автобуса має всі три права: на точну інформацію про рух, на безпечне перевезення себе й багажу та на відшкодування шкоди.","Знати, доїхати безпечно й отримати компенсацію — усе твоє."],
"o5-3":["Пасажир, причетний до ДТП, має і допомогти потерпілим, і повідомити поліцію та дочекатися її на місці. Правильні обидва варіанти.","Пасажир у ДТП — як водій: допоможи, виклич поліцію, чекай."],
"o5-4":["Їхати на підніжках чи виступах машини пасажирам заборонено — навіть якщо водій не проти або треба наглядати за вантажем.","Підніжка — щоб сісти, а не щоб їхати."],
"o5-5":["Відчиняти двері з боку тротуару, майданчика чи узбіччя можна, коли машина вже зупинилася біля них. Спершу переконайся, що авто стоїть.","Двері — лише коли машина стоїть біля бордюру."],
"o5-6":["Пасажирам заборонено відволікати водія та заважати йому кермувати під час руху — навіть щоб уточнити дорогу.","Водій кермує — пасажир не заважає."],
"o5-7":["Пасажир мотоцикла чи мопеда має бути в застебнутому мотошоломі завжди, а не лише на автомагістралі.","Сідаєш на мотоцикл — застебни шолом."],
"o5-8":["Якщо в машині є ремені безпеки, пасажири мають пристібатися обов’язково — і в місті, і за містом.","Є ремінь — пристебнись."],
"o5-9":["Їхати стоячи можна, лише якщо це передбачено конструкцією транспорту, як в автобусі з поручнями. Відсутність вільних місць — не підстава.","Стоячи — тільки там, де це задумав виробник."],
"o5-10":["Пасажир має сидіти на призначеному місці або стояти там, де це передбачено, тримаючись за поручень. «Будь-яке зручне місце» не підходить.","Сидиш на сидінні або стоїш і тримаєшся — іншого не дано."],
"o5-11":["Сідаючи чи виходячи з крайньої смуги дороги, пасажир має переконатися, що це безпечно й нікому не заважає.","Виходиш на дорогу — спершу подивись, чи безпечно."],
"o5-12":["Якщо немає майданчика, тротуару й узбіччя, сідати й виходити можна з крайньої смуги, але не з боку сусідньої смуги руху, і лише коли це безпечно.","З крайньої смуги — тільки з боку краю дороги, не з боку потоку."],
"o5-13":["Сідати й виходити з узбіччя чи тротуару можна тоді, коли немає посадкового майданчика.","Немає майданчика — тротуар або узбіччя."],
"o5-14":["Сідати й виходити можна з посадкового майданчика, а якщо його немає — з узбіччя чи тротуару, а коли й це неможливо — з крайньої смуги. Правильні обидва варіанти.","Майданчик — тротуар чи узбіччя — крайня смуга: за порядком."],
"o5-15":["Пристібатися мають пасажири на всіх сидіннях, де є ремені безпеки, а не тільки спереду.","Ремінь є на сидінні — він для тебе, хоч спереду, хоч ззаду."],
"o5-16":["Ні: на малюнку жінка з дітьми сідає з боку проїзної частини, де їздять машини. Сідати з крайньої смуги можна лише не з боку сусідньої смуги руху й лише коли це безпечно.","Дітей — у двері з боку узбіччя, а не з боку потоку."],
"o6-1":["Якщо велодоріжка перетинає дорогу поза перехрестям, як на малюнку, велосипедист перевагу не має: він пропускає машини на дорозі.","Велодоріжка через дорогу — велосипедист чекає."],
"o6-2":["Возити пасажирів на велосипеді не можна — ні на багажнику, ні на рамі. Виняток — діти до 7 років на додатковому сидінні з надійно закріпленими підніжками.","Велосипед — для одного; дитина до 7 років — лише в спецкріслі."],
"o6-3":["Велосипедисту заборонено чіплятися за іншу машину, їхати без рук на кермі й знімати ноги з педалей. Правильні обидва варіанти.","Руки — на кермі, ноги — на педалях, за машини не чіпляйся."],
"o6-4":["Тротуарами й пішохідними доріжками можуть їздити лише діти до 7 років на дитячих велосипедах під наглядом дорослих. Решта велосипедистів туди не заїжджає.","Тротуар — велодоріжка тільки для малюків до 7 років."],
"o6-5":["Якщо поруч є велосипедна доріжка, їхати проїзною частиною велосипедисту заборонено — треба користуватися доріжкою.","Є велодоріжка — їдь нею, а не дорогою."],
"o6-6":["Їхати не можна, якщо в велосипеда несправні гальма чи звуковий сигнал, а також у темряві чи погану видимість без увімкненої фари або без світлоповертачів.","Несправні гальма чи сигнал, а в темряві ще й без світла — не їдь."],
"o6-7":["Велосипедист може везти вантаж, який не заважає йому кермувати й не створює перешкод іншим на дорозі.","Вантаж не заважає ні тобі, ні іншим — можна везти."],
"o6-8":["Між колонами велосипедистів, що їдуть, тримають дистанцію 80 – 100 м, щоб машини могли безпечно їх обганяти.","Між колонами велосипедистів — 80 – 100 м."],
"o6-9":["Групою велосипедисти їдуть дорогою один за одним, а не поряд, щоб не заважати іншим.","Велогрупа — ланцюжком, по одному."],
"o6-10":["Щоб їхати в темряві чи при поганій видимості, на велосипед встановлюють ліхтар, тобто фару.","Темно — світи фарою."],
"o6-11":["Велосипед має бути зі звуковим сигналом, білими світлоповертачами спереду, оранжевими по боках і червоними ззаду, а в темряві — з увімкненою фарою. Потрібне все перелічене.","Дзвоник, світлоповертачі й фара — повний комплект."],
"o6-12":["Їздити дорогами на велосипеді дозволено з 14 років.","14 — і можна на дорогу з велосипедом."],
"o6-13":["Якщо поруч є велодоріжка, на автомагістраль, дорогу для автомобілів чи проїзну частину велосипедисту виїжджати заборонено.","Є велодоріжка — машинні дороги не для тебе."],
"o6-14":["Буксирувати велосипед заборонено — його не можна тягнути за іншим транспортом.","Велосипед на тросі — ніколи."],
"o6-15":["Там, де рух регулюють, велосипедист їде за сигналами регулювальника або світлофора, як і водії машин.","Регульоване місце — слухай регулювальника чи світлофор."],
"o6-16":["Синій квадратний знак із білим трикутником і велосипедистом позначає велосипедний переїзд — місце, де велодоріжка перетинає дорогу.","Велосипедист у трикутнику — переїзд для велосипедів."],
"o6-17":["Червона смуга з білими прямокутниками впоперек дороги, як на малюнку, позначає велосипедний переїзд — тут велодоріжка перетинає проїзну частину.","Червоний «килимок» через дорогу — велопереїзд."],
"o6-18":["Невірне твердження — що велосипедистам можна їздити тротуарами. Насправді це дозволено лише дітям до 7 років на дитячих велосипедах під наглядом дорослих.","Тротуар — для пішоходів і малюків до 7 років, а не для велосипедистів."],
"o6-19":["Ні, синій знак зі стрілкою й велосипедом позначає смугу тільки для велосипедистів. Мопедам туди не можна.","Намальовано велосипед — їде лише велосипед."],
"o6-20":["Ні, велосипедна смуга — тільки для велосипедистів. Мотоциклам там не місце.","Велосмуга — не для мотора."],
"o6-21":["Велосипедна смуга призначена тільки для велосипедистів: ні мотоциклам, ні мопедам їхати нею не можна.","Велосмуга — тільки педалі, жодного мотора."],
"o6-22":["Ні, навіть без зустрічних машин велосипедисти на дорозі мають їхати в один ряд, а не поруч, як на малюнку.","Велосипедисти — тільки гуськом."],
"o7-1":["Виїжджаючи з прилеглої території туди, де погано видно дорогу, водій воза веде коня за вуздечку. Так тварина не вискочить на дорогу несподівано.","Погано видно — веди коня за вуздечку."],
"o7-2":["Гужовий віз чи сани мають бути зі світлоповертачами: білими спереду й червоними ззаду.","Віз як машина: спереду біле, ззаду червоне."],
"o7-3":["Ліхтарі на возі чи санях встановлюють з лівого боку — того, що ближче до машин, які обганяють і їдуть назустріч.","Ліхтар на возі — зліва, ближче до потоку."],
"o7-4":["У темряві й при поганій видимості на возі світять ліхтарі: білий спереду, червоний ззаду, обидва з лівого боку.","Білий спереду, червоний ззаду — і все зліва."],
"o7-5":["Людей на возі можна везти, лише якщо вони не можуть опинитися за межами воза ні з боків, ні ззаду. Потрібні обидві умови.","Пасажири — всередині воза: ні ноги збоку, ні ноги ззаду."],
"o7-6":["Переганяти стадо дорогою в темряві заборонено, хоч скільки буде погоничів і яка б не була дорога.","Темно — стадо вдома."],
"o7-7":["Возам і погоничам тварин заборонено пересуватися дорогами державного значення. Якщо можна, треба їхати місцевими дорогами.","Віз — на місцеву дорогу, траса державного значення — для машин."],
"o7-8":["Погоничам заборонено все перелічене: вести тварин по добрій дорозі, коли поруч є інші, переганяти їх у темряві, переводити через колії й дороги поза спецмісцями та лишати без нагляду біля дороги.","Тварини й дорога — лише вдень, у визначених місцях і під наглядом."],
"o8_1-1":["Основний світлофор червоний, світиться лише зелена стрілка ліворуч. Тож їхати може тільки синє авто — ліворуч або на розворот. Жовте й червоне чекають.","Стрілка ліворуч — їде лише той, хто ліворуч чи на розворот."],
"o8_1-2":["Регулювальник стоїть до тебе боком, руки опущені — тобі можна прямо й праворуч. Але, повертаючи праворуч, пропусти пішоходів, які переходять дорогу, на яку ти заїжджаєш.","Боком і руки вниз — їдь. Але поворот завжди закінчується поглядом на «зебру»."],
"o8_1-3":["Регулювальник стоїть до тебе грудьми з розведеними руками — це «стоп», навіть якщо світлофор зелений. Жест регулювальника завжди важливіший за світлофор.","Груди чи спина регулювальника — як стіна: крізь неї не їдуть."],
"o8_1-4":["Регулювальник тримає праву руку витягнутою вперед. З того боку, звідки під’їжджають трамвай і зелене авто, цей жест рух дозволяє, тож їхати можуть обидва — кожен у дозволеному для нього напрямку.","Права рука вперед: лівий бік від регулювальника їде, правий бік і спина стоять."],
"o8_1-5":["Регулювальник із розведеними руками стоїть до тебе боком — тобі можна їхати. А трамвай під’їжджає до його грудей чи спини, тож йому зараз рух заборонено.","Руки в сторони: боки їдуть, груди й спина стоять."],
"o8_1-6":["Повертаючи праворуч, синє авто перетинає перехід, де пішоходам горить зелений. Пішоходи йдуть на свій сигнал, тож водій мусить їх пропустити.","Поворот через «зебру» із зеленим чоловічком: спершу пішохід, потім ти."],
"o8_1-7":["Регулювальник стоїть до тебе грудьми з розведеними в сторони руками — рух заборонено в будь-якому напрямку. Зелений світлофор тут нічого не важить: регулювальник головніший.","Бачиш груди регулювальника — вважай, що бачиш червоне світло."],
"o8_1-8":["Регулювальник головніший за світлофор і за зелену стрілку. Його жест у цій ситуації для тебе означає «стоп», тож повертати ліворуч не можна — чекай його дозволу.","Регулювальник перекриває все: і світлофор, і стрілку, і знаки."],
"o8_1-9":["Регулювальник із розведеними руками стоїть до тебе боком — можна прямо або праворуч. Червоний світлофор не важить: виконуй сигнал регулювальника.","Руки в сторони, ти збоку: прямо або праворуч, а ліворуч — ні."],
"o8_1-10":["Регулювальник стоїть до тебе боком із розведеними руками — праворуч повертати можна. Але на дорозі, куди ти повертаєш, ідуть пішоходи, тож їх треба пропустити.","Дозвіл на поворот — не дозвіл їхати крізь пішохода."],
"o8_1-11":["Хоч у додатковій секції й горить зелена стрілка, на перехресті працює регулювальник, а його сигнали головніші. Його жест зараз забороняє тобі рух, тож на стрілку не зважай.","Є регулювальник — світлофор стає просто декорацією."],
"o8_1-12":["Звуковий сигнал біля пішохідного світлофора допомагає людям, які погано бачать: він звучить тоді, коли їм можна переходити дорогу.","Звучить — значить, іди: звук для незрячих — це їхній «зелений»."],
"o8_1-13":["Світлофор із червоним і зеленим силуетом людини призначений тільки для пішоходів. Водії на нього не орієнтуються.","Чоловічок на світлофорі — сигнал для чоловічків на тротуарі."],
"o8_1-14":["На залізничних переїздах ставлять світлофор із двома червоними вогнями, як світлофор 1, або такий самий із білим вогником згори, як світлофор 2. А світлофор 3 у формі літери Т — для трамваїв.","Переїзд — це два червоні «очі», іноді з білим вогником над ними. Літера Т — для трамвая."],
"o8_1-15":["Трамвайний світлофор дозволяє рух, коли нижній вогник горить разом із верхнім: лівий — ліворуч, середній — прямо, правий — праворуч. Правий верхній разом із нижнім світяться лише на другому.","Трамвайна «Т»: горить низ і верх справа — можна праворуч."],
"o8_1-16":["Для трамвая горять тільки три верхні вогники, а нижній вимкнений — це заборона. Звичайний світлофор для авто й мотоцикла зелений, тож їдуть лише вони.","У трамвайній «Т» нижній вогник — як ключ запалювання: не горить — не їдеш."],
"o8_1-17":["Трамвай не зважає на червоний звичайного світлофора — у нього свій. Там горить нижній вогник разом із лівим і середнім, тож трамваю можна прямо або ліворуч, а праворуч — ні.","Трамвай дивиться на свою «Т»: який верхній вогник горить — туди й можна."],
"o8_1-18":["Регулювальник стоїть з опущеними руками. Сіре й біле авто під’їжджають до його грудей і спини — їм стоп. Жовте й синє під’їжджають збоку — їм можна прямо або праворуч.","Руки вниз — те саме, що в сторони: боки їдуть, груди й спина стоять."],
"o8_1-19":["Регулювальник стоїть до тебе боком із розведеними руками — це дозвіл прямо або праворуч. Знаки головної дороги тут не діють, бо сигнали регулювальника головніші.","Регулювальник старший за знаки: ти в нього збоку — прямо або праворуч."],
"o8_1-20":["Права рука регулювальника витягнута вперед, а всі під’їжджають з його лівого боку. Звідти авто можуть їхати куди завгодно, а трамвай — лише ліворуч, тож рушають біле й синє авто.","Права рука вперед: зліва від неї авто їдуть куди хочуть, трамвай — лише ліворуч."],
"o8_1-21":["Горить зелений, а знаків чи розмітки, що щось забороняють, немає. Тож можна і прямо, і праворуч, і ліворуч, і навіть розвернутися.","Зелений без заборон — відкриті всі шляхи, включно з розворотом."],
"o8_1-22":["Поліцейський рукою показує, де саме тобі зупинитися. Туди й стань, але так, щоб не порушити правил зупинки — без заборонених місць і небезпечних маневрів.","Поліцейський показує місце — ти паркуєшся туди за правилами, а не абияк."],
"o8_1-23":["Якщо поліцейський подає знак зупинитися, стань у тому місці, яке він покаже, і при цьому дотримуйся правил зупинки. Не з лівого боку навмання і не впритул до поліцейського.","Вимога поліцейського плюс правила зупинки — дві умови разом, не одна замість іншої."],
"o8_1-24":["Регулювальник підняв руку вгору — це сигнал «Увага!». Він забороняє рух усім учасникам: і водіям, і пішоходам.","Рука вгору — як жовтий для всіх: ніхто не рушає."],
"o8_1-25":["Права рука регулювальника витягнута вперед. Жовте авто під’їжджає з лівого від нього боку — йому можна в будь-якому напрямку. Червоне й чорне — з правого боку і спини, їм стоп, а біле з боку грудей могло б лише праворуч.","Права рука вперед: лівий бік — їде куди хоче, груди — лише праворуч, правий бік і спина — стоять."],
"o8_1-26":["Регулювальник стоїть до тебе грудьми, права рука витягнута вперед. З боку грудей при такому жесті можна тільки праворуч — прямо не можна.","Груди регулювальника й витягнута права рука — тільки праворуч, як «повз руку»."],
"o8_1-27":["Регулювальник витягнув праву руку вперед. Жовте авто з його лівого боку може їхати куди хоче, зелене з боку грудей — лише праворуч. Синє і чорне під’їжджають з правого боку та спини — їм стоп.","Права рука вперед: лівий бік — усе можна, груди — праворуч, правий бік і спина — стоп."],
"o8_1-28":["Регулювальник витягнув праву руку вперед, і ти під’їжджаєш з його правого боку. З правого боку і зі спини при такому жесті рух заборонено.","Права рука регулювальника «закриває» свій правий бік: стоїш праворуч від нього — чекай."],
"o8_1-29":["Регулювальник стоїть до тебе спиною. Хоч би що він робив руками, з боку спини рух заборонено — чекай, поки він повернеться.","Спина регулювальника — завжди зачинені двері."],
"o8_1-30":["Коли права рука регулювальника витягнута вперед, пішоходи можуть переходити дорогу лише за його спиною. Спиною він стоїть до переходу Г — там і можна йти.","Пішоходи ходять за спиною регулювальника — там, де він їх не «відрізає» рукою."],
"o8_1-31":["Регулювальник дивиться на трамвай 1 і сіре авто — з боку грудей можна праворуч, і вони туди повертають. Трамвай 2 і біле авто з його лівого боку: трамваю можна ліворуч, авто — куди хоче.","Права рука вперед: груди — праворуч, лівий бік — трамваю ліворуч, авто куди завгодно."],
"o8_1-32":["Права рука регулювальника витягнута вперед, а трамвай під’їжджає з його лівого боку. Звідти трамваю дозволено тільки ліворуч — прямо чи праворуч не можна.","Трамвай з лівого боку регулювальника їде лише туди, куди показує рука, — ліворуч."],
"o8_1-33":["Регулювальник витягнув праву руку вперед, а ти під’їжджаєш з його лівого боку — звідси можна в усіх напрямках. Ти вже з лівим поворотником, тож можеш повернути ліворуч або розвернутися.","Лівий бік від витягнутої правої руки — зелене світло на все, і розворот теж."],
"o8_1-34":["Права рука регулювальника витягнута вперед, а ти під’їжджаєш з його лівого боку. Звідти автомобілям дозволено рух у будь-якому напрямку: прямо, праворуч, ліворуч і навіть розворот.","Ти зліва від регулювальника з витягнутою правою рукою — їдь куди хочеш."],
"o8_1-35":["Регулювальник головніший за світлофор. Ти під’їжджаєш з лівого боку від його витягнутої правої руки, тож прямо тобі можна. А трамваю з цього боку дозволено лише ліворуч, тож він чекає.","Зліва від регулювальника авто їде куди хоче, а трамвай — тільки ліворуч."],
"o8_1-36":["Регулювальник головніший за світлофор. Усі три авто під’їжджають з лівого боку від його витягнутої правої руки, а звідти машинам можна в будь-якому напрямку — тож їдуть усі.","Лівий бік регулювальника з витягнутою правою рукою — «зелена хвиля» для всіх авто."],
"o8_1-37":["Світлофор у формі літери Т з білими вогниками — трамвайний. Звичайні авто, тролейбуси й автобуси на нього не дивляться.","Літера Т — від слова «Трамвай»."],
"o8_1-38":["Над смугами висять світлофори для реверсивного руху. Над смугою ліворуч від вантажівки горить червоний хрестик, тож заїжджати на неї не можна — а отже, й випередити вантажівку зліва.","Хрестик над смугою — смуга закрита. Стрілка вниз — твоя."],
"o8_1-39":["Світлофори на перехресті працюють. Поки світлофор показує звичайні сигнали, знаки пріоритету не діють — їдь за світлофором.","Світлофор працює — знаки пріоритету «сплять»."],
"o8_1-40":["На зеленому сигналі намальовано стрілки прямо і ліворуч — туди й можна. А поворот ліворуч дозволяє ще й розворот, якщо його ніщо не забороняє. Праворуч — ні.","Стрілка ліворуч — квиток і на поворот, і на розворот."],
"o8_1-41":["Поліцейський вимагає зупинитися — зупинись там, куди він вкаже, і обов’язково дотримуйся правил зупинки. Ставати будь-де чи неодмінно з лівого боку — неправильно.","Сигнал поліцейського — це «де», а правила зупинки — це «як»."],
"o8_1-42":["Регулювальник головніший за червоний світлофор. Права рука в нього витягнута вперед, а обидва авто під’їжджають з його лівого боку — звідти можна їхати, тож обидва продовжують рух.","Є регулювальник — дивись на нього, а не на світлофор."],
"o8_1-43":["Регулювальник підняв руку вгору — це «Увага!», рух заборонено всім. Зелений світлофор у цю мить нічого не важить: регулювальник головніший, тож зупиняйся.","Рука вгору — стоп, навіть під зеленим світлом."],
"o8_1-44":["Якщо на перехресті працює регулювальник, слухаються саме його — і водії, і пішоходи. Світлофори та знаки в цей час відходять на другий план.","Живий регулювальник старший за будь-яку залізяку зі світлом."],
"o8_1-45":["Регулювальник стоїть грудьми до авто з розведеними в сторони руками. З боку грудей і спини при такому жесті рух заборонено — ні прямо, ні в поворот.","Груди регулювальника перед тобою — це шлагбаум."],
"o8_1-46":["Регулювальник головніший за світлофор. Права рука в нього витягнута вперед, а обидва авто під’їжджають з його лівого боку — звідти можна в будь-якому напрямку, тож їдуть обидва.","Зліва від витягнутої правої руки регулювальника — дорога відкрита."],
"o8_1-47":["На перехресті є і світлофори, і знаки, і регулювальник. Головний тут — регулювальник: його сигнали переважують і світлофор, і знаки пріоритету.","Ієрархія проста: регулювальник, потім світлофор, потім знаки."],
"o8_1-48":["Регулювальник підняв руку вгору — це сигнал «Увага!». Він забороняє рух усім: і машинам, і пішоходам.","Рука вгору — завмирають усі, хто на колесах і хто пішки."],
"o8_1-49":["На червоний треба зупинитися перед стоп-лінією. Вантажівка стала як слід, а легкове авто заїхало за лінію — порушник саме легковик.","Стоп-лінія — як край обриву: зупиняйся до неї, а не на ній."],
"o8_1-50":["Сіре авто заїжджає на реверсивну смугу одразу за світлофором із червоним хрестиком, тобто туди, де рух нею заборонено. Зелена стрілка далі не дає права заскочити на смугу раніше.","На реверсивну смугу — лише під зелену стрілку, хрестик означає «зачинено»."],
"o8_1-51":["Червоний разом із жовтим — це ще заборона: зелений от-от увімкнеться, але поки що ні. А коли він загориться, спершу дай пішоходам закінчити перехід.","Червоний плюс жовтий — «готуйся», а не «їдь»."],
"o8_1-52":["Зелена стрілка в додатковій секції дозволяє повернути праворуч навіть на червоний. Але їдеш ти «в гості»: пропусти і машини з інших напрямків, і пішоходів.","Їдеш на стрілку — пропускаєш усіх: і колеса, і ноги."],
"o8_1-53":["Основний зелений дозволяє трамваю їхати прямо, а червоному авто — повернути праворуч. Біле ж повертає ліворуч, а для цього потрібна ліва додаткова секція, яка не горить.","Вимкнена секція зі стрілкою — зачинений поворот."],
"o8_1-54":["На зеленому сигналі намальовано лише стрілку ліворуч — отже, можна повернути ліворуч. А поворот ліворуч дозволяє ще й розворот, якщо його ніщо не забороняє.","Стрілка ліворуч — це і поворот, і розворот."],
"o8_1-55":["Основний сигнал червоний, а в додатковій секції горить зелена стрілка праворуч. Тож рушити може лише синє авто, яке повертає праворуч. Червоному та сірому — чекати.","Червоний з бічною стрілкою — їде лише той, хто їде за стрілкою."],
"o8_1-56":["Основний сигнал червоний, але в додатковій секції горить зелена стрілка ліворуч. Отже, можна повернути ліворуч або розвернутися. Прямо — не можна, бо там червоний.","Стрілка ліворуч відчиняє двоє дверей: поворот і розворот."],
"o8_1-57":["Горять червоний і жовтий разом — це ще заборона, просто попередження, що скоро буде зелений. Рушати можна лише тоді, коли засвітиться зелений.","Червоний і жовтий — заводь думки, але не рушай."],
"o8_1-58":["Червоний разом із жовтим означає: рух поки що заборонено, а зараз увімкнеться зелений. Це сигнал «готуйся», а не дозвіл.","Поки горить червоний — хай навіть із жовтим — стоїмо."],
"o8_1-59":["Чорні контурні стрілки на червоному й жовтому нічого не дозволяють — вони лише заздалегідь показують, куди можна буде їхати, коли увімкнеться зелений.","Контурна стрілка — анонс: «ось куди поїдеш на зелений»."],
"o8_1-60":["Контурні стрілки на сигналах заздалегідь показують, куди можна їхати на зелений. Стрілки ліворуч серед них немає, тож і на зелений повертати ліворуч заборонено.","Немає стрілки ліворуч на світлофорі — немає й повороту ліворуч."],
"o8_1-61":["Чорні контурні стрілки на червоному — це підказка наперед: ось у яких напрямках можна буде рушити, коли загориться зелений. Значення червоного вони не змінюють.","Червоний зі стрілками — все одно червоний, а стрілки — план на зелений."],
"o8_1-62":["Основний зелений тут не дозволяє повертати ліворуч — для цього є окрема додаткова секція, і вона поки не горить. Тож зупинись перед стоп-лінією і чекай, коли засвітиться стрілка ліворуч.","Є своя секція для повороту — чекай саме її, а не загального зеленого."],
"o8_1-63":["Для смуг, де напрямок руху може змінюватися на протилежний, ставлять реверсивні світлофори: червоний хрестик і зелена стрілка вниз, як у світлофора 1.","Хрестик і стрілка вниз — мова реверсивної смуги: «зачинено» або «заїжджай»."],
"o8_1-64":["Над смугою ліворуч від вантажівки горить червоний хрестик — рух нею заборонено. Щоб випередити вантажівку зліва, треба заїхати саме туди, тож маневр заборонений, навіть якщо потім повернутися назад.","Червоний хрестик над смугою — туди не можна навіть «на хвилинку»."],
"o8_1-65":["Поруч із червоним сигналом висить табличка із зеленою стрілкою праворуч. На зелений повертати праворуч можна, а завдяки табличці — і на червоний, якщо пропустиш усіх інших.","Зелена табличка-стрілка біля червоного — «праворуч можна, але ти тут гість»."],
"o8_1-66":["Табличка із зеленою стрілкою біля червоного сигналу дозволяє повернути праворуч навіть на червоний. Увімкни правий поворотник і пропусти всіх, хто їде на свій зелений, та пішоходів.","Червоний плюс зелена табличка: праворуч можна, але поступаючись усім."],
"o8_1-67":["Два червоні вогники, що блимають по черзі, ставлять біля залізничних переїздів. Вони означають заборону руху — найчастіше наближається поїзд.","Червоні «очі» переїзду моргають по черзі — стоп, поїзд не гальмує."],
"o8_1-68":["Червоний сигнал світлофора забороняє рух — і легковикам, і трамваям. Ніяких поворотів праворуч «на свій страх» без окремої стрілки чи таблички немає.","Червоний — це стоп для всіх, без «але»."],
"o8_1-69":["На реверсивну смугу можна заїжджати тільки тоді, коли над нею горить зелена стрілка. Якщо горить червоний або світлофор узагалі вимкнений — в’їзд заборонено, тож обидва варіанти правильні.","Реверсивна смуга відкрита лише під зеленою стрілкою: червоне чи темрява — зачинено."],
"o8_1-70":["Розповісти, де населений пункт, заправка, лікарня чи зона з особливими правилами, — це робота інформаційно-вказівних знаків. Вони не забороняють і не наказують, а підказують.","Інформаційні знаки — як довідкове бюро на дорозі."],
"o8_1-71":["Регулювальником може бути не лише поліцейський, а й дорожник, військовий інспектор безпеки руху чи черговий на переїзді або поромі — якщо він у формі, з посвідченням і засобами регулювання.","Регулювальник — це роль, а не лише поліцейська форма: усі четверо рахуються."],
"o8_1-72":["Розмітка буває горизонтальна — лінії й написи на дорозі, і вертикальна — смуги на бордюрах, стовпчиках, опорах мостів. Діагональної як окремого виду немає.","Розмітка лежить або стоїть: горизонтальна й вертикальна."],
"o8_1-73":["На червоний чи підняту руку регулювальника зупиняйся перед стоп-лінією. Немає лінії — перед знаком «Місце зупинки». Немає й знака — перед світлофором або переходом. Правильні всі варіанти.","Порядок пошуку: лінія, потім знак, потім світлофор чи «зебра»."],
"o8_1-74":["Наказові знаки — круглі сині: вони кажуть, куди саме треба їхати, кому дозволено певну смугу чи ділянку, і вводять або скасовують деякі обмеження.","Наказові — сині кола, які «наказують»: їдь тільки так."],
"o8_1-75":["Якщо поліцейський вимагає зупинитися, зупинись там, куди він вкаже, і дотримуйся правил зупинки. Будь-де — не можна: можеш створити небезпеку.","Поліція показує «де», правила зупинки кажуть «як»."],
"o8_1-76":["Поліцейський може вимагати зупинитися будь-яким способом: диском чи рукою, маячком або сиреною, через гучномовець чи на спеціальному табло. Усі вони рахуються.","Жест, маячок, гучномовець чи табло — вимога одна: зупинись."],
"o8_1-77":["Обмеження в русі вводять і скасовують заборонні знаки — здебільшого круглі з червоною облямівкою: «Обгін заборонено», «Обмеження максимальної швидкості» тощо.","Заборонні знаки забороняють — і вони ж ці заборони знімають."],
"o8_1-78":["Миготливий зелений — ще дозвіл їхати, але попередження: зараз буде жовтий, а потім червоний. Оціни, чи встигнеш, або готуйся зупинитися.","Зелений підморгує — каже «поспішай, але обережно, я йду»."],
"o8_1-79":["Про те, що зелений скоро зміниться, світлофор може попередити миготінням або цифровим табло зі зворотним відліком. Обидва способи правильні.","Зелений прощається двома способами: моргає або рахує секунди."],
"o8_1-80":["Якщо регулювальник показує одне, а світлофор інше, слухай регулювальника. Він бачить ситуацію наживо, і його сигнали головніші за світлофор і знаки.","Людина старша за техніку: регулювальник перемагає світлофор."],
"o8_1-81":["Свисток регулювальника потрібен, щоб привернути увагу всіх учасників руху — і водіїв, і пішоходів, а не когось одного.","Свисток чують усі — тому він і для всіх."],
"o8_1-82":["Так: коли регулювальник показує одне, а світлофор інше, виконуєш сигнали регулювальника. Він бачить ситуацію наживо і може «перевизначити» світлофор.","Людина з жезлом перемагає лампочку."],
"o8_1-83":["Ні: якщо світлофор і регулювальник «сперечаються», світлофор програє. Дивишся на регулювальника і робиш, як він показує.","Світлофор проти регулювальника — завжди нічия на користь регулювальника."],
"o8_1-84":["Ні, знаки не головніші. Сигнали регулювальника переважують і знаки, і світлофор, і розмітку — виконуй те, що показує він.","Регулювальник — на вершині: над ним ні знаків, ні світлофорів."],
"o8_2-1":["Жовтий тимчасовий знак «Рух прямо» переважує постійні знаки розвороту. Поки він стоїть, їхати можна лише прямо — у напрямку А.","Жовтий тимчасовий знак — свіжа новина: вона важливіша за стару синю."],
"o8_2-2":["Тимчасовий знак кріплять на щиті з жовтим фоном. Саме такий знак є на малюнку 1, а на інших — звичайні постійні знаки.","Жовта рамка — значить, тимчасово."],
"o8_2-3":["Миготливий жовтий нічого не забороняє: їхати можна. Він лише попереджає, що перехрестя нерегульоване й небезпечне, тож проїжджай його за знаками пріоритету — тут треба дати дорогу.","Жовтий моргає — світлофор ніби вимкнений, тепер командують знаки."],
"o8_2-4":["Якщо знак і розмітка кажуть різне, слухай знак. Наприклад, тимчасовий знак під час ремонту переважує старі лінії на асфальті.","Знак стоїть вище за фарбу на асфальті — і буквально, і за правилами."],
"o8_2-5":["Тимчасові знаки ставлять під час ремонтів чи інших змін, тому вони важливіші за постійні. Якщо вони суперечать один одному, виконуй тимчасовий.","Тимчасове сильніше за постійне: воно описує дорогу, якою вона є саме зараз."],
"o8_2-6":["Тимчасові знаки ставлять на переносних стійках і дорожньому обладнанні або кріплять на щиті з жовтим фоном. А от над постійними знаками їх не вішають.","Тимчасовий знак — на переносній стійці або в жовтій рамці."],
"o8_2-7":["Попереджувальні знаки — трикутні з червоною облямівкою — заздалегідь кажуть про небезпеку попереду: крутий поворот, слизьку дорогу, переїзд. Їх бачиш — готуйся діяти обережно.","Трикутник попереджає: «Увага, попереду сюрприз»."],
"o9-1":["Авто в колоні вдень їдуть з увімкненим ближнім світлом фар — так їх легше помітити й зрозуміти, що це одна колона. Денних ходових вогнів для цього недостатньо.","Колона — це «світлий» ланцюжок: у всіх горить ближнє."],
"o9-2":["Знак аварійної зупинки ззаду на авто, що їде, може означати дві речі: машина несправна і їде до місця ремонту чи стоянки, або її буксирують. Обидва випадки можливі.","Трикутник на ходу: «я хворий» або «мене тягнуть»."],
"o9-3":["Якщо в машини, яку буксирують, не працює аварійка, ззаду на ній треба закріпити знак аварійної зупинки або миготливий червоний ліхтар — щоб водії позаду бачили небезпеку.","Немає аварійки — її замінює трикутник або червоний ліхтар ззаду."],
"o9-4":["Коли колона зупиняється на дорозі, на всіх її машинах вмикають аварійну сигналізацію. Так інші водії одразу бачать, що колона стоїть.","Колона їде — ближнє світло, колона стоїть — аварійка."],
"o9-5":["У населеному пункті знак аварійної зупинки ставлять на такій відстані, щоб це було безпечно, але не ближче ніж за 20 м від машини.","Місто — 20 м: приблизно чотири довжини авто до трикутника."],
"o9-6":["Аварійку разом зі знаком аварійної зупинки чи червоним ліхтарем виставляють після ДТП і під час вимушеної зупинки там, де погано видно дорогу. Для посадки дітей потрібна лише аварійка.","Трикутник на асфальт — коли ДТП або коли тебе погано видно."],
"o9-7":["Місце ДТП позначають подвійно: вмикають аварійну сигналізацію і ставлять знак аварійної зупинки або миготливий червоний ліхтар. Одних лише вогнів на авто мало.","ДТП — дві «мигалки»: аварійка на авто і трикутник позаду."],
"o9-8":["Рушаючи від правого краю дороги, ти виїжджаєш ліворуч, тож потрібен лівий покажчик повороту. Саме так зроблено на першому малюнку — чіткий сигнал без зайвих жестів.","Рушаєш від узбіччя — лівий поворотник, і всім зрозуміло."],
"o9-9":["Якщо ввімкнути правий поворотник ще перед першим перехрестям, водій білого авто подумає, що ти повертаєш до нього, і може виїхати. Тож проїдь перше перехрестя, а вже потім сигналь.","Поворотник — це обіцянка: вмикай його там, де справді повертаєш."],
"o9-10":["На машині, яку буксирують, вмикають лише аварійну сигналізацію. Ближнє світло — справа того, хто буксирує.","Хто тягне — світить фарами, кого тягнуть — моргає аварійкою."],
"o9-11":["Якщо поворотники не працюють, поворот праворуч показують лівою рукою: висувають її у вікно й згинають у лікті вгору під прямим кутом. Саме так на першому малюнку.","Ліва рука «гачком» угору — поворот праворуч."],
"o9-12":["Якщо їдеш із несправністю, з якою рух ще дозволено, вмикай аварійну сигналізацію. Так інші водії розуміють, що з твоєю машиною щось не так.","Їдеш «хворим» — моргай аварійкою."],
"o9-13":["Якщо аварійка не працює, ззаду на машині закріплюють знак аварійної зупинки або миготливий червоний ліхтар. Підходить будь-що з цих двох.","Немає аварійки — трикутник чи червоний ліхтар ззаду, на вибір."],
"o9-14":["У тунелі вмикай ближнє світло фар — навіть удень. Денних ходових вогнів чи протитуманок без ближнього там недостатньо.","Тунель — це ніч посеред дня: вмикай ближнє."],
"o9-15":["Аварійку обов’язково вмикають на автобусі зі знаком «Діти» під час посадки чи висадки дітей і на машинах колони, коли вона стоїть на дорозі. На тому, хто буксирує, — ні.","Діти виходять чи колона стала — моргає аварійка."],
"o9-16":["Якщо доводиться вимушено зупинитися там, де дорогу погано видно, увімкни аварійку і вистав знак аварійної зупинки або миготливий червоний ліхтар на потрібній відстані.","Тебе погано видно — значить, потрібні і аварійка, і трикутник."],
"o9-17":["Перед тим як рушити чи зупинитися, вмикай покажчик повороту. Так інші бачать, що ти виїжджаєш від краю або збираєшся до нього пригальмувати.","Рушаю чи стаю — поворотник, а не аварійка."],
"o9-18":["Під час вимушеної зупинки, якщо аварійка не працює, постав знак аварійної зупинки або миготливий червоний ліхтар. Досить одного з них.","Аварійка зламалася — її замінює трикутник або червоний ліхтар."],
"o9-19":["Якщо аварійки немає, знак аварійної зупинки чи червоний ліхтар ставлять з того боку, звідки машину гірше видно. Саме звідти найбільший ризик, що в тебе вріжуться.","Трикутник — туди, звідки тебе не видно."],
"o9-20":["Якщо рухаєшся по колу в одній смузі й не перестроюєшся, поворотник не потрібен. Блимати без маневру — лише плутати інших.","Поворотник — тільки під маневр. Немає маневру — немає миготіння."],
"o9-21":["Перед розворотом у населеному пункті сигнал подають заздалегідь — не менш як за 50–100 метрів, щоб інші встигли зрозуміти твій намір. І незалежно від того, чи є хтось поруч.","50–100 метрів — це від половини до цілого футбольного поля."],
"o9-22":["Збираєшся перестроїтися в місті — вмикай поворотник не менш як за 50–100 метрів до маневру. Сигнал подають завжди, а не лише коли поруч є інші.","У місті попереджай за 50–100 м — півполя чи поле до маневру."],
"o9-23":["Повертаючи праворуч на перехресті в місті, вмикай поворотник не менш як за 50–100 метрів. Так водії позаду встигнуть пригальмувати, а пішоходи — зрозуміти тебе.","Місто: поворотник за 50–100 м до повороту, а не в останню мить."],
"o9-24":["Велосипедист показує, що гальмує, піднявши вгору ліву або праву руку. Як у школі: рука вгору — «увага, зупиняюсь».","Рука вгору — гальмую, хоч ліва, хоч права."],
"o9-25":["Поворот праворуч на велосипеді: або праву руку витягни вбік, або ліву руку вбік і зігни в лікті вгору під прямим кутом. Обидва жести означають «праворуч».","Пряма рука показує свій бік, зігнута вгору — протилежний."],
"o9-26":["Поворот ліворуч на велосипеді: ліву руку витягни вбік або праву руку вбік і зігни в лікті вгору. Пряма рука вказує свій бік, зігнута — протилежний.","Ліворуч: пряма ліва або «гачок» правою."],
"o9-27":["Водій сидить зліва, тож сигналить лівою рукою у вікно. Пряма ліва рука вбік означає поворот ліворуч — вона просто показує, куди їдеш.","Ліва рука прямо з вікна — показуєш пальцем: ліворуч."],
"o9-28":["З машини правою рукою назовні не дотягнешся, тож поворот праворуч показують лівою: висунь її у вікно й зігни в лікті вгору під прямим кутом.","Ліва рука «гачком» угору — поворот праворуч."],
"o9-29":["Рушаючи з місця, вмикай покажчик повороту — так інші бачать, що ти виїжджаєш у потік. Аварійка й габарити тут ні до чого.","Рушаєш — моргни поворотником, наче кажеш усім: «я рушаю»."],
"o9-30":["Збираєшся зупинитися біля правого краю — вмикай правий поворотник завжди: і в місті, і за містом, і навіть коли поруч нікого не видно.","Поворотник вмикають не «для когось», а завжди."],
"o9-31":["Миготливий червоний ліхтар може замінити знак аварійної зупинки, лише якщо його добре видно завжди: і яскравим сонячним днем, і в темряві чи тумані.","Ліхтар замість трикутника — тільки якщо його видно і вдень, і вночі."],
"o9-32":["Коли тебе зупиняє поліцейський, увімкни аварійну сигналізацію. Так іншим водіям видно, що машина стоїть не просто так.","Зупиняє поліція — вмикай аварійку."],
"o9-33":["Аварійку вмикають, коли тебе зупиняє поліцейський, і коли доводиться зупинитися, бо засліпили фари зустрічних. А за кожної звичайної зупинки — ні.","Поліція або засліплення — два приводи для аварійки."],
"o9-34":["Звуковий сигнал можна подати, щоб попередити водія, якого обганяєш поза населеним пунктом, і коли інакше ДТП не уникнути. У місті для обгону гудок не використовують.","За містом гудок — для обгону й порятунку, у місті — тільки для порятунку."],
"o9-35":["Сигналити заборонено в населених пунктах, а за містом — там, де стоїть знак заборони звукового сигналу. Виняток один: коли без гудка не уникнути ДТП. Обидва варіанти правильні.","Місто або знак заборони — тиша, якщо не рятуєш від ДТП."],
"o9-36":["У населеному пункті гудіти заборонено. Єдиний виняток — коли без звукового сигналу не вдасться відвернути ДТП.","Місто любить тишу: гудок — тільки щоб врятувати від аварії."],
"o9-37":["Поворотник лише попереджає про твій намір — він не дає права їхати першим. Ти все одно мусиш переконатися, що маневр безпечний, і пропустити тих, кого треба.","Поворотник — це «я хочу», а не «мені можна»."],
"o9-38":["Увімкнений поворотник не робить тебе головним. Перестроюючись, пропусти тих, хто вже їде смугою, на яку ти хочеш зайти.","Поворотник просить, а не наказує."],
"o9-39":["Сигнал рукою подають заздалегідь, а припиняють безпосередньо перед маневром — під час повороту руки мають бути на кермі.","Рука сигналить до маневру, а кермує — під час нього."],
"o9-40":["Поворотник має блимати під час усього маневру й вимкнутися одразу після нього. Інакше інші думатимуть, що ти ще збираєшся повертати.","Маневр закінчився — поворотник замовк."],
"o9-41":["За містом швидкості вищі, тож попереджати про маневр треба раніше — не менше ніж за 150–200 м.","За містом попереджай здалеку: 150–200 м, а не під самим поворотом."],
"o9-42":["Якщо стоп-сигнали не працюють, гальмування показують рукою, піднятою вгору, — лівою або правою.","Стоп-сигнали зламалися — твоя рука вгору стає стоп-сигналом."],
"o9-43":["Перед тим як рушити з місця або зупинитися, вмикай світловий покажчик повороту. Аварійка й стоянкові вогні для цього не підходять.","Рушаєш чи стаєш — поворотник розповідає про твій план."],
"o9-44":["Поворотник перед перестроюванням вмикають завжди — навіть коли поруч нікого не видно. Машина чи мотоцикл можуть ховатися в «мертвій зоні».","Поворотник — звичка, а не реакція на сусідів."],
"o9-45":["За містом сигналом можна попередити водія, якого обганяєш, — але не там, де стоїть знак заборони звукового сигналу. Знак завжди головніший.","Знак заборони гудка вимикає гудок навіть за містом."],
"o9-46":["У місті звуковий сигнал для обгону заборонено. Привернути увагу водія, якого обганяєш, можна лише перемиканням світла фар — коротким миганням.","У місті обганяєш — моргай фарами, а не гуди."],
"o9-47":["Щоб водій, якого обганяєш, тебе помітив, можна перемкнути світло фар, а поза населеними пунктами — ще й посигналити. Тож правильні і фари, і гудок за містом.","Фари — завжди, гудок — лише за містом."],
"o9-48":["Якщо доводиться вимушено зупинитися на дорозі, вмикай аварійну сигналізацію — так інші бачать, що машина стоїть через проблему.","Вимушено стоїш — аварійка блимає."],
"o9-49":["Удень під час буксирування машина, що тягне, їде з ближнім світлом, а та, яку тягнуть, — з аварійкою.","Хто тягне — світить, кого тягнуть — блимає."],
"o9-50":["Денні ходові вогні, а якщо їх немає, ближнє світло вдень вмикають на всіх дорогах поза населеними пунктами — не лише на автомагістралях.","Знак кінця населеного пункту — сигнал увімкнути денні вогні чи ближнє."],
"o9-51":["Денні ходові вогні або ближнє світло вдень вмикають під час руху на дорогах поза населеними пунктами — цілий рік, а не лише в певні місяці.","За містом удень вогні горять завжди, без сезонів."],
"o9-52":["Удень за містом денні ходові вогні або ближнє світло мають горіти на всіх механічних транспортних засобах — від легковика до вантажівки, а не лише на великих чи особливих.","За містом удень світиться кожен, хто їде на моторі."],
"o9-53":["Якщо в машини немає денних ходових вогнів, за містом удень вмикай ближнє світло фар. Габарити чи аварійка його не замінять.","Немає денних вогнів — їхню роботу робить ближнє."],
"o9-54":["За містом удень вмикай денні ходові вогні, а якщо їх у машині немає — ближнє світло фар. Дальнє засліплює, а аварійка тут не до речі.","Денні вогні — план А, ближнє світло — план Б."],
"o9-55":["У тунелі ближнє світло вмикають завжди — навіть якщо там є штучне освітлення. Так тебе краще видно іншим.","Тунель — фари завжди, хоч би як яскраво там світили лампи."],
"o9-56":["Удень машина, яка буксирує, їде з увімкненим ближнім світлом фар. Аварійка — для тієї, яку буксирують.","Тягач — фари, причеплений — аварійка."],
"o9-57":["Машини колони вдень завжди їдуть з ближнім світлом фар — навіть із супроводом з маячками чи з денними ходовими вогнями.","Колона без ближнього світла не буває."],
"o9-58":["Ближнє світло вдень як попереджувальний сигнал вмикають на машині, що буксирує, і на машинах колони. На тій, яку буксирують, — аварійка, а не фари.","Фари вдень — у тягача і в колони."],
"o9-59":["Поворотник вмикають завжди: перед тим як рушити, зупинитися, перестроїтися, повернути чи розвернутися — незалежно від того, чи є поруч інші й наскільки щільний рух.","Рушаю, стаю, перестроююсь, повертаю, розвертаюсь — завжди з поворотником."],
"o9-60":["Щоб пригальмувати й стати праворуч, вмикай правий покажчик повороту. Так водій позаду, якого видно в дзеркалі, зрозуміє твій намір.","Паркуєшся — поворотник, а не аварійка: аварійка для біди."],
"o10-1":["Розвертатися на самому залізничному переїзді заборонено, тому траєкторія Б відпадає. До переїзду, як А, або вже після нього, як В, розворот можливий.","Рейки — не майданчик для розвороту: крутись до них або після."],
"o10-2":["Смуга розгону потрібна, щоб набрати швидкість і акуратно влитися в потік. Але перевага в тих, хто вже їде дорогою: ти підлаштовуєшся під них і пропускаєш.","Смуга розгону — щоб розігнатися, а не щоб тебе пропускали."],
"o10-3":["На автомагістралях і дорогах для автомобілів їздити заднім ходом заборонено — навіть якщо інакше до потрібного місця не під’їхати. Там високі швидкості, і машина, що їде назад, — смертельна несподіванка.","Магістраль — дорога однієї думки: тільки вперед."],
"o10-4":["У тунелі задній хід заборонений навіть тоді, коли інакше до потрібного місця не під’їхати. Там тісно й темно, тож здавати назад надто небезпечно.","Тунель — лише вперед. Назад у тунелі — зась."],
"o10-5":["Знак попереджає про небезпечний поворот: дорогу за ним майже не видно. Їхати тут заднім ходом заборонено — водій із-за повороту просто не встигне тебе помітити.","Крутий поворот — задню передачу не вмикай: з-за рогу тебе не видно."],
"o10-6":["У тумані дорогу видно погано, тому їхати заднім ходом тут заборонено. Ти не бачиш інших, а вони — тебе, і жодна обережність тут не допоможе.","Нічого не видно — назад не їдь."],
"o10-7":["На лісовій дорозі обидві дороги рівнозначні, тож діє правило «перешкода справа». Біле авто для синього — праворуч, тому синій пропускає білого й рушає другим.","Хто праворуч — той і перший. Синій бачить білого справа — чекає."],
"o10-8":["У житловій зоні на такому перехресті теж діє правило «перешкода справа». Сіре авто для жовтого — праворуч, тож жовте пропускає сіре й проїжджає другим.","Правило правої руки працює і серед будинків: хто справа — той перший."],
"o10-9":["Виїзд із житлової зони — як виїзд із двору: ти пропускаєш усіх, хто вже рухається дорогою. Тож чекаєш і пішохода, що переходить виїзд, і жовте авто.","Виїжджаєш із житлової зони — ти гість: пропусти і людей, і машини."],
"o10-10":["Повертаючи праворуч, ти перетинаєш велосипедну смугу. Велосипедист їде прямо своєю смугою, тож ти завжди пропускаєш його й лише потім повертаєш. Сигнал переваги не дає.","Велосмуга — доріжка велосипедиста: перетинаєш її — пропусти його."],
"o10-11":["Ти на сірому авто, а праворуч уже їде біле. Хто перестроюється, той пропускає тих, хто вже рухається потрібною смугою. Тож спершу пропусти біле, переконайся, що безпечно, — і тоді перестроюйся.","Чужа смуга — не твоя, доки там хтось їде. Спершу пропусти, потім заходь."],
"o10-12":["Ти на білому авто й хочеш ліворуч, а там уже їде сіре. Одностороння дорога переваги не дає: хто перестроюється, той пропускає тих, хто вже їде смугою, куди він заходить.","Перестроюєшся — ти гість у чужій смузі. Господаря пропускаєш першим."],
"o10-13":["Коли два авто перестроюються одночасно й можуть зіткнутися, поступається той, хто ліворуч. Ти на білому — праворуч від сірого, тож перевага твоя.","Одночасне перестроювання — як рівнозначне перехрестя: перешкода справа має перевагу."],
"o10-14":["Ти на сірому — ліворуч від білого. Коли обидва перестроюються одночасно, поступається той, хто ліворуч, тобто ти. Пропусти біле авто, а потім перестроюйся.","Хто ліворуч — той чекає. Білий справа — він і перший."],
"o10-15":["Розвертатися просто на залізничному переїзді заборонено — рейки не місце для маневрів. Тому синій розвертається або перед переїздом, або вже після нього.","Рейки — не місце для розвороту: розвертайся до них або після них."],
"o10-16":["Якщо дорога має смугу для розгону, повертай саме на неї: розженися там до швидкості потоку й лише потім перестроюйся. Це шлях Б. Шлях А веде одразу в потік, без розгону.","Смуга розгону — як злітна смуга: спершу розженися на ній, потім вливайся в потік."],
"o10-17":["На автомагістралі розвертатися заборонено, зокрема й через технологічні розриви в розділювальній смузі. Ці проїзди зроблені для служб, а не для розвороту звичайних авто.","Автомагістраль — тільки вперед. Розрив у розділювальній смузі — не для тебе."],
"o10-18":["Порушник лише синій: він розвертається просто на мосту, а там розворот заборонено. Зелений розвертається на нижній дорозі поруч із мостом, не під ним, тож правил не порушує.","Міст — не карусель: на ньому не розвертаються."],
"o10-19":["Знак за виїздом дозволяє рух лише праворуч, тож повертати праворуч можна з обох смуг одночасно. Біле авто з лівої смуги теж повертає праворуч — це дозволено, кожен займає свою смугу.","Стрілка показує тільки праворуч — значить, праворуч повертають обидві смуги."],
"o10-20":["Перед небезпечним поворотом дорогу далеко не видно, тому розвертатися тут заборонено. Авто з-за повороту з’явиться раптово й може не встигнути загальмувати.","Не бачиш, що за поворотом, — не розвертайся."],
"o10-21":["Знак дозволяє рух лише праворуч, тож повертати праворуч можна з обох смуг. Біле авто ліворуч від червоного теж повертає праворуч — і робить це правильно, займаючи свою смугу.","Одна стрілка праворуч на всіх — повертають обидві смуги, кожна у свою."],
"o10-22":["На виїзді з кола обидва авто з’їжджають кожне у свою смугу й не заважають одне одному. Тому біле може з’їхати одночасно із синім — порушення тут немає.","Дві смуги на виїзді — два авто поруч. Кожен у своїй — і все гаразд."],
"o10-23":["На коло тут можна заїжджати з обох смуг: червоне — з правої, біле — з лівої. Обидва водії правильно зайняли смуги для в’їзду на перехрестя з круговим рухом.","На коло ведуть обидві смуги: заїжджай з тієї, у якій їдеш."],
"o10-24":["Знак напрямків руху по смугах дозволяє повертати праворуч з обох правих смуг. Тож червоне авто ліворуч правильно повертає з другої смуги у другу смугу, а чорне — у крайню праву.","Кожна смуга повороту веде у «свою» смугу: друга — у другу, крайня — у крайню."],
"o10-25":["Тут розвертаються саме на перехресті, а там розворот дозволений, якщо його не заборонено. Вимога про 10 м від пішохідного переходу стосується розвороту поза перехрестям, тож тут вона не заважає.","Перехрестя — законне місце для розвороту, навіть якщо довкола «зебри»."],
"o10-26":["Розвертатися на пішохідному переході й у позначеній зоні біля нього заборонено. Б — просто на переході, В — надто близько за ним. Лише А — на безпечній відстані перед переходом.","«Зебра» й зона довкола неї — не для розвороту. Розвертайся далеко від неї, як у місці А."],
"o10-27":["Перестроюючись ліворуч, роби все разом: увімкни лівий покажчик, подивися в ліве дзеркало й глянь у сліпу зону, а тим, хто вже їде лівою смугою, дай дорогу.","Поворотник — дзеркало — сліпа зона — пропусти. Жоден крок не пропускай."],
"o10-28":["Перестроюючись, пропускай усіх, хто їде попутно смугою, куди ти перебираєшся: і авто, і автобуси, і мопеди, і велосипедистів. Винятків «тільки для когось» тут немає.","У чужій смузі всі мають перевагу: пропускаєш кожного, хто там їде."],
"o10-29":["Авто попереду вже почало розворот, тож ти пропускаєш його й лише потім повертаєш ліворуч. Сигнал тут нічого не вирішує — треба поступитися.","Хто попереду й уже розвертається — той перший. Сигнал не замінює поступливості."],
"o10-30":["Перестроюючись праворуч, роби все разом: увімкни правий покажчик, подивися в праве дзеркало й перевір сліпу зону, а тим, хто вже їде правою смугою, дай дорогу.","Сигнал, дзеркало, сліпа зона, пропусти — повний набір для кожного перестроювання."],
"o10-31":["Повертаючи праворуч, тримайся ближче до правого краю дороги. Так ніхто не протиснеться між тобою і бордюром, а ти не зачепиш сусідню смугу.","Праворуч — притискайся до правого краю, щоб збоку не лишалося щілини."],
"o10-32":["Повертаючи ліворуч поза перехрестям, увімкни лівий покажчик, займи крайнє ліве положення на своїй половині дороги й пропусти зустрічні авто. Потрібно все разом.","Ліворуч поза перехрестям: блимни, стань лівіше, пропусти зустрічних."],
"o10-33":["Розвертатися можна на звичайній дорозі з однією смугою в кожен бік, якщо немає заборонних знаків і суцільної лінії. У тунелях, на мостах, шляхопроводах і естакадах розворот заборонений.","Немає суцільної, немає заборонних знаків, ти не в тунелі й не на мосту — розвертайся."],
"o10-34":["На перехрестя з круговим рухом можна заїжджати з будь-якої смуги, якою їдеш у цьому напрямку. Перестроюватися для цього в крайню праву не обов’язково.","На коло — з будь-якої смуги свого напрямку."],
"o10-35":["На мосту розвертатися заборонено, навіть якщо розумієш, що їдеш не туди. Доїдь до кінця мосту й розвернися там, де це дозволено.","Не той напрямок на мосту — спершу переїдь міст, а вже потім розвертайся."],
"o10-36":["На перехресті, повертаючи праворуч, тримайся ближче до правого краю дороги — за будь-якої швидкості. Так поворот акуратний, і ніхто не втиснеться справа.","Повертаєш праворуч — тримайся правого краю, як за поручень."],
"o10-37":["Перед поворотом ліворуч заздалегідь увімкни покажчик і займи крайнє ліве положення. А повертай так, щоб після перехрестя не опинитися на зустрічній смузі.","Ліворуч: завчасно блимни, стань лівіше й не вилітай на зустрічку."],
"o10-38":["Авто попереду вже почало розвертатися, тож ти пропускаєш його й тільки потім повертаєш ліворуч. Звуковий сигнал не дає права проїхати першим.","Сусід попереду вже розвертається — почекай, твій поворот після нього."],
"o10-39":["Розвертаючись поза перехрестям, перевір, що знаки й розмітка це дозволяють, займи крайнє положення, пропусти зустрічні авто й переконайся, що нікому не заважаєш. Потрібно все разом.","Розворот — повний комплект: дозвіл, позиція, пропуск зустрічних, безпека."],
"o10-40":["Розвертаючись поза перехрестям, увімкни лівий покажчик, займи крайнє ліве положення й пропусти зустрічні авто. Без будь-якої з цих дій розворот неправильний.","Розворот: блимни ліворуч, стань лівіше, пропусти зустрічних."],
"o10-41":["Перестроюючись праворуч, пропускай усіх, хто попутно їде смугою, куди ти переходиш, — і авто, і велосипедистів, і будь-кого ще. Винятків немає.","У смузі, куди перестроюєшся, кожен, хто вже їде, — перший."],
"o10-42":["Виїжджаючи із заправки, ти поступаєшся всім: перед тротуаром — пішоходам, а перед дорогою — усім, хто нею їде. Хто вже рухається, той і має перевагу.","Із заправки — як із двору: пропусти всіх, хто йде чи їде."],
"o10-43":["Виїжджаючи зі стоянки, пропусти пішоходів на тротуарі й усіх, хто їде дорогою. Ти тільки вливаєшся в рух, тож поступаєшся тим, хто вже рухається.","Зі стоянки — останнім: спершу всі, хто вже йде та їде, потім ти."],
"o10-44":["Їдучи заднім ходом, головне — нікому не заважати й нікого не наражати на небезпеку. Аварійка чи гудок тут не обов’язкові, обов’язкова безпека.","Задній хід — тихо й обережно: головне не мигалки, а нікому не заважати."],
"o10-45":["Якщо позаду погано видно, попроси когось допомогти: людина ззовні підкаже, куди їхати й коли зупинитися. Аварійка цього не замінить.","Не бачиш, що позаду, — поклич помічника: його очі замінять дзеркала."],
"o10-46":["На дорозі з одностороннім рухом задній хід дозволений, але лише тоді, коли інакше до потрібного місця не під’їхати і коли це безпечно.","Односторонка не забороняє заднього ходу: можна, якщо інакше ніяк і безпечно."],
"o10-47":["Розвертатися ближче ніж за 10 м від пішохідного переходу заборонено з обох боків — і перед ним, і за ним. Так «зебра» лишається вільною й добре видимою.","Довкола «зебри» по 10 м з кожного боку — зона без розворотів."],
"o10-48":["Заднім ходом не можна їхати просто на пішохідному переході й на залізничному переїзді: там люди й потяги, а тебе погано видно.","«Зебра» і рейки — тільки вперед."],
"o10-49":["Заднім ходом заборонено їхати на перехрестях і там, де погана оглядовість чи видимість. На перехресті рух з усіх боків, а в тумані чи за поворотом тебе просто не помітять.","Перехрестя і погана видимість — задню не вмикай."],
"o10-50":["Якщо перед з’їздом є смуга гальмування, заздалегідь перестройся на неї й гальмуй уже там. Так ти не заважаєш тим, хто швидко їде основною дорогою.","Смуга гальмування — щоб гальмувати на ній, а не в загальному потоці."],
"o10-51":["Розвертатися заборонено в тунелях, на мостах, шляхопроводах, естакадах і під ними. У таких місцях тісно й погано видно, тож розворот надто небезпечний.","Тунель, міст і місце під мостом — розворот під забороною."],
"o10-52":["Якщо через розміри авто з крайнього положення не повернути, можна повертати інакше — але нікому не заважаючи. А за потреби попроси когось допомогти й підказати.","Велике авто не вписується — повертай обережно й поклич помічника."],
"o10-53":["Повернути не з крайнього положення можна, коли габарити авто інакше не дозволяють. Але при цьому не можна порушувати знаки й розмітку та створювати небезпеку — тому правильні обидва варіанти.","Великому авто можна ширше — але без порушення знаків і без небезпеки для інших."],
"o10-54":["Якщо шляхи перетинаються, а правила не кажуть, хто перший, пропускай того, хто наближається справа. Це базове правило «перешкода справа».","Сумніваєшся, хто перший, — дивись праворуч: хто справа, той і їде."],
"o10-55":["Перш ніж рушити, переконайся і що це безпечно, і що ти нікому не заважаєш. Потрібні обидві умови разом.","Перш ніж рушати — озирнися: безпечно й нікому не заважаю?"],
"o10-56":["Перед поворотом праворуч займи крайнє праве положення, переконайся, що це безпечно і що ти нікому не заважаєш. Потрібно все разом.","Праворуч: стань правіше, глянь довкола, нікому не заважай."],
"o10-57":["Виїжджаючи з двору, заправки чи стоянки, ти поступаєшся всім: пішоходам на тротуарі й транспорту на дорозі. Хто вже рухається, той і має перевагу.","Із прилеглої території виїжджаєш останнім: спершу люди, потім машини, тоді ти."],
"o10-58":["Для велосипедиста правило те саме: виїжджаючи з двору чи іншої прилеглої території, пропусти і пішоходів, і весь транспорт на дорозі.","Хоч на авто, хоч на велосипеді: із двору — пропусти всіх."],
"o10-59":["Звертаючи з дороги у двір чи на стоянку, пропусти велосипедистів і пішоходів, чий шлях ти перетинаєш. Вони рухаються прямо, а ти змінюєш напрямок.","Заїжджаєш у двір — пропусти тих, через чий шлях проїжджаєш."],
"o10-60":["Велосипедист перед поворотом праворуч теж займає крайнє праве положення й переконується, що це безпечно та нікому не заважає. Правила тут ті самі, що й для авто.","Велосипед — теж транспорт: праворуч — правіше й обережно."],
"o10-61":["Ліворуч на перехресті зазвичай повертають із крайньої лівої смуги. Але якщо знаки чи розмітка дозволяють поворот і з інших смуг, можна й з них — залежно від ситуації.","Ліворуч — із лівої смуги, якщо знаки й розмітка не відкривають інших."],
"o10-62":["На перехресті розвертатися можна навіть поруч із пішохідним переходом. Заборона розвороту ближче 10 метрів від переходу стосується розвороту поза перехрестям.","Перехрестя — дозволене місце для розвороту, навіть коли «зебра» поруч."],
"o10-63":["Тут туман і крутий поворот, тож дорогу далеко не видно. Розвертатися в такому місці заборонено: наступне авто вигулькне з-за повороту раптово.","Туман і поворот — не бачиш дороги, не розвертайся."],
"o10-64":["Коли дорогу видно менш як на 100 м в обидва боки, розвертатися заборонено. Інші авто з’являться надто пізно, і ні ти, ні вони не встигнете загальмувати.","Не бачиш і на 100 м — забудь про розворот."],
"o10-65":["Заїжджаючи на коло, ти не повертаєш ліворуч, а вливаєшся в рух по колу, тож лівий покажчик тут не потрібен. Він лише заплутає інших водіїв.","На коло заїжджають без лівого «поворотника»: ліворуч тут ніхто не повертає."],
"o10-66":["Знак над дорогою показує, куди можна їхати з кожної смуги. Червоне авто в смузі, з якої дозволено і прямо, і ліворуч, тож прямо їхати можна.","Читай стрілки над своєю смугою: є стрілка прямо — їдь прямо."],
"o10-67":["Синя табличка зі стрілкою показує, що дорога попереду одностороння і рух нею йде праворуч. Повернувши ліворуч, поїдеш назустріч потоку, тож це заборонено.","Стрілка на синій табличці — напрямок потоку. Проти стрілки не повертай."],
"o10-68":["На пішохідному переході розвертатися заборонено, навіть коли довкола порожньо. Виняток один: перехід на перехресті, де розворот дозволений.","«Зебра» — не місце для розвороту, хіба що це дозволений розворот на перехресті."],
"o10-69":["Навіть якщо перехід розділений острівцем безпеки, це все одно пішохідний перехід, і розвертатися на ньому заборонено.","«Зебра» з острівцем — та сама «зебра»: розворот на ній заборонений."],
"o10-70":["У тунелі розвертатися заборонено завжди — хай який він світлий і широкий. Там тісно, і розворот надто небезпечний, тож їдь до виїзду.","Тунель — труба з одним напрямком: тільки вперед до виходу."],
"o10-71":["Так, якщо позаду погано видно, попроси когось допомогти. Людина ззовні побачить те, чого не видно з місця водія.","Задній хід наосліп — ні. Задній хід із помічником — так."],
"o10-72":["Так, виїжджаючи з паркування заднім ходом, можна попросити когось допомогти, якщо огляду не вистачає. Помічник підкаже, коли зупинитися.","Тісно й погано видно — поклич помічника: він твої очі позаду."],
"o10-73":["На автомагістралі задній хід заборонений, навіть якщо позаду порожньо й увімкнена аварійка. Якщо з’їзд пропущено — їдь до наступного.","Проґавлений з’їзд на магістралі — не біда: буде наступний. А задній хід — під забороною."],
"o10-74":["На автомагістралі авто мчать дуже швидко, тож задній хід там заборонений, навіть коли позаду нікого не видно.","Магістраль — тільки вперед, як потяг по рейках."],
"o10-75":["На гірському спуску передачу вимикати не можна: двигун допомагає стримувати авто, а без нього воно розганяється, і гальма швидко перегріваються.","Гірський спуск — тільки на передачі: двигун тримає авто, як віжки коня."],
"o10-76":["Технологічні розриви в розділювальній смузі на автомагістралі — не для розворотів. Розвертатися там заборонено, навіть якщо дорогу добре видно.","Розрив на магістралі — для служб, а не для твого розвороту."],
"o11-1":["Якщо посередині дороги є трамвайна колія твого напрямку, розвертатися треба саме з неї. Тому правильний шлях Б, а не широка дуга з правої смуги.","Є трамвайна колія твого напрямку — розворот починай із неї."],
"o11-2":["Трамвайною колією попутного напрямку, що на одному рівні з дорогою, їхати можна, якщо не заважаєш трамваю. Тож виїхати на неї тут дозволено.","Колія твого напрямку на рівні з дорогою — можна, але трамвай завжди головний."],
"o11-3":["На дорозі з трамвайною колією попутного напрямку ліворуч повертають саме з цієї колії — це шлях Б. Інші траєкторії неправильні.","Є колія твого напрямку — ліворуч повертай з неї: шлях Б."],
"o11-4":["Стрілки на дорозі показують: ліворуч повертають із лівої смуги проїзної частини, а не з колії. Коли розмітка задає такий порядок, з трамвайної колії повертати не можна.","Стрілка «ліворуч» намальована на смузі — повертай зі смуги, а не з рейок."],
"o11-5":["Знак над дорогою показує, що ліворуч повертають з лівої смуги проїзної частини. Коли знак задає такий порядок, повертати ліворуч із трамвайної колії не можна.","Знак указав смугу для повороту — рейки вже не варіант."],
"o11-6":["Тут трамвайна колія відокремлена від дороги бордюром і газоном, тож виїжджати на неї й їхати нею не можна. Це територія трамвая, а не продовження дороги.","Колія за бордюром і газоном — тільки для трамвая."],
"o11-7":["Їхати весь час посередині, накриваючи переривчасту лінію, не можна. Заїжджати на неї дозволено лише тоді, коли перестроюєшся в іншу смугу.","Переривчаста — щоб її перетинати, а не щоб їхати по ній."],
"o11-8":["Червоне авто їде посередині, займаючи дві смуги одразу. Якщо їдеш прямо, тримайся правого краю — тож перестройся у праву смугу.","Одне авто — одна смуга. Їдеш прямо — займай праву."],
"o11-9":["У щільному потоці білий може перестроїтися, але лише з поважної причини: щоб об’їхати перешкоду, повернути чи розвернутися. Шукати швидшу смугу не можна.","Затор — не привід стрибати зі смуги на смугу. Перестроюйся лише з потреби."],
"o11-10":["Повертаючи на дорогу з реверсивною смугою, спершу займи крайню праву смугу. На реверсивну перестроюйся вже після перехрестя, переконавшись, що світлофор над нею дозволяє. Так і їде шлях Б.","Реверсивна — не з розгону: спершу праворуч, потім, якщо світлофор дозволяє, — на неї."],
"o11-11":["Тут у кожен бік кілька смуг, тож велосипедистові повертати ліворуч чи розвертатися з проїзної частини не можна. Він їде прямо біля правого краю — шлях Б.","Широка дорога — велосипед тримається правого краю і їде прямо."],
"o11-12":["Велосипедистам, мопедам, візкам і вершникам повертати ліворуч і розвертатися можна лише на дорозі з однією смугою в кожен бік і без трамвайної колії посередині. Така тут тільки дорога 1.","Дорога 1 — одна смуга в кожен бік і без рейок: тільки тут повільним можна ліворуч."],
"o11-13":["Трактор із табличкою обмеження швидкості — повільний транспорт, тож тримається правого краю. На крайню ліву смугу йому можна лише перестроїтися перед поворотом ліворуч чи розворотом.","Повільний транспорт заїжджає ліворуч тільки для того, щоб повернути ліворуч або розвернутися."],
"o11-14":["Це одностороння дорога в місті, тож зупинятися можна і біля правого, і біля лівого краю. Тому смугу перед зупинкою правильно зайняли обидва водії.","Односторонка в місті — обидва краї твої: стати можна і праворуч, і ліворуч."],
"o11-15":["Виїжджати на зустрічний бік дозволено лише на дорозі з однією смугою в кожен бік без суцільної лінії, як на малюнку 1. На малюнках 2 і 3 дороги ширші або із суцільними — туди не можна.","Одна смуга туди, одна назад — можна на зустрічний бік. Ширша дорога — тримайся свого боку."],
"o11-16":["Ліворуч від жовтого — суцільна лінія, яку перетинати не можна. Тому виїжджати на зустрічну смугу заборонено, хай як повільно їде авто попереду.","Суцільна — як стіна: навіть за черепахою через неї не виїжджаєш."],
"o11-17":["На дорозі з розділювальною смугою крайню ліву смугу займають, щоб повернути ліворуч або розвернутися. Для зупинки біля розділювальної смуги виїжджати туди не можна.","Крайня ліва — для лівих маневрів: поворот ліворуч і розворот."],
"o11-18":["Авто, що з технічних причин не їде швидше 40 км/год, тримається правого краю. На крайню ліву смугу йому можна, щоб об’їхати перешкоду або перестроїтися перед поворотом ліворуч чи розворотом.","Повільний — праворуч. Ліворуч лише з потреби: об’їзд, поворот ліворуч, розворот."],
"o11-19":["Стати біля лівого краю, заїхавши на зустрічний бік, можна тільки в населеному пункті, на дорозі з однією смугою в кожен бік, без суцільної лінії, заборонних знаків і трамвайних колій.","Ліве узбіччя — лише в місті й на вузькій дорозі без суцільної та рейок."],
"o11-20":["Навіть у щільному потоці смугу змінювати можна, якщо треба об’їхати перешкоду, повернути, розвернутися чи зупинитися. Просто так, щоб їхати швидше, — ні.","У щільному потоці змінюй смугу лише з потреби: перешкода, поворот, розворот, зупинка."],
"o11-21":["На дорозі з кількома смугами в кожен бік тримайся ближче до правого краю. Лівіше можна, коли випереджаєш, об’їжджаєш або готуєшся повернути ліворуч чи розвернутися.","Звичайне місце — праворуч. Ліворуч — тільки з поважної причини."],
"o11-22":["Не триматися правого краю можна, коли об’їжджаєш перешкоду, випереджаєш когось або перестроюєшся перед поворотом ліворуч чи розворотом. Правильні всі ці випадки.","Законні причини піти ліворуч: об’їзд, випередження, поворот ліворуч чи розворот."],
"o11-23":["Заїжджати на тротуар можна лише тоді, коли треба щось привезти чи виконати роботу біля магазину або іншого закладу, а іншого під’їзду немає. І пішоходи завжди мають перевагу.","Тротуар — для людей. Авто там гість: лише для справи і коли іншої дороги немає."],
"o11-24":["Навіть для робіт чи доставки на тротуар можна заїхати, тільки якщо іншого під’їзду немає. А пішоходів при цьому пропускаєш завжди.","Тротуар — останній варіант: немає іншого під’їзду — тоді обережно й пропускаючи людей."],
"o11-25":["Велосипедисти, мопеди, візки й вершники їдуть в один ряд якомога правіше. Лівіше можна, щоб об’їхати перешкоду, а повернути ліворуч чи розвернутися — лише на дорозі з однією смугою в кожен бік без трамвайної колії посередині.","Повільним — правий край. Ліворуч повертають лише з вузької дороги без рейок."],
"o11-26":["Навіть коли дорога порожня, тримайся ближче до правого краю, якщо не треба маневрувати. Ліві смуги лишаються вільними для випередження й поворотів.","Порожня дорога — не привід їхати лівою смугою: правий край завжди за замовчуванням."],
"o11-27":["Коли немає розмітки й знаків про смуги, кількість смуг визначаєш сам: зважай на ширину дороги свого напрямку, розміри авто й безпечні проміжки між машинами.","Немає розмітки — рахуй смуги «на око»: ширина дороги, розмір авто й запас збоку."],
"o11-28":["Якщо дорога розмічена на смуги, їдь чітко у своїй смузі. Наїжджати на лінії можна лише тоді, коли перестроюєшся.","Смуга — твоя колія: з’їжджаєш з неї лише для перестроювання."],
"o11-29":["Якщо в одному напрямку щонайменше дві смуги, виїжджати на зустрічний бік заборонено. А переривчаста лінія посередині, навпаки, якраз дозволяє її перетинати.","Дві смуги в твій бік — зустрічна закрита. Переривчаста — не заборона."],
"o11-30":["Розділювальна смуга, відокремлена суцільними лініями, — не дорога. Заїжджати на неї, щоб когось випередити, заборонено.","Суцільні з обох боків — це острів, а не смуга для руху."],
"o11-31":["Повільний транспорт, що не їде швидше 40 км/год, тримається правого краю. Лівіше можна лише для об’їзду, обгону або перестроювання перед поворотом ліворуч чи розворотом.","Повільний — праворуч. Ліворуч лише для об’їзду, обгону, лівого повороту й розвороту."],
"o11-32":["На дорозі з розділювальною смугою легковик може їхати крайньою лівою, якщо праві смуги зайняті, а також щоб повернути ліворуч чи розвернутися. Для зупинки чи стоянки зліва туди не виїжджають.","Ліва смуга: коли праві зайняті або коли треба ліворуч чи на розворот."],
"o11-33":["Трамвайною колією свого напрямку можна їхати, якщо знаки й розмітка цього не забороняють, а також коли випереджаєш чи об’їжджаєш, а дорога для цього надто вузька.","Рейки свого напрямку — коли немає заборони і дорога затісна для об’їзду."],
"o11-34":["На колію свого напрямку не можна, якщо це заборонено знаками чи розміткою, якщо дорога й так достатньо широка для об’їзду або якщо ти заважатимеш трамваю. Правильні всі варіанти.","Рейки — ні, якщо: є заборона, вистачає місця без них, заважаєш трамваю."],
"o11-35":["На перехресті на колію свого напрямку можна виїжджати в тих самих випадках, що й поза ним, якщо знаки не визначають кількість смуг і напрямки руху по них.","Перехрестя — ті самі правила для рейок, якщо знаки не розписали смуги."],
"o11-36":["Крайню ліву смугу займають для повороту ліворуч чи розвороту. А ще — якщо праві смуги зайняті або щоб зупинитися біля лівого краю односторонньої дороги в населеному пункті, де це дозволено.","Ліва смуга: поворот ліворуч, розворот, зайняті праві або зупинка зліва на односторонці в місті."],
"o11-37":["На трамвайну колію зустрічного напрямку виїжджати заборонено завжди — навіть щоб щось об’їхати. Назустріч може йти трамвай, а йому нікуди звернути.","Зустрічні рейки — шлях до лобового зіткнення з трамваєм. Ніколи туди не виїжджай."],
"o11-38":["Якщо в одному напрямку дві смуги чи більше, виїжджати на зустрічний бік заборонено. На такій дорозі для маневрів вистачає своїх смуг.","Дві смуги в твій бік — тримайся своєї половини дороги."],
"o11-39":["Кількість смуг передусім визначай за розміткою або за знаками «Напрямок руху по смугах» і «Напрямок руху по смузі». Вони головні, а «на око» — лише коли їх немає.","Смуги рахуй за лініями й знаками, а не за відчуттями."],
"o12-1":["Постійні обмеження швидкості знаками ставлять на небезпечних ділянках, біля нерегульованих пішохідних переходів, а також біля дитсадків, шкіл і дитячих таборів. Правильні обидва варіанти.","Де небезпечно або де діти — там знак обмеження швидкості."],
"o12-2":["Новачок зі стажем менш ніж два роки не може їхати швидше 70 км/год, навіть там, де іншим дозволено більше. Синя табличка села означає, що міська межа тут не діє, тож для новачка — 70.","Новачок — «сімдесятник»: до двох років стажу максимум 70."],
"o12-3":["На автомагістралі легковикам дозволено до 130 км/год — це найшвидша дорога. На новачків зі стажем до 2 років це не поширюється.","Автомагістраль — максимум 130: найвища цифра для найкращої дороги."],
"o12-4":["Синій знак із білим авто означає «Дорога для автомобілів». На ній легковикам дозволено до 110 км/год — менше, ніж на автомагістралі, але більше, ніж на звичайній трасі.","Дорога для автомобілів — 110: на сходинку нижче за автомагістраль."],
"o12-5":["Якщо зустрічні потоки розділені смугою, як на малюнку, легковик може їхати до 110 км/год. Розділювальна смуга прибирає ризик лобового зіткнення.","Є розділювальна смуга — можна 110."],
"o12-6":["За межами населеного пункту на звичайній дорозі без розділювальної смуги легковикам дозволено до 90 км/год.","Звичайна траса за містом — 90."],
"o12-7":["Синя табличка з назвою села означає, що ця дорога не підпадає під міські правила, тож прямо можна їхати до 90 км/год. А повернувши праворуч до будинків, ти вже в селі — там до 50.","Синя табличка — село збоку: прямо 90, а до хат — 50."],
"o12-8":["За межами населеного пункту на звичайній дорозі з однією смугою в кожен бік легковик може їхати до 90 км/год.","Поза містом, звичайна дорога — стрілка не далі 90."],
"o12-9":["Біле авто тягне синє на тросі. Під час буксирування не можна їхати швидше 50 км/год навіть за містом: трос і авто позаду роблять гальмування й повороти набагато складнішими.","Буксир — як прогулянка на повідку: не швидше 50."],
"o12-10":["На малюнку одне авто буксирує інше. Буксирувати швидше 50 км/год не можна навіть на автомагістралі, де іншим дозволено набагато більше.","Хоч автомагістраль, хоч сільська дорога — з буксиром не більше 50."],
"o12-11":["На червоному авто ззаду табличка «70» — знак обмеження швидкості для самого авто. Тож хоч яка дорога, швидше 70 км/год йому їхати не можна.","Що написано на табличці ззаду — те й стеля: 70."],
"o12-12":["Тимчасові обмеження швидкості (знаки на жовтому тлі) ставлять там, де ремонтують дорогу, проводять масові чи спеціальні заходи, або через негоду. Патрулювання поліції — не причина.","Жовтий знак швидкості — тимчасовий: ремонт, захід або негода."],
"o12-13":["Це житлова зона, а в ній і авто, і мотоцикл можуть їхати не швидше 20 км/год. Тут ходять люди й граються діти, тож швидше не можна нікому.","Житлова зона — для всіх 20: це двір, а не траса."],
"o12-14":["У житловій і пішохідній зонах можна їхати не швидше 20 км/год. Тут люди ходять просто дорогою, а діти граються, тож треба вміти зупинитися миттєво.","Двір і пішохідна зона — 20, швидкість неспішного велосипеда."],
"o12-15":["Уночі та в погану видимість їдь так, щоб устигнути зупинитися в межах того, що бачиш попереду. Не бачиш далі — їдь повільніше.","Зупинитися маєш раніше, ніж закінчиться світло фар."],
"o12-16":["Побачивши перешкоду, зменш швидкість аж до зупинки або, переконавшись, що нікому не заважаєш, об’їдь її. Якоїсь «обов’язкової» цифри зниження швидкості немає.","Перешкода попереду: гальмуй або безпечно об’їжджай — третього не дано."],
"o12-17":["Білий знак із назвою міста означає початок населеного пункту. У місті максимальна швидкість — 50 км/год, якщо знаки не дозволяють інакше.","Назва міста на білому — значить, ти в місті: 50."],
"o12-18":["Після білого знака з назвою населеного пункту діють міські правила, тож швидше 50 км/год їхати не можна.","Біла табличка з назвою — і стрілка не вище 50."],
"o12-19":["Навіть широка дорога з розділювальною смугою в місті — все одно міська дорога. Тут дозволено не більше 50 км/год, якщо знаки не кажуть іншого.","Місто є місто: хоч яка широка дорога — 50."],
"o12-20":["Знак показує, що ти в’їжджаєш у житлову зону. Тут дозволено не більше 20 км/год, бо люди й діти можуть бути просто на дорозі.","Будинок і діти з м’ячем на знаку — тримай 20."],
"o12-21":["Обираючи швидкість, завжди зважай на вантаж: навіть добре закріплений, він змінює вагу авто, гальмування й поведінку в поворотах.","Вантаж — завжди частина розрахунку швидкості."],
"o12-22":["Водія не притягнуть до відповідальності за перевищення, якщо знак обмеження поставили з порушенням правил чи стандартів або забули зняти, коли причина вже зникла. Правильні всі варіанти.","Неправильний чи забутий знак обмеження — не підстава для покарання."],
"o12-23":["Взимку завжди дивися, яка дорога: лід, сніг чи сльота. Зимові шини допомагають, але не роблять слизьку дорогу сухою.","Зимові шини — не чарівні: на льоду однаково повільніше."],
"o12-24":["Різко гальмувати не можна, бо водій позаду може не встигнути зупинитися. Виняток — коли інакше не уникнути аварії.","Різке гальмо — лише щоб урятуватися від аварії."],
"o12-25":["Без потреби повзти дуже повільно не можна, якщо цим заважаєш іншим авто. Надто повільний водій теж створює небезпеку.","Черепаха на дорозі — теж перешкода."],
"o12-26":["Обираючи безпечну швидкість, зважай на все: що відбувається на дорозі, який у тебе вантаж і в якому стані авто.","Дорога, вантаж, авто — три кити безпечної швидкості."],
"o12-27":["Під час буксирування перевищувати максимальну дозволену швидкість заборонено, хай який довгий трос. Довжина зчеплення швидкості не додає.","Довгий трос не додає дозволеної швидкості."],
"o12-28":["У житловій і пішохідній зонах ніхто не може їхати швидше, ніж там дозволено, — ні мешканці, ні працівники, ні ті, хто обслуговує магазини.","Обмеження у дворі — для всіх, навіть для тих, хто там живе."],
"o12-29":["У місті дозволену швидкість можуть підняти, якщо дорогу облаштували для швидшого руху і поліція погодила це з власником дороги, а також поставивши відповідні знаки. Правильні обидва варіанти.","Швидше в місті — лише за спільним рішенням поліції й власника дороги та зі знаками."],
"o12-30":["Для водія підтвердження, що можна їхати швидше, — це відповідний дорожній знак. Без такого знака діють звичайні обмеження.","Хочеш їхати швидше — шукай знак. Немає знака — звичайна межа."],
"o12-31":["Уночі чи в тумані правильна та швидкість, за якої ти встигаєш зупинитися в межах видимої ділянки дороги. Бачиш недалеко — їдеш повільно.","Не можеш зупинитися там, куди сягає погляд, — ти їдеш надто швидко."],
"o12-32":["У темряві чи тумані немає правила «мінус 10 км/год». Швидкість має бути такою, щоб устигнути зупинитися в межах видимої ділянки дороги.","Світло фар — твій гальмівний ліміт: зупинка має вміститися в нього."],
"o12-33":["Під час буксирування більше 50 км/год не можна: зчеплені авто гальмують і повертають значно гірше, тож поспіх тут небезпечний.","Тягнеш авто — забудь про поспіх: максимум 50."],
"o12-34":["Помітивши небезпеку чи перешкоду, зменшуй швидкість аж до зупинки або об’їжджай так, щоб нікому не заважати. Їхати далі, нічого не змінюючи, не можна.","Бачиш небезпеку — гальмуй або безпечно об’їжджай, а не мчи далі."],
"o12-35":["Водій зі стажем до двох років за межами населених пунктів не може їхати швидше 70 км/год на жодній дорозі — навіть на автомагістралі.","Перші два роки за кермом — максимум 70 за містом."],
"o12-36":["На дворових територіях можна їхати не швидше 20 км/год. Там граються діти, гуляють люди й раптово виходять з-за припаркованих авто.","Двір — 20: тут діти важливіші за поспіх."],
"o12-37":["Безпечна швидкість — це не цифра зі знака й не можливості авто, а та, за якої ти впевнено керуєш і контролюєш машину саме в цих умовах.","Безпечна швидкість — та, на якій авто слухається тебе, а не ти його."],
"o12-38":["Ні: обмеження швидкості однакові для всіх, хоч скільки в тебе стажу. Досвід понад 5 років не дає права їхати швидше.","Досвід не скасовує знаків: стаж — не перепустка для швидкості."],
"o12-39":["Ні, у житловій зоні межа нижча за 30 км/год. Тут люди ходять просто дорогою, а діти граються, тож їхати треба зовсім повільно.","Житлова зона — навіть не «тридцятка», а ще повільніше: тут гуляють діти."],
"o12-40":["Ні: знак показує лише верхню межу. Безпечна швидкість залежить від погоди, дороги, видимості й стану авто, тож часто вона нижча за дозволену.","Знак — це стеля, а не мета. Безпечно — часто нижче."],
"o12-41":["Знак «70» обмежує максимальну швидкість, а не вимагає розганятися. Їдучи 68 км/год, просто продовжуй так само або повільніше, не перевищуючи 70.","Обмеження — це стеля, а не підлога: з 68 до 70 підтягуватися не треба."],
"o13-1":["Безпечна дистанція — відстань до авто попереду у твоїй смузі, за якої, якщо воно раптом загальмує, ти встигнеш зупинитися без жодних маневрів. Фіксованої цифри тут немає.","Дистанція правильна, якщо можеш зупинитися, нікуди не звертаючи."],
"o13-2":["Перешкода — вибоїна з камінням — на смузі червоного авто. Хто має перешкоду на своєму боці, той і поступається, тож перевага в синього.","Чия перешкода — того й черга чекати."],
"o13-3":["Знаки попереджають про крутий підйом і спуск. На такій ділянці під час роз’їзду поступається той, хто їде на спуск, — тут це білий, навіть якщо перешкода на боці синього.","На крутій гірці поступається той, хто їде вниз: тому, хто вгору, важче рушити знову."],
"o13-4":["Огороджена перешкода — на смузі синього авто, тож саме синій має пропустити червоного. Рушати, не чекаючи, не можна.","Перешкода на твоєму боці — ти й чекаєш."],
"o13-5":["Під час зустрічного роз’їзду поступається той водій, на смузі якого перешкода. Тут це синій: він чекає, поки червоний проїде.","Чия смуга заблокована — той і пропускає."],
"o13-6":["Повільні трактори за містом мають триматися на такій дистанції, щоб авто, яке їх обганяє, могло спокійно повернутися у свою смугу між ними.","Між повільними — «кишеня» для того, хто обганяє."],
"o13-7":["Безпечний інтервал — відстань збоку між авто або між авто й іншими об’єктами, за якої ніхто ні в кого не зачепиться. Це стосується всіх сусідів збоку, а не лише зустрічних чи попутних.","Інтервал — це простір збоку, якого вистачає, щоб не зачепитися."],
"o13-8":["На крутому підйомі чи спуску, коли важко роз’їхатися, поступається той, хто їде вниз. Тому, хто їде вгору, важче зупинитися й знову рушити.","На гірці: вниз — поступайся, вгору — їдь."],
"o13-9":["Безпечний інтервал збоку потрібен завжди: коли обганяєш, випереджаєш, об’їжджаєш перешкоду і коли роз’їжджаєшся із зустрічним авто.","Будь-який маневр поруч з іншим — тримай місце збоку."],
"o13-10":["За містом повільна машина (до 40 км/год) має тримати від передньої такий проміжок, щоб той, хто її обганяє, міг спокійно вклинитися між вами й повернутися на свою смугу.","Їдеш повільно за містом — залиш «кишеню» для того, хто тебе обганяє."],
"o13-11":["Безпечна дистанція й інтервал залежать від усього одразу: від швидкості, ситуації на дорозі, вантажу й технічного стану твоєї машини. Тому правильно — всі варіанти разом.","Швидкість, дорога, вантаж, машина — враховуй усе, нічого не пропускай."],
"o13-12":["На крутому схилі поступається той, хто їде вниз, навіть якщо перешкода на твоїй смузі. Тож ти, рухаючись угору, проїжджаєш першим: зупинитися й рушити на підйомі значно важче.","Угору — їдеш, униз — чекаєш: на крутому схилі поступається той, хто спускається."],
"o13-13":["Там, де розминутися важко, поступається той, у кого на смузі перешкода. Хто під’їхав першим — тут не має значення.","Чия перешкода — того й черга чекати."],
"o14-1":["На першому малюнку червоне авто об’їжджає темно-синє через смугу зустрічного руху — це обгін. На другому дорога розділена, червоне лишається на своєму боці, тож це лише випередження.","Є виїзд на зустрічку — є обгін. Немає зустрічки — просто випередження."],
"o14-2":["Перед залізничним переїздом обгін треба повністю закінчити заздалегідь — не ближче ніж за 100 м до рейок. Завершити його просто «до переїзду» чи за 50 м — уже порушення.","Рейки попереду — обгін закінчено ще за 100 м."],
"o14-3":["Червоне авто вже біля залізничного переїзду, тут обганяти заборонено, хоч би як повільно їхала вантажівка. Обганяти можна, коли переїдеш рейки.","Спершу рейки, потім обгін."],
"o14-4":["Ці знаки лише попереджають, що попереду переїзд. Обганяти ще можна, але так, щоб повністю повернутися на свою смугу не ближче ніж за 100 м до рейок.","Бачиш знак переїзду — встигни закінчити обгін за 100 м до рейок."],
"o14-5":["Обидві машини вже проїхали залізничний переїзд, рейки позаду. Заборона діє перед переїздом і на ньому, тож синє авто може обганяти біле.","Рейки позаду — і заборона позаду."],
"o14-6":["У населеному пункті перед пішохідним переходом є зона, де обганяти не можна, і червоне авто вже в ній. Швидкість передньої машини тут нічого не змінює.","Видно «зебру» попереду — обгін відкладай."],
"o14-7":["За містом перед пішохідним переходом теж є зона, де обганяти не можна, і вона довша, ніж у місті. Червоне авто вже в ній, тож обгін заборонено, хоч би як повільно їхала передня машина.","За містом швидкості більші — тому й зона без обгону перед «зеброю» довша."],
"o14-8":["Синє авто наближається до вершини крутого підйому: що за нею — не видно, назустріч може вискочити машина. Тут обганяти заборонено, і аварійка білого авто цього не змінила б.","Не бачиш, що за горбом, — не виїжджай на зустрічну."],
"o14-9":["Ти на мосту через річку, а на мостах обганяти заборонено завжди — навіть якщо зустрічних немає і передній водій нікуди не перестроюється.","На мосту — без обгону: тікати вбік нікуди."],
"o14-10":["Попереду знак небезпечних поворотів, дорога в’ється між деревами, і зустрічних не видно. На таких ділянках обганяти заборонено, хоч би як повільно їхала вантажівка.","Поворот закриває огляд — і обгін закритий."],
"o14-11":["Біле авто вже ввімкнуло лівий поворотник — воно саме збирається обганяти трактор. Обганяти машину, яка показала, що виїжджає ліворуч, заборонено.","Передній мигає ліворуч — чекай своєї черги."],
"o14-12":["Червоне авто попереду ввімкнуло лівий поворотник, щоб об’їхати сіре з аварійкою. Поки передній показує, що виїжджає ліворуч, зеленому обганяти його не можна.","Хто першим увімкнув лівий поворотник — той і виїжджає першим."],
"o14-13":["Попереду колона, яку супроводжують поліцейські авто з увімкненими маячками. Таку колону обганяти заборонено — біле авто має їхати за нею.","Маячки спереду й ззаду — колону не обганяй."],
"o14-14":["Ти в тунелі, а тут обганяти заборонено завжди: тісно, темно й нікуди ухилитися. Ні швидкість вантажівки, ні вільна зустрічна смуга цього не змінюють.","Тунель — як труба: у трубі не обганяють."],
"o14-15":["Ліворуч від жовтого авто суцільна лінія, за нею зустрічний рух. Щоб обігнати червоне, довелося б її перетнути, а це заборонено.","Суцільну не перетинаєш — отже, й обгону немає."],
"o14-16":["Ліворуч від смуги синього авто — суцільна лінія. Щоб обігнати сіре, довелося б її перетнути, а це заборонено, хоч би як повільно воно їхало.","Суцільна лінія — як стіна: через неї не обганяють."],
"o14-17":["Оранжевий маячок має великий або повільний транспорт, як ця вантажівка з екскаватором. Він лише попереджає про небезпеку й не забороняє обгін, тож жовте авто може обганяти, якщо це безпечно.","Оранжевий маячок — «обережно», а не «стоп»: обганяти можна."],
"o14-18":["Зелене авто обігнало синє ще далеко від рейок і повернулося на свою смугу за 100 м до переїзду. Обгін перед переїздом не заборонений зовсім — головне закінчити його вчасно.","Перед переїздом обганяти можна — якщо закінчуєш не ближче ніж за 100 м."],
"o14-19":["Жовте авто закінчує обгін уже зовсім близько до залізничного переїзду, а там обганяти заборонено. Швидкість синього авто тут нічого не змінює.","Біля рейок обгону немає — хоч повільно попереду їдуть, хоч швидко."],
"o14-20":["Мопед уже на перехресті, а на перехрестях обганяти заборонено — знак головної дороги тут не допомагає. Почекай, поки перехрестя залишиться позаду.","Перехрестя — не місце для обгону."],
"o14-21":["Перед обгоном переконайся, що встигнеш повернутися на свою смугу, не підрізаючи машину, яку обганяєш. Рівність дороги тут не головне.","Виїжджаючи на обгін, думай, як повернешся: без підрізання."],
"o14-22":["Назустріч уже їде бірюзове авто. Почати обгін зараз означає вискочити йому в лоб, тож чорному треба пропустити зустрічного й лише потім обганяти.","Зустрічна смуга зайнята — обгін чекає."],
"o14-23":["Сіре авто вже ввімкнуло лівий поворотник і починає обгін. Зеленому треба дочекатися, поки сіре закінчить, — звуковий сигнал права на обгін не дає.","Обганяють по черзі: спершу той, хто попереду."],
"o14-24":["Мотоцикліст уже на перехресті, а на перехрестях обганяти заборонено, навіть коли твоя дорога головна. Обгін можна почати, коли перехрестя лишиться позаду.","На перехресті — без обгонів, хоч як повільно їде мотоцикліст."],
"o14-25":["Біле авто ззаду вже почало обгін. Чорному треба спершу пропустити його, не розганяючись, і тільки потім самому обганяти жовте. Тож правильні обидві дії.","Хто вже виїхав на обгін — той перший. Не газуй, пропусти, потім твоя черга."],
"o14-26":["Перед обгоном перевір, чи не ввімкнуло сіре авто лівий поворотник. Якщо ні — можна обганяти. Сигналити й кидатися в обгін негайно не потрібно.","Перед обгоном — погляд на лівий поворотник переднього."],
"o14-27":["Зелене авто вже ввімкнуло лівий поворотник і йде на обгін. Сірому не можна розганятися й вискакувати перед ним — треба дати себе обігнати, а потім обганяти самому.","Тебе вже обганяють — спершу пропусти, потім обганяй сам."],
"o14-28":["Трактор уже біля перехрестя, а ліворуч суцільна лінія. На перехресті обганяти заборонено, хоч би як повільно їхав трактор.","Перехрестя плюс суцільна — подвійне «ні» обгону."],
"o14-29":["Фіолетове авто стоїть ліворуч і повертає ліворуч, а праворуч від нього вільно. Синьому, що їде прямо, не треба чекати — можна обережно об’їхати його праворуч.","Передній повертає ліворуч — проїжджай праворуч від нього."],
"o14-30":["Знак попереджає, що до перехрестя ще досить далеко. Тому білому авто обганяти можна, якщо обгін повністю завершиться ще до перехрестя.","Перехрестя попереду — встигни закінчити обгін до нього."],
"o14-31":["Знак попереджає про перехрестя рівнозначних доріг, і синє авто вже під’їжджає до нього. На перехрестях обганяти заборонено, хоч би як повільно їхала передня машина.","Хрестик на знаку — обгін перекреслено."],
"o14-32":["Якщо машина попереду сама вже об’їжджає перешкоду чи обганяє когось, обганяти її заборонено — інакше на зустрічній опиняться дві машини поряд.","Хто вже на обгоні — того не обганяють. Один обгін за раз."],
"o14-33":["Якщо в одному напрямку дві смуги або більше, виїжджати на зустрічну для обгону заборонено. Місця й так вистачає, щоб випереджати у своїх смугах.","Дві смуги в один бік — їдь своїми, на зустрічну ні ногою."],
"o14-34":["Обгін — це коли випереджаєш одну чи кілька машин і для цього виїжджаєш на смугу зустрічного руху. Просто швидша їзда лівою смугою — це не обгін.","Обгін = випередження + виїзд на зустрічку."],
"o14-35":["Зелений проблисковий маячок означає, що це авто когось супроводжує. Обганяти і його, і машини, які воно веде, заборонено.","Зелений маячок тут не «зелене світло»: колону з ним не обганяй."],
"o14-36":["Коли тебе обганяють, не можна розганятися й заважати обгону — так ти затягуєш небезпечний маневр. Повертати праворуч чи зупинятися за правилами можна.","Тебе обганяють — не газуй, дай спокійно повернутися на смугу."],
"o14-37":["На залізничному переїзді обганяти заборонено завжди — і на регульованому, і на нерегульованому. Опинитися на рейках поряд з іншою машиною надто небезпечно.","Рейки — не бігова доріжка: на переїзді не обганяють."],
"o14-38":["На перехресті обганяти заборонено завжди: хоч воно регульоване, хоч ти на головній дорозі, хоч це за містом. Жодного винятку немає.","Перехрестя = нуль обгонів, без жодних «якщо»."],
"o14-39":["Обгін заборонено тільки перед пішохідним переходом: ближче ніж за 50 м у населеному пункті й за 100 м — поза ним. Після переходу такої заборони немає.","У місті — 50, за містом — 100, і рахують лише перед «зеброю»."],
"o14-40":["Обгін заборонено ближче ніж за 50 м перед пішохідним переходом у населеному пункті й за 100 м — поза ним. А дорога з однією смугою в кожен бік — якраз звичайне місце для обгону.","Перед «зеброю»: місто — 50, траса — 100. Одна смуга в кожен бік — не заборона."],
"o14-41":["Перед обгоном головне — бути певним, що зможеш повернутися на свою смугу, не підрізаючи того, кого обганяєш. Чи зрозумів тебе інший водій, ти перевірити не можеш.","Обгін починай лише тоді, коли знаєш, куди повернешся."],
"o14-42":["На перехресті обганяти заборонено будь-кого — навіть мопед, віз чи машину, що ледве їде, повільніше ніж 30 км/год.","На перехресті не обганяють навіть равлика."],
"o14-43":["Обгін заборонено на мостах, естакадах, шляхопроводах і в тунелях. А от проїзд під шляхопроводом чи естакадою в цей перелік не входить.","Міст, естакада, тунель — обгону немає; «під естакадою» в цьому списку зайве."],
"o14-44":["Коли погано видно — туман, злива, снігопад, — ти не помітиш зустрічну машину вчасно. Тому в умовах недостатньої видимості обганяти заборонено.","Не бачиш далеко — не виїжджай на зустрічну."],
"o14-45":["Туман сам по собі обгону не забороняє — важить, наскільки далеко видно. Якщо видимість понад 300 м, вона ще не вважається недостатньою, тож обганяти можна.","Туман — не заборона, а лінійка: видно понад 300 м — обганяти можна."],
"o14-46":["Обгін — це коли випереджаєш одну чи кілька машин і для цього виїжджаєш на зустрічну смугу. Перестроїтися ліворуч чи праворуч у своєму напрямку — це просто випередження.","Обгін = випередження через зустрічку."],
"o14-47":["Дорога різко завертає за скелю, і що за поворотом — не видно. На небезпечних поворотах з поганим оглядом обганяти заборонено.","За скелею не видно зустрічних — на зустрічну не виїжджаєш."],
"o14-48":["Ти на мосту, а на мостах обганяти заборонено: ухилитися нікуди, з боків лише огорожа.","Міст — вузька стежка над водою: без обгонів."],
"o14-49":["Дорога петляє, попереду поворот, а назустріч уже їде машина. На поворотах з обмеженим оглядом обганяти заборонено, тож жовте авто має їхати за червоним.","Поворот ховає зустрічних — не виїжджай на зустрічку."],
"o14-50":["Аварійка — для аварії чи вимушеної зупинки, а не для обгону. Під час обгону, і вночі теж, вмикаєш лівий поворотник.","Аварійка — для аварії, обгін — з поворотником."],
"o14-51":["Попереду в’їзд у тунель. У тунелі обганяти заборонено завжди — і вдень, і вночі, бо там тісно й нікуди ухилитися.","Тунель — як труба: в трубі не обганяють, хоч день, хоч ніч."],
"o14-52":["Ліворуч суцільна лінія, за нею зустрічні смуги, а у твоєму напрямку і так дві смуги. Виїжджати на зустрічну, щоб обігнати машину попереду, тут заборонено.","Суцільна ліворуч — стіна: за неї на обгін не виїжджають."],
"o14-53":["На перехресті обганяти заборонено завжди — навіть на зелений сигнал і навіть коли зустрічна смуга порожня.","Перехрестя — зона без обгонів, хоч зелене, хоч порожньо."],
"o14-54":["У тунелі обганяти заборонено в будь-якому разі — навіть якщо зустрічна вільна й здається, що все безпечно.","Тунель — труба: в трубі не обганяють. Жодних «якщо»."],
"o14-55":["Ти в тунелі, а тут обганяти заборонено завжди. Ні вільна зустрічна смуга, ні повільна передня машина цього не змінюють.","У тунелі — тільки слідом, не поруч."],
"o14-56":["За містом перед обгоном можна коротко посигналити, щоб водій попереду тебе помітив і не почав раптом виїжджати ліворуч.","За містом гудок перед обгоном — це «я тут», а не грубість."],
"o15-1":["Зупинятися не можна на шляхопроводі й під ним, а місце Б якраз під мостом. А і В — на звичайній дорозі, оддалік шляхопроводу, тож там зупинка дозволена.","Ні на мосту, ні під мостом — тільки на відкритій дорозі."],
"o15-2":["Між машиною й суцільною лінією лишилося замало місця: іншим довелося б перетинати суцільну, щоб її об’їхати. Тому зупинятися тут не можна — ні надовго, ні для пасажирів.","Щоб тебе об’їхати, треба перетнути суцільну? Значить, стояти тут не можна."],
"o15-3":["А стоїть одразу перед «зеброю», Б — ще в зоні біля перехрестя, де зупинятися не можна. Лише місце В достатньо далеко і від переходу, і від перехрестя.","Від «зебри» й перехрестя — подалі: зупиняйся там, де вони вже позаду."],
"o15-4":["Біля пішохідного переходу зупинятися не можна ні на ньому, ні близько перед чи після нього. Мотоцикл стоїть просто на «зебрі», а обидва авто — впритул до неї, тож порушують усі.","Біля «зебри» не стоять: ні на ній, ні впритул до неї."],
"o15-5":["На дорозі з одностороннім рухом можна зупинятися й ліворуч. А, В і Д стоять на безпечній відстані від переходу, а Б — надто близько після нього, Г — просто на «зебрі».","Одностороння — стоїш з обох боків, але подалі від «зебри»."],
"o15-6":["Біле авто стоїть на безпечній відстані від переходу. А зелене — надто близько перед «зеброю», синє — одразу за нею, мотоцикл — теж поряд із переходом. Вони й порушують.","Біля «зебри» — зона без зупинок з обох боків."],
"o15-7":["Дорога одностороння, тож зупинятися можна з обох боків, але не біля переходу. Жовте стоїть далеко від «зебри», а зелене, синє й біле — надто близько до неї, тому вони порушують.","Ліворуч чи праворуч — неважливо, важить відстань до «зебри»."],
"o15-8":["Біле авто стоїть впритул перед пішохідним переходом, червоне — одразу після нього. Біля «зебри» зупинятися не можна з обох боків, тож порушують обидва.","«Зебра» — не парковка: ні перед нею, ні після неї."],
"o15-9":["На мосту зупинятися заборонено, тож місце Б не годиться. А — на узбіччі ще до мосту, там зупинка дозволена.","Міст — для проїзду, а не для зупинки."],
"o15-10":["Жовте авто стоїть на узбіччі ще перед тунелем, а не в ньому. Тут зупинятися можна без обмежень, не лише для посадки пасажирів.","У тунелі — ні, перед тунелем на узбіччі — так."],
"o15-11":["Ти в тунелі, а в тунелі зупинятися заборонено — навіть щоб підібрати пасажира, хоч удень, хоч уночі.","Тунель — не зупинка: пасажир почекає на виході."],
"o15-12":["На мосту зупинятися заборонено зовсім — навіть на хвилинку, щоб узяти пасажира. Людині, що голосує посеред мосту, доведеться почекати.","Міст — не зупинка, навіть для пасажирів."],
"o15-13":["Біле авто їде шляхопроводом над іншою дорогою, а тут зупинятися заборонено зовсім — навіть на хвилинку, щоб узяти пасажира.","Шляхопровід — як міст: на ньому не зупиняються."],
"o15-14":["Чорне авто й автобус стоять на шляхопроводі, а сіре — під ним. Зупинятися заборонено і на шляхопроводі, і під ним, тож порушують усі.","Ні на мосту, ні під мостом — тут винні всі."],
"o15-15":["Біля зупинки громадського транспорту з обох боків є зона, де легковикам зупинятися не можна: туди потрапляють Б, В і Г. А і Д стоять за її межами.","Зупинка — для автобусів: не стій ні на ній, ні поряд із нею."],
"o15-16":["Зупинятися біля суцільної лінії можна, якщо між машиною й лінією лишається не менше 3 м — щоб інші могли проїхати, не перетинаючи суцільну.","Суцільна поруч — залиш 3 м, щоб інші проїхали."],
"o15-17":["Між машиною й суцільною лінією лишилося замало місця: інші не проїдуть, не перетнувши суцільну. Тому зупинятися тут заборонено.","Інші мусять перетнути суцільну, щоб тебе об’їхати? Тут не стоять."],
"o15-18":["Коли зупиняєшся, між твоєю машиною й протилежним краєм дороги має лишатися щонайменше 3 м — щоб інші могли спокійно проїхати.","Стоїш — залиш іншим 3 м для проїзду."],
"o15-19":["Конуси й бар’єри на дорогу ставлять лише з поважної причини: під час оформлення ДТП, дорожніх робіт або коли рух обмежують за законом. Усі три варіанти правильні.","Конус на дорозі — лише для ДТП, ремонту чи офіційного перекриття."],
"o15-20":["Біле авто стоїть надто близько до сміттєвих баків, і сміттєвоз не зможе до них нормально під’їхати. Тому стоянка тут заборонена.","Баки — для сміттєвоза, а не для твого авто: стань подалі."],
"o15-21":["Стоянка в такому проїзді сама по собі не заборонена. Заборона діє тоді, коли машина заблокує проїзд іншим авто або заважатиме людям проходити.","Ставиш авто — перевір: чи проїде машина і чи пройде людина."],
"o15-22":["Чорне авто стоїть на повороті за містом, де дорогу видно менш ніж на 100 м. Стоянка тут заборонена: інші водії помітять машину надто пізно, і денні ходові вогні не рятують.","Поворот без огляду — не місце для стоянки: тебе не побачать вчасно."],
"o15-23":["Біля залізничного переїзду стоянку заборонено з обох боків: Б і В стоять надто близько до рейок. А і Г — достатньо далеко, тож там стати можна.","Рейки поруч — не паркуйся: стань подалі перед переїздом або за ним."],
"o15-24":["Фіолетове й червоне авто стали впритул до залізничного переїзду, а там стоянку заборонено. Біле й синє стоять значно далі від рейок — вони все роблять правильно.","Біля рейок не паркуються — тільки на безпечній відстані."],
"o15-25":["Вимушена зупинка — коли їхати далі не можна з поважної причини: зламалося авто чи небезпечний вантаж, комусь стало зле або на дорозі з’явилася перешкода. Тому правильні всі варіанти.","Поломка, самопочуття, перешкода — усе це причини вимушеної зупинки."],
"o15-26":["Біля виїзду з двору зупинятися не можна ні просто на ньому, ні надто близько збоку, щоб не закривати огляд тим, хто виїжджає. Жовте стоїть на виїзді, синє — надто близько, а сіре — на безпечній відстані.","Виїзд із двору — як двері: не стій ні перед ними, ні впритул збоку."],
"o15-27":["Дві машини можуть стояти одна навпроти одної, якщо між ними лишається досить місця, щоб інші могли роз’їхатися або їх об’їхати.","Стоїте навпроти — лиши коридор для інших."],
"o15-28":["У зоні дорожніх робіт зупинятися не можна навіть на хвилинку для пасажирів: там працюють люди й техніка, а дорога й так звужена.","Ремонт на дорозі — не місце для висадки пасажирів."],
"o15-29":["Зупинятися заборонено ближче ніж за 10 м до позначеного місця дорожніх робіт — щоб не заважати ні робітникам, ні машинам, які його об’їжджають.","Бачиш знак ремонту — зупиняйся не ближче ніж за 10 м."],
"o15-30":["Червоне авто стало впритул перед пішохідним переходом, а біля «зебри» зупинятися заборонено: машина закриває пішоходів від інших водіїв.","Перед «зеброю» не стають — там мають бачити пішоходів."],
"o15-31":["Червоне авто стало просто на зупинці громадського транспорту, де місце для автобусів, — це порушення. Жовте стоїть на протилежному боці дороги, тож правил не порушує.","Зупинка з табличкою автобуса — не для твого авто."],
"o15-32":["Зелене авто стоїть біля суцільної лінії, і між ними замало місця: щоб його об’їхати, іншим довелося б перетнути суцільну. Тому зупинятися тут не можна.","Суцільна поруч і тісно — шукай інше місце."],
"o15-33":["Зелене авто стоїть на трамвайних коліях за трамваєм. Без потреби взяти чи висадити пасажира зупинятися тут заборонено — так ти заблокуєш трамвай.","Колія трамвая — його дорога, а не твоя стоянка."],
"o15-34":["Табличка під знаком показує спосіб стоянки, і він стосується лише легковиків і мотоциклів. Тож легковик і мотоцикл стоять правильно, а вантажівці тут не місце.","Табличка з легковиком — для легковиків і мотоциклів, не для вантажівок."],
"o15-35":["Червоне авто стало в другий ряд, поряд із припаркованими машинами, і пасажир виходить посеред дороги. Так висаджувати людей не можна — зупинятися треба біля краю дороги.","Другий ряд — не зупинка: пасажира висаджуй біля тротуару."],
"o15-36":["Табличка під знаком «Зупинку заборонено» показує, де закінчується зона заборони: А ще в ній, а Б — уже ні. Дорога одностороння, тож ліворуч, на В і Г, зупинятися теж можна.","Одностороння — стоїш з обох боків; заборону шукай на знаку з табличкою."],
"o15-37":["Обидва авто їдуть в один бік. Синє стало праворуч за своїм напрямком, на узбіччі, — так і треба. Червоне стало ліворуч, а за містом на дорозі з двостороннім рухом так не можна.","За містом зупиняйся праворуч, на узбіччі — як синє авто."],
"o15-38":["На другому малюнку знак показує дорогу з одностороннім рухом — там ставати ліворуч можна. На першому це лише половина дороги з розділювальною смугою, тож ліворуч ставати не можна.","Розділювальна смуга не робить дорогу односторонньою — ліворуч не ставай."],
"o15-39":["Ліворуч у населеному пункті можна ставати на дорозі з однією смугою в кожен бік, як на першому малюнку. На другому посередині суцільна, її не можна перетинати, а на третьому — трамвайні колії.","Переривчаста посередині — можна й ліворуч; суцільна чи трамвай — тільки праворуч."],
"o15-40":["Після цих знаків зелене авто в’їжджає в населений пункт, а синє — виїжджає з нього. Ставати ліворуч на такій дорозі можна лише в населеному пункті, тож це дозволено тільки зеленому.","Ліворуч — лише в межах населеного пункту: хто в’їжджає — може, хто виїжджає — ні."],
"o15-41":["Зупинятися треба якомога ближче до правого краю дороги — як у місці А. Місце Б далеко від краю: машина там заважатиме іншим, а пасажирам доведеться йти по дорозі.","Зупиняєшся — притискайся праворуч, до самого краю."],
"o15-42":["У населеному пункті на такій дорозі — по одній смузі в кожен бік — можна ставати і біля правого, і біля лівого краю. Тож обидва місця годяться.","Місто, по смузі в кожен бік — стати можна з будь-якого боку."],
"o15-43":["За містом зупинятися треба тільки на правому узбіччі — не на проїзній частині і не ліворуч: там великі швидкості, і це небезпечно.","За містом — праворуч і на узбіччя."],
"o15-44":["За містом, коли є придатне узбіччя, зупинятися треба на ньому, як червоне авто. Сіре стало на проїзній частині — це неправильно.","Є узбіччя — з’їжджай на нього, не стій на дорозі."],
"o15-45":["Біля краю дороги ставлять в один ряд. Лише велосипеди, мопеди й мотоцикли без коляски можна ставити у два ряди. Коричневий мотоцикл із коляскою став у другий ряд — це порушення.","Двоколісні — можна у два ряди, а з коляскою — тільки в один."],
"o15-46":["Узбіччя тут розбите, тож стати на ньому не вийде. Тоді зупиняйся на дорозі біля правого краю, якомога правіше, щоб не заважати іншим. Тротуар і лівий бік не підходять.","Узбіччя непридатне — притиснись праворуч на дорозі."],
"o15-47":["Зупинятися заборонено на самому залізничному переїзді, як у місці Б. Перед ним і за ним ненадовго зупинитися можна, тож А і В годяться: обмеження відстані від переїзду стосується стоянки.","На рейках — ні, біля рейок на хвилинку — так."],
"o15-48":["Синє авто стоїть перед переїздом, а не на рейках. Ненадовго зупинитися, щоб узяти людину, тут можна, а от довго стояти поряд із переїздом — ні.","Зупинка біля рейок — так, стоянка біля рейок — ні."],
"o15-49":["Ця стоянка облаштована за бордюром, на рівні тротуару біля магазину, а там можна ставити лише легковики й мотоцикли. Вантажівка й мікроавтобус стоять тут неправильно.","Стоянка на тротуарі — для легковиків і мотоциклів, габаритним туди не можна."],
"o15-50":["Ці таблички показують, як ставити машину на тротуарі, і стосуються лише легковиків і мотоциклів. Вантажівки, навіть легкі, сюди не ставлять.","На табличці намальовано легковик — отже, тут стоять легковики й мотоцикли."],
"o15-51":["За крайовою лінією є смуга узбіччя — зупинятися треба саме там, у місці А. Місце Б уже на проїзній частині, машина там заважала б руху.","Є узбіччя — став авто туди, а не на дорогу."],
"o15-52":["Біле авто стоїть на підйомі біля вершини, звідки дорогу видно менш ніж на 100 м. Ставити машину тут не можна, навіть якщо вона начебто нікому не заважає: її просто не побачать вчасно.","Ти не бачиш, що за горбом, — і з-за горба не бачать тебе: тут не стоять."],
"o15-53":["Поруч є придатне узбіччя, а фіолетове авто стоїть на проїзній частині. Коли узбіччя дозволяє, ставати треба саме на ньому, а не займати смугу руху.","Є узбіччя — з’їжджай на нього, а не стій на смузі."],
"o15-54":["Червоне авто заїхало правими колесами на тротуар, а без відповідного знака ставити машину на тротуар не можна. Біле стоїть біля правого краю дороги — це правильно.","Тротуар — для пішоходів: без знака колесами туди не заїжджай."],
"o15-55":["Відчиняти двері й виходити можна, якщо це безпечно й нікому не заважає. Вузька дорога сама по собі не заборона — важить, чи не створюєш ти небезпеки чи перешкоди.","Перш ніж відчинити двері, глянь у дзеркало: нікому не загрожує? нікому не заважає?"],
"o15-56":["Ставити машину на стоянку ближче ніж за 50 м до залізничного переїзду заборонено — біля рейок має бути добре видно і нічого не повинно заважати проїзду.","Від рейок відступи на 50 м — тоді й паркуйся."],
"o15-57":["Заборона стосується всього одразу: і відчиняти двері, і тримати їх відчиненими, і виходити, якщо це небезпечно чи заважає іншим. Слово «тільки» в інших варіантах — пастка.","Відчиняти, тримати відчиненими, виходити — усе під забороною, якщо це небезпечно."],
"o15-58":["Біля правого краю машину ставлять якомога правіше, щоб не заважати нікому — ні машинам, ні велосипедистам, ні пішоходам.","Ставиш авто — притисни його до правого краю."],
"o15-59":["Стоянку заборонено там, де тебе погано видно: на небезпечних поворотах і переломах дороги за містом, коли огляд менше 100 м, а також ближче ніж за 50 м до залізничного переїзду.","Не видно — не стій; рейки ближче ніж за 50 м — теж не стій."],
"o15-60":["Якщо узбіччя придатне для зупинки, ставати треба саме на ньому, а не біля краю проїзної частини — так машина не заважає руху.","Є нормальне узбіччя — з’їжджай на нього."],
"o15-61":["Стоянку заборонено, якщо машина заблокує проїзд іншим авто чи заважатиме пішоходам, а також на газонах. Тож правильні всі три варіанти.","Не блокуй, не заважай, не заїжджай на траву."],
"o15-62":["На тротуарі, де це дозволено, можна ставити лише легковики й мотоцикли — вантажівки й автобуси для нього надто великі й важкі.","Тротуар витримає легковик і мотоцикл — і тільки їх."],
"o15-63":["Стоянку заборонено ближче 5 м до сміттєвих контейнерів — щоб сміттєвоз міг до них під’їхати, а люди — спокійно підійти.","Від сміттєвих баків — щонайменше 5 м: це дорога для сміттєвоза."],
"o15-64":["Газон — не парковка: ставити на ньому машину заборонено, бо колеса нищать траву й землю.","Трава — для зелені, а не для шин."],
"o15-65":["За містом у темряві чи в тумані машину на узбіччі погано видно, тож стояти можна тільки на майданчиках для стоянки або взагалі за межами дороги.","Темно за містом — геть із дороги: на майданчик або за її межі."],
"o15-66":["Якщо машина вимушено стала там, де зупинятися не можна, і прибрати її не виходить, вмикаєш аварійку або ставиш знак аварійної зупинки, а коли правила вимагають — робиш і те, і те.","Стоїш там, де не можна, — аварійка або знак, а коли треба, то й обидва."],
"o15-67":["За містом у темряві чи при поганій видимості машину ставлять лише на майданчику для стоянки або за межами дороги. Узбіччя, навіть зі стоянковими ліхтарями, не годиться.","Ніч за містом — авто з дороги геть: на майданчик або за її межі."],
"o15-68":["Біля правого краю проїзної частини ставати можна, коли немає узбіччя чи спеціальних місць або коли стати там неможливо. Посадка пасажирів сама по собі такого права не дає.","Край дороги — запасний варіант: спершу узбіччя чи стоянка."],
"o15-69":["Залишаючи машину, подбай, щоб вона сама не покотилася і щоб ніхто не зміг у неї залізти чи її забрати. Цілісність вантажу до цього обов’язку не належить.","Ідеш від авто — щоб не поїхало саме і не поїхало з чужим."],
"o15-70":["Перед тим як відчинити двері, переконайся, що це безпечно й нікому не заважає. Зовсім порожня дорога не обов’язкова — головне, щоб двері нікого не зачепили.","Глянь у дзеркало: безпечно і нікому не заважає — тоді відчиняй."],
"o15-71":["Стоянка дозволена не ближче ніж за 50 м від залізничного переїзду. Саме ця межа записана в правилах.","Рейки — 50 м: ближче не паркуйся."],
"o15-72":["Залишаючи легковик на схилі біля краю дороги, поверни передні колеса так, щоб машина не могла сама покотитися. Противідкатні упори для легковика не обов’язкові.","Схил — крути кермо до бордюру: колесо стане упором."],
"o15-73":["Зупинка заборонена саме на залізничному переїзді. Перед ним і за ним ненадовго зупинитися можна — обмеження відстані стосується стоянки.","Зупинка — не на рейках; стоянка — не біля рейок."],
"o15-74":["Під кутом ставити можна там, де це не заважає іншим машинам. Біля тротуару ставлять передом до нього, а на підйомі — лише задом. Тож правильні обидві відповіді.","Під кутом: біля тротуару — носом, на підйомі — задом."],
"o15-75":["Біля пішохідного переходу зупинятися можна не ближче ніж за 10 м — і перед ним, і після нього. Так машина не закриває пішоходів від інших водіїв.","«Зебра» плюс 10 м з кожного боку — без зупинок."],
"o15-76":["Ставити машину під кутом до краю дороги можна, якщо це не заважає іншим машинам. Тротуар цього не забороняє — він лише впливає на те, яким боком ставити.","Під кутом — можна, якщо всі інші спокійно проїжджають."],
"o15-77":["У два ряди на проїзній частині можна ставити лише велосипеди, мопеди й мотоцикли без коляски — вони вузькі й займають мало місця. Решту — в один ряд.","Два ряди — тільки для вузьких двоколісних, без коляски."],
"o15-78":["Зупинку заборонено в усіх трьох випадках: коли до суцільної чи протилежного краю лишається менше 3 м, на перехрестях і поряд із ними, а також на пішохідних переходах і ближче 10 м до них.","Суцільна поруч, перехрестя, «зебра» — три місця, де не зупиняються."],
"o15-79":["Біля розділювальної смуги чи бульвару посеред дороги машина стоїть у крайній лівій смузі, де всі їдуть найшвидше, і заважає руху. Тому там заборонені і зупинка, і стоянка.","Розділювальна смуга — не узбіччя: біля неї не стають."],
"o15-80":["Ні на мосту, шляхопроводі чи естакаді, ні під ними зупинятися не можна: там тісно, погано видно, і машина, що стала, створює небезпеку й затор. Правильні всі три варіанти.","Міст — ні зверху, ні знизу: ні на мосту, ні під мостом не зупиняйся."],
"o15-81":["У населеному пункті легковик можна поставити й ліворуч: на дорозі з однією смугою в кожен бік без трамвайних колій і суцільної посередині, а також на дорозі з одностороннім рухом.","Ні рейок, ні суцільної, по смузі в кожен бік — або рух в один бік: ліворуч ставати можна."],
"o15-82":["Ліворуч у місті можна ставати на дорозі з одностороннім рухом і на дорозі з однією смугою в кожен бік, але лише якщо посередині немає трамвайних колій і суцільної лінії. Не на кожній такій дорозі.","Ліворуч можна, коли нема ні рейок, ні суцільної — або коли рух в один бік."],
"o15-83":["Не можна ставати там, де через твою машину інші не зможуть роз’їхатися із зустрічними, об’їхати тебе, або де ти закриваєш світлофор чи знаки. Усі три варіанти правильні.","Зупинка нікому не заважає: ні роз’їхатись, ні об’їхати, ні побачити знак."],
"o15-84":["Біля виїзду з двору чи іншої прилеглої території впритул ставати не можна: ти закриваєш огляд тим, хто виїжджає. Зупиняйся не ближче ніж за 10 м від такого виїзду.","Виїзд із двору — відступи 10 метрів, щоб тому, хто виїжджає, було видно дорогу."],
"o15-85":["Стоянка — це та сама зупинка, тільки довша. Якщо навіть ненадовго ставати тут не можна, то стояти довго — тим паче.","Де заборонено зупинитися, там стояти — й поготів."],
"o15-86":["На тротуарі ставити машину загалом заборонено. Винятків два: де це дозволяє знак із табличкою, і коли легковик чи мотоцикл стоїть на краю, лишаючи пішоходам щонайменше 2 м. Тому правильні обидва варіанти з винятками.","Тротуар — для людей. Машині туди можна лише за знаком або з краю, лишивши 2 метри."],
"o15-87":["На тротуар можна ставати лише легковикам і мотоциклам: або там, де це дозволяє знак із табличкою, або на самому краю, якщо пішоходам лишається щонайменше 2 м. Думка «я ж нікому не заважаю» — не підстава.","Тротуар: знак із табличкою або 2 метри для людей. Інакше — ні."],
"o15-88":["Якщо ставиш легковик чи мотоцикл на краю тротуару, пішоходам має лишитися прохід щонайменше 2 м — щоб люди могли спокійно розминутися чи провезти візочок.","Два метри для пішоходів — двоє людей розминуться."],
"o15-89":["Зупинятися не можна на мостах, шляхопроводах, естакадах і в тунелях: там тісно й немає куди з’їхати. А на набережній ставати можна, якщо немає заборонних знаків.","Міст і тунель — проїжджай без зупинок. Набережна — не заборона."],
"o15-90":["Чорне авто заїхало на тротуар і стоїть упритул до сміттєвих контейнерів: заважає і пішоходам, і вивезенню сміття. Знака, що дозволяв би тут паркуватися, немає — тож стоянка заборонена.","Біля сміттєвих баків — місце для баків, а не для твого авто."],
"o15-91":["Сіре авто зупинилося поруч із червоним, яке вже стоїть біля бордюру, тобто в другому ряду. Так ставати не можна: машина перекриває смугу й заважає іншим їхати.","Біля бордюру — один ряд. Другий ряд — заборонено, навіть на хвилинку."],
"o15-92":["Обидва авто стоять біля самого пішохідного переходу: жовте — впритул до зебри, біле — трохи далі, але теж надто близько. Машини ховають пішоходів від інших водіїв, тому порушили обидва.","Біля зебри не стають — машина ховає пішохода від інших водіїв."],
"o15-93":["Біле авто стоїть на залізничному переїзді, просто біля колій. Тут зупинятися не можна: поїзд не загальмує вчасно, а затриматися на коліях смертельно небезпечно.","Біля рейок не стоять — поїзд не об’їде і не загальмує."],
"o15-94":["Знак пішохідного переходу показує, що зебра просто тут. Зупинятися на переході чи надто близько до нього не можна: машина закриває пішоходів від інших водіїв.","Бачиш знак переходу — шукай місце для зупинки далі від нього."],
"o15-95":["Чорне авто стало впритул до пішохідного переходу — знак видно просто над ним. Так зупинятися не можна: машина закриває від інших водіїв пішоходів, які виходять на зебру.","Зебра — зона без зупинок: і на ній, і поряд."],
"o15-96":["Чорне авто стоїть просто на газоні. На траві паркуватися заборонено — байдуже, скільки місця лишається пішоходам і чи є поруч вільні місця.","Газон — для трави, а не для коліс."],
"o15-97":["Чорне авто зупинилося поруч із білим, яке вже стоїть біля бордюру, тобто в другому ряду. Так ставати не можна: машина перекриває смугу й заважає руху.","Біля бордюру вже хтось стоїть — шукай інше місце, а не другий ряд."],
"o16_1-1":["Біле авто стоїть першим у лівій смузі, а за ним — зелене з лівим поворотником. Горить зелена стрілка ліворуч: якщо чекати сигналу прямо, заблокуєш тих, хто позаду. Тож вмикай лівий поворотник і їдь за стрілкою.","Стрілка горить, а позаду чекають на поворот — не затримуй смугу, їдь за стрілкою."],
"o16_1-2":["Синє авто повертає праворуч і перетинає трамвайні колії. Трамвай тут має перевагу, тож пропускай обидва: і той, що їде назустріч, і той, що їде в тому ж напрямку, що й ти.","Повертаєш через рейки — пропусти всі трамваї, скільки б їх не було."],
"o16_1-3":["Обидва їдуть на зелений. На регульованому перехресті трамвай має перевагу перед машинами, що їдуть назустріч чи в тому ж напрямку, куди б він не повертав. Тож першим проїжджає трамвай.","Зелений для обох — трамвай перший: рейки не об’їдеш."],
"o16_1-4":["Біле авто вже на перехресті, заїхало на дозвільний сигнал і повертає ліворуч. Перед світлофором на виїзді немає стоп-лінії, тож зупинятися не треба — завершуй поворот і звільняй перехрестя.","Заїхати на зелений — означає й виїхати: посеред перехрестя не стоять."],
"o16_1-5":["Перед світлофором на шляху білого авто є стоп-лінія і знаки STOP, а світлофор червоний. Якщо на шляху є стоп-лінія, зупиняйся перед нею й чекай зеленого, навіть якщо на перехрестя заїжджаєш на зелений.","Бачиш стоп-лінію перед червоним — стій, навіть посеред перехрестя."],
"o16_1-6":["Зелене авто повертає ліворуч, і на його шляху є стоп-лінія та знаки STOP біля світлофора з червоним сигналом. Тож треба зупинитися перед стоп-лінією й рушати далі лише на зелений.","Є стоп-лінія — є зупинка. Немає — завершуй маневр."],
"o16_1-7":["Трамвай їде прямо за зеленою стрілкою в додатковій секції, коли основний сигнал для нього червоний. Хто рушає за такою стрілкою, пропускає всіх, хто їде з інших напрямків на свій зелений, — тож поступається трамвай.","Їдеш за стрілкою додаткової секції — пропусти всіх, у кого повний зелений."],
"o16_1-8":["Червоне авто їде на основний зелений, а синє — за зеленою стрілкою в додатковій секції при червоному. Хто рухається за стрілкою, пропускає інших, тож першим проїжджає червоне.","Повний зелений сильніший за стрілку: хто за стрілкою — той пропускає."],
"o16_1-9":["Трамвай повертає праворуч за зеленою стрілкою в додатковій секції, бо основний сигнал для нього червоний. Велосипедист їде на свій зелений, тож перевага в нього, а трамвай має його пропустити.","Стрілка в додатковій секції не дає переваги — навіть трамваю."],
"o16_1-10":["Поруч із червоним сигналом висить табличка із зеленою стрілкою праворуч: повертати можна, але пропускаючи всіх. Поступися пішоходам і машинам, що їдуть з інших напрямків.","Зелена стрілка на табличці — поворот дозволений, але всіх пропусти."],
"o16_1-11":["Біля червоного сигналу є табличка із зеленою стрілкою праворуч — отже, на червоний повертати праворуч можна. Але поступитися треба всім: і машинам з інших напрямків, і пішоходам.","Стрілка на табличці — повертай, але пропусти всіх: і авто, і людей."],
"o16_1-12":["На першому малюнку стрілка світиться в додатковій секції: якщо позаду чекають повороту праворуч, треба їхати за стрілкою, щоб не блокувати смугу. На другому — це лише табличка, яка дозволяє поворот, але не зобов’язує.","Світна стрілка в секції — зобов’язує звільнити смугу. Стрілка на табличці — лише дозволяє."],
"o16_1-13":["Чорне авто стоїть першим у правій смузі, горить зелена стрілка праворуч, а позаду машина з правим поворотником. Якщо стояти й чекати сигналу прямо, заблокуєш її. Тож їдь праворуч за стрілкою.","Стрілка горить, позаду чекають — звільни смугу: їдь за стрілкою."],
"o16_1-14":["Синє авто повертає ліворуч, а назустріч прямо їде велосипедист. Повертаючи ліворуч на зелений, пропускай усіх зустрічних, що їдуть прямо чи праворуч, — і велосипедистів теж.","Ліворуч — пропусти зустрічних. Велосипед — теж зустрічний транспорт."],
"o16_1-15":["Обидва на зелений: біле повертає ліворуч, фіолетове їде назустріч прямо. Хто повертає ліворуч, пропускає зустрічних, тож спершу проїжджає фіолетове, потім біле.","Ліворуч — після зустрічних: спершу той, хто прямо, потім той, хто повертає."],
"o16_1-16":["Біле авто повертає ліворуч, а назустріч їдуть сіре й зелене. Повертаючи ліворуч, треба пропустити всіх зустрічних, що їдуть прямо чи праворуч, — тож пропускаєш обидва авто.","Ліворуч — останнім: пропусти всіх зустрічних, хоч прямо, хоч праворуч."],
"o16_1-17":["Над світлофором висить знак STOP, але світлофор працює й показує зелений. Сигнал світлофора важливіший за знаки пріоритету, тож можна їхати без зупинки.","Світлофор працює — знаки пріоритету відпочивають."],
"o16_1-18":["Автомобіль повертає праворуч, а поруч прямо в тому ж напрямку їде велосипедист. Повертаючи, ти перетинаєш його шлях, тож мусиш його пропустити — навіть якщо сам їдеш на зелений.","Повертаєш праворуч — глянь праворуч: велосипедист, що їде прямо, проїжджає першим."],
"o16_1-19":["Повертаючи праворуч, ти перетинаєш шлях велосипедиста, який їде прямо поруч. Тому пропускати його треба завжди — і коли він на велодоріжці, і коли просто на дорозі.","Праворуч повертаєш — велосипедиста пропускаєш. Завжди."],
"o16_1-20":["Синє авто їде на зелений, а пішоходи переходять дороги ліворуч і праворуч на свій сигнал. Хоч ліворуч, хоч праворуч — ти перетинаєш їхній перехід, тож пропускаєш їх в обох випадках.","Повертаєш — на шляху зебра. Люди на ній ідуть першими."],
"o16_1-21":["За перехрестям затор, і червоному авто довелося б зупинитися просто на перехресті. Так виїжджати не можна навіть на дозвільний сигнал: застрягнеш і заблокуєш тих, хто поїде впоперек.","Нема куди виїхати — не заїжджай. Перехрестя — не місце, щоб стояти в заторі."],
"o16_1-22":["Для чорного авто щойно ввімкнувся зелений, але фіолетове ще розвертається на перехресті, а пішохід ще не дійшов до тротуару. Спершу дай їм обом завершити рух, а вже потім рушай.","Зелений — не старт: спершу випусти тих, хто ще на перехресті."],
"o16_1-23":["Пішохід ще не встиг перейти, хоча для нього вже червоний. Твій зелений не дає права його квапити сигналом чи об’їжджати — зачекай, доки він закінчить перехід.","Зелений загорівся, а людина ще на зебрі — чекаєш, доки дійде."],
"o16_1-24":["Для синього авто горять червоний і жовтий — зараз увімкнеться зелений. Але зелене авто ще виїжджає з перехрестя, тож спершу його треба пропустити.","Хто вже на перехресті — виїжджає першим, навіть коли тобі вже зелений."],
"o16_1-25":["Світлофори працюють, тож знаки пріоритету тут не діють. Червоне авто повертає ліворуч, а біле й синє їдуть йому назустріч. Хто повертає ліворуч, пропускає зустрічних — тому першими проїжджають біле й синє.","Є світлофор — знаки пріоритету мовчать. Ліворуч — після зустрічних."],
"o16_1-26":["Ти повертаєш ліворуч на зелений. Знак головної дороги тут не діє, бо працює світлофор. Отже, діє звичайне правило: спершу пропусти зустрічне авто.","Зелений і поворот ліворуч — пропусти зустрічного. Знаки при світлофорі не рахуються."],
"o16_1-27":["Ти їдеш прямо на зелений, а зустрічне авто повертає ліворуч. Знак «Дати дорогу» не діє, бо працює світлофор. Тож пропускає той, хто повертає ліворуч, а ти проїжджаєш першим.","Прямо на зелений — твоя черга. Хто ліворуч — той чекає."],
"o16_1-28":["Виїжджати на перехрестя не можна, якщо за ним затор і доведеться зупинитися посеред нього, заблокувавши машини й пішоходів. Повільна машина попереду чи авто з оранжевим маячком такої заборони не створюють.","За перехрестям корок — стій перед перехрестям, а не посеред нього."],
"o16_1-29":["Коли тобі вмикається зелений, на перехресті ще можуть бути машини й пішоходи, які не встигли проїхати чи перейти. Спершу дай їм усім завершити рух, а потім рушай.","Зелений увімкнувся — спершу випусти всіх, хто ще на перехресті."],
"o16_1-30":["Якщо і трамваю, і машинам дозволено рух одночасно, перевага в трамвая: він їде рейками, не може об’їхати перешкоду і гальмує довше.","Зелений для всіх — трамвай перший: рейки не звернуть."],
"o16_1-31":["Регульоване перехрестя — те, де черговість проїзду визначає світлофор або регулювальник. Якщо там лише знаки, воно нерегульоване.","Керує світлофор чи людина з жезлом — перехрестя регульоване. Лише знаки — ні."],
"o16_1-32":["Сигнали регулювальника важливіші за світлофор. Якщо він дозволяє тобі їхати прямо, їдь, навіть коли світлофор показує заборонний сигнал.","Регулювальник головніший за світлофор."],
"o16_1-33":["Коли на перехресті працює регулювальник, його сигнали головніші за світлофор і знаки. Тож орієнтуйся на нього, навіть якщо світлофор показує інше.","Людина з жезлом переважує будь-який світлофор."],
"o16_1-34":["Для чорного авто горить основний зелений, а він дозволяє рух в усіх напрямках, якщо знаки цього не забороняють. Тож повертати праворуч можна. Табличка зі стрілкою праворуч стає потрібною лише на червоний.","Зелений — їдь, куди треба. Стрілка на табличці потрібна лише на червоний."],
"o16_2-1":["Знак «Дати дорогу» з табличкою показує: головна дорога йде праворуч і прямо. Червоне й сіре авто їдуть по ній — їх пропускаєш. Біле ліворуч — на другорядній, як і ти, але зліва, тож воно пропускає тебе.","Табличка — карта головної: хто на ній, той перший. Між другорядними — правило правої руки."],
"o16_2-2":["Знаків і світлофора немає — дороги рівнозначні, діє правило правої руки. Синє авто ліворуч від тебе, тож це воно має пропустити тебе, а ти проїжджаєш першим.","Перешкода справа — пропускаєш ти, зліва — пропускають тебе."],
"o16_2-3":["Знаків немає, дороги рівнозначні, тож діє правило правої руки. Червоне авто наближається праворуч — його треба пропустити.","Правило правої руки: хто справа, той і перший."],
"o16_2-4":["Перехрестя рівнозначних доріг, знаків немає. Біле авто праворуч від тебе — за правилом правої руки воно проїжджає першим, а ти після нього.","Справа — значить перший. Біле справа, тож ти другий."],
"o16_2-5":["Знаків немає, дороги рівнозначні. Синє авто виїжджає зліва, тож за правилом правої руки воно має тебе пропустити — ти проїжджаєш першим.","Хто зліва — той чекає, хто справа — той їде."],
"o16_2-6":["Перехрестя рівнозначних доріг. Зелене авто праворуч від тебе, тож воно проїжджає першим, а ти — після нього.","Зелене авто справа — для нього й «зелене світло»: пропусти."],
"o16_2-7":["Ти повертаєш праворуч на перехресті рівнозначних доріг. Жовте авто ліворуч від тебе, а праворуч нікого немає, тож ти проїжджаєш першим.","Справа пусто — дорога твоя. Хто зліва, той пропускає."],
"o16_2-8":["Ти повертаєш ліворуч на перехресті рівнозначних доріг, а біле авто наближається праворуч. За правилом правої руки його треба пропустити.","Справа хтось є — ти чекаєш. Байдуже, куди повертаєш."],
"o16_2-9":["Ти повертаєш ліворуч, а сіре авто наближається зліва. Дороги рівнозначні, тож поступається той, у кого перешкода справа, — тобто сіре, а ти проїжджаєш першим.","Для сірого ти — справа, тож воно тебе й пропускає."],
"o16_2-10":["Знаків немає, дороги рівнозначні. Фіолетове авто праворуч від тебе, тож за правилом правої руки його треба пропустити.","Перешкода справа — пропусти, навіть якщо їдеш прямо."],
"o16_2-11":["Ти повертаєш праворуч, а біле авто зліва. На рівнозначних дорогах поступається той, у кого перешкода справа, — тобто біле. Тож ти проїжджаєш першим, а воно після тебе.","Ти для білого — справа, отже, ти перший."],
"o16_2-12":["Перехрестя рівнозначних доріг. Синє авто праворуч від тебе, тож воно проїжджає першим, а ти — після нього.","Синє справа — синє й перше."],
"o16_2-13":["Ти повертаєш праворуч, а чорне авто ліворуч. Дороги рівнозначні: перешкода справа саме в чорного, тож пропускати має воно, а ти проїжджаєш першим.","Зліва — не твоя турбота: хто зліва, той чекає."],
"o16_2-14":["Сіре авто наближається зліва, дороги рівнозначні. За правилом правої руки ти для нього перешкода справа, тож ти проїжджаєш першим, а сіре після тебе.","Ти справа від сірого — значить, ти перший."],
"o16_2-15":["У тебе знак «Дати дорогу»: червоне й синє авто на головній дорозі, їх пропускаєш. А «швидку» з увімкненим синім маячком пропускають усі й завжди. Тож ти їдеш останнім.","Синій маячок — пропусти. Головна дорога — пропусти. Тож ти останній."],
"o16_2-16":["Ти на головній дорозі, яка повертає ліворуч, і їдеш саме по ній. Біле авто попереду — на другорядній, тож пропускає тебе. Жовте теж на головній, але зліва від тебе, тож за правилом правої руки поступається тобі.","Головна повертає — ти разом із нею. Другорядні чекають, а жовте зліва — теж."],
"o16_2-17":["Головна дорога тут повертає праворуч, і ти, трамвай та синє авто — на ній. Між собою ви роз’їжджаєтеся як на рівнозначних: трамвай має перевагу, а синє наближається справа. Тож ти проїжджаєш після них.","Між своїми на головній — правило правої руки, а трамвай серед рівних завжди перший."],
"o16_2-18":["Головна йде знизу ліворуч. Трамвай 2 і червоне — на ній, і для жовтого вони справа, тож рушають першими й разом, далі жовте. Потім другорядні: трамвай 1 має перевагу перед синім.","Спершу головна (між своїми — правило правої руки), потім другорядна, де трамвай перший."],
"o16_2-19":["У тебе знак «Дати дорогу», а головна йде прямо й праворуч. Чорне й біле авто їдуть по ній — їх пропускаєш. Синє ліворуч — на другорядній, як і ти, і для нього ти справа, тож воно чекає тебе.","Спершу всі з головної, потім — правило правої руки між другорядними."],
"o16_2-20":["У тебе «Дати дорогу», головна йде прямо й праворуч. Жовте й фіолетове на головній — їх пропускаєш. Трамвай поруч на другорядній, як і ти, а серед рівних трамвай має перевагу. Тож ти їдеш після всіх трьох.","Головна — перша, а серед рівних трамвай завжди попереду тебе."],
"o16_2-21":["У тебе «Дати дорогу», головна йде ліворуч і прямо. Трамвай і біле авто на ній — їх пропускаєш. Чорне праворуч — на другорядній, як і ти, але справа, тож його теж пропускаєш.","Головна — перша, а з другорядних — той, хто справа."],
"o16_2-22":["Знаків немає, дороги рівнозначні. Сіре авто праворуч від тебе, тож воно проїжджає першим, а ти — слідом.","Справа — значить перший. Сіре якраз справа."],
"o16_2-23":["Перехрестя рівнозначних доріг, біле авто наближається праворуч. За правилом правої руки його треба пропустити.","Без знаків пропускай того, хто праворуч."],
"o16_2-24":["Велосипедист — теж водій. Він наближається праворуч на перехресті рівнозначних доріг, тож за правилом правої руки ти його пропускаєш.","Велосипед справа — такий самий учасник руху: пропусти."],
"o16_2-25":["Ти їдеш прямо, а велосипедист наближається праворуч. На перехресті рівнозначних доріг правило правої руки діє й щодо велосипедистів, тож пропусти його.","Хто справа — той перший, хоч на авто, хоч на велосипеді."],
"o16_2-26":["Знак кругового руху: хто вже їде по колу, той має перевагу. Фіолетове авто вже на колі, тож пропусти його й лише потім заїжджай.","Хто на колі — той перший. Хто заїжджає — чекає."],
"o16_2-27":["Ти повертаєш ліворуч, а назустріч прямо їде велосипедист. Повертаючи ліворуч, пропускаєш зустрічних, що їдуть прямо чи праворуч, — і велосипедистів теж.","Ліворуч — пропусти зустрічного, навіть на двох колесах."],
"o16_2-28":["Ти повертаєш ліворуч, а біле авто їде назустріч. Хто повертає ліворуч, пропускає зустрічних, що їдуть прямо чи праворуч, тож біле проїжджає першим.","Ліворуч — через чужу смугу: зустрічний завжди перший."],
"o16_2-29":["Ти повертаєш ліворуч. Червоне авто праворуч — його пропускаєш за правилом правої руки. Мотоцикл їде назустріч — його пропускаєш, бо повертаєш ліворуч. Тож ти їдеш останнім.","Справа — пропусти, назустріч — пропусти. Хто повертає ліворуч, той їде останнім."],
"o16_2-30":["Ти повертаєш ліворуч. Трамвай на перехресті рівнозначних доріг має перевагу, куди б він не їхав, а біле авто їде назустріч, і його ти пропускаєш як зустрічне. Тож ти — останній.","Трамвай серед рівних — перший; зустрічний, коли повертаєш ліворуч, — теж."],
"o16_2-31":["Ти їдеш прямо. Трамвай праворуч, а на перехресті рівнозначних доріг він має перевагу — пропусти його. Сіре зустрічне повертає ліворуч, тож воно саме має пропустити тебе.","Трамвай серед рівних — перший. Зустрічний, що повертає ліворуч, чекає тебе."],
"o16_2-32":["Ти повертаєш ліворуч. Зелене авто праворуч — його пропускаєш за правилом правої руки, синє їде назустріч — його пропускаєш, бо повертаєш ліворуч. Тож ти третій.","Ліворуч на рівнозначних: спершу той, хто справа, і зустрічний, а вже тоді ти."],
"o16_2-33":["Біле авто праворуч від тебе — воно проїжджає першим. Синє ліворуч, і для нього ти справа, тож воно чекає тебе. Виходить: біле, ти, синє.","Кожен пропускає того, хто справа: біле, потім ти, потім синє."],
"o16_2-34":["Ти повертаєш ліворуч. Зелене авто праворуч — його пропускаєш. Сіре ліворуч, і для нього ти справа, тож воно чекає тебе. Отже, проїжджаєш одразу після зеленого.","Зелене справа — йому й «зелене світло». Сіре зліва почекає."],
"o16_2-35":["Під снігом не видно, чи має твоя дорога покриття, а знаків пріоритету немає. У такому разі вважай, що ти на другорядній, і пропускай інших — так безпечніше.","Не знаєш, хто головний, — вважай, що не ти."],
"o16_2-36":["Дорогу замело, тож не зрозуміти, яка з доріг має покриття, а знаків немає. Те, що ти їдеш прямо, переваги не дає: вважай свою дорогу другорядною й пропускай.","Сніг сховав асфальт — сховай і впевненість: ти на другорядній."],
"o16_2-37":["Ти повертаєш ліворуч, а синє авто їде назустріч. Повертаючи ліворуч, пропускаєш зустрічних, тож синє проїжджає першим.","Повертаєш ліворуч — зустрічний їде першим."],
"o16_2-38":["Ти їдеш прямо. Жовте авто ліворуч, і для нього ти справа, тож воно чекає. Червоне зустрічне повертає ліворуч, тож теж має пропустити тебе. Ти проїжджаєш першим.","Справа нікого, а зустрічний повертає ліворуч — шлях вільний, ти перший."],
"o16_2-39":["Знак кругового руху означає: хто вже їде по колу, той має перевагу. Жовте авто вже на колі, тож воно проїжджає першим, а ти заїжджаєш після нього.","Коло — як карусель: хто вже катається, той і має перевагу."],
"o16_2-40":["На перехресті з круговим рухом перевагу має той, хто вже їде по колу. Синє авто вже на колі, тож спершу воно, а потім ти.","Хто на колі — той перший. Хто заїжджає — чекає."],
"o16_2-41":["Біле авто праворуч від тебе — його пропускаєш. Але біле саме чекає синього, бо синє для нього справа. Тож черга така: синє, біле, а потім ти.","Ланцюжок правої руки: кожен чекає того, хто в нього справа."],
"o16_2-42":["Ти їдеш прямо. Червоне авто праворуч — його пропускаєш. Біле ліворуч, і для нього ти справа, тож воно чекає тебе.","Пропускай лише того, хто справа. Зліва — пропускають тебе."],
"o16_2-43":["Ти їдеш прямо. Велосипедист праворуч — його пропускаєш за правилом правої руки. Синє авто ліворуч, і для нього ти справа, тож воно чекає тебе.","Справа велосипед — пропусти. Зліва авто — почекає."],
"o16_2-44":["Трамвай на перехресті рівнозначних доріг має перевагу. Жовте авто праворуч від тебе — його пропускаєш, але воно саме чекає біле, яке для нього справа. Тож ти — останній.","Трамвай перший, далі ланцюжок правої руки — а ти в самому кінці."],
"o16_2-45":["Червоне авто праворуч від тебе — його пропускаєш. Але червоне повертає ліворуч і саме пропускає чорне, яке для нього справа. Тож черга: чорне, червоне, а потім ти.","Ланцюжок: кожен чекає того, хто в нього справа, — і ти в кінці."],
"o16_2-46":["Трамвай серед рівнозначних доріг має перевагу. Велосипедист праворуч від тебе — його пропускаєш, але й він чекає трамвай. Тож спершу трамвай, потім велосипедист, а ти останній.","Трамвай — перший, той, хто справа, — другий, ти — останній."],
"o16_2-47":["Трамвай на перехресті рівнозначних доріг має перевагу, куди б не їхав. Біле авто праворуч від тебе — його теж пропускаєш. Тож ти проїжджаєш після обох.","Трамвай серед рівних — завжди перший. Хто справа — теж перед тобою."],
"o16_2-48":["Трамвай на перехресті рівнозначних доріг має перевагу, а в жовтого немає нікого справа — тож вони рушають одночасно. Далі ти: жовте праворуч від тебе, тому чекаєш його. Синє зліва пропускає тебе.","Трамвай і той, у кого справа порожньо, — разом. Потім ти, а той, хто зліва, — після тебе."],
"o16_2-49":["Ти їдеш прямо, а назустріч трамвай, що повертає й перетинає твій шлях. На рівнозначних дорогах трамвай має перевагу, куди б не їхав, — пропусти його. Синє авто ліворуч, тож воно чекає тебе.","Трамвай серед рівних — перший, навіть коли повертає."],
"o16_2-50":["Знаків немає, дороги рівнозначні. Червоне авто праворуч від тебе, тож за правилом правої руки його треба пропустити.","Червоне справа — для тебе це «червоне світло»: зачекай."],
"o16_2-51":["Головна йде згори ліворуч: на ній фіолетове й зелене. Для фіолетового зелене справа, тож зелене перше, фіолетове друге. Потім другорядні: для білого чорне справа, тож чорне третє, а біле останнє.","Спершу головна, потім другорядна — і всюди правило правої руки."],
"o16_2-52":["Головна тут пряма: на ній трамвай і синє. Трамвай серед рівних має перевагу, тож він перший, синє друге. Далі другорядні: чорне повертає ліворуч і пропускає зустрічне біле. Тож біле — третє.","Спершу головна, де трамвай найперший; на другорядних хто ліворуч — пропускає зустрічного."],
"o16_2-53":["Біле авто на головній дорозі, яка повертає ліворуч, і їде саме за нею. У червоного знак «Дати дорогу», тож воно пропускає біле й проїжджає другим.","Знак «Дати дорогу» — значить, ти після тих, хто на головній."],
"o16_2-54":["Знак кругового руху: перевагу має той, хто вже їде по колу. Фіолетове авто вже на колі, тож пропусти його, а потім заїжджай.","Коло — для тих, хто вже на ньому: заїжджай, коли звільниться."],
"o16_2-55":["Ти на головній дорозі, тож сіре авто праворуч, із другорядної, пропускає тебе. Але авто з увімкненими спецсигналами пропускають усі, навіть із головної. Тож ти — другий.","Синій маячок сильніший за будь-яку головну: спершу він, потім ти."],
"o16_2-56":["Коричневе авто виїжджає з ґрунтової дороги на дорогу з покриттям. Дорога з покриттям для нього головна, тож треба пропустити всіх, хто нею їде.","З ґрунтівки на асфальт — як із другорядної: пропусти всіх."],
"o16_2-57":["Синє авто їде дорогою з покриттям, а трактор виїжджає з ґрунтової. Дорога з покриттям щодо ґрунтової — головна, тож синє проїжджає першим, а трактор чекає.","Асфальт головніший за ґрунтівку — навіть коли з неї їде трактор."],
"o16_2-58":["Ти на головній дорозі, але зустрічний трамвай — теж на головній, а серед рівних трамвай має перевагу, куди б не повертав. Тож пропусти його й проїжджай другим.","Головна для обох — трамвай однаково перший."],
"o16_2-59":["Ти на головній, але трамвай поруч зліва — теж на ній і збирається повертати праворуч, перетинаючи твій шлях. Серед рівних трамвай має перевагу, тож пропусти його.","Головна для обох — і знову трамвай перший."],
"o16_2-60":["Жовте стоїть під знаком «Дати дорогу» й повертає ліворуч: воно пропускає всіх із головної, а ще трамвай і чорне, що їдуть йому назустріч. Тож жовте проїжджає останнім.","Другорядна й поворот ліворуч — це кінець черги."],
"o16_2-61":["Головна — згори вниз: на ній трамваї й червоне. Трамваї мають перевагу, причому трамвай 1 повертає ліворуч і пропускає зустрічний трамвай 2. Далі червоне, потім другорядні: фіолетове повертає ліворуч і пропускає зелене.","Спершу головна, де трамваї перші, потім другорядна; хто ліворуч — пропускає зустрічного."],
"o16_2-62":["Сіре й жовте — на другорядних, тож спершу пропускають усіх із головної. А між собою: сіре повертає ліворуч і пропускає зустрічне жовте. Тож сіре — останнє.","Другорядна й поворот ліворуч — це кінець черги."],
"o16_2-63":["Знак кругового руху: перевага в того, хто вже їде по колу. Сіре авто вже на колі, тож воно проїжджає першим, а зелене заїжджає після нього.","Заїжджаєш на коло — пропусти тих, хто вже по ньому кружляє."],
"o16_2-64":["Перед білим авто знак головної дороги, тож воно на головній. Сіре й синє виїжджають із другорядних і мусять його пропустити. Біле проїжджає першим.","Ромб — твоя перевага: на головній ти перший."],
"o16_2-65":["Нерегульоване перехрестя — те, де немає ні працюючого світлофора, ні регулювальника. На першому світлофор показує зелений, на третьому стоїть регулювальник, а на другому лише миготить жовтий — це й є нерегульоване.","Миготливий жовтий без регулювальника — керують знаки, перехрестя нерегульоване."],
"o16_2-66":["Світлофор вимкнений, тож діють знаки. Знак STOP вимагає обов’язково зупинитися перед стоп-лінією і пропустити тих, хто їде дорогою, яку перетинаєш.","Світлофор згас — слухай знак: STOP означає зупинку завжди."],
"o16_2-67":["Ти повертаєш праворуч, а велосипедист праворуч від тебе їде прямо до велопереїзду. Ваші шляхи перетинаються, тож хоч ти й на головній, його треба пропустити.","Повертаєш — пропусти тих, хто поруч їде прямо: велосипедист перший."],
"o16_2-68":["Білий автомобіль повертає праворуч, а пішоходи переходять дорогу, на яку він заїжджає. Навіть без зебри на перехресті вони мають перевагу, хоч авто і їде головною.","Невидима зебра: продовження тротуару через перехрестя — теж перехід."],
"o16_2-69":["Білий повертає ліворуч, синій — праворуч, і обидва перетинають пішохідні переходи на дорогах, куди повертають. Пішоходи там мають перевагу, тож чекати мусять обидва водії.","Ліворуч чи праворуч — неважливо: повертаєш через зебру, значить пропускаєш."],
"o16_2-70":["Білий автомобіль повертає ліворуч, а пішоходи переходять дорогу, на яку він виїжджає. Навіть на головній і без розмітки водій, що повертає, мусить їх пропустити.","Головна дорога дає перевагу над машинами, а не над пішоходами."],
"o16_2-71":["Знак «Дати дорогу» і поперечна пунктирна лінія показують, де чекати. Зупиняйся перед лінією, на місці А, — так ти не висунешся на перехрестя й нікому не заважатимеш.","Лінія — це поріг: стоїш перед ним, а не на ньому."],
"o16_2-72":["Хоч білий автомобіль і на головній, за перехрестям його смуга зайнята. Виїхавши, він застрягне посеред перехрестя й заблокує всіх, тож треба чекати, доки звільниться місце.","Немає куди виїхати — не заїжджай, бо станеш пробкою посеред перехрестя."],
"o16_2-73":["Вантажівка їде головною дорогою, а трамвай стоїть перед знаком «Дати дорогу». Знаки важливіші за звичну перевагу трамвая, тож першим їде автомобіль, а трамвай чекає.","Знак сильніший за рейки: трамвай на другорядній теж пропускає."],
"o16_2-74":["Велосипедист їде головною дорогою, а для трамвая стоїть знак «Дати дорогу». На перехресті з такими знаками трамвай не має переваги, тож першим проїжджає велосипедист.","Головна дорога важить більше, ніж рейки: навіть велосипед їде перед трамваєм."],
"o16_2-75":["Синє авто на головній дорозі, тож воно перше. Трамвай і зелене авто обидва на другорядній, а між рівними трамвай має перевагу над машиною. Тому: синій, трамвай, зелений.","Спершу головна дорога, потім серед рівних — трамвай, а вже тоді звичайна машина."],
"o16_2-76":["Спершу головна дорога: білий їде прямо, синій повертає ліворуч і пропускає зустрічного білого. Потім другорядна: жовтий повертає праворуч, а зелений, що повертає ліворуч, чекає зустрічного жовтого.","Головна раніше за другорядну, а хто повертає ліворуч — пропускає зустрічних."],
"o16_2-77":["Ти на головній і повертаєш ліворуч. Машини зліва й справа стоять на другорядних дорогах і чекають тебе, а зустрічне авто теж на головній і їде прямо — його пропусти.","Ліворуч по головній — чекаєш лише зустрічного, бокові стоять за знаками."],
"o16_2-78":["Головна дорога тут повертає праворуч, а ти їдеш ліворуч, тобто з’їжджаєш з неї. Блакитне авто справа рухається головною, тож спершу пропусти його, а тоді проїжджай.","Табличка з товстою лінією — карта головної. З’їжджаєш з товстої лінії — поступаєшся."],
"o16_2-79":["Головна дорога тут повертає праворуч, а ти їдеш прямо, тобто залишаєш її. Велосипедист справа рухається головною дорогою, тож має перевагу — пропусти його.","Їдеш не по товстій лінії таблички — переваги вже немає, пропускай."],
"o16_2-80":["Головна дорога повертає ліворуч, і ти їдеш саме по ній. Вантажівка і біле авто на другорядних, а червоне хоч і на головній, але ти в нього справа, тож воно поступається тобі.","Обидва на головній — пропускає той, у кого перешкода справа. Справа від червоного — ти."],
"o16_2-81":["Синє авто повертає ліворуч, і саме так іде головна дорога. Трамвай стоїть перед знаком «Дати дорогу», тобто на другорядній, тому першим проїжджає автомобіль, а трамвай чекає.","Знак «Дати дорогу» діє і на трамвай: на другорядній рейки переваги не дають."],
"o16_2-82":["Головна дорога повертає ліворуч, і ти повертаєш разом з нею. Трамвай справа стоїть на другорядній дорозі, тому він пропускає тебе, і перехрестя ти проїжджаєш раніше за нього.","Їдеш товстою лінією таблички — перевага твоя, навіть над трамваєм."],
"o16_2-83":["Головна дорога йде праворуч, а ти повертаєш ліворуч, тобто з’їжджаєш з неї. Тому пропускаєш і швидку з увімкненим синім маячком, і сіре авто, що їде головною дорогою.","Швидка з маячком — поза чергою, а з’їжджаєш із головної — пропусти й тих, хто на ній."],
"o16_2-84":["Сірий повертає ліворуч і залишається на головній — вона теж іде ліворуч. Зелений стоїть на другорядній, а чорний хоч і на головній, але сірий у нього справа. Тож сірий проїжджає першим.","На головній між собою — правило правої руки: хто справа, той перший."],
"o16_2-85":["Головна йде зліва вниз, тож червоне й сіре авто на ній, а зелене — на другорядній і чекає обох. Між червоним і сірим діє правило правої руки: червоне в сірого справа, тому воно перше.","Спершу головна, а всередині неї — хто справа, той і перший."],
"o16_2-86":["Головна дорога повертає праворуч, а ти їдеш прямо — з’їжджаєш з неї. Тому чорне авто справа, що їде головною, проїжджає перед тобою. А синє зустрічне на другорядній, тож воно чекає тебе.","Ти посередині черги: перед другорядним, але після того, хто на головній."],
"o16_2-87":["Головна дорога повертає праворуч, а ти їдеш ліворуч — з’їжджаєш з неї. Тому пропускаєш синє авто справа, що їде головною, і машину з увімкненими маячками зліва.","З’їжджаєш з головної — пропускаєш і тих, хто на ній, і тих, хто з маячками."],
"o16_2-88":["Головна дорога йде справа вниз, тож синє і зелене авто на ній, а червоне зліва — на другорядній і чекає обох. Синє й зелене роз’їжджаються за правилом правої руки: синє в зеленого справа, тому воно перше.","Спершу всі на головній, серед них — хто справа; другорядний — у кінці."],
"o16_2-89":["Головна дорога йде зліва вниз, тож червоне і біле авто на ній, а синє зверху — на другорядній і чекає. Біле в червоного справа, тому біле перше, за ним червоне, а потім синє.","Головні між собою — за правою рукою, другорядний завжди останній."],
"o16_2-90":["Синє авто стоїть перед знаком «Дати дорогу» і повертає ліворуч. Спершу їдуть усі на головній, потім трамвай поруч, що має перевагу на рівних, і зустрічне сіре авто. Тож синє — останнє.","Другорядна дорога плюс поворот ліворуч — найдовша черга: пропускаєш усіх."],
"o16_2-91":["Ти на головній і повертаєш ліворуч, тож пропускаєш зустрічного велосипедиста — він теж на головній і їде прямо. Фіолетове авто справа виїжджає з другорядної й чекає тебе. Тож твоя черга — друга.","Ліворуч — пропусти зустрічного, навіть якщо він на двох колесах."],
"o16_2-92":["Білий і червоний на головній: білий їде прямо, а червоний повертає ліворуч і пропускає зустрічного білого. Далі другорядна: велосипедист їде прямо, а синій повертає ліворуч і чекає зустрічного велосипедиста.","Спершу головна, потім другорядна, і в кожній парі лівий поворот чекає зустрічного."],
"o16_2-93":["Трамвай і мотоцикл їдуть головною, а легковик зліва стоїть перед знаком «Дати дорогу». Мотоцикл повертає ліворуч через колію, тож пропускає трамвай, що йде в тому ж напрямку. Тому: трамвай, мотоцикл, легковик.","Повертаєш ліворуч через рейки — спершу пропусти трамвай, що їде поруч."],
"o16_2-94":["Ти на головній і повертаєш ліворуч, тож пропускаєш зустрічне червоне авто, яке теж на головній. Синє авто зліва стоїть перед знаком «Дати дорогу» і чекає. Тому твоя черга — друга.","Поворот ліворуч — поступися зустрічному, а бокові з другорядних поступляться тобі."],
"o16_2-95":["Жовтий і синій на головній, фіолетовий зліва — на другорядній. Синій повертає ліворуч, тож пропускає зустрічного жовтого. Тому: жовтий, синій, а фіолетовий останнім.","Спершу головна, а на ній лівий поворот чекає зустрічного."],
"o16_2-96":["Велосипедист рукою показує поворот ліворуч. Він і біле авто обидва на головній, а хто повертає ліворуч, пропускає зустрічних, що їдуть прямо. Тож спершу проїжджає авто, а тоді велосипедист.","Велосипед чи авто — правило одне: ліворуч пропускає зустрічного."],
"o16_2-97":["Ти на головній, але повертаєш ліворуч, а назустріч їдуть трамвай і червоне авто — теж головною. Хто повертає ліворуч, пропускає зустрічних, тож спершу їдуть обидва, а потім ти.","Ліворуч — значить після всіх зустрічних: і рейкових, і колісних."],
"o16_2-98":["Ти й трамвай зліва обидва на головній, тож умови між вами рівні, а за рівних трамвай має перевагу, навіть коли повертає праворуч через твою смугу. Біле авто справа стоїть на другорядній і чекає.","На рівних трамвай — старший: він перший, куди б не повертав."],
"o16_2-99":["Ти повертаєш ліворуч, тож пропускаєш зустрічне сіре авто, яке теж їде головною. А швидку з увімкненим синім маячком пропускаєш, хоч вона й виїжджає з другорядної.","Маячок — поза чергою, а зустрічний — перед твоїм лівим поворотом."],
"o16_2-100":["Головна дорога йде від тебе праворуч, а ти повертаєш ліворуч, тобто з’їжджаєш з неї. Велосипедист справа їде головною, тож його пропускаєш. Червоне авто зліва стоїть перед знаком «Дати дорогу» і чекає тебе.","З’їжджаєш з головної — пропусти всіх, хто на ній, навіть велосипед."],
"o16_2-101":["Нерегульоване — це коли рухом ніхто не керує: світлофор вимкнений або блимає жовтим, світлофора й регулювальника немає взагалі, або черговість задають лише знаки. Правильні всі три варіанти.","Немає робочого світлофора і регулювальника — перехрестя нерегульоване."],
"o16_2-102":["Знак «Дати дорогу» і трикутники на дорозі кажуть: ти на другорядній. Тут пропускаєш усіх, хто їде головною, — і зліва, і справа, а не лише тих, хто справа.","Трикутники на асфальті дивляться на тебе вістрям: пропускаєш усіх, з будь-якого боку."],
"o16_2-103":["Знаків пріоритету немає, тож діє правило «перешкода справа». Сіре авто в тебе справа — ти його пропускаєш, а для сірого справа синє, тож сіре чекає синього. Синє, потім сіре, а ти в самому кінці.","Справа від тебе сіре, справа від сірого синє — ти в кінці ланцюжка."],
"o16_2-104":["Знаків немає, тож діє правило правої руки. Справа від тебе сіре авто, справа від сірого — синє, а в синього праворуч нікого немає. Тому синє проїжджає першим.","Першим їде той, у кого справа порожньо."],
"o16_2-105":["Жовтий, що блимає, лише попереджає про небезпеку, але рух не регулює. Тож перехрестя стає нерегульованим, і черговість визначаєш за знаками пріоритету та правилами для таких перехресть.","Блимає жовтий — світлофор «спить»: їдь за знаками."],
"o16_2-106":["На дорозі праворуч стоїть знак «В’їзд заборонено» — червоне коло з білою смугою. Отже, повернути туди не можна взагалі, хоч пішохода пропусти, хоч ні.","Червоне коло з білою «цеглиною» — двері зачинені, туди не заїжджають."],
"o16_2-107":["Під знаком «Дати дорогу» висить синій круглий знак зі стрілкою праворуч — він дозволяє їхати тільки праворуч. Тож ліворуч повертати тут не можна.","Синє коло зі стрілкою — наказ: куди стрілка, туди й їдеш."],
"o16_2-108":["Синій круглий знак зі стрілкою праворуч — це наказ рухатися тільки в цьому напрямку. Тож так, з цього місця можна лише повернути праворуч, попередньо пропустивши тих, хто на головній.","Синій кружок — не порада, а наказ: стрілка праворуч — їдеш праворуч."],
"o16_2-109":["Табличка під знаком головної дороги показує, що головна повертає праворуч — саме туди, куди й ти. Авто зліва виїжджає з другорядної, тож воно пропускає тебе, а не навпаки.","Повертаєш разом із товстою лінією на табличці — перевага твоя, зліва чекають."],
"o17-1":["Знак з автобусом і стрілкою виділяє смугу для громадського транспорту. Крім маршруток, що їдуть своїм маршрутом, нею можуть їхати таксі, мопеди, двоколісні мотоцикли й велосипедисти.","Смуга «А» — для маршруток, таксі й усіх, хто на двох колесах."],
"o17-2":["Перед поворотом праворуч треба зайняти крайнє праве положення, а тут ним є смуга для маршруток. Там, де її лінія переривчаста, заїжджаєш на неї і вже звідти повертаєш — це траєкторія Б.","Праворуч — завжди з крайньої правої, навіть якщо це смуга автобусів: шлях Б."],
"o17-3":["Щоб повернути праворуч, авто має спершу перейти в крайню праву смугу — тут це смуга для маршрутних засобів, на яку для повороту заїжджати можна. Тому правильний шлях — Б, а не різкий поворот через неї.","Поворот праворуч починається з крайньої правої смуги — Б, а не навскоси через неї."],
"o17-4":["На смугу для маршрутних авто можна заїхати, щоб посадити чи висадити пасажира. Тож біле авто має право перестроїтися туди й зупинитися біля людини на тротуарі.","Пасажира взяти чи висадити — на автобусну смугу можна, а їхати нею — ні."],
"o17-5":["На смугу для маршрутних авто звичайній машині можна заїхати лише у двох випадках: щоб посадити чи висадити пасажира або щоб звідти повернути праворуч.","Два «можна» для смуги автобусів: пасажир і поворот праворуч."],
"o17-6":["Знак із трамваєм попереджає: колія тут перетинає дорогу поза перехрестям. У такому місці трамвай має перевагу, тож автомобіль чекає, поки він проїде.","Рейки впоперек дороги — трамвай господар, авто чекає."],
"o17-7":["У населеному пункті автобусу, що рушає із зупинки в «кишені», треба дати виїхати. Пригальмуй, а якщо треба — зупинись, щоб він спокійно виїхав на дорогу.","У місті автобус із «кишені» — як гість у дверях: дай йому вийти."],
"o17-8":["Пропускати автобус, що рушає з «кишені», обов’язково лише в населеному пункті. Тут дорога поза ним, тож перевага в білого автомобіля, а автобус виїжджає, коли буде вільно.","Поза містом «кишеня» не дає автобусу переваги — черга твоя."],
"o17-9":["Таксі можна їхати і звичайними смугами, і смугою для маршрутних авто — правила прямо це дозволяють.","Для смуги маршруток таксі — свій: його туди пускають."],
"o17-10":["Таксі дозволено і їхати смугою для маршрутних авто, і зупинятися на ній, щоб посадити чи висадити пасажирів.","Таксі на автобусній смузі — свій: посадити й висадити можна."],
"o17-11":["На смузі для маршрутних авто іншим машинам не можна ні їхати, ні зупинятися. Виняток — таксі, мопеди, двоколісні мотоцикли й велосипеди: їм така смуга дозволена.","На смугу «А» з легковиків пускають лише таксі, а ще всіх на двох колесах."],
"o18-1":["Жовтий сигнал, що блимає біля переходу, не керує рухом, а попереджає: тут небезпечний нерегульований перехід. Пригальмуй і пильнуй пішоходів.","Жовтий блимає — світлофор не командує, а гукає: «Обережно, перехід!»"],
"o18-2":["Автобус зі знаком «Діти», аварійкою й оранжевим маячком означає, що поруч можуть вибігти діти. Знизь швидкість, а якщо треба — зупинись, щоб нікого не зачепити.","Бачиш «Діти» з аварійкою — нога над гальмом: дитина може вискочити будь-якої миті."],
"o18-3":["Трамвай зупинився там, де немає острівця, тож люди йдуть до нього просто через дорогу. Сірому авто треба стати й чекати, доки пішоходи зійдуть з дороги, а двері трамвая зачиняться.","Двері трамвая відчинені — дорога зайнята: стоїш, доки люди не зійдуть і двері не зачиняться."],
"o18-4":["Пішохід на острівці чи на лінії між потоками стоїть зовсім поруч із машинами. Проїжджаючи повз, тримай від нього безпечну відстань, щоб випадково не зачепити.","Людина на острівці — як на вузькій стежці: об’їжджай із запасом, а не з гудком."],
"o18-5":["Якщо машина попереду гальмує перед переходом, вона, найпевніше, пропускає пішохода, якого тобі не видно. Пригальмуй, за потреби зупинись і рушай, лише переконавшись, що на переході нікого немає.","Сусід гальмує біля зебри — значить, бачить людину, якої не бачиш ти."],
"o18-6":["Біла тростина, витягнута вперед, — це сигнал незрячої людини, що вона хоче перейти дорогу. Зупинись і пропусти її.","Біла тростина вперед — для тебе як червоне світло: стоп і пропусти."],
"o18-7":["Тут потрібні обидві умови разом: пішоходи вже зійшли з дороги, і двері трамвая зачинилися. Поки двері відчинені, хтось іще може вибігти до трамвая чи від нього.","Дві умови: дорога порожня і двері зачинені. Одна з двох — замало."],
"o18-8":["Якщо трамвай зупинився там, де люди виходять просто на дорогу, зупинись і чекай. Рушай лише тоді, коли пішоходи зійдуть з дороги, а двері трамвая зачиняться.","Трамвай відчинив двері — для тебе це «стоп», поки їх не зачинить."],
"o18-9":["Якщо за переходом затор, не заїжджай на зебру — інакше застрягнеш на ній і перекриєш шлях пішоходам. Зупинись перед переходом і чекай, поки звільниться місце.","Зебра — не стоянка: за нею тісно — стоїш перед нею."],
"o18-10":["Якщо машина в сусідній смузі гальмує перед переходом, вона, мабуть, пропускає пішохода, якого тобі за нею не видно. Пригальмуй, за потреби зупинись і рушай, лише переконавшись, що на переході нікого немає.","Сусід зупинився біля зебри — за ним може ховатися людина."],
"o18-11":["Головна дорога дає перевагу над машинами, а не над пішоходами. Якщо мікроавтобус зупинився перед переходом, за ним може йти людина, тож пригальмуй і рушай, лише переконавшись, що на переході нікого немає.","Мікроавтобус став біля зебри — вважай, що за ним пішохід."],
"o18-12":["Якщо авто попереду пригальмувало й зупинилося перед переходом, найпевніше, воно пропускає людей. Знизь швидкість, за потреби зупинись і рушай далі, лише переконавшись, що на переході нікого немає.","Хтось став перед зеброю — спершу переконайся, а вже тоді їдь."],
"o18-13":["Зелений для тебе не означає, що можна їхати просто на людей. Якщо пішоходи ще завершують перехід, дочекайся, поки вони зійдуть з дороги.","Зелений — дозвіл рушати, але не через людей: спершу хай дійдуть."],
"o18-14":["На нерегульованому переході перевага в пішоходів. Знизь швидкість, а коли треба — зупинись, щоб вони спокійно перейшли.","Зебра без світлофора — пішохід головний: пригальмуй і пропусти."],
"o18-15":["Жовтий, що блимає, означає, що перехід фактично без світлофора. Тож пішоходи мають перевагу: знизь швидкість, а за потреби зупинись і пропусти їх.","Блимає жовтий — зебра стає звичайною: пішохід перший."],
"o18-16":["Біля зебри без світлофора головні — пішоходи. Пригальмуй заздалегідь, а якщо хтось переходить чи збирається ступити на перехід, — зупинись і пропусти.","Під’їжджаєш до зебри — нога на гальмо: повільніше, а якщо треба — стоп."],
"o18-17":["Біля автобуса, з якого виходять чи в який сідають діти, будь-хто може вибігти на дорогу. Знизь швидкість, а за потреби зупинись — гудок тут нічим не допоможе.","Діти біля автобуса — не гуди, а гальмуй."],
"o18-18":["Трамвай стоїть на зупинці, і люди йдуть до нього просто через дорогу. Біле авто може рушати тільки тоді, коли всі пішоходи зійдуть з дороги і двері трамвая зачиняться.","Рушай, коли збіглися обидві умови: люди на тротуарі й двері трамвая закриті."],
"o18-19":["Люди йдуть до трамвая чи від нього просто через дорогу, і об’їжджати їх тут не можна. Біле авто має стояти й чекати, доки вони зійдуть з дороги, а двері трамвая зачиняться.","Біля відчинених дверей трамвая не маневруй — просто чекай."],
"o19-1":["За правилами темна пора доби — це весь час від заходу до сходу сонця, без жодних додаткових хвилин сутінків.","Сонце сіло — темна пора почалася, сонце зійшло — закінчилася."],
"o19-2":["Коли зустрічні фари сліплять, ти гірше бачиш дорогу попереду. Тож скидай швидкість до такої, за якої встигнеш зреагувати на те, що раптом з’явиться.","Гірше бачиш — повільніше їдеш."],
"o19-3":["Коли зупиняєшся на дорозі в темряві, машину має бути видно, але без зайвого світла. Для цього вмикають габаритні або стоянкові ліхтарі.","Стоїш у темряві — світять габарити: «я тут, але не їду»."],
"o19-4":["Вимушена зупинка в темряві — це вже небезпека для інших. Тому, крім габаритних чи стоянкових ліхтарів, вмикають ще й аварійну сигналізацію.","Звичайна зупинка — габарити, вимушена — габарити плюс аварійка."],
"o19-5":["Під час зупинки в тумані чи зливі вмикають габаритні або стоянкові ліхтарі. А щоб машину точно помітили, можна додати ближнє світло або протитуманні фари й задні протитуманні ліхтарі.","Погано видно — габарити обов’язково, а ближнє чи протитуманки — на додачу."],
"o19-6":["Якщо габарити не працюють, у темряві машину на дорозі просто не побачать. Тож прибери її з дороги, а якщо не вийде — позначи так, як вимагають правила.","Не світишся — не стій на дорозі: з’їдь убік або познач машину."],
"o19-7":["У тумані чи зливі протитуманні фари можна вмикати як окремо, так і разом із ближнім або дальнім світлом — обидва варіанти дозволені.","Туман — протитуманки можна і соло, і в дуеті з фарами."],
"o19-8":["У темряві протитуманні фари самі по собі не дають достатньо світла для дороги. Тому вночі їх вмикають тільки разом з ближнім або дальнім світлом.","Уночі протитуманки — лише в парі з фарами, соло — тільки в тумані."],
"o19-9":["У темряві самих протитуманних фар замало: їздити з ними без ближнього чи дальнього світла не можна.","Ніч — протитуманки без фар не рахуються."],
"o19-10":["Фара-прожектор і фара-шукач — це службове обладнання. Вмикати їх можна лише під час виконання службових завдань і так, щоб не засліпити інших водіїв і пішоходів.","Прожектор — інструмент служби: світи по справі й не в очі."],
"o19-11":["Задній протитуманний ліхтар світить постійно, а стоп-сигнал має спалахувати лише під час гальмування. Якщо їх поєднати, водії позаду не зрозуміють, коли ти гальмуєш.","Стоп — тільки для гальма, туманка — тільки для туману: не змішуй."],
"o19-12":["Задній протитуманний ліхтар дуже яскравий і в звичайну ніч сліпить тих, хто позаду. Його вмикають лише тоді, коли видимість погана — у тумані, зливі, снігопаді.","Задня туманка — для туману, а не для темряви."],
"o19-13":["Якщо тебе засліпили, ти на мить нічого не бачиш, тож будь-яке перестроювання небезпечне. Зупинись у своїй смузі й увімкни аварійку, щоб тебе помітили.","Засліпило — не крути кермом: гальмуй у своїй смузі й вмикай аварійку."],
"o19-14":["Якщо зустрічний перемикає фари, він показує, що твоє дальнє його сліпить. Переходь на ближнє одразу, навіть якщо до нього ще понад 250 м.","Тобі блимають — значить, сліпиш: ближнє вмикай негайно, не міряй метри."],
"o19-15":["Коли видимість погана, вмикай ближнє або дальнє світло. Протитуманні фари можна додати до них або вмикати окремо — обидва способи дозволені.","Погана видимість — фари обов’язково, протитуманки — окремо чи разом, як зручно."],
"o19-16":["Машину на буксирі мають добре бачити ззаду й розуміти, що вона не їде сама. Тому на ній вмикають габаритні ліхтарі разом з аварійною сигналізацією.","На буксирі — габарити й аварійка: «мене тягнуть, обережно»."],
"o19-17":["Уночі, у сильний дощ чи туман їхати можна лише з увімкненими фарами — ближнім або дальнім світлом, залежно від ситуації.","Темно або мокро — фари світять завжди: ближнє чи дальнє."],
"o19-18":["У тунелі світла завжди менше, ніж надворі, і машину мають добре бачити. Тому при в’їзді вмикають фари — ближнє або дальнє світло, а не лише габарити чи протитуманки.","Тунель — як ніч: фари вмикаєш на в’їзді."],
"o19-19":["Навіть якщо тунель освітлений, при в’їзді в нього вмикають ближнє або дальнє світло фар — так тебе краще видно в напівтемряві.","Освітлений чи ні — тунель завжди з фарами."],
"o19-20":["Будь-який тунель, хоч темний, хоч з ліхтарями, проїжджають з увімкненими фарами — ближнім або дальнім світлом.","Тунель — фари, без винятків і без «тут же світло»."],
"o19-21":["Навіть віз чи сани в темряві мають світити самі, а не лише відбивати чуже світло. Тому на них потрібні фари або ліхтарі, хай якою освітленою є дорога.","Світлоповертач лише відбиває, а ліхтар світить сам — уночі потрібен ліхтар."],
"o19-22":["Дальнє світло можна вмикати, коли воно нікого не засліпить — ні зустрічних, ні тих, хто їде попереду в тому ж напрямку. Роздільна смуга сама по собі такої гарантії не дає.","Дальнє — лише коли нікого не сліпить: ні в лоб, ні в дзеркала."],
"o19-23":["Якщо їдеш за іншою машиною, дальнє світло б’є її водієві в дзеркала й сліпить. Тому позаду когось тримай ближнє.","Їдеш за кимось — не світи йому в дзеркала: ближнє."],
"o19-24":["Перемикайся на ближнє заздалегідь — коли до зустрічної машини ще щонайменше 250 м. Так її водій не буде засліплений, поки ви наближаєтеся одне до одного.","250 м — це чверть кілометра: бачиш зустрічного здалеку — вже ближнє."],
"o19-25":["Коли роз’їжджаєшся із зустрічною машиною вночі, вмикай ближнє світло. Дальнє засліпить водія навпроти, а протитуманки для цього не призначені.","Зустрічний поруч — ближнє: світи на дорогу, а не в очі."],
"o19-26":["Їдучи в темряві, навіть освітленою вулицею, вмикай фари — ближнє або дальнє світло. Габарити чи самі протитуманки їх не замінять.","Ніч — фари завжди: вуличні ліхтарі не рахуються."],
"o19-27":["Дальнє світло засліпить зустрічного водія, і він на мить перестане бачити дорогу — це небезпечно для обох. Перед зустрічною машиною вмикають ближнє, а не дальнє.","Хочеш, щоб тебе бачили, — не сліпи: зустрічному лише ближнє."],
"o19-28":["Ні, якраз навпаки: коли наближаєшся до зустрічних машин, дальнє світло перемикають на ближнє, щоб не засліпити водіїв.","Зустрічний попереду — дальнє геть, вмикай ближнє."],
"o19-29":["На погано освітленій вулиці габаритів замало, щоб бачити дорогу, а протитуманки для цього не призначені. Вмикай фари — ближнє або дальнє світло.","Темна вулиця — світять фари, а не габарити."],
"o19-30":["Засліплений водій кілька секунд не бачить, що поруч, тож перестроюватися дуже небезпечно. Зупинитися можна лише у своїй смузі, увімкнувши аварійку.","Засліпило — тримай смугу: гальмуй прямо, без маневрів."],
"o19-31":["Якщо попереду нікого немає і нікого засліпити, дальнє світло вмикати можна — воно допоможе краще бачити дорогу.","Порожня дорога вночі — дальнє твоє."],
"o19-32":["У темряві на неосвітленій дорозі протитуманні фари не замінюють звичайних. Їх вмикають тільки разом з ближнім або дальнім світлом.","Неосвітлена дорога вночі — протитуманки лише як доповнення до фар."],
"o19-33":["Задній протитуманний ліхтар дуже яскравий і сліпить водіїв позаду. Якщо туману, дощу чи снігопаду немає, вмикати його не можна навіть уночі.","Темно, але ясно — задня туманка вимкнена."],
"o20-1":["Тут у твоєму напрямку дві смуги, і кожне авто стоїть у своїй. Тож через переїзд можна їхати поруч у два ряди — ніхто не виїжджає на зустрічну.","Є дві свої смуги — можна два ряди; зустрічну перед переїздом не займай."],
"o20-2":["Якщо за переїздом затор, на рейках можна застрягнути саме тоді, коли йде поїзд. Тому стій перед переїздом і заїжджай на нього лише тоді, коли за ним буде вільне місце.","Рейки — не місце для очікування: за переїздом тісно — чекаєш перед ним."],
"o20-3":["Тут у кожен бік лише одна смуга, тож друге авто поруч опиняється на зустрічній. Об’їжджати чергу перед переїздом через зустрічну смугу не можна — їдуть одним рядом.","Одна смуга у твій бік — один ряд через рейки."],
"o20-4":["Шлагбаум закриває переїзд недарма — до нього наближається поїзд або є інша небезпека. Самовільно піднімати чи відкривати його не можна.","Шлагбаум піднімає залізниця, а не водій."],
"o20-5":["На такому переїзді є все: світлофор зі звуковим сигналом, шлагбаум, черговий і розмітка. Водій зважає на кожне з них, тож правильно — усе перелічене.","На переїзді слухаєш усіх: світло, звук, шлагбаум, чергового й розмітку."],
"o20-6":["Шлагбаума й чергового тут немає, зате є знаки, розмітка і світлофор зі звуковим сигналом. Водій зважає на все це разом, тому правильна відповідь — усе перелічене.","Немає шлагбаума — тим уважніше до знаків, розмітки й світлофора."],
"o20-7":["Над переїздом блимає біло-місячний вогник, а червоні не горять — це дозвіл їхати. Тільки через знак «STOP» спершу зупинись біля стоп-лінії, а потім проїжджай.","Біле блимає — можна, червоне блимає — стоп."],
"o20-8":["На світлофорі переїзду блимає червоний вогник — це пряма заборона руху. Стій перед стоп-лінією, поки червоний не згасне.","Червоне миготіння на переїзді — як шлагбаум, тільки світловий: стоп."],
"o20-9":["Червоні вогні й звуковий сигнал уже забороняють проїзд, навіть якщо шлагбауми ще підняті. Зупинись у передбаченому місці й не намагайся проскочити.","Червоне блимає — переїзд закрито, хай шлагбаум ще й не опустився."],
"o20-10":["Якщо машина зупинилася на рейках, діяти треба одразу в обидва боки: висадити людей у безпечне місце і намагатися звільнити переїзд.","Машина стала на рейках — люди назовні й авто з колії, усе одразу."],
"o20-11":["Якщо звільнити переїзд не вдається, роблять усе: посилають людей уздовж колій назустріч поїзду, лишаються біля машини, подаючи сигнали тривоги, а коли з’явиться поїзд — біжать до нього, подаючи сигнал зупинки.","Машина на рейках — працюють усі: хтось біжить уздовж колії, хтось сигналить і рятує авто."],
"o20-12":["Машиністові показують зупинку, крутячи рукою по колу з яскравою тканиною чи іншою помітною річчю. Уночі або коли погано видно — так само крутять факелом чи ліхтарем.","Поїзд зупиняє коло: крути рукою, як пропелером."],
"o20-13":["Сигналізація може не спрацювати, але поїзд від цього не зупиниться. Якщо бачиш поїзд, що наближається, зупинись у передбаченому місці й чекай, поки він проїде.","Бачиш поїзд — вір очам, а не світлофору."],
"o20-14":["Поки світло й звук на переїзді працюють, проїзд заборонений, навіть якщо поїзд уже проїхав, — може йти ще один. Дочекайся, поки сигнали вимкнуться, переконайся, що поїзда немає, і тоді рушай.","Один поїзд проїхав — це ще не дозвіл: чекай, поки замовкне сигнал."],
"o20-15":["Світло й звук на переїзді вмикаються заздалегідь, ще до появи поїзда. Тож навіть якщо поїзда не видно, проїзд уже заборонений — зупинись у передбаченому місці.","Сигнал є, поїзда не видно — він усе одно їде: стоп."],
"o20-16":["Шлагбаум почав опускатися — значить, переїзд закривається. Проїзд заборонено, навіть якщо ти ще не бачиш червоного світла чи не чуєш сигналу.","Шлагбаум сам по собі — стоп-сигнал: опускається — зупиняєшся."],
"o20-17":["Залізничний переїзд — це місце, де дорога перетинає залізничні колії на одному рівні. Перетин з трамвайними рейками чи міст над залізницею переїздом не є.","Дорога + залізниця + один рівень = переїзд. Трамвай і міст не рахуються."],
"o20-18":["Якщо на переїзді немає ні шлагбаума, ні світлофора, ні знаків, зупиняйся за 10 м до найближчої рейки й пропускай поїзд.","Нічого не підказує, де стати, — відміряй 10 м від рейки: це твоя стоп-лінія."],
"o20-19":["На будь-якому переїзді — зі шлагбаумом чи без — головне переконатися, що не наближається поїзд, локомотив чи дрезина. Знаки й розмітка можуть бути, а можуть і не бути.","Перед рейками крути головою: ліворуч, праворуч — чи не йде поїзд."],
"o20-20":["Проїжджаючи переїзд, водій зважає на все, що там є: на чергового, шлагбаум, світло й звук, знаки й розмітку. Тому правильна відповідь — усе перелічене.","На переїзді слухаєш усіх, хто «говорить»: людину, шлагбаум, світло, знаки."],
"o20-21":["Перетинати залізничні колії можна тільки на переїздах. Навіть якщо колію добре видно в обидва боки, поза переїздом перетинати її заборонено.","Рейки перетинають лише там, де для цього є переїзд."],
"o20-22":["Перетинати колії дозволено на будь-якому залізничному переїзді — і зі шлагбаумом, і без нього. А от у випадковому місці, навіть з гарним оглядом, не можна.","Будь-який переїзд — так, будь-яке інше місце — ні."],
"o20-23":["Сигнал загальної тривоги — це один довгий гудок і три короткі. Його подають, щоб попередити про небезпеку на переїзді.","Тривога звучить як «Ту-у-у, ту, ту, ту»: один довгий — три короткі."],
"o20-24":["Шлагбаум опускається — значить, поїзд уже близько і переїзд закривається. Проскакувати під ним не можна за жодних умов, хоч би як далеко здавався поїзд.","Шлагбаум рушив униз — і ти стоїш. Без «встигну»."],
"o20-25":["Перед переїздом зупиняються там, де це показано: біля стоп-лінії, біля знака «Проїзд без зупинки заборонено» або перед світлофором так, щоб бачити його сигнали. Усі варіанти правильні.","Стоп-лінія, знак «STOP» чи світлофор — усі три показують, де стати перед рейками."],
"o20-26":["Обганяти на залізничному переїзді заборонено завжди — хай він регульований чи шлагбаум піднятий.","Рейки під колесами — ніякого обгону."],
"o20-27":["Обгін на переїзді заборонений без винятків: ні повільна машина попереду, ні те, що обганяєш лише одну, правил не змінюють.","Рейки під колесами — обгону немає, хоч би як повільно повзли попереду."],
"o20-28":["Світло й звук на переїзді уже забороняють рух, навіть якщо шлагбаум ще не опустився. Не намагайся проскочити — зупинись і чекай.","Звук і червоне світло важать стільки ж, скільки опущений шлагбаум."],
"o20-29":["Рухатися заднім ходом через залізничний переїзд заборонено. Якщо поворот лишився позаду, доведеться їхати далі й розвертатися там, де це дозволено.","Поворот позаду — не біда, а задній хід через рейки — біда."],
"o20-30":["Машина вже на залізничному переїзді, а їхати по ньому заднім ходом заборонено. На рейках не маневрують — колію треба просто проїхати.","На рейках задньої передачі немає — тільки вперед."],
"o20-31":["Розвертатися на залізничному переїзді заборонено, навіть якщо поруч немає жодної машини. Поки маневруєш на рейках, можна застрягнути саме тоді, коли наближається поїзд.","Переїзд — не майданчик для розвороту: рейки тільки перетинають."],
"o21-1":["Пасажирів можна везти стільки, скільки передбачено технічною характеристикою машини, а не скільки здається безпечним чи скільки фактично вміститься.","Кількість пасажирів рахують за документами машини, а не «скільки влізе»."],
"o21-2":["У будь-якій машині пасажирів може бути не більше, ніж передбачено її технічною характеристикою. Ні фіксована цифра, ні навантаження на осі тут не мірило.","Скільки передбачив виробник — стільки й пасажирів, у будь-якому авто."],
"o21-3":["Водію маршрутки під час перевезення пасажирів не можна розмовляти з ними, їсти й пити, тримати телефон у руці чи палити. Усе це відволікає від дороги, тож правильно — усе перелічене.","За кермом маршрутки — тільки кермо: ні розмов, ні їжі, ні телефону в руці, ні цигарки."],
"o21-4":["Відчиняти двері, поки машина ще їде, заборонено: пасажир може випасти чи вийти на ходу. Двері відчиняють лише після повної зупинки.","Спершу стоп, потім двері — ніколи навпаки."],
"o21-5":["Поза кабіною пасажирів можна везти лише в обладнаному для цього кузові вантажівки — відкритому з бортами або закритому фургоні. Кузов трактора для цього не годиться.","Людей возять у кузові вантажівки, обладнаному для них, а не трактора."],
"o21-6":["Дитина в автокріслі має бути пристебнута завжди — це не на розсуд батьків. Непристебнута дитина під час різкого гальмування може вилетіти з крісла.","Автокрісло без ременів — не захист, а просто сидіння."],
"o21-7":["Везти дитину без автокрісла, пристебнувши звичайним ременем, можна, коли її зріст уже 150 см або більше. Тоді ремінь лягає правильно — на плече й стегна, а не на шию й живіт.","Виросла до 150 см — можна пересідати з автокрісла на звичайний ремінь."],
"o21-8":["Неправильне твердження — про крісло проти руху на передньому сидінні без вимкнення подушки. Подушка, розкриваючись, вдарить просто в спинку такого крісла, тому її обов’язково вимикають.","Крісло спиною вперед і ввімкнена подушка — несумісні: подушку вимикають."],
"o21-9":["Найбезпечніше місце для дитячого крісла — посередині заднього ряду. Воно найдалі від ударів з будь-якого боку і від передніх подушок безпеки.","Найбезпечніше — в центрі позаду: від усіх ударів найдалі."],
"o21-10":["Якщо дитяче крісло стоїть на передньому сидінні, фронтальну подушку цього місця треба вимкнути. Під час аварії вона розкривається з великою силою і може травмувати дитину.","Дитина спереду — подушку вимкнено, без винятків."],
"o21-11":["Малюка до трьох років на передньому сидінні везуть у кріслі, повернутому проти руху. Так під час різкого гальмування удар приймає спинка крісла, а не тендітна шия дитини.","Малюк спереду — обличчям назад, спиною до дороги."],
"o21-12":["У дитячому кріслі дитина має бути завжди пристебнута ременями. Без цього крісло не захистить її під час різкого гальмування чи удару.","Дитина в кріслі — завжди клац ременем, навіть на коротку поїздку."],
"o22-1":["Якщо вантаж стирчить убік більше ніж на 0,4 м за край габаритного ліхтаря, його позначають щитками або прапорцями, щоб інші водії бачили справжню ширину машини.","Вшир суворо: досить 0,4 м зайвого — і вже потрібен прапорець."],
"o22-2":["Якщо вантаж виступає спереду чи ззаду більше ніж на 1 м за габарит машини, його треба позначити щитками або прапорцями, щоб ніхто в нього не врізався.","Вздовж межа — 1 м: стирчить довше — чіпляй прапорець."],
"o22-3":["Вантаж має і лежати надійно, і бути добре закріпленим — перевіряти це треба і перед виїздом, і дорогою. Тому правильні обидва варіанти.","Покласти й прив’язати — мало: перевіряй і дорогою."],
"o22-4":["Перевіряти, як лежить і чи міцно закріплений вантаж, треба двічі: перед тим як рушити, і вже під час руху. Тож правильно — обидві дії.","Вантаж перевіряють «до» і «під час», а не лише раз."],
"o22-5":["Вантаж можна везти, лише коли виконано все разом: він нікому не загрожує й не смітить, не розхитує машину, не закриває огляд, фари, номери й не заважає сигналам рукою.","Вантаж не заважає ні тобі, ні машині, ні іншим — лише всі умови разом."],
"o22-6":["Вантаж перевіряють, щоб він не падав і не волочився, не загрожував людям і не смітив на дорогу, а ще не закривав огляд водієві. Усі ці цілі важливі, тож правильні всі три варіанти.","Перевірка вантажу — від усіх бід одразу: падіння, бруду й поганого огляду."],
"o23-1":["Машину з несправними гальмами на жорсткому зчепленні можна тягнути, лише якщо вона важить не більше ніж половину ваги тягача. Інакше тягач може її не втримати під час гальмування.","Без гальм буксирують лише того, хто щонайменше вдвічі легший за тягач."],
"o23-2":["Жорстке зчеплення — це металева штанга між машинами. З нею відстань між ними має бути не більше ніж 4 м.","Жорстка штанга — до 4 м, не довше."],
"o23-3":["Якщо легкове авто тягнуть на тросі чи на жорсткій зчіпці, пасажирам у ньому їхати можна. Обмеження діють для іншого способу — коли машину частково піднімають на платформу.","Легковик на тросі чи штанзі — пасажири можуть лишатися всередині."],
"o23-4":["Коли машину буксирують, піднявши частину її на платформу, у ній нікому не можна сидіти. Пасажири їдуть лише в кабіні машини, що тягне, — не в кузові й не в буксируваному авто.","Частково навантажена машина — порожня. Люди — лише в кабіні того, хто тягне."],
"o23-5":["Пасажирам можна залишатися в буксируваній машині, коли це легковик і його тягнуть на тросі або жорсткій зчіпці. У разі часткового навантаження в буксируваному авто людей бути не повинно.","Легковик + трос чи штанга = пасажири можуть лишатися."],
"o23-6":["Буксирування — це коли друга машина котиться власними колесами: на тросі, на жорсткій зчіпці або частково піднята на платформу. Якщо авто повністю стоїть на платформі — це вже перевезення.","Хоч частина коліс котиться по дорозі — це буксирування. Повністю на платформі — це вантаж."],
"o23-7":["На ожеледиці тягнути машину на тросі заборонено: на слизькій дорозі задня машина не встигне загальмувати, наїде на передню або її занесе.","Лід і трос — погана пара: трос не тримає відстань, коли машини ковзають."],
"o23-8":["На ожеледиці буксирувати можна лише так, щоб відстань між машинами трималася жорстко: на жорсткій зчіпці або частково піднявши авто на платформу. Трос на слизькій дорозі заборонений.","Ожеледиця — тільки «жорсткі» способи: штанга або платформа. Трос — ні."],
"o23-9":["Тягнути одразу дві чи більше машин зазвичай не можна. Виняток — коли це заздалегідь погоджено з відповідним підрозділом Національної поліції.","Більше однієї машини на буксирі — тільки з погодження поліції."],
"o23-10":["Якщо кермо не працює, машину не можна тягнути ні на тросі, ні на жорсткій зчіпці — вона не зможе повертати. Тому частину її піднімають на платформу чи опорний пристрій.","Не працює кермо — колеса в повітря: лише часткове навантаження."],
"o23-11":["Немеханічні засоби, тобто без двигуна, буксирують лише на жорсткій зчіпці: вона тримає їх на сталій відстані й не дає наїхати на машину, що тягне.","Без мотора — тільки на штанзі."],
"o23-12":["Буксирувати можна, лише коли справний зчіпний пристрій є в обох машин — і в тієї, що тягне, і в тієї, яку тягнуть. Трос чи штанга мають надійно кріпитися з обох боків.","Зчіпка — як рукостискання: потрібні дві справні руки."],
"o23-13":["На тросі між машинами має бути від 4 до 6 метрів: ближче — задня легко наїде на передню, далі — трос провисає і смикає машини.","Гнучке зчеплення: від 4 до 6 метрів — не ближче й не далі."],
"o23-14":["Трос має бути добре видно іншим водіям: або прапорці чи щитки з червоно-білими смугами через кожен метр, або покриття, що відбиває світло фар. Підходить будь-який із цих способів.","Трос має бути помітним — прапорцями або світловідбиттям, обидва способи годяться."],
"o23-15":["На тросі задня машина має сама повертати й гальмувати, бо трос її не втримає й не спрямує. Тому і кермо, і гальма в неї мають бути справні.","Трос не гальмує й не кермує — це роблять кермо і гальма задньої машини."],
"o23-16":["На тросі заборонено тягнути машину з несправними гальмами чи кермом: трос не втримає її від наїзду й не поверне. А от зламаний двигун чи паливна система — якраз звичайна причина взяти авто на трос.","Трос + машина без гальм або керма = заборона."],
"o23-17":["Жорстка штанга тримає відстань між машинами, тож проблему з гальмами частково компенсує. А от повернути колеса вона не може — тому з несправним кермом так буксирувати заборонено всім.","Штанга замінить гальма, але не кермо."],
"o23-18":["Якщо в машині не працює кермо, її не можна тягнути ні на тросі, ні на жорсткій зчіпці: вона котиться куди заманеться. Таке авто буксирують лише частково піднятим на платформу.","Немає керма — ні троса, ні штанги, тільки платформа."],
"o23-19":["За кермом буксируваної машини на жорсткій зчіпці може нікого не бути лише тоді, коли сама зчіпка змушує її точно повторювати шлях передньої машини на будь-якому повороті.","Немає водія — зчіпка має кермувати за нього: слід у слід."],
"o23-20":["Буксирувати машину з причепом правила не забороняють — треба лише дотримуватися звичайних вимог до буксирування.","Причіп — не перешкода: буксирувати машину з ним можна."],
"o24-1":["На автомагістралі (зелений знак) і на дорозі для автомобілів (синій знак з машиною) вчитися кермувати заборонено: там швидкий рух, а учень може розгубитися.","Зелена магістраль і синя «машинка» — не для учнів: там їздять ті, хто вже вміє."],
"o24-2":["Знак житлової зони — це двір, де люди ходять просто по дорозі, а діти граються. Навчальна їзда тут заборонена, навіть якщо тут пролягає навчальний маршрут.","Де діти грають у м’яч — там не вчаться кермувати."],
"o24-3":["Знак 4 — дорога зі смугою для маршрутних автобусів, знак 5 — рух легковиків. На таких дорогах учитися можна. А магістраль (1), дорога для автомобілів (2) і житлова зона (3) для навчальної їзди закриті.","Зелена магістраль, синя «машинка» і двір — не для учнів. Решта — можна."],
"o24-4":["Навчальна їзда заборонена на автомагістралі (знак 1), на дорозі для автомобілів (знак 2) і в житловій зоні (знак 3). На дорозі зі смугою для автобусів (4) і за знаком руху легковиків (5) учитися можна.","Швидкі траси й двори з дітьми — не для учнів: знаки 1, 2 і 3."],
"o24-5":["Щоб сісти за кермо навіть як учень, треба бути здоровим, і це підтверджує дійсна медична довідка. Вміти вже щось кермувати не потрібно — для того й навчання.","Спершу довідка від лікаря — потім педалі."],
"o24-6":["Перші уроки водіння проходять там, де немає інших машин і пішоходів: на закритому майданчику чи автодромі. Спершу треба відчути авто, а вже потім виїжджати в місто.","Спершу майданчик — потім вулиця. Як плавати вчаться спершу на мілкому."],
"o24-7":["Навчальна машина з механікою має додаткові педалі для інструктора (зчеплення, гальмо, а де можливо — газ), окреме дзеркало для нього та знаки «Навчальний транспортний засіб». Потрібне все це разом.","Навчальне авто: педалі й дзеркало для інструктора плюс табличка «Навчальний». Обидва варіанти правильні."],
"o24-8":["Навчальний автомобіль має бути обладнаний усім одразу: знаками «Навчальний транспортний засіб», додатковими педалями й окремим дзеркалом для інструктора. Так інструктор бачить дорогу й може зупинити машину.","Знак, педалі, дзеркало — повний комплект, усі три варіанти."],
"o24-9":["Учитися кермувати на дорозі можна лише поруч зі спеціалістом з підготовки водіїв. Досвідчений знайомий чи родич, навіть з великим стажем, його не замінить.","Учень за кермом — інструктор поруч. Тато зі стажем — не інструктор."],
"o24-10":["Початкове навчання проводять на закритому майданчику, автодромі або там, де взагалі немає інших учасників руху. Підходить будь-яке з цих місць, а дорога навіть зі слабким рухом — ще ні.","Перші уроки — там, де нікого немає: майданчик, автодром чи пусте місце."],
"o24-11":["Учень за кермом — такий самий учасник руху, як і всі. Він обов’язково має знати правила й виконувати їх, навіть коли поруч інструктор.","Навчаєшся кермувати — правила вже діють і для тебе."],
"o24-12":["Вчитися кермувати автомобілем дозволено з 16 років — разом зі спеціалістом з підготовки водіїв.","Солодкі 16 — час сідати за кермо з інструктором."],
"o24-13":["Учень зобов’язаний знати правила дорожнього руху й дотримуватися їх. Без знання правил виїжджати на дорогу навіть з інструктором небезпечно.","Спершу правила в голові — потім кермо в руках."],
"o24-14":["Учень — такий самий водій, як усі: пристібатися треба завжди, і в місті теж. Ремінь безпеки рятує навіть на невеликій швидкості.","Спершу клац ременя — потім рушай."],
"o25-1":["Якщо колону ніхто не супроводжує, кожна машина в ній має знак «Колона» спереду й ззаду та вмикає ближнє світло фар. Денних ходових вогнів тут не досить.","Без супроводу колона позначає себе сама: знак «Колона» + ближнє світло."],
"o25-2":["Коли колону супроводжують машини з маячками, знак «Колона» не обов’язковий — її і так помітно. Кожна машина колони просто вмикає ближнє світло фар.","Попереду маячки — досить ближнього світла."],
"o25-3":["Колона має їхати в один ряд якомога правіше, щоб не заважати іншим. Але коли її супроводжують машини з маячками, це обмеження не діє.","Без супроводу — один ряд біля правого краю. З маячками — виняток."],
"o25-4":["Швидкість колони й відстань між машинами задає старший колони або їх визначають за тим, як їде головна машина. В обох випадках — у межах правил на цій ділянці дороги.","Колона рівняється на старшого або на «голову»."],
"o25-5":["Колона без супроводу їде в один ряд біля правого краю й ділиться на групи до п’яти машин із проміжками між ними, щоб інші могли обганяти її частинами.","Колона — як потяг із вагонами: групи до п’яти машин і розриви для обгону."],
"o25-6":["Коли колона зупиняється на дорозі, кожна її машина вмикає аварійну сигналізацію. Так усі бачать, що ці машини стоять, і об’їжджають їх обережно.","Колона стала — аварійка заблимала."],
"o25-7":["Чужій машині не можна вклинюватися в колону, яку ніхто не супроводжує, і їхати в ній постійно — це розриває колону й заважає їй рухатися разом.","Колона — одна команда: чужим у строю не місце."],
"o25-8":["Стати в проміжок між машинами колони можна лише тимчасово, коли обганяєш її частинами. Їхати в колоні постійно не можна.","У розрив колони — лише на хвилинку, під час обгону."],
"o26-1":["Житлова зона — це двори й ділянки, позначені знаком 5.34: синій знак із будинком, машиною, пішоходом і дитиною з м’ячем. Знак 5.53 із силуетом будинків до житлової зони стосунку не має.","На знаку житлової зони намальоване все життя двору: дім, авто, пішохід і дитина з м’ячем."],
"o26-2":["Виїзд із житлової зони — як виїзд із двору: поступаєшся тим, хто рухається дорогою. Тут це пішохід, який переходить, і жовтий автомобіль, що наближається.","З житлової зони виїжджають як із двору: спершу пропусти, потім їдь."],
"o26-3":["У пішохідну зону можуть заїжджати машини, що обслуговують людей і підприємства всередині неї, авто тих, хто там живе чи працює, і машини зі знаком «Водій з інвалідністю». Правильні всі три варіанти.","У пішохідну зону — лише «свої»: обслуга, мешканці й водії з інвалідністю."],
"o26-4":["На синьому авто знак «Н» — за кермом учень, а довкола житлова зона. Навчальна їзда тут заборонена: у дворах люди ходять дорогою, а діти граються.","Буква «Н» на авто і двір із дітьми — несумісні."],
"o26-5":["Виїзд із пішохідної зони — як виїзд із двору: поступаєшся всім, хто на дорозі. Тут це пішохід, що переходить, і жовтий автомобіль, який їде дорогою.","Із зони виїжджаєш останнім: спершу пішохід і машина, потім ти."],
"o26-6":["У житловій і пішохідній зонах пішоходи можуть ходити просто по дорозі, і водій завжди має їх пропускати. Тут головні люди, а машина — гість.","У дворі машина — гість, пішохід — господар."],
"o26-7":["Їхати через житлову зону навпростець, аби скоротити шлях, заборонено. Заїжджати туди можна лише тоді, коли тобі потрібно саме туди.","Двір — не дорога-навпростець: заїжджай лише в справах."],
"o26-8":["У житловій зоні не можна стояти з увімкненим двигуном і їхати через неї транзитом. А от пішоходам ходити по проїжджій частині там якраз дозволено.","У дворі мотор глушать і навпростець не їздять. Пішоходам по дорозі — можна."],
"o26-9":["У житловій і пішохідній зонах пішоходи можуть іти проїжджою частиною в будь-який час доби. Головне — не заважати машинам без потреби.","Пішохід у дворі — господар, але чемний: іде дорогою, не заважаючи без причини."],
"o26-10":["У житловій і пішохідній зонах пішоходи можуть ходити і тротуарами, і просто дорогою — навіть коли тротуар поруч є.","Двір — територія пішоходів: і тротуар, і дорога їхні."],
"o26-11":["У житловій зоні машину ставлять лише там, де спеціально відведено місце для стоянки. Залишати авто де заманеться не можна, навіть якщо воно нікому не заважає.","У дворі є відведене місце — став туди. Немає — шукай далі."],
"o26-12":["Зелене авто стоїть на тротуарі просто біля арки, що веде у двір. Так воно заважає пішоходам і загороджує проїзд, тому ставити машину отак заборонено.","Арка й тротуар — для проходу, не для парковки."],
"o26-13":["Правила житлової зони діють у будь-якому дворі, навіть якщо знака на в’їзді немає. Двір уже сам по собі вважається житловою зоною.","Двір — це завжди житлова зона, зі знаком чи без."],
"o27-1":["На автомагістраль можна виїжджати й новачкам зі стажем до двох років, і важким вантажівкам понад 3,5 т. А тракторам і самохідним машинам туди не можна — вони надто повільні.","Магістраль — для швидких: новачок і вантажівка — так, трактор — ні."],
"o27-2":["Машинам, які не можуть їхати хоча б 40 км/год — через конструкцію чи несправність, — на автомагістраль не можна. Вони стали б небезпечною перешкодою для швидкого потоку.","Не тягне машина 40 — магістраль не для неї."],
"o27-3":["На автомагістралі не можна їхати заднім ходом, а ще туди не пускають трактори, самохідні машини й велосипеди. Причіп чи буксирування самі по собі там не заборонені.","Магістраль — тільки вперед і тільки швидкі: ні задньої, ні тракторів, ні велосипедів."],
"o27-4":["На дорозі для автомобілів (синій знак з машиною) зупинятися будь-де не можна, навіть на узбіччі. Лише на майданчиках зі знаками «Місце відпочинку» або «Місце для стоянки».","Швидка дорога — зупинка лише там, де є знак стоянки чи відпочинку."],
"o27-5":["Розриви в розділювальній смузі на автомагістралі зроблені для службової техніки, а не для звичайних водіїв. Розвертатися через них заборонено — навіть якщо дорогу добре видно.","Технологічний розрив — двері для службових машин, не для тебе."],
"o27-6":["Переходити автомагістраль пішоходам можна лише підземним або надземним переходом. Машини там надто швидкі, щоб переходити по асфальту.","Магістраль переходять тільки згори або знизу — ніколи по асфальту."],
"o27-7":["На дорозі для автомобілів заборонено все перелічене: їхати заднім ходом, вчитися кермувати, зупинятися поза спеціальними місцями й виїжджати тракторами чи самохідними машинами.","Дорога для автомобілів — майже магістраль: ті самі суворі заборони."],
"o27-8":["Хто виїжджає на автомагістраль чи дорогу для автомобілів, завжди пропускає тих, хто вже по ній їде, — навіть якщо знака «Дати дорогу» немає.","На швидку дорогу вливаються, а не вриваються: спершу пропусти потік."],
"o27-9":["Учитися кермувати на автомагістралі не можна ні вдень, ні вночі: швидкості там великі, а помилка учня може коштувати дуже дорого.","Магістраль — для тих, хто вже вміє, а не для уроків."],
"o27-10":["На автомагістралі заборонено їхати заднім ходом за будь-яких умов. Пропустиш потрібний з’їзд — їдь до наступного.","З’їзд позаду — не задкуй, а їдь до наступного."],
"o27-11":["Розвертатися на автомагістралі заборонено, навіть якщо дорогу добре видно. Щоб змінити напрямок, треба доїхати до розв’язки.","На магістралі розвертаються тільки на розв’язках."],
"o27-12":["На автомагістралі зупинятися можна лише на майданчиках зі знаками «Місце відпочинку» або «Місце для стоянки». Просто узбіччя для цього не годиться.","Магістраль — зупинка лише там, де знак обіцяє відпочинок або стоянку."],
"o27-13":["Якщо довелося вимушено зупинитися на швидкій дорозі, треба і позначити машину — аварійкою, знаком аварійної зупинки чи червоним ліхтарем, — і постаратися прибрати її з проїжджої частини праворуч.","Вимушена зупинка на магістралі: засвітись і з’їдь праворуч — обидва кроки."],
"o28-1":["На гірських дорогах заборонено буксирувати на тросі: на крутих спусках задня машина може наздогнати передню. Жорстка зчіпка й часткове навантаження там дозволені.","Гори і трос — не друзі: на спуску трос не тримає відстань."],
"o28-2":["Коли на гірській дорозі важко роз’їхатися, поступається той, хто їде вниз. Тому, хто їде вгору, зупинитися й рушити знову на підйомі значно важче.","Вниз — поступаєшся, вгору — їдеш. Тому, хто дереться вгору, важче рушити."],
"o28-3":["Перевагу на вузькій гірській дорозі має той, хто їде вгору: зупинитися й рушити знову на підйомі йому важче, ніж тому, хто спускається.","Хто дереться вгору — той і головний."],
"o28-4":["Ти їдеш униз, і перешкода саме на твоїй смузі — отже, поступатися маєш ти. Пропусти зустрічну машину, а потім об’їжджай перешкоду.","Їдеш униз чи перешкода на твоєму боці — пропускаєш ти."],
"o28-5":["У горах не можна їхати з вимкненим двигуном чи накатом — з вичавленим зчепленням або на нейтралі. Тоді двигун не допомагає гальмувати, і на спуску легко втратити контроль.","У горах ніякого «накату»: двигун працює, передача увімкнена."],
"o28-6":["На гірській дорозі двигун має працювати, а зчеплення й передача — бути увімкнені. Так двигун допомагає гальмувати на спуску, і машина не котиться неконтрольовано.","Гори: мотор, зчеплення й передача — усе ввімкнене разом."],
"o28-7":["У горах буксирувати можна лише на жорсткій зчіпці або частково піднявши авто на платформу. Трос заборонений: на спусках він не втримає відстань між машинами.","У горах — лише «жорсткі» способи: штанга або платформа."],
"o28-8":["Гірська дорога в ожеледицю — надто небезпечне поєднання, тож буксирувати там заборонено будь-яким способом.","Гори + лід = жодного буксирування."],
"o29-1":["Щоб виїхати за кордон на авто, потрібні і документи на машину, і посвідчення водія, що відповідають міжнародній Конвенції про дорожній рух. Обидва варіанти правильні.","За кордон — два документи міжнародного зразка: на себе і на машину."],
"o30-1":["Трикутник із червоною облямівкою та літерою «Ш» означає, що на авто шиповані шини. Так попереджають водіїв позаду, щоб тримали більшу дистанцію.","«Ш» — шипи."],
"o30-2":["Знак «Таксі» — шашечки — може стояти на даху машини або на її боці. Підходить будь-яке з цих місць.","Шашечки таксі — зверху чи збоку, обидва місця годяться."],
"o30-3":["Червоно-білі смугасті таблички ставлять на машини для дорожніх робіт і на авто незвичної форми. Смуги одразу привертають увагу й попереджають: об’їжджай обережно.","Смугасті таблички — на дорожній техніці й машинах дивної форми."],
"o30-4":["Водії зі стажем до двох років ставлять на авто третій знак — червоне коло з обмеженням швидкості. Він показує іншим, що новачок їде не так швидко, як решта.","Новачок — це коло з обмеженням швидкості: їде повільніше за інших."],
"o30-5":["Квадрат із червоно-білими смугами чіпляють на вантаж, що виступає за габарити машини далі, ніж дозволяють правила. Так інші водії бачать, де закінчується вантаж.","Вантаж стирчить — смугастий квадрат на кінці."],
"o30-6":["Зелений хрест на синьому квадраті — знак «Лікар». Його ставлять на машини, що належать лікарям: так інші розуміють, що власник авто — медик.","Зелений хрест — машина лікаря: важливо, кому авто належить."],
"o30-7":["Помаранчева прямокутна табличка означає, що машина везе небезпечний вантаж — наприклад, пальне чи хімію. Біля такої машини потрібна особлива обережність.","Помаранчевий — колір тривоги: везу небезпечне."],
"o30-8":["Знак із людиною у візку ставлять на авто, яким керує водій з інвалідністю. Для глухих водіїв є інший знак — жовте коло з трьома чорними крапками.","Інвалідний візок на знаку — за кермом водій з інвалідністю."],
"o30-9":["Водіїв з інвалідністю позначає перший знак — синій квадрат із людиною у візку. Жовте коло з крапками — для глухих водіїв, зелений хрест — для лікарів.","Візок на знаку — водій з інвалідністю. Усе просто: що намальовано, те й означає."],
"o30-10":["Жовта табличка з червоною облямівкою й фігурками дітей означає, що машина везе організовану групу дітей. Біля такого авто потрібна особлива увага.","Біжать діти на табличці — в салоні організована група дітей."],
"o30-11":["Глухих або глухонімих водіїв позначає перший знак — жовте коло з трьома чорними крапками. Сигнал клаксона такий водій може не почути.","Три крапки на жовтому — водій не чує."],
"o30-12":["Жовте коло з трьома чорними крапками ставлять на машини, якими керують глухі або глухонімі водії. Такий водій може не почути звукового сигналу.","Три крапки на жовтому — водій не чує: глухий чи глухонімий."],
"o30-13":["Номерні знаки кріплять не будь-де, а саме в місцях, які для цього передбачені на машині. Так їх добре видно, і вони нічого не закривають.","Номер має свою «прописку» — штатне місце на авто."],
"o30-14":["Якщо після ремонту чи переобладнання треба змінити дані в документах на машину, на перереєстрацію в уповноваженому органі МВС дається 10 діб від завершення робіт.","Ремонт завершено — пішов відлік: 10 діб, як десять пальців."],
"o31-1":["Білі вогні спереду, які роблять машину помітнішою вдень, — це денні ходові вогні. Габарити, ближнє світло й протитуманки мають інше призначення.","Денні ходові — назва підказує: світять удень, щоб машину бачили."],
"o31-2":["На одній осі шини мають бути однакові: або обидві з шипами, або обидві без. Інакше машину під час гальмування може повести вбік.","Одна вісь — пара близнюків: шипи або в обох, або в жодної."],
"o31-3":["Якщо в темряві не світять фари й задні габарити, їхати не можна навіть до ремонту чи стоянки: тебе не видно, і ти не бачиш дороги.","Темно й без світла — стоїш на місці."],
"o31-4":["Якщо спідометр відмовив у дорозі, спробуй полагодити його на місці. Не вийде — обережно їдь до стоянки чи ремонту з увімкненою аварійкою або знаком аварійної зупинки ззаду.","Не бачиш швидкості — увімкни аварійку й їдь на ремонт."],
"o31-5":["Протитуманні фари — необов’язкове обладнання, тож без них їздити можна. А от збиті фари чи невідповідні розсіювачі сліплять інших і погано світять — з таким їздити не можна.","Протитуманки — бонус, а не обов’язок."],
"o31-6":["Аптечка, вогнегасник і знак аварійної зупинки мають бути в кожному легковику. А противідкатні упори для легкового авто не обов’язкові.","Легковику — аптечка, вогнегасник і трикутник. Упори — для важких машин."],
"o31-7":["На одній осі шини мають бути з однаковим малюнком протектора. Різні шини по-різному тримають дорогу, і машину може повести вбік.","На одній осі — шини-близнюки з однаковим малюнком."],
"o31-8":["Зламаний склопідйомник на безпеку не впливає, тож їздити можна. А от несправні запори паливних баків, регулювання сидіння водія чи обдув скла вже заважають безпечно їхати.","Склопідйомник — для зручності, не для безпеки."],
"o31-9":["Якщо не світять фари й задні габарити, їхати не можна ні в темряві, ні коли погано видно — у туман, дощ чи снігопад. В обох випадках тебе важко помітити.","Темно чи туман — без світла ні метра."],
"o31-10":["Без склопідйомника їздити можна — це лише зручність. Склоочисники й склообмивачі потрібні, щоб бачити дорогу, тож несправні вони — привід не їхати.","Двірники й омивач — для очей водія, склопідйомник — для комфорту."],
"o31-11":["Під час дощу чи снігу далі їхати не можна, якщо не працює двірник з боку водія — ти просто не бачитимеш дороги. Тоді треба зупинитися.","Дощ, а двірник перед тобою стоїть — стоїш і ти."],
"o31-12":["Якщо не працює покажчик температури охолоджувальної рідини, їздити можна — безпеці руху це не загрожує. А надмірна димність, протікання пального чи несправний вихлоп — привід не виїжджати.","Термометр мотора — підказка, а не гальма: без нього їхати можна."],
"o31-13":["Якщо робочі гальма не можуть зупинити машину навіть на мінімальній швидкості, своїм ходом далі їхати не можна зовсім — навіть до ремонту чи стоянки.","Не гальмує навіть на повзанні — нікуди не їдеш."],
"o31-14":["Якщо кермо настільки несправне, що навіть на мінімальній швидкості не вдається повернути, рухатися далі не можна навіть до ремонту. Зі зламаним склопідйомником чи глушником такої суворої заборони немає.","Не повертає кермо навіть на повзанні — стоїш, доки не полагодиш."],
"o31-15":["З несправною системою випуску відпрацьованих газів експлуатувати машину заборонено: вихлоп може потрапляти в салон чи надмірно шуміти. А нестійкий холостий хід чи слабкий двигун — не підстава для заборони.","Дірявий вихлоп — машина на ремонт. Слабкий мотор — їздити можна."],
"o31-16":["Без покажчика температури охолоджувальної рідини легковиком їздити можна. А от несправний спідометр чи замки дверей — це вже заборона.","Термометр мотора — не обов’язковий, спідометр і замки дверей — обов’язкові."],
"o31-17":["Звуковий сигнал — обов’язковий засіб попередження, тож без нього машину експлуатувати заборонено. Несправний покажчик пального, збите запалювання чи важкий запуск такої заборони не тягнуть.","Клаксон мовчить — машина стоїть."],
"o31-18":["Двірник з боку водія конче потрібен саме під час дощу чи снігопаду: без нього скло швидко заллє, і ти не бачитимеш дороги. Тоді далі їхати заборонено.","Дощ або сніг + двірник водія не працює = стоп."],
"o32-1":["Якщо в колоні більше 5 машин з двигунами, умови й порядок її руху треба заздалегідь погодити з Національною поліцією: велика колона помітно впливає на рух інших.","Колона більша за п’ять машин — спершу погодь із поліцією."],
"o32-2":["Тягнути за раз дві чи більше машин можна лише після погодження з Національною поліцією. Звичайне буксирування однієї машини погоджувати не треба.","Одна машина на буксирі — без погоджень. Дві й більше — з поліцією."],
"o32-3":["Ставити кіоски, павільйони, рекламу чи пересувні точки торгівлі вздовж дороги, у смузі відведення, можна лише за погодженням з Національною поліцією, бо вони можуть заважати руху й огляду.","Кіоск чи реклама біля дороги — спершу погодь із поліцією."],
"o32-4":["Спеціальні звукові й світлові сигнали — сирени й маячки — можна встановлювати на машину лише за погодженням із сервісним центром МВС, тобто територіальним органом з надання сервісних послуг.","Маячки й сирени — тільки через сервісний центр МВС."],
"o32-5":["Змінювати, переносити чи відновлювати ідентифікаційні номери кузова, рами чи двигуна можна лише після попереднього погодження з сервісним центром МВС. Дозволу самого лише заводу недостатньо.","Номер кузова чи двигуна чіпаєш — спершу до сервісного центру МВС."],
"o33-1":["Синій круглий знак зі стрілкою навскіс униз ліворуч дозволяє об’їжджати перешкоду лише з лівого боку. Це не дозвіл на поворот ліворуч.","Стрілка навскіс униз — показує, з якого боку об’їхати перешкоду."],
"o33-2":["Обмеження мінімальної швидкості — синій круглий знак із числом. Його скасовує такий самий синій знак, перекреслений червоною смугою, — це знак 2.","Мінімальна швидкість — синя, тож і її кінець — синій, перекреслений."],
"o33-3":["Зелений знак із широкою дорогою та мостом над нею — початок автомагістралі. Звідси діють особливі правила, встановлені саме для магістралей.","Зелений знак — магістраль, синій з машиною — дорога для автомобілів."],
"o33-4":["Автомагістраль позначає знак 3 — зелений, із дорогою та мостом. Синій знак з машиною (1) — це лише дорога для автомобілів.","Магістраль завжди зелена."],
"o33-5":["Зелений знак магістралі, перекреслений червоною смугою, означає, що автомагістраль закінчилася й її особливі правила більше не діють.","Перекреслене — закінчене: зелений знак навскіс — кінець магістралі."],
"o33-6":["Синє авто заїжджає на дорогу з одностороннім рухом (знак із білою стрілкою вгору) і там розвертається. Після такого розвороту воно поїде назустріч потоку, тож це заборонено.","Одностороння дорога — як ескалатор: їдеш лише в один бік, назад не розвернешся."],
"o33-7":["Синій квадратний знак із білою стрілкою вгору означає дорогу з одностороннім рухом: на всій її ширині машини їдуть лише в один бік.","Квадрат зі стрілкою — вся дорога в один бік. Коло зі стрілкою — це наказ, куди їхати."],
"o33-8":["Дорогу з одностороннім рухом позначає знак 4 — синій квадрат з однією широкою білою стрілкою. Круглий знак 1 зі стрілкою — це наказ «рух прямо», а не позначення дороги.","Квадрат з однією стрілкою — дорога в один бік."],
"o33-9":["На дорозі з одностороннім рухом не можна розвертатися й задкувати, бо так поїдеш проти потоку; задній хід — лише коли інакше до місця не під’їхати. А зупинитися біля лівого краю тут можна.","Одностороння — тільки вперед: ні розвороту, ні задньої. Зупинка ліворуч — можна."],
"o33-10":["Синій круглий знак із числом — це обмеження мінімальної швидкості: їхати треба не повільніше, ніж написано. Швидше — можна, якщо дозволяють інші обмеження.","Червоне коло — «не більше», синє коло — «не менше»."],
"o33-11":["Доріжку для вершників позначає синій круглий знак 1 із вершником на коні. Трикутники з тваринами (2 і 3) лише попереджають, що звірі чи худоба можуть вийти на дорогу.","Синє коло — доріжка, червоний трикутник — попередження. Вершник у синьому — його доріжка."],
"o33-12":["На синьому круглому знаку намальовані пішоходи і велосипед — отже, ця доріжка і для тих, і для інших разом.","Що намальовано на синьому колі — те й дозволено: пішоходи плюс велосипед."],
"o33-13":["Перед ремонтною ділянкою стоїть знак зі стрілкою навскіс униз ліворуч — «Об’їзд перешкоди з лівого боку». Тож об’їжджати перешкоду треба лише ліворуч.","Стрілка показує, де об’їжджати: дивиться ліворуч — і ти ліворуч."],
"o33-14":["На острівці стоїть знак зі стрілками, що обходять його з обох боків: об’їжджати можна і праворуч, і ліворуч. Тому їхати можна як дорогою А, так і дорогою Б.","Дві стрілки в різні боки — обирай будь-яку дорогу."],
"o33-15":["Синій круглий знак зі стрілками по колу ставлять на перехресті з круговим рухом. Він вимагає об’їжджати центральну клумбу в тому напрямку, який показують стрілки.","Стрілки по колу — їдь по колу, як показують стрілки."],
"o33-16":["Синій круглий знак із легковиком дозволяє рух легковикам і мотоциклам, автобусам і маршруткам, а також вантажівкам з дозволеною максимальною масою не більше 3,5 т. Правильні всі три варіанти.","Знак з легковиком пускає не лише легковики: ще мотоцикли, автобуси й вантажівки до 3,5 т."],
"o33-17":["Синій знак із легковиком пускає на дорогу лише машини. Велосипедам, мопедам і гужовим возам туди не можна — усім трьом.","Знак з легковиком — велосипеди, мопеди й вози лишаються за бортом."],
"o33-18":["Синій знак із легковиком лише визначає, кому можна їхати цією дорогою, а не куди. Ти їдеш легковиком, тож можна рухатися в будь-якому напрямку — А, Б, В чи Г.","Знак каже «хто», а не «куди»: на легковику — будь-який напрямок."],
"o33-19":["Синій круглий знак із велосипедом позначає велодоріжку. Нею їздять велосипедисти, а пішоходи можуть іти нею лише тоді, коли поруч немає тротуару чи пішохідної доріжки.","Велодоріжка — для велосипедів. Пішохід тут гість, якщо тротуару немає."],
"o33-20":["Знак із пішоходами означає пішохідну доріжку. Іти нею може лише пішохід у білому, а велосипедистові й водієві мопеда сюди не можна.","Пішохідна доріжка — тільки для ніг: колеса лишаються за знаком."],
"o33-21":["Кінець дороги з одностороннім рухом — знак 5: та сама біла стрілка вгору, але перекреслена червоною смугою. Перекреслена стрілка в обидва боки (знак 4) — це кінець реверсивного руху.","Перекреслена одна стрілка — односторонка закінчилась."],
"o33-22":["Біла стрілка вгору, перекреслена червоною смугою, означає, що дорога з одностороннім рухом закінчилася. Далі можливий зустрічний рух.","Перекреслена стрілка — кінець односторонки, чекай на зустрічних."],
"o33-23":["Знак зі стрілкою, що вказує і вгору, і вниз, означає початок дороги з реверсивним рухом: на одній чи кількох смугах напрямок може змінюватися на протилежний.","Стрілка в обидва боки — смуга, що «перемикається» туди-сюди."],
"o33-24":["Початок реверсивної ділянки позначає знак 5 — біла стрілка, що вказує в обидва боки. Знак 2 з однією стрілкою — це дорога з одностороннім рухом.","Двоголова стрілка — смуги, що змінюють напрямок."],
"o33-25":["Кінець реверсивної ділянки — знак 2: стрілка в обидва боки, перекреслена червоною смугою. Знак 1 з перекресленою одинарною стрілкою — це кінець односторонньої дороги.","Перекреслена двоголова стрілка — реверс закінчився."],
"o33-26":["Синій знак із горизонтальною стрілкою в обидва боки попереджає, що попереду виїзд на дорогу з реверсивним рухом, де напрямок на смугах може змінюватися.","Двоголова стрілка лежить поперек — попереду дорога з реверсом."],
"o33-27":["Цей знак показує, скільки смуг на перехресті й куди можна їхати з кожної: з лівої — ліворуч і прямо, із середньої — прямо, з правої — прямо й праворуч.","Скільки стрілок — стільки смуг, а кожна стрілка підказує, куди можна."],
"o33-28":["Кількість смуг на перехресті й напрямки з кожної показує знак 1 — у ньому стрілки повертають ліворуч і праворуч. Знаки 2 і 3 показують напрямок руху смугами дороги, а не на перехресті.","Стрілки з поворотами — це про перехрестя."],
"o33-29":["Синій знак зі стрілкою між пунктирними лініями показує, куди можна їхати саме тією смугою, над якою він висить. На інші смуги він не поширюється.","Знак над смугою — правило для цієї смуги, як табличка над дверима."],
"o33-30":["На цьому знаку в одній зі смуг намальовано символ транспорту. Це означає, що смуга призначена лише для певних видів машин і лише в зазначеному напрямку.","Картинка на смузі знака — підказка, кому ця смуга."],
"o33-31":["Кінець смуги для маршрутних машин, що їдуть разом із загальним потоком, — знак 5: стрілка з автобусом, перекреслена червоною смугою. Знак 4 — кінець дороги із зустрічною автобусною смугою.","Стрілка з автобусом, перекреслена, — попутна автобусна смуга закінчилась."],
"o33-32":["Знак смуги для маршрутних машин діє лише на ту смугу, над якою висить. А якщо його поставили праворуч від дороги — лише на крайню праву смугу.","Над смугою — для цієї смуги, збоку праворуч — для правої."],
"o33-33":["Смугу для маршрутних машин і велосипедистів, що йде в одному напрямку із загальним потоком, позначає знак 4 — стрілка вгору над автобусом. Знак 1 — це зустрічна смуга для автобусів, а знак 5 — зупинка.","Стрілка над автобусом — попутна смуга для маршруток і велосипедистів."],
"o33-34":["Табличка зі стрілкою над знаком «Дати дорогу» показує, що попереду дорога з двома односторонніми проїзними частинами. На ближчій рух іде праворуч, тож ліворуч можна повернути лише в другий проїзд.","Ліворуч — лише туди, де потік іде ліворуч: у другий проїзд."],
"o33-35":["Розворот тут ніщо не забороняє. Знак «Дати дорогу» лише вимагає пропустити тих, хто їде дорогою, яку перетинаєш, а табличка зі стрілкою підказує, звідки чекати машин.","«Дати дорогу» — це «пропусти», а не «не можна»: розворот дозволено."],
"o33-36":["Табличка зі стрілкою ліворуч над знаком «Дати дорогу» означає, що дорога, яку перетинаєш, одностороння і рух там іде ліворуч. Тому праворуч не можна, а прямо, ліворуч чи розворот — можна.","Стрілка на табличці показує потік: проти нього не повертай, решта — можна."],
"o33-37":["Синя прямокутна табличка зі стрілкою вказує напрямок руху на дорозі, що перетинається, якщо там односторонній рух. Це не наказ повертати ліворуч і не напрямок головної дороги.","Стрілка на табличці — куди тече одностороння дорога попереду."],
"o33-38":["Цей знак позначає дорогу з окремою смугою, якою їздять маршрутні машини, а також мопеди, мотоцикли без бокового причепа й велосипедисти. Іншим машинам на цю смугу не можна.","Автобус на знаку — смуга для маршруток, мопедів, мотоциклів і велосипедів."],
"o33-39":["Той самий знак зі смугою для маршрутних машин, але перекреслений червоною смугою, означає кінець такої дороги. Далі окремої смуги для маршруток, мопедів, мотоциклів і велосипедистів немає.","Перекреслений автобус зі стрілками — особлива смуга закінчилась."],
"o33-40":["Табличка показує: на дорозі, що перетинається, загальний потік іде праворуч, а ліворуч — лише маршрутні автобуси своєю смугою. Тому ліворуч (В) білому авто не можна, а праворуч (А), прямо (Б) чи розворот (Г) — можна.","Ліворуч на табличці їде тільки автобус — отже, ліворуч не для тебе."],
"o33-41":["Табличка показує: на дорозі, що перетинається, загальний потік іде ліворуч, а праворуч — лише маршрутні автобуси. Тож праворуч (А) білому авто не можна, а прямо (Б), ліворуч (В) чи розворот (Г) — можна.","Праворуч на табличці їде лише автобус — отже, праворуч не для тебе."],
"o33-42":["Знак, де праворуч відгалужується ще одна смуга, повідомляє про початок додаткової смуги: це може бути смуга гальмування праворуч або додаткова смуга на підйомі. Обидва варіанти правильні.","Стрілка відгалужується праворуч — з’явилася додаткова смуга."],
"o33-43":["Знак «Зупинку заборонено» (червоний хрест на синьому) не діє на маршрутні машини, а також на таксі, коли вони саджають чи висаджують пасажирів або вантажать речі. Водіїв з інвалідністю він не звільняє.","Хрест на синьому — зупинятися не можна нікому, крім маршруток і таксі з пасажирами."],
"o33-44":["Знак «Стоянку заборонено» (одна червона смуга) не діє на таксі з увімкненим таксометром і на машини водіїв з інвалідністю зі знаком «Водій з інвалідністю». Для мешканців вулиці винятку немає.","Одна смуга — стоянки немає, крім таксі з лічильником і водіїв з інвалідністю."],
"o33-45":["Знак з однією червоною смугою забороняє лише стоянку, а зупинятися не заважає. Тому зупинитися можна в будь-якому з місць — А, Б, В чи Г.","Одна смуга — стояти довго не можна, зупинитися — можна."],
"o33-46":["Знак «Стоянку заборонено» не забороняє зупинок. Посадка й висадка пасажирів — це зупинка, тож вона дозволена.","Одна смуга на знаку забороняє стоянку, а не посадку пасажирів."],
"o33-47":["Знак заборони стоянки діє лише на тому боці дороги, де стоїть, і лише вперед від себе на вказану відстань. Він стоїть ліворуч, тож не можна ставати тільки в місці В, а в місцях А, Б і Г — можна.","Знак стоянки «працює» лише на своєму боці й лише вперед від себе."],
"o33-48":["Таблички зі стрілкою вниз означають, що тут закінчується зона заборони стоянки. Тому до знаків, у місцях А і Г, стояти не можна, а за ними — у місцях Б або В — можна.","Стрілка вниз на табличці — «тут кінець»: за знаком стояти можна."],
"o33-49":["Знак 3 з однією білою вертикальною смужкою забороняє стоянку в непарні числа місяця. Знак 4 із двома смужками — у парні.","Одна смужка — непарна одиничка, дві смужки — парна двійка."],
"o33-50":["Знак 4 — перекреслене синє коло з двома білими вертикальними смужками: стоянку заборонено в парні числа місяця. Одна смужка, як на знаку 3, — це вже непарні дні.","Дві смужки — пара, тобто парні числа. Одна смужка — непарні."],
"o33-51":["Коли поруч стоять обидва знаки — заборона стоянки в непарні та в парні числа, — машину переставляють на інший бік дороги ввечері, з 19:00 до 24:00, щоб наступного дня вже стояти правильно.","Переставляєш увечері — зранку спокійно: з 19:00 до півночі, до 24:00."],
"o33-52":["Знак «Стоянку заборонено» з табличкою відстані забороняє лише довго стояти. Коротка зупинка, щоб пасажир сів у машину, — це не стоянка, тож посадка тут дозволена.","Одна риска — стояти не можна, а зупинитися на хвилинку — можна."],
"o33-53":["Синє коло з однією червоною рискою забороняє тільки стоянку. Ненадовго зупинитися, щоб висадити людину чи забрати речі, під ним можна.","Одна риска — заборона стоянки. Хрест — заборона ще й зупинки."],
"o33-54":["Під знаком «Зупинка заборонена» висить табличка з перекресленим візком: на авто зі знаком «Водій з інвалідністю» заборона не діє — червоне стоїть правильно. Чорне стоїть на іншому боці, де знака немає.","Перекреслений візок під знаком — «крім водіїв з інвалідністю». А сам знак діє лише на своєму боці."],
"o33-55":["Знак «Зупинка заборонена» доповнює жовта суцільна лінія біля краю дороги або на бордюрі. Жовта переривчаста — це вже про заборону стоянки, а не зупинки.","Суцільна жовта — суцільна заборона: навіть на хвилинку не стаємо."],
"o33-56":["Знак «Зупинка заборонена» з табличкою відстані діє вперед від себе і лише на своєму, правому боці. Жовте авто стоїть саме там. Чорне ще не доїхало до знака, а зелене — на іншому боці.","Стрілка вгору з метрами — заборона попереду. Порушник той, хто стоїть за знаком на його боці."],
"o33-57":["Табличка зі стрілкою вниз каже, що тут зона заборони закінчується, тобто діяла вона до знака. Червоне авто стоїть саме в цій зоні. Чорне вже за знаком, а сіре й жовте — на іншому боці дороги.","Стрілка вниз — «тут заборона закінчується». Порушник той, хто стоїть перед знаком."],
"o33-58":["За містом зупинятися можна тільки на правому боці, тож біле авто ліворуч стоїть неправильно. Синє стоїть у зоні знака «Зупинка заборонена» з табличкою відстані. Фіолетове ще перед знаком — усе гаразд.","За містом стаємо лише праворуч, а одразу за хрестом із табличкою не стаємо взагалі."],
"o33-59":["Під знаком «Зупинка заборонена» немає таблички-винятку для водіїв з інвалідністю, тож заборона діє на всіх. Неправильно стоять обидва: і біле авто зі знаком, і синє.","Хрест без таблички-винятку — заборона для всіх, навіть зі знаком «Водій з інвалідністю»."],
"o33-60":["Подвійна стрілка під знаком означає, що ти вже всередині зони заборони зупинки — вона тягнеться і вперед, і назад. Тому на правому боці порушують і жовте, і зелене авто. Червоне й чорне — на іншому боці.","Стрілка в обидва боки — заборона і до знака, і після нього."],
"o33-61":["Кожен знак діє тільки на своєму боці й на вказану відстань уперед. Праворуч за знаком стоїть червоне авто, ліворуч за своїм знаком — сіре: обидва порушують. Жовте й чорне ще не доїхали до знаків.","Два знаки — два боки. На кожному порушник той, хто стоїть за знаком."],
"o33-62":["Знак стоїть праворуч і забороняє зупинку лише на правому боці, на ділянці за ним, — тобто в місці Б. Місце А ще перед знаком, а на лівому боці (В і Г) на такій міській дорозі зупинитися можна.","Знак праворуч стереже тільки правий бік: Б — ні, а А, В і Г — так."],
"o33-63":["Усі чотири знаки — заборона зупинки, стоянки, стоянки в непарні та в парні числа — діють лише на тому боці дороги, де встановлені. На протилежному боці вони нічого не забороняють.","Знаки зупинки й стоянки сторожують тільки свій бік дороги — і всі четверо однаково."],
"o33-64":["Знак «Зона» з колом заборони стоянки позначає цілий район міста, де стояти можна лише обмежений час. Платна там стоянка чи безкоштовна — значення не має.","Слово «ЗОНА» — це цілий район, а не один бік вулиці: стоянка тут з лімітом часу."],
"o33-65":["Під знаком «Дати дорогу» висить синій знак зі стрілкою праворуч — він дозволяє тільки поворот праворуч. Розворот дозволяє лише знак зі стрілкою ліворуч, тож тут — тільки праворуч.","Стрілка праворуч — і нікуди більше. Розворот буває тільки при стрілці ліворуч."],
"o33-66":["Синій знак зі стрілкою ліворуч дозволяє повернути ліворуч, а також розвернутися — розворот теж починається з лівого боку. Прямо їхати не можна.","Стрілка ліворуч — квиток і на поворот, і на розворот."],
"o33-67":["Знак «Рух ліворуч» дозволяє і повернути ліворуч, і розвернутися, бо розворот теж виконують ліворуч. Прямо чи праворуч під ним їхати не можна.","Ліва стрілка — два шляхи: ліворуч або назад, на розворот."],
"o33-68":["Тут ти перетинаєш дорогу з двома проїзними частинами. Знак «Прямо або праворуч» стоїть перед першою з них і діє тільки там: праворуч (А) або прямо. На другій знака немає — можна прямо, ліворуч і на розворот.","Знак діє лише до першої проїзної частини. За розділювальною смугою — усі напрямки відкриті."],
"o33-69":["Знак «Рух прямо або ліворуч» обов’язковий для всіх, крім маршрутного транспорту (автобусів, тролейбусів), що їде своїм маршрутом: йому можна туди, куди веде маршрут.","Маршрутка їде маршрутом, а не стрілками."],
"o33-70":["Знак «Рух праворуч або ліворуч» дозволяє легковику тільки повернути. Прямо може їхати лише автобус, що йде своїм маршрутом: на маршрутний транспорт такі знаки не поширюються.","Стрілки — для всіх, маршрут — для автобуса."],
"o33-71":["Знак «Рух праворуч або ліворуч» дозволяє повернути праворуч (А) чи ліворуч (Б), а де можна ліворуч, там можна й розвернутися (В). Заборонено лише прямо.","Стрілка ліворуч на знаку відкриває і поворот, і розворот."],
"o33-72":["Синій круглий знак із косою стрілкою вниз праворуч означає: перешкоду попереду об’їжджай тільки справа. Це не дозвіл на поворот, а підказка, з якого боку її обминути.","Коса стрілка вниз — «обминай перешкоду з цього боку», а не «повертай»."],
"o33-73":["Знак «Рух прямо» обов’язковий для всіх, крім маршрутного транспорту, що їде своїм маршрутом. Мешканці району, авто з оранжевим маячком чи зі знаком «Водій з інвалідністю» такого винятку не мають.","Синя стрілка — для всіх, крім маршрутки на своєму маршруті."],
"o33-74":["Знак «Рух прямо» стоїть на початку ділянки й діє до найближчого перехрестя. Він дозволяє їхати прямо (Б) і не забороняє звернути праворуч у двір (А). Ліворуч у двір (В) і на розворот (Г) — не можна.","Після знака «прямо» — прямо, а праворуч хіба що у двір."],
"o33-75":["Знаки «Рух прямо» стоять саме біля розриву розділювальної смуги й дозволяють тільки їхати прямо. Тому розвернутися через цей розрив не можна.","Біля розриву стоїть «тільки прямо» — отже, розвороту тут немає."],
"o33-76":["Кінець зони обмеженої стоянки позначає знак 3: той самий прямокутник зі словом «ЗОНА», але сірий і перекреслений. Перекреслення на знаку означає «тут закінчується».","Табличка «ЗОНА» перекреслена — зона скінчилася."],
"o33-77":["Знак з написом «Митниця» ставлять перед митним пунктом, біля якого обов’язково треба зупинитися. Проїжджати його без зупинки не можна.","Митниця — це стоп: без зупинки кордон не перетнеш."],
"o33-78":["Знак 1 з написами «STOP» і «контроль» забороняє проїжджати повз контрольний пункт без зупинки. Тут обов’язково зупиняються, а вже потім їдуть далі.","Написано «STOP» — значить, стоп. Слово «контроль» підказує, навіщо."],
"o33-79":["Знак «STOP контроль» стоїть перед контрольним пунктом: перед ним треба обов’язково зупинитися, а не просто пригальмувати чи чекати сигналу регулювальника.","STOP — це не «повільніше», а «зупинись»."],
"o33-80":["Сірий знак з косими рисками скасовує одразу кілька заборон, які ввели деякі заборонні знаки, наприклад обмеження швидкості чи заборону обгону. Решта знаків і загальні правила діють далі.","Сірі риски — гумка для деяких заборонних знаків, а не для всіх Правил."],
"o33-81":["Знак «Небезпека» забороняє рух далі всім без винятку — там може бути аварія, пожежа чи інша біда. Ні мешканцям, ні тим, хто обслуговує підприємства в цій зоні, проїзду немає.","DANGER — небезпека для всіх, тож перепустки немає ні в кого."],
"o33-82":["Знак «Рух прямо» стоїть перед першим проїздом ліворуч і діє тільки на цей перетин. Тож у перший проїзд повертати не можна, а в другий, що вже за знаком, — можна.","Знак «прямо» стереже лише найближчий поворот, наступний уже вільний."],
"o33-83":["Знак «Рух прямо» стоїть перед перехрестям і діє саме на нього: повернути праворуч чи ліворуч тут не можна, тільки прямо.","Одна стрілка вгору — одна дорога: прямо."],
"o33-84":["Попереду ремонт, а синій знак зі стрілкою вниз праворуч показує, що перешкоду об’їжджають тільки справа. Тож завчасно перестроюйся на праву смугу.","Стрілка показує вправо — і ти туди: у праву смугу."],
"o33-85":["Знак 2 — коричневий, з назвою церкви та стрілкою: такі знаки ведуть до пам’яток і туристичних місць. Сині знаки показують дорогу до міст і трас.","Коричневий — колір старовини: такий знак веде до пам’яток."],
"o33-86":["Табличка зі стрілками на обох кінцях показує, яка довга небезпечна ділянка або на якому відрізку діє заборонний чи інформаційний знак над нею.","Дві стрілки — «від і до»: це довжина ділянки, а не відстань до неї."],
"o33-87":["Табличка зі стрілкою вгору й метрами показує, на яку відстань діє знак заборони зупинки чи стоянки. Її ставлять з будь-яким із цих чотирьох знаків.","Стрілка вгору з метрами — спільна «лінійка» для всіх знаків зупинки й стоянки."],
"o33-88":["Табличка зі стрілкою вбік може показувати, на який напрямок діють знаки перед перехрестям, або куди звернути до об’єкта біля дороги. Тож обидва варіанти правильні.","Стрілка вбік — як вказівний палець: «знак діє туди» або «об’єкт там»."],
"o33-89":["Червона позначка на табличці означає, що знак діє лише в суботу, неділю та святкові дні. Як у календарі, де вихідні часто червоні.","Червоне — як вихідні в календарі: субота, неділя, свята."],
"o33-90":["Табличка 2 з молотками означає робочі дні: знак з нею діє в будні. Червона позначка — це вихідні та свята, а таблички з годинами чи днями тижня обмежують знак конкретним часом.","Молотки — інструмент роботи, отже робочі дні."],
"o33-91":["Табличка з вантажівкою означає, що знак діє на вантажні авто, зокрема з причепами, дозволеною максимальною масою понад 3,5 т. Легших вантажівок вона не стосується.","Намальована вантажівка — це важковаговик: понад 3,5 т."],
"o33-92":["Знак «Рух ліворуч» з табличкою вантажівки стосується тільки вантажних авто. Легковика він не обмежує: можна прямо (В), ліворуч (Б) і на розворот (А).","Табличка з вантажівкою — заборона для вантажівки, легковика вона не стосується."],
"o33-93":["Табличка з автомобілем і причепом означає, що знак діє тільки на авто з причепом. На тих, хто буксирує інше авто, вона не поширюється.","Намальовано причіп — значить, про причіп. Буксир — уже інша історія."],
"o33-94":["Табличка «STOP» з метрами попереджає, що попереду буде місце, де треба обов’язково зупинитися. Її ставлять зі знаком «STOP» або зі знаком «Дати дорогу» — тобто там, де ти пропускаєш інших, а не з «Головною дорогою».","Табличка «STOP» буває лише там, де ти поступаєшся: біля «STOP» чи трикутника, але не біля ромба."],
"o33-95":["Табличка з самими метрами, без стрілок, показує, скільки ще їхати до небезпечної ділянки, потрібного об’єкта чи місця, де почнеться обмеження. Тож обидва перші варіанти правильні.","Просто «метри» без стрілок — це «скільки ще до», а не «як довго діє»."],
"o33-96":["Знак 1 з ялинкою та столиком позначає обладнане місце відпочинку біля дороги. Кран — це питна вода, «i» — інформація, слухавка — телефон.","Ялинка й лавка — пікнік: тут можна відпочити."],
"o33-97":["Знак з потягом і годинником показує, де залізничний вокзал або пункт, де зупиняються поїзди. Тож обидва варіанти правильні.","Намальовано потяг — шукай вокзал чи зупинку поїзда."],
"o33-98":["Знак з автобусом і годинником на синьому прямокутнику показує, де автовокзал або автостанція. Звичайну зупинку автобуса позначають іншим знаком.","Автобус із годинником — розклад і каса, тобто автовокзал."],
"o33-99":["Знак на зеленому тлі з колонкою та вилкою на дроті показує електрозарядну станцію — тут заряджають електромобілі.","Зелений знак з вилкою — місце, щоб зарядити електрокар."],
"o33-100":["На знаку поруч стоять дві колонки, і одна з них зелена, «електрична». Отже, тут можна і заправитися пальним, і зарядити електромобіль.","Дві колонки — два види «їжі» для авто: пальне і струм."],
"o33-101":["Знак з фотокамерою попереджає, що тут порушення правил можуть фіксувати спеціальні технічні засоби — камери. Це не обов’язково пост поліції і не лише контроль швидкості.","Камера на знаку — «тебе знімають»: порушення фіксує техніка."],
"o33-102":["Знак зі слухавкою і написом SOS показує, де стоїть телефон для виклику аварійних служб. Звичайний телефон позначають без напису SOS.","SOS — сигнал лиха: цим телефоном кличуть допомогу."],
"o33-103":["Знак з блакитною колонкою показує газозаправну станцію — тут заправляють авто газом.","Колонка блакитна, як полум’я газової плити, — отже, газ."],
"o33-104":["Червона позначка на табличці означає вихідні: знак з нею діє в суботу, неділю та святкові дні. Будні позначають іншою табличкою — з молотками.","Червоне — святкове: субота, неділя й свята."],
"o33-105":["Помаранчевий прямокутник на табличці — позначка небезпечного вантажу. Отже, знак діє на всі транспортні засоби, що везуть небезпечний вантаж, а не лише на вантажівки.","Помаранчева табличка — як на цистерні з небезпечним вантажем: діє на кожного, хто його везе."],
"o33-106":["Табличка під знаком «Місце для стоянки» показує, що авто можна ставити частково на тротуар. Так дозволено лише легковикам і мотоциклам, тому вантажівка стоїть неправильно.","На тротуар за такою табличкою заїжджають лише легкі: легковики й мотоцикли."],
"o33-107":["Знак 4 — червоне коло з білою смугою, «цеглина»: в’їзд заборонено всім, крім маршрутного транспорту, що їде своїм маршрутом.","«Цеглина» — це стіна: заїхати не можна, хіба маршруткою."],
"o33-108":["Знаки «Діти» та «Дорожні роботи» попереджають про небезпеку, що може виникнути зненацька. Тому в населеному пункті, коли їх ставлять надовго, їх повторюють, щоб водій точно не пропустив.","Діти й ремонт — про таке нагадують двічі."],
"o33-109":["Хрест забороняє і зупинку, і стоянку, а одна риска — тільки стоянку. Отже, спільне в них одне: стояти довго не можна під обома.","Хрест — це «стоянки нема» плюс «зупинки нема». Спільне — стоянка."],
"o33-110":["Обидва знаки — квадратний зі стрілкою вгору і довгий зі стрілкою вбік — повідомляють про дорогу з одностороннім рухом: усі машини на ній їдуть в одному напрямку.","Біла стрілка на синьому прямокутнику — «вулиця в один бік»."],
"o33-111":["Знак «Прямо або ліворуч» дозволяє лівий поворот, а з ним і розворот. Заборона повороту праворуч розвороту теж не забороняє. Тож обидва знаки розворот дозволяють.","Заборонили лише праворуч — ліворуч і розворот лишилися."],
"o33-112":["На обох знаках є автобус: вони повідомляють про смугу для маршрутного транспорту. Один — про зустрічну таку смугу, другий — про попутну, тож спільне в них саме смуга для маршруток.","Автобус на знаку — смуга для маршруток. Куди вона веде — уже деталі."],
"o33-113":["Обидва знаки стрілками показують, куди можна їхати з кожної смуги. Тому спільне в них одне: вони вказують дозволені напрямки руху по смугах.","Скільки стрілок — стільки смуг, і кожна стрілка каже, куди з неї їхати."],
"o33-114":["Кінець зони стоянки позначає знак 4: синя літера P зі словом «ЗОНА», перекреслена рисками. Інші перекреслені знаки — кінець пішохідної зони, житлової зони чи населеного пункту.","Шукай літеру P у «ЗОНІ» з рисками — це кінець зони стоянки."],
"o33-115":["Таблички з видом аварії — зіткнення, перекидання, наїзд на пішохода чи велосипедиста — ставлять зі знаком 4, знаком оклику. Він попереджає про аварійно небезпечну ділянку, а табличка уточнює, що тут трапляється.","Знак оклику каже «тут небезпечно», а табличка — «ось що тут буває»."],
"o33-116":["Зі знаком оклику, що попереджає про аварійно небезпечну ділянку, можна ставити будь-яку з цих табличок: про зіткнення, перекидання, наїзд на пішохода чи на велосипедиста.","Табличок багато, знак один: усі види аварій — під знаком оклику."],
"o33-117":["Табличка «Понеділок — середа» показує дні, коли знак діє. В інші дні тижня він не працює.","Написано дні — отже, знак працює саме в ці дні."],
"o33-118":["На табличці 3 авто стоїть на дорозі вздовж тротуару, а не на ньому, — так ставити дозволено всім. Таблички, де авто частково чи повністю на тротуарі, стосуються лише легковиків і мотоциклів.","Колеса на дорозі — для всіх. Колеса на тротуарі — тільки для легких."],
"o33-119":["Такі таблички під знаками стоянки показують і те, як поставити машину (на дорозі чи на тротуарі), і те, яким авто так ставити можна. Тож правильна відповідь, де названо обидва.","Табличка-схема відповідає на два питання: «як» і «хто»."],
"o33-120":["Перекреслена хмаринка вихлопу означає, що на цій стоянці авто можна залишати лише з вимкненим двигуном. Стояти з увімкненим мотором не можна.","Перекреслений дим — став авто і глуши мотор."],
"o33-121":["Табличка 3 з перекресленою хмаринкою вихлопу показує, що авто дозволено залишати лише з вимкненим двигуном. Інші таблички — про спосіб стоянки чи вид транспорту.","Перекреслений дим із вихлопної труби — глуши мотор."],
"o33-122":["Табличка зі стрілкою донизу показує конкретну смугу, на яку діє знак чи світлофор над нею. На сусідні смуги він не поширюється.","Стрілка вниз — «ось ця смуга, під знаком»."],
"o33-123":["Табличка з хвилястою лінією доповнює знак 3, який попереджає про кілька небезпечних поворотів поспіль. На ній та сама звивиста лінія, тож пару легко впізнати.","Хвиляста лінія на табличці — пара для знака з кількома поворотами."],
"o33-124":["Табличка з монетами означає, що послуги тут платні, наприклад стоянка. Час і зону дії знака показують інші таблички.","Монети на табличці — тут доведеться платити."],
"o33-125":["Табличка з неперекресленим візком ставиться зі знаком «Місце для стоянки»: тут можуть стояти лише авто, якими керують люди з інвалідністю або які їх перевозять.","Візок + «P» — паркінг для людей з інвалідністю."],
"o33-126":["Червоно-біла смуга з шевронами показує, що прямо дороги немає і треба повертати, а синій знак дозволяє праворуч або ліворуч. Жоден з них не забороняє повернути праворуч.","Шеврони в обидва боки, стрілки в обидва боки — праворуч можна в обох випадках."],
"o33-127":["Синє коло з числом на стрілці лівої смуги задає мінімальну швидкість саме для неї на підйомі: їхати лівою смугою повільніше не можна. На правій смузі такого кола немає.","Синє коло — «не повільніше», червоне — «не швидше». Тут синє, на лівій смузі."],
"o33-128":["Знак з білою літерою «Т», у якої червоний кінець, означає тупик: дорога далі не має наскрізного проїзду. Заїхати туди можна, але проїхати наскрізь не вийде.","Біла дорога впирається в червону стіну — тупик, наскрізь не проїдеш."],
"o33-129":["Знак «Тупик» лише каже, що дорога праворуч не має наскрізного проїзду, але пріоритету не встановлює. Перехрестя рівнозначне, тож мотоцикл, що їде справа, треба пропустити.","«Тупик» — не «головна». Хто справа — той і їде першим."],
"o33-130":["Рекомендовану швидкість показує знак 2 — синій квадрат з числом. Червоне коло з числом — це заборона їхати швидше, а синє кругле — мінімальна швидкість.","Синій квадрат — порада, червоне коло — наказ."],
"o33-131":["Синій квадратний знак з числом — це порада: з такою швидкістю рекомендується їхати на цій ділянці. Обмеження максимальної швидкості позначають червоним колом.","Синій квадрат — дружня порада, а не заборона."],
"o33-132":["Початок житлової зони позначає знак 5: синій прямокутник, де разом намальовані будинок, авто і діти, що граються. Знаки з пішоходами в колі — про пішохідну зону чи доріжку.","Будинок, машина й діти з м’ячем — тут живуть люди: житлова зона."],
"o33-133":["Знак з будинком, машиною та дітьми, що граються, означає в’їзд у житлову зону — двори й вулиці, де пішоходи мають перевагу. Пішохідну зону позначають іншим знаком.","Діти граються біля авто — значить, це двір, житлова зона."],
"o33-134":["Кінець житлової зони позначає знак 2: той самий знак з будинком, авто і дітьми, але перекреслений червоною смугою.","Житлову зону закреслили — вона скінчилася."],
"o33-135":["Знак з дорослим і дитиною та написом «ЗОНА» позначає в’їзд у пішохідну зону — територію для тих, хто йде пішки. Житлову зону позначають знаком з будинком і дітьми, що граються.","Люди пішки + слово «ЗОНА» = пішохідна зона."],
"o33-136":["Знак «Тупик» зі стрілкою вгору лише каже, що дорога прямо не має наскрізного проїзду. Заборони він не встановлює, тож їхати прямо можна.","«Тупик» — попередження, а не «цеглина»: заїхати можна, проїхати наскрізь — ні."],
"o33-137":["Сині таблички з вантажівкою і стрілкою підказують, куди краще їхати вантажним авто й самохідним машинам. Це рекомендація, а не обов’язковий напрямок, тож правильні обидва перші варіанти.","Синя табличка з вантажівкою — підказка дороги, а не наказ."],
"o33-138":["Знак з розворотом і вказаними метрами позначає ділянку, де можна розвернутися, і її довжину. Повертати ліворуч у такому місці не можна — тільки розвертатися.","Зона розвороту — лише для розвороту, ліворуч звідси не звертаємо."],
"o33-139":["Знак, де ліворуч від основних стрілок відгалужується ще одна, повідомляє, що зліва починається додаткова смуга або смуга гальмування для повороту ліворуч чи розвороту.","Стрілка відгалужується вліво — з’явилася нова смуга для лівого маневру."],
"o33-140":["На знаку права стрілка вигинається й вливається в ліву — отже, права додаткова смуга або смуга розгону закінчується. Час перестроюватися лівіше.","Права стрілка «з’їжджає» вліво — права смуга зникає."],
"o33-141":["На знаку ліва стрілка вигинається й вливається в праву — отже, ліва смуга цього напрямку закінчується, а права триває далі.","Ліва стрілка звертає вправо — зникає ліва смуга, а не смуга розгону."],
"o33-142":["Знак 5: до правої стрілки знизу справа підходить коротка гілка — так позначають місце, де смуга розгону приєднується до основної смуги на одному рівні справа.","Маленький «хвостик» справа знизу — смуга розгону вливається в потік."],
"o33-143":["Знак 4: права стрілка виходить з правого нижнього кута й плавно стає поруч з лівою — так позначають додаткову смугу, що прилягає до основної справа на одному рівні.","Права стрілка приходить збоку й стає поруч — додалася смуга справа."],
"o33-144":["Знак 2 — жовтий, з червоним колом на закритій смузі та стрілкою, що переводить на ліву проїзну частину. Він показує, як об’їхати закриту ділянку на дорозі з розділювальною смугою.","Жовтий знак із закритою смугою й стрілкою вліво — об’їзд через сусідню проїзну частину."],
"o33-145":["Цей жовтий знак показує, як після об’їзду закритої ділянки повернутися на праву проїзну частину дороги з розділювальною смугою: стрілка веде праворуч, на своє місце.","Стрілка повертає вправо — «додому», на свою проїзну частину."],
"o33-146":["Знак з розвилкою, де одна гілка веде вбік до спеціальної смуги, показує аварійну зупинну смугу — сюди з’їжджають, якщо відмовили гальма.","Гальма відмовили — шукай знак із «запасним виходом» убік."],
"o33-147":["Кінець пішохідної зони позначає знак 1: той самий знак з людьми й написом «ЗОНА», але сірий і перекреслений рисками.","Пішохідна «ЗОНА» в рисках — пішохідна зона закінчилася."],
"o33-148":["Сині знаки з людиною на «зебрі» позначають пішохідний перехід — місце, де пішоходи переходять просто по проїзній частині. Підземні й надземні переходи мають свої знаки.","Людина на «зебрі» — перехід по дорозі, а не під чи над нею."],
"o33-149":["Такий знак стоїть на в’їзді в країну: він нагадує загальні обмеження швидкості в місті, за містом і на автомагістралі, а також у який період року треба вмикати денні ходові вогні чи ближнє світло.","Табличка «UKRAINE» — шпаргалка для гостей: швидкості й коли вмикати світло."],
"o33-150":["Знак 2 складається з окремих віконець, у яких цифри можна міняти, тому інформація на ньому змінюється. На інших знаках написи постійні.","Віконця з цифрами — як табло: що в них показано, те й змінюється."],
"o33-151":["Це попередній покажчик напрямків на зеленому тлі, з розв’язкою та відстанню до неї. Такий знак ставлять поза населеним пунктом.","Зелений покажчик з розв’язкою — це траса за містом."],
"o33-152":["Знак 1 — синя табличка з літерою, номером дороги та стрілкою: він показує номер маршруту й куди той веде. Знак 2 — лише номер, а знак 3 — назва населеного пункту.","Номер + стрілка = номер дороги і напрямок."],
"o33-153":["Знак із силуетом будинків позначає місце, де забудова підходить до самої дороги. Звідси максимальна швидкість обмежена до 50 км/год.","Будинки біля дороги — пригальмуй до 50 км/год."],
"o33-154":["Кінець забудови біля дороги позначає знак 4: той самий силует будинків, але перекреслений червоною рискою. Знак 5 з перекресленою назвою — це кінець населеного пункту.","Будиночки перекреслено — забудова скінчилася."],
"o33-155":["Червона табличка «Попереду встановлені нові дорожні знаки» попереджає, що далі змінено схему руху або з’явилися нові знаки, — неважливо, тимчасово чи назавжди. Тож правильні обидві відповіді.","Червона табличка «нові знаки» — дивись уважно: попереду все по-новому."],
"o33-156":["Аеропорт позначає знак 4: синій прямокутник з білим квадратом, на якому літак. Трикутник з літаком попереджає про низько летючі літаки, а «P» — про стоянки.","Літак у синьому прямокутнику — аеропорт; у трикутнику — обережно, літаки низько."],
"o33-157":["Назва населеного пункту на синьому тлі означає, що на цій дорозі міські правила руху не діють — їдеш як за містом. Якщо тло біле — міські правила діють.","Синє тло — назва лише для довідки, міські правила не діють."],
"o33-158":["Біла табличка з назвою міста означає, що ти в’їжджаєш у населений пункт і відтепер їдеш за правилами для руху в містах і селах. Якби табличка була синя, ці правила тут не діяли б.","Біла назва міста — міські правила діють. Синя — це лише назва для орієнтиру."],
"o33-159":["Синій знак з автобусом — це зупинка автобуса. Він стоїть там, де починається посадковий майданчик, на якому люди чекають, сідають в автобус і виходять з нього.","Автобус на синьому — тут починається зупинка, де чекають пасажири."],
"o33-160":["Перехід просто по дорозі позначає знак 2 — пішохід на «зебрі» в білому трикутнику. Знаки зі сходинками (1 і 3) — це переходи над дорогою чи під нею, а не по ній.","Зебра на знаку — переходять по дорозі. Сходинки — над нею чи під нею."],
"o33-161":["Чоловічок на знаку спускається сходами вниз — отже, це підземний перехід. Дорогу тут переходять під землею, а не по проїжджій частині.","Сходи вниз — перехід під землею."],
"o33-162":["Чоловічок на знаку піднімається сходами вгору — отже, це надземний перехід. Дорогу тут переходять мостом над нею.","Сходи вгору — перехід угорі, над дорогою."],
"o33-163":["Звичайний синій знак з літерою P позначає місце чи майданчик, де можна поставити машину на стоянку. Ні про дах, ні про пересадку на автобус він нічого не каже.","Просто P — просто паркінг: місце, де можна залишити авто."],
"o33-164":["Літера P під «дахом» означає криту стоянку — підземну чи надземну, наприклад паркінг у будівлі. Машина там стоїть під накриттям.","P під дахом — паркінг під дахом."],
"o33-165":["Знак стоянки з табличкою «плюс автобус» означає: тут можна залишити машину й пересісти на громадський транспорт, бо поруч зупинка маршрутних засобів.","P + автобус = залиш авто і сідай на автобус."],
"o33-166":["Напис «ЗОНА» над літерою P означає, що стоянку дозволено не в одній точці, а на цілій території — аж до знака, що цю зону завершує.","ЗОНА + P — паркуватися можна по всій зоні, а не лише біля знака."],
"o33-167":["Перекреслений знак «ЗОНА P» означає, що зона, де дозволено стоянку, закінчилася. Далі можна ставити машину лише там, де це дозволяють загальні правила.","Знак перекреслено — зона стоянки скінчилась."],
"o33-168":["Синій квадрат із числом — це лише рекомендована швидкість, порада, а не обмеження. Синє коло задає мінімальну швидкість, червоне коло і «ЗОНА» — максимальну. Тож не обмежує лише знак 1.","Квадрат радить, коло наказує."],
"o33-169":["Знак попереджає, що попереду поспіль два прилягання другорядних доріг — зліва і справа. Товста лінія — твоя дорога, вона головна, тож на обох перехрестях перевага в тебе.","Товста лінія на знаку — це ти, головна дорога; тонкі відгалуження — другорядні."],
"o33-170":["Подвійний хрест ставлять прямо перед переїздом без шлагбаума, де колій дві чи більше. Шлагбаума немає, тож дивись уважно: потяг може йти по будь-якій колії.","Два хрести — дві й більше колій, а шлагбаума немає."],
"o33-171":["Перед переїздом без шлагбаума з двома і більше коліями стоїть знак 3 — подвійний хрест. Одинарний хрест (знак 2) ставлять там, де колія одна.","Подвійний хрест — колій дві й більше."],
"o33-172":["Знаки зі смугами стоять перед переїздом по черзі: спершу з трьома смугами (знак 3), потім із двома, а найближче до рейок — з однією.","Смуги — як зворотний відлік: 3, 2, 1 — і переїзд."],
"o33-173":["Знак з трьома смугами стоїть разом із першим знаком про переїзд, з однією — разом із другим. А знаки з двома смугами — середні, тож їх ставлять самостійно, посередині між ними.","Дві смуги — в середині ряду, тому стоять самі, без «пари»."],
"o33-174":["Найближче до переїзду стоїть знак з однією смугою — знак 1. Смуг стає менше в міру наближення до рейок: три, дві, одна.","Одна смуга — останній знак: рейки вже зовсім близько."],
"o33-175":["Про нерегульований пішохідний перехід заздалегідь попереджає червоний трикутник з пішоходом на «зебрі» — знак 1. Синій квадрат (знак 3) стоїть уже на самому переході.","Трикутник попереджає заздалегідь, синій квадрат каже: «перехід тут»."],
"o33-176":["Трикутник з пішоходом на «зебрі» попереджає, що попереду нерегульований перехід — без світлофора й регулювальника. Заздалегідь зменш швидкість і приготуйся пропустити пішоходів.","Трикутник із «зеброю» — попереду перехід без світлофора: пригальмуй."],
"o33-177":["Перед ділянкою, де на дорогу можуть вибігти діти зі школи чи садочка поруч, ставлять знак 2 — трикутник із дітьми, що біжать.","Діти на знаку біжать — значить, можуть вибігти й на дорогу."],
"o33-178":["Одинарний червоно-білий хрест ставлять прямо перед переїздом без шлагбаума, де лише одна колія. Шлагбаума немає, тож переконайся, що потяга немає, і лише тоді їдь.","Один хрест — одна колія, шлагбаума немає."],
"o33-179":["Перед переїздом без шлагбаума з однією колією стоїть знак 2 — одинарний хрест. Подвійний хрест (знак 3) — для двох і більше колій.","Скільки «поверхів» у хреста, стільки колій: один хрест — одна колія."],
"o33-180":["Трикутник зі світлофором попереджає, що попереду світлофор. Він може стояти будь-де: на перехресті, на пішохідному переході чи на окремій ділянці дороги, тож правильні всі три варіанти.","Світлофор на знаку — попереду світлофор, а де саме — неважливо."],
"o33-181":["Знак попереджає про розвідний міст: на малюнку частина мосту піднята над водою. Такий міст можуть розвести, щоб пропустити судна, тож стеж за сигналами перед ним.","Піднята половинка мосту над хвилями — розвідний міст."],
"o33-182":["Про початок зустрічного руху після одностороннього попереджає знак 2 — трикутник зі стрілками, що дивляться в різні боки. Трикутник саме попереджає про небезпеку, а синій знак 4 лише інформує, що одностороння дорога скінчилася.","Стрілки в трикутнику — назустріч одна одній: попереду машини їдуть тобі в лоб."],
"o33-183":["Трикутник зі стрілками вгору і вниз попереджає: досі дорога була односторонньою, а далі машини поїдуть і назустріч тобі.","Дві стрілки в різні боки — рух знову двосторонній."],
"o33-184":["Трикутник із парканом — це шлагбаум на малюнку. Він попереджає про залізничний переїзд зі шлагбаумом.","Паркан на знаку — переїзд «з парканом», тобто зі шлагбаумом."],
"o33-185":["Перед переїздом зі шлагбаумом ставлять знак 3 — трикутник із парканом-шлагбаумом. Паровоз (знак 4) — це переїзд без шлагбаума, а трамвай і тунель — зовсім інші знаки.","Паркан — є шлагбаум. Паровоз — шлагбаума немає."],
"o33-186":["Перед переїздом без шлагбаума ставлять знак 4 — трикутник із паровозом. Шлагбаума немає, тож тобі показують сам потяг, якого треба остерігатися.","Шлагбаума немає — на знаку паровоз: чекай потяга."],
"o33-187":["Трикутник із паровозом ставлять перед будь-яким залізничним переїздом без шлагбаума — і в місті, і за містом. Трамвай і переїзд зі шлагбаумом мають свої окремі знаки.","Паровоз на знаку — шлагбаума немає, тож за потягом стеж без підказок."],
"o33-188":["Трикутник із дітьми, що біжать, ставлять там, де поруч із дорогою школа, садочок чи табір і діти можуть раптово вибігти на дорогу.","Діти на знаку біжать — значить, можуть вибігти й на дорогу."],
"o33-189":["Трикутник із велосипедом ставлять і там, де дорогу перетинає велодоріжка поза перехрестям, і там, де на дорозі можуть з’явитися велосипедисти. Тож правильні обидва варіанти — перший і третій.","Велосипед у трикутнику — чекай велосипедиста: чи з велодоріжки, чи просто на дорозі."],
"o33-190":["Попереджає про перетин з велодоріжкою червоний трикутник з велосипедом — знак 2. Сині круглі знаки 1 і 3 позначають самі доріжки, а не попереджають про них.","Трикутник попереджає, синє коло — наказує чи позначає."],
"o33-191":["Червоно-білі знаки з «галочками» показують, у який бік повертає дорога. Куди спрямовані вістря, туди й треба повертати.","Куди дивляться «галочки» — туди й поворот."],
"o33-192":["Усі ці знаки попереджають про небезпеку на дорозі, і поза населеними пунктами їх ставлять двічі, щоб ти встиг підготуватися. Тому правильна відповідь — усі зображені знаки.","За містом швидкість більша, тож попередження повторюють, щоб точно його помітити."],
"o33-193":["Поза населеними пунктами повторюють знак 1 — виїзд на набережну чи берег. Попереду вода, і помилка може закінчитися падінням машини у воду, тому попередження дають двічі.","Машина над водою — така небезпека варта двох знаків."],
"o33-194":["У населених пунктах повторюють знаки «Дорожні роботи» (знак 1) і «Діти» (знак 2). І робітники, і діти можуть з’явитися на дорозі просто перед машиною, тому попередження дають двічі.","Робітники й діти — люди на дорозі. Про них у місті попереджають двічі."],
"o33-195":["Тимчасові знаки мають жовтий фон — тут це знак 1. Такі знаки ставлять, наприклад, на час ремонту дороги, і вони важливіші за звичайні білі.","Жовтий фон — знак тимчасовий."],
"o33-196":["Знак «Дати дорогу» діє лише на нерегульованому перехресті. Якщо працює світлофор чи регулювальник, головним стає їхній сигнал, а не знаки пріоритету.","Світлофор працює — знак пріоритету відпочиває."],
"o33-197":["«Дати дорогу» не вимагає обов’язкової зупинки. Достатньо пригальмувати або зупинитися, якщо треба, щоб пропустити машини на головній дорозі. Без поступки проїжджати не можна.","Перевернутий трикутник — пропусти; знак «STOP» — зупинись обов’язково."],
"o33-198":["Знак «Дати дорогу» не змушує зупинятися щоразу: якщо на головній нікого немає, можна проїхати, лише пригальмувавши. Зупинка потрібна тільки тоді, коли інакше не вийде пропустити інших.","Перевернутий трикутник каже «пропусти», а не «стій». Стояти обов’язково велить лише STOP."],
"o33-199":["Хрести — одинарний і подвійний (знаки 1 і 2) — стоять прямо біля переїзду без шлагбаума, тобто безпосередньо перед небезпечним місцем. Бачиш хрест — рейки вже поруч.","Хрест — це вже поріг переїзду: рейки одразу за ним."],
"o33-200":["Знак крутого спуску (знак 1) можна поставити прямо на початку спуску — наприклад, коли спуски й підйоми йдуть один за одним і попередити заздалегідь просто ніде.","Спуск за спуском — знак стоїть прямо на краю схилу."],
"o33-201":["Корова на знаку означає, що тут на дорогу може вийти домашня худоба — наприклад, коли її женуть на пасовище. Для диких тварин є окремий знак з оленем.","Корова — худоба, олень — дикі тварини."],
"o33-202":["Олень на знаку попереджає, що тут дорогу можуть перебігати дикі тварини, найчастіше біля лісу. Для худоби є окремий знак з коровою.","Олень на знаку — чекай «гостей» з лісу."],
"o33-203":["Робітник з лопатою на знаку попереджає саме про дорожні роботи попереду. Для нерівної дороги чи обмеження руху є інші знаки.","Людина з лопатою — на дорозі працюють."],
"o33-204":["Якщо роботи короткочасні й ідуть у місті, знак «Дорожні роботи» можна поставити зовсім близько — за 10—15 м до місця робіт. Тож пригальмуй одразу, щойно побачиш знак.","Короткі роботи — короткий відступ: лише 10—15 м."],
"o33-205":["Знак із вервечкою машин попереджає про затор: попереду дорога звужується, і через це машини скупчуються. Знизь швидкість заздалегідь, щоб не наздогнати хвіст затору надто швидко.","Машини на знаку стоять одна за одною — попереду затор."],
"o33-206":["Чорна крапка в трикутнику (знак 2) попереджає про місце, де часто стаються аварії. Тут їдь особливо уважно і не поспішай.","Чорна крапка — «чорна пляма» на карті аварій."],
"o33-207":["Трикутник зі знаком оклику попереджає про ділянку, де сама дорога зроблена не за нормами: надто крутий поворот, різкий перепад висоти тощо. Тому їдь обережніше, ніж зазвичай.","Знак оклику — «увага: дорога тут не така, як має бути»."],
"o33-208":["Знак, де машина з’їжджає з рівного покриття на ґрунт, попереджає: тут закінчується дорога з твердим покриттям і починається гравійна чи ґрунтова. Знизь швидкість заздалегідь.","Асфальт закінчується — попереду ґрунтовка."],
"o33-209":["Якщо перед тобою «Дати дорогу», то дорога, яку ти перетинаєш, — головна. На ній стоїть знак 2 «Головна дорога» — жовтий ромб.","Тобі — трикутник «поступись», іншим — жовтий ромб «головна»."],
"o33-210":["Знак попереджає про два прилягання другорядних доріг поспіль — справа і зліва. Ти їдеш по головній, тож перевага твоя на обох перехрестях, а зелене авто справа має тебе пропустити.","Товста лінія — твоя головна, обидва тонкі відгалуження поступаються тобі."],
"o33-211":["Дорожні роботи — це не лише будівництво чи ремонт самої дороги, мостів і водовідводу, а й встановлення та заміна знаків, світлофорів, огорож. Тож правильні обидва варіанти.","Дорожні роботи — все, що роблять із дорогою: від асфальту до знаків."],
"o33-212":["Знак зі стрілками в обидва боки показує, що далі дорога розходиться ліворуч і праворуч: на Т-подібному перехресті, на розгалуженні чи на об’їзді ремонту. Про звуження він не говорить.","Галочки в обидва боки — дорога розходиться: ліворуч або праворуч."],
"o33-213":["Напрямок повороту показує знак 3 — червоний прямокутник з білою «галочкою». Трикутники 1 і 2 лише попереджають про небезпечні повороти, а галочка показує, куди саме кермувати.","Галочка — як стрілка: куди вістря, туди й поворот."],
"o33-214":["Обидві лінії на знаку сходяться до середини — отже, попереду дорога звужується з обох боків. Проїжджай це місце обережно.","Обидві лінії стискаються — дорогу «стискає» з двох боків."],
"o33-215":["Про звуження справа попереджає знак 2: ліва лінія на ньому пряма, а права заходить усередину. Знак 1 — звуження з обох боків, знак 3 — зліва.","Котра лінія «ламається» — з того боку й звуження."],
"o33-216":["На знаку ліва лінія заходить усередину, а права йде рівно — отже, дорога звужується зліва.","Котра лінія «ламається» — з того боку й звуження."],
"o33-217":["Крутий підйом позначає знак 1 — схил на ньому йде вгору зліва направо. На знаку 2 він іде вниз, тобто це крутий спуск.","Читай знак зліва направо: схил угору — підйом, униз — спуск."],
"o33-218":["Крутий спуск позначає знак 2 — схил на ньому йде вниз зліва направо. Знак 1 зі схилом угору — це крутий підйом, а смугаста табличка (знак 3) стосується залізничного переїзду.","Читай знак зліва направо: схил униз — спуск, угору — підйом."],
"o33-219":["Схил на знаку йде вгору зліва направо — отже, попереду крутий підйом. Знак спуску виглядає дзеркально: схил там іде вниз.","Читай знак зліва направо: схил угору — підйом."],
"o33-220":["Довгий знак із білими «галочками» ставлять на повороті дороги, щоб показати, в який бік вона завертає. Тут вістря дивляться ліворуч — отже, і поворот ліворуч.","Куди дивляться галочки — туди й завертає дорога."],
"o33-221":["Такі «галочки» ставлять на поворотах, де погано видно, куди йде дорога, а також на круговому перехресті — щоб показати, як об’їжджати центр. Тож правильні обидва ці варіанти.","Галочки ведуть там, де дорогу важко розгледіти: на повороті чи навколо кола."],
"o33-222":["Лінія на знаку загинається праворуч — це попередження про небезпечний поворот праворуч. Пригальмуй заздалегідь, ще до повороту.","Куди загинається лінія — туди й поворот."],
"o33-223":["Лінія на знаку загинається ліворуч — це попередження про небезпечний поворот ліворуч. Пригальмуй заздалегідь, ще до повороту.","Куди загинається лінія — туди й поворот."],
"o33-224":["Про небезпечне заокруглення, за яке погано видно, попереджає знак 4 — трикутник із лінією, що загинається. Знак 1 — прилягання дороги, знак 2 — слизька дорога, знак 3 — звуження.","Загнута лінія на знаку — дорога сама загинається, і за поворот не видно."],
"o33-225":["Попереджувальні знаки — це трикутники, тож про небезпечний поворот каже знак 3 із загнутою лінією. «Галочки» (знак 1) показують напрямок уже на самому повороті.","Попередження — завжди трикутник: тут він один, отже, знак 3."],
"o33-226":["Лінія на знаку спершу йде праворуч, а потім ліворуч — отже, попереду два небезпечні повороти, і перший з них праворуч.","Читай лінію знизу вгору: перший вигин — твій перший поворот."],
"o33-227":["Лінія на знаку спершу йде ліворуч, а потім праворуч — отже, попереду два чи більше небезпечних поворотів, і перший з них ліворуч.","Читай лінію знизу вгору: перший вигин — твій перший поворот."],
"o33-228":["Лінія на знаку спершу загинається праворуч — отже, перший поворот праворуч. А табличка з числом під знаком уточнює, що таких поворотів поспіль аж дев’ять.","Знак показує, куди перший поворот, табличка — скільки їх усього."],
"o33-229":["Перед двома небезпечними поворотами поспіль ставлять знак 2 — трикутник зі звивистою лінією. Знак 1 — це лише табличка, яка уточнює кількість поворотів під основним знаком.","Звивиста лінія в трикутнику — повороти йдуть один за одним."],
"o33-230":["Машина на краю причалу над водою — це попередження, що дорога виходить на берег водойми або набережну. Не встигнеш зупинитися — можна опинитися у воді.","Машина над хвилями — попереду вода: берег чи набережна."],
"o33-231":["Сам знак попереджає про вихід на берег чи набережну, а табличка з поромом уточнює: тут дорога веде на поромну переправу.","Знак каже «попереду вода», табличка з поромом — «а далі пором»."],
"o33-232":["Тунель на знаку попереджає про споруду без освітлення, в’їзд до якої погано видно або перед якою звужується дорога. Пригальмуй і стеж за дорогою.","Темна арка на знаку — темний тунель попереду."],
"o33-233":["Про кругове перехрестя попереджає трикутник зі стрілками по колу — знак 2. Синє коло зі стрілками (знак 1) стоїть уже на самому перехресті й наказує їхати по колу.","Трикутник — «попереду коло», синій кружок — «ти вже на колі»."],
"o33-234":["Перед перетином з трамвайною колією, де погано видно, ставлять трикутник із трамваєм — знак 2. Синій прямокутний знак із трамваєм (знак 1) — це зупинка трамвая.","Трамвай у трикутнику — попереду трамвайні рейки."],
"o33-235":["Косий хрест у трикутнику попереджає про перехрестя рівнозначних доріг: головної тут немає, тож пропускаєш тих, хто під’їжджає справа.","Рівний хрест — рівні дороги: пропускай того, хто справа."],
"o33-236":["Перед перехрестям рівнозначних доріг ставлять знак 2 — трикутник із косим хрестом. Знак 1 з товстою лінією попереджає про перехрестя з другорядною дорогою.","Рівний хрест — рівні дороги."],
"o33-237":["Товста вертикальна лінія — це твоя головна дорога, а тонка поперечна — другорядна. Отже, попереду перехрестя нерівнозначних доріг, і перевага в тебе.","Товста лінія — твоя головна дорога, тонка — другорядна."],
"o33-238":["Перехрестя з другорядною дорогою позначає знак 2: товста лінія — твоя дорога, тонка — другорядна. Косий хрест (знак 1) означає вже рівнозначні дороги.","Товста лінія — твоя дорога важливіша за тонку."],
"o33-239":["Знак перед тобою попереджає про перехрещення з другорядною дорогою: ти на головній. Тож на найближчому перехресті перевага твоя в будь-якому разі, навіть без знака «Головна дорога».","Товста лінія на знаку — уже твоя перевага, окремий ромб не потрібен."],
"o33-240":["Товста вертикальна лінія — твоя головна дорога, а коротка гілка праворуч — другорядна, що до неї прилягає. Отже, попереду перехрестя, де другорядна дорога підходить справа.","Куди стирчить гілочка — звідти й прилягає другорядна дорога."],
"o33-241":["Літак на знаку попереджає про ділянку біля аеродрому або там, де літаки чи гелікоптери пролітають низько над дорогою. Тож не дивуйся раптовому гуркоту над головою.","Літак на знаку — небо над дорогою може загуркотіти."],
"o33-242":["Смугастий «рукав» на знаку — це вітровказ. Він попереджає про сильний боковий вітер або раптові пориви, які можуть штовхнути машину вбік, тож міцніше тримай кермо.","Вітровказ на знаку — дмухатиме збоку, тримай кермо міцніше."],
"o33-243":["Жовтий знак із хвилястою лінією попереджає про нерівну дорогу: хвилі, напливи, здуття покриття. Жовтий фон означає, що знак тимчасовий.","Хвиляста лінія — хвиляста дорога."],
"o33-244":["Знак з одним горбом попереджає про бугор на дорозі: штучний «лежачий поліцейський», що змушує скинути швидкість, або напливи й нерівні стики на мостах. Тож правильні обидва ці варіанти.","Горб на знаку — горб на дорозі: пригальмуй, щоб не підкинуло."],
"o33-245":["Западина на знаку — це вибоїна. Знак попереджає про ями чи просідання покриття, тож знизь швидкість, щоб не пошкодити колеса й підвіску.","Горб угору — бугор, ямка вниз — вибоїна."],
"o33-246":["Про вибоїни й просідання покриття попереджає знак 3 — на ньому видно ямку в дорозі. Знак 1 — це бугор, а знак 2 — хвиляста нерівна дорога.","Ямка на знаку — яма на дорозі."],
"o33-247":["Про слизьку дорогу попереджає знак 2 — машина, яку заносить, і звивисті сліди шин за нею. На такій ділянці гальмуй плавно й не поспішай.","Звивистий слід за авто — машину заносить: слизько!"],
"o33-248":["Машина, з-під коліс якої летить каміння, попереджає: тут гравій чи щебінь може вилітати з-під коліс. Тримай більшу дистанцію, щоб камінець не розбив скло.","Каміння з-під коліс на знаку — бережи скло, тримай дистанцію."],
"o33-249":["Машина, що нахилилася на краю дороги, попереджає про небезпечне узбіччя: воно вище чи нижче за дорогу, зруйноване або там ідуть ремонтні роботи. З’їжджати на нього небезпечно.","Машина нахилилась на краю — узбіччя ненадійне."],
"o33-250":["Каміння, що котиться зі схилу, попереджає: тут можливі падіння каміння, обвали та зсуви. Стеж, чи немає на дорозі каміння.","Каміння падає зі скелі — може впасти й на дорогу."],
"o33-251":["Товста лінія — твоя головна дорога, а коротка гілка ліворуч — другорядна. Отже, попереду до твоєї дороги зліва прилягає другорядна.","Куди стирчить гілочка — звідти й прилягає другорядна дорога."],
"o33-252":["«Дати дорогу» з табличкою відстані — це попередження наперед: на найближчому перехресті стоїть такий самий знак, знак 1. Табличка лише показує, скільки до нього їхати.","Трикутник із табличкою відстані — анонс: попереду такий самий трикутник."],
"o33-253":["Знак із конем і возом забороняє рух гужових возів і саней, а також тварин під сідлом чи з в’юком і прогін худоби. Пішоходів він не стосується.","Кінь із возом під забороною — і всі тварини з ним, а пішоходи йдуть далі."],
"o33-254":["Знак забороняє поворот праворуч лише на перехрещенні, перед яким стоїть, — це поворот В. Їхати прямо (А) він не забороняє, як і поворот Б далі.","Знак повороту діє лише на «своєму» перехрещенні, а не на всіх поспіль."],
"o33-255":["Знак стоїть на розділювальній смузі, тобто перед перетином з дальньою проїзною частиною. Тож на ближню частину (А) повертати праворуч можна, а на дальню (Б) — ні.","Знак діє там, де стоїть: за розділювальною смугою, а не перед нею."],
"o33-256":["Знак «Поворот ліворуч заборонено» не забороняє розворот. Тож розвернутися на цьому перехресті можна, а от просто повернути ліворуч — ні.","Заборонили поворот ліворуч — розворот не заборонили."],
"o33-257":["Дорога попереду має розділювальну смугу, тобто два перехрещення проїзних частин. Знак стоїть перед ближнім, тому повернути там (А) не можна, а на дальньому (Б) — можна.","Знак повороту діє лише на перехрещенні, перед яким стоїть."],
"o33-258":["Знак стоїть перед ближньою проїзною частиною, тому повертати ліворуч на неї (А) не можна. Прямо (В) їхати можна, а поворот Б робиться вже на дальньому перехрещенні, де знак не діє.","Знак повороту діє лише на перехрещенні, перед яким стоїть."],
"o33-259":["Обидва знаки забороняють лише розворот. Повертати ліворуч вони не забороняють, тож цей маневр дозволено — головне, не перетинати суцільну лінію.","Заборонили розворот — не поворот."],
"o33-260":["Знак «Розворот заборонено» стоїть перед ближнім перехрещенням проїзних частин, тож розвернутися там (А) не можна. Розворот Б виконується на дальньому перехрещенні, де знак уже не діє.","Знак діє на перехрещенні, перед яким стоїть, а не далі."],
"o33-261":["Розворот забороняє знак 3 — перекреслена стрілка, що загинається назад. Знак 2 забороняє лише поворот ліворуч, а розвертатися з ним можна.","Перекреслений «гачок» назад — розворот заборонено."],
"o33-262":["«Цеглина» забороняє в’їзд. Її ставлять, щоб не заїжджали назустріч потоку на односторонній дорозі чи смузі для маршрутного транспорту, щоб розділити в’їзд і виїзд на стоянках і АЗС, і щоб закрити в’їзд на окрему смугу.","«Цеглина» — як стіна: сюди не в’їжджають. Причин багато, тож правильні всі варіанти."],
"o33-263":["«В’їзд заборонено» з табличкою-стрілкою вниз діє лише на ту смугу, над якою висить, — смугу зустрічного руху. Ти на неї не заїжджаєш, тож дозволено всі три напрямки.","Стрілка вниз під знаком — заборона лише для смуги під ним."],
"o33-264":["Рух машин із вибуховими й легкозаймистими вантажами забороняє знак 3 — авто, охоплене полум’ям. Знак 1 забороняє рух усіх механічних транспортних засобів, а знак 4 обмежує масу.","Вогонь над машиною — вогненебезпечний вантаж заборонено."],
"o33-265":["На знаку — машина в полум’ї: сюди не можна їхати авто, які везуть вибухові або легкозаймисті вантажі. Для інших небезпечних вантажів є окремий знак.","Вогонь над машиною — вантаж може вибухнути чи спалахнути."],
"o33-266":["Обмеження маси — це знак, де всередині лише число й літера «т»: знак 2 з написом «7т». Він не пускає машини, які разом із вантажем важать більше 7 т.","Бачиш «т» — думай про тонни, тобто вагу машини."],
"o33-267":["Знак перед мостом обмежує фактичну масу. Для автопоїзда рахують вагу всього складу разом із причепом і вантажем, тож якщо він важчий за 18 т, на міст заїжджати не можна.","Міст витримує 18 т — і рахують усе: тягач, причіп і вантаж."],
"o33-268":["Знак зі стрілками, що стискають число з боків, обмежує ширину. Він стосується всіх машин без винятку — легковиків, вантажівок, автобусів, — якщо разом із вантажем вони ширші, ніж написано на знаку.","Стрілки тиснуть з боків — мова про ширину, і для всіх."],
"o33-269":["Попереду знак «В’їзд заборонено» без жодних табличок. Винятків для мешканців чи тих, хто обслуговує підприємства, він не має, тож прямо їхати не можна.","«Цеглина» — це стіна: крізь неї не проїде ніхто, навіть місцеві."],
"o33-270":["Під знаком «В’їзд заборонено» табличка зі стрілкою вниз: заборона діє лише на одну смугу — зустрічну смугу для автобусів, про яку каже синій знак праворуч. Твоя смуга вільна, тож прямо можна.","Табличка-стрілка звужує заборону до однієї смуги — решта дороги твоя."],
"o33-271":["Знак «В’їзд заборонено» з табличкою відстані — лише попередження: заборона почнеться далі по дорозі, а не тут. На цьому перехресті можна і прямо (А), і ліворуч (Б), і розвернутися (В).","Табличка з метрами каже «попереду», а не «тут» — поки що всі напрямки відкриті."],
"o33-272":["Знаки заборони повороту праворуч, ліворуч і розвороту діють лише на тому перехресті чи в тому місці, перед яким стоять. Минаєш його — і заборона закінчується.","Знак стоїть перед перехрестям — і діє саме на ньому, не далі."],
"o33-273":["Знак «Обгін заборонено» не дозволяє обганяти нікого, крім поодиноких машин, що їдуть повільніше за 30 км/год. Такого одинокого «равлика» обігнати можна.","Обганяти можна лише одинака-тихохода: менш ніж 30 км/год."],
"o33-274":["Тут діє знак «Обгін заборонено». Виняток — лише поодинока машина, що ледве повзе, а вантажівка їде 50 км/год, тож синьому авто обганяти її не можна.","50 км/год — це не тихохід. Під цим знаком обганяти не можна."],
"o33-275":["Максимальну швидкість обмежує круглий знак із червоною облямівкою й числом — знак 5. Сині круглі знаки стосуються мінімальної швидкості, а прямокутні лише інформують.","Червоне коло — «не швидше». Синє коло — «не повільніше»."],
"o33-276":["Обмеження максимальної швидкості — це знак у червоному колі з числом, знак 3. Синій знак 1 задає мінімальну швидкість, а перекреслені знаки 2 і 4 скасовують обмеження.","Червоне коло — «стеля» швидкості, синє коло — «підлога»."],
"o33-277":["Число в червоному колі — це межа швидкості: їхати швидше за неї не можна. Повільніше — будь ласка.","Червоне коло з числом — стеля для твого спідометра."],
"o33-278":["Кінець обмеження максимальної швидкості — білий знак із сірим числом, перекресленим чорними смугами, знак 4. Синій перекреслений знак 3 скасовує мінімальну швидкість, а знак 2 — заборону обгону.","Червоне обмеження «вицвіло» в сіре й перекреслене — воно закінчилося."],
"o33-279":["Кінець обмеження максимальної швидкості позначає білий знак із сірим перекресленим числом — знак 3. Синій перекреслений знак 2 — це кінець мінімальної швидкості, не плутай їх.","Сіре перекреслене число на білому — «відбій» для обмеження швидкості."],
"o33-280":["Слово «ЗОНА» над знаком означає: обмеження швидкості діє не на шматку дороги, а на всій території, куди ти в’їжджаєш, — аж до знака кінця зони.","Написано «ЗОНА» — обмеження діє на всю зону, а не на одну ділянку."],
"o33-281":["Кінець зони обмеження швидкості — прямокутний знак із написом «ЗОНА» й перекресленим числом, знак 4. Круглий перекреслений знак 3 скасовує звичайне обмеження, а не зону.","Зона починається табличкою «ЗОНА» — і закінчується нею ж, тільки перекресленою."],
"o33-282":["Знак із перекресленим ріжком забороняє сигналити. Єдиний виняток — коли без сигналу не вдасться відвернути аварію. Попереджати сигналом про обгін тут не можна.","Тут тиша — сигнал лише тоді, коли він рятує від аварії."],
"o33-283":["Знак «Обгін вантажним автомобілям заборонено» діє і на трактори. Винятку для повільних машин, як у звичайного знака заборони обгону, тут немає, тож трактор не обганяє навіть авто, що їде менш ніж 30 км/год.","Червона вантажівка на знаку — заборона для «важковиків», а трактор теж такий."],
"o33-284":["Знак із червоною вантажівкою забороняє обганяти лише важким вантажівкам — з дозволеною максимальною масою понад 3,5 т — і тракторам. Легковикам і легким вантажівкам обганяти можна.","Червоний кузов — для «важковиків» понад 3,5 т і тракторів."],
"o33-285":["Під знаком «Обгін заборонено» можна обігнати поодиноку машину, що їде повільніше за 30 км/год. Вантажівка з причепом — це один транспортний засіб, тож обігнати її дозволено.","Причіп не робить колону: одна вантажівка-тихохід менш ніж 30 км/год — обганяй."],
"o33-286":["Знак «Обгін заборонено» має один виняток — поодинокий транспорт, що повзе повільніше за 30 км/год. Тож вантажівку тут можна обігнати лише тоді, коли вона їде так повільно.","Межа цього знака — 30, а не 40: повільніше за 30 км/год — можна обганяти."],
"o33-287":["Табличка з відстанню біля знака каже, що заборона обгону почнеться лише через 500 м. Тож обганяти можна, якщо встигнеш закінчити маневр до цієї межі.","«500 м» — це відлік до заборони: закінчи обгін, поки вона не почалася."],
"o33-288":["Знак «Обгін заборонено» дозволяє обігнати лише поодинокий транспорт, що їде повільніше за 30 км/год. Авто на буксирі рухаються як одне ціле, тож сірий автомобіль може обігнати їх лише за такої швидкості.","Під знаком «Обгін заборонено» обганяють лише тихоходів: менш ніж 30 км/год."],
"o33-289":["Знак «Обгін заборонено» не дає обганяти нікого, крім поодиноких машин, що їдуть повільніше за 30 км/год. А випереджати без виїзду на зустрічну він не забороняє.","Знак про обгін, а не про випередження; виняток — одинак повільніше 30 км/год."],
"o33-290":["Знак «Обгін заборонено» стосується всіх, хто керує будь-яким транспортом, — і машиною з двигуном, і без нього. Окремих «пільговиків» за видом транспорту тут немає.","Знак без табличок — для всіх: винятків за видом транспорту немає."],
"o33-291":["Обгін усім забороняє знак із двома легковиками, червоним і чорним, — знак 4. Знак 1 з червоною вантажівкою стосується лише вантажівок і тракторів, а знак 5 забороняє рух машин із двигуном.","Два легковики — обгін заборонено всім. Червона вантажівка — лише важким."],
"o33-292":["Сірі машинки, перекреслені чорними смугами, — це кінець зони заборони обгону. Далі можна знову обганяти за звичайними правилами.","Кольорові машинки «вицвіли» й перекреслені — заборона обгону скінчилась."],
"o33-293":["Зупинку забороняє синій знак із червоним хрестом — знак 5. Знак з однією косою смугою (знак 4) забороняє лише стоянку, а зупинитися під ним можна.","Хрест — ні зупинитися, ні стояти. Одна риска — лише без стоянки."],
"o33-294":["Восьмикутний червоний знак «STOP» вимагає обов’язково зупинитися перед перехрестям чи переїздом, навіть якщо нікого немає. Трикутник (знак 3) лише велить дати дорогу.","Вісім кутів — «стоп» без варіантів: колеса мають зупинитися."],
"o33-295":["Перевагу зустрічним на вузькій ділянці дає круглий знак у червоному колі з чорною й червоною стрілками — знак 3. Синій квадратний знак 1, навпаки, дає перевагу тобі.","Червоне коло — ти поступаєшся. Синій квадрат — поступаються тобі."],
"o33-296":["Цей знак ставлять там, де дорога вузька і двом зустрічним машинам важко роз’їхатися. Він велить пропустити зустрічних першими.","Твоя стрілка червона, як «стоп»: на вузькому місці спершу їдуть зустрічні."],
"o33-297":["Перед звуженням стоїть тимчасовий знак «Перевага зустрічного руху» на жовтому фоні. Тож ти пропускаєш жовте авто й лише потім проїжджаєш вузьке місце.","Червоне коло зі стрілками — «після вас»: зустрічний їде першим."],
"o33-298":["Перед мостом у вантажівки знак, що велить пропустити зустрічних, а в легковика — синій знак переваги. Тож першим через вузький міст їде легковик.","Синій квадрат — «я перший», червоне коло — «я після тебе»."],
"o33-299":["Ці знаки стоять парою з двох боків вузького місця. Якщо в тебе знак, що велить пропускати зустрічних, то в них — синій квадратний знак переваги, знак 1.","Пара-дзеркало: у тебе червоне коло — у зустрічних синій квадрат."],
"o33-300":["Перевагу над зустрічними на вузькій ділянці дає синій квадратний знак із великою білою стрілкою вгору — знак 1. Знак 3 у червоному колі, навпаки, велить поступитися.","Твоя стрілка біла й велика — черга проїзду твоя."],
"o33-301":["Цей синій знак ставлять на вузьких ділянках, де двом зустрічним машинам важко роз’їхатися. Він каже, що перевага твоя: зустрічні мають тебе пропустити.","Велика біла стрілка вгору — «місце вузьке, але черга моя»."],
"o33-302":["На огорожі ремонту висить знак «Перевага перед зустрічним рухом». Тож хоч перешкода й на твоєму боці, перевага твоя — зустрічні мають тебе пропустити.","Знак важить більше за звичку: синій квадрат із білою стрілкою — черга твоя."],
"o33-303":["Жовтий ромб, перекреслений чорними смугами, — це «Кінець головної дороги». На найближчому перехресті перевага вже не твоя, діють звичайні правила проїзду.","Ромб перекреслили — «корону» головної дороги з тебе зняли."],
"o33-304":["Право першим проїжджати нерегульовані перехрестя скасовує жовтий ромб, перекреслений чорними смугами, — знак 2. Знак 1 без смуг, навпаки, це право дає.","Жовтий ромб — «головна дорога», перекреслений ромб — «уже ні»."],
"o33-305":["Трикутник «Дати дорогу» з табличкою «STOP» і відстанню попереджає: на найближчому перехресті стоятиме знак «Проїзд без зупинки заборонено» — восьмикутник STOP, знак 2. Готуйся зупинитися.","Табличка «STOP» під трикутником — анонс: далі чекає восьмикутний «STOP»."],
"o33-306":["Знак «STOP» вимагає зупинитися обов’язково — навіть якщо дорога порожня. Рушати можна лише після повної зупинки, коли переконаєшся, що нікому не заважаєш.","STOP — це не «пригальмуй», а «колеса стоп». Завжди."],
"o33-307":["Знак «STOP» вимагає двох речей: повністю зупинитися і пропустити тих, хто їде головною дорогою. Тільки пригальмувати — замало, а рушити після зупинки, не пропустивши інших, — теж порушення.","STOP = зупинка + «дати дорогу». Обидва кроки, без скорочень."],
"o33-308":["Зупинка за іншим авто не рахується. Знак «STOP» вимагає стати саме перед стоп-лінією, тож жовте авто, під’їхавши до неї, має зупинитися ще раз.","Стоп за чужим бампером — не той стоп. Зупиняйся біля стоп-лінії."],
"o33-309":["Коли світлофор працює звичайно, як у першій ситуації, знаки пріоритету не діють — керує світлофор. Миготливий жовтий означає, що перехрестя нерегульоване, і тоді знак «STOP» треба виконати.","Світлофор горить — він головний. Мигає жовтий — головний знак."],
"o33-310":["І трикутник «Дати дорогу», і восьмикутник «STOP» велять пропустити машини, що їдуть дорогою, яка перетинається. Різниця лише в тому, що «STOP» ще й вимагає обов’язково зупинитися.","Трикутник і «STOP» кажуть «пропусти»; «STOP» додає ще й «стань»."],
"o33-311":["Перевагу на нерегульованому перехресті дає жовтий ромб «Головна дорога» — знак 3. Трикутник і «STOP» велять поступитися, а перекреслений ромб (знак 4) означає кінець головної.","Жовтий ромб — як золота корона: перевага на перехресті твоя."],
"o33-312":["Жовтий ромб «Головна дорога» означає, що на нерегульованих перехрестях перевага твоя: машини з другорядних доріг мають тебе пропустити.","Жовтий ромб — «золота карта»: тебе пропускають."],
"o33-313":["Перед мостом у тебе синій знак «Перевага перед зустрічним рухом». Тож через вузьке місце перевага твоя, а вантажівка має тебе пропустити.","Біла стрілка вгору — твоя, і вона головна: перевага за тобою."],
"o33-314":["Знак «Рух заборонено» біля пішохідної зони не пускає транзит, але пропускає машини тих, хто там живе чи працює, а також тих, хто обслуговує місцевих мешканців і підприємства. Тож правильні всі три варіанти.","Свої можуть: живеш, працюєш чи обслуговуєш когось у зоні — заїжджай."],
"o33-315":["Знак «Рух заборонено» на в’їзді до пішохідної зони не дозволяє проїжджати її наскрізь. Заїхати можна лише у справах самої зони — якщо там живеш, працюєш чи когось обслуговуєш.","Пішохідна зона — не скорочення шляху: транзитом сюди не можна."],
"o33-316":["Знак із вантажівкою й причепом забороняє рух вантажівкам і тракторам із будь-яким причепом, а також буксирування машин. Легковику з причепом цей знак не заважає.","Вантажівка тягне причіп — заборона для «тягачів»: вантажівок, тракторів і буксирів."],
"o33-317":["Знак «Рух з причепом заборонено» стосується лише вантажівок і тракторів із причепами та буксирування. Легковик із причепом може їхати прямо.","На знаку вантажівка, а не легковик — легковий з причепом проїде."],
"o33-318":["Знак із вантажівкою й причепом забороняє і буксирування машин. Тож синьому авто, яке тягне на тросі біле, прямо їхати не можна.","Трос між машинами — той самий «причіп»: під цим знаком не можна."],
"o33-319":["Знак із трактором забороняє рух тракторам, а також самохідним машинам і механізмам. Вантажівок цей знак не стосується — для них є окремий знак.","Трактор на знаку — і вся повільна техніка з ним: трактори й самохідні машини."],
"o33-320":["Знак із мопедом забороняє рух мопедам і велосипедам з підвісними двигунами — по суті, всім «велосипедам із мотором». Мотоциклів і звичайних велосипедів він не стосується.","Мопед і велосипед із мотором — близнюки: заборона для обох."],
"o33-321":["Знак із велосипедом забороняє рух лише велосипедам. Для мопедів і мотоциклів є свої окремі знаки.","Що намальовано, те й заборонено: велосипед — лише велосипеди."],
"o33-322":["Знак заборони для велосипедів із табличкою-стрілкою діє праворуч, але не стосується тих, хто обслуговує мешканців цієї території. Тож велосипедист у справах до мешканців може повернути.","Обслуговування мешканців — перепустка: такий знак пропускає."],
"o33-323":["Рух пішоходів забороняє знак із пішоходом у червоному колі — знак 1. Сині знаки 2 і 3, навпаки, позначають місця для пішоходів, а трикутник 4 лише попереджає про перехід.","Червоне коло — «не можна», синє коло — «тільки сюди»."],
"o33-324":["Знак заборони для вантажівок із табличкою-стрілкою в обидва боки закриває дорогу ліворуч і праворуч. Він стосується і тракторів, тож трактор може їхати лише прямо (Б) або розвернутися (Г).","Стрілка в обидва боки — закриті і ліво, і право. Лишаються прямо й розворот."],
"o33-325":["Знак із легковиком забороняє рух лише транспорту з двигуном. Велосипед не механічний, тож велосипедист на цьому перехресті може їхати в усіх напрямках, попри табличку зі стрілками.","Знак для «моторних». Педалі — не мотор, тож велосипедисту відкрито всюди."],
"o33-326":["Знак «Рух механічних транспортних засобів заборонено» не діє на тих, хто працює в цій зоні. Якщо твоя робота одразу за знаком, заїхати туди можна.","Робота одразу за знаком — твоя перепустка в цю зону."],
"o33-327":["Знаки «Рух заборонено» і «Пішохідна зона» не діють на водіїв з інвалідністю, якщо іншого під’їзду немає. Тож такий водій може заїхати в зону.","Знак «Водій з інвалідністю» на авто — як перепустка, коли іншого шляху немає."],
"o33-328":["Поруч зі знаком «Рух заборонено» висить знак «Небезпека». Він закриває проїзд для всіх без винятку, тож навіть ті, хто працює в зоні, заїхати не можуть.","«НЕБЕЗПЕКА» поруч — жодних перепусток: не їде ніхто."],
"o33-329":["Знаки «Рух заборонено» і «Пішохідна зона» не діють на машини, що обслуговують підприємства в цій зоні, коли іншого під’їзду немає. Тож заїхати можна.","Справи підприємства в зоні — твоя перепустка, коли іншого під’їзду немає."],
"o33-330":["Знак із легковиком забороняє рух усім механічним транспортним засобам — тобто з двигуном. Мопеди, мотоцикли й квадроцикли мають мотор, а велосипед — ні, тож на нього знак не діє.","Є мотор — не їдеш. Крутиш педалі — їдеш."],
"o33-331":["Знак «Рух механічних транспортних засобів заборонено» стосується всього, що їде з двигуном: автомобілів, автобусів, мотоциклів і мопедів. Тож правильні всі варіанти.","На знаку легковик, але заборона для всіх із мотором."],
"o33-332":["Знак забороняє рух транспорту з двигуном. Гужовий віз і велосипед — без мотора, таксі везе мешканця зони, тож може заїхати. Порушує лише водій мопеда.","Мопед — теж із мотором, а «перепустки» мешканця в нього немає."],
"o33-333":["Знак «Рух механічних транспортних засобів заборонено» не діє на машини мешканців і тих, хто працює в зоні, на тих, хто обслуговує громадян і підприємства, та на маршрутний транспорт. Правильні всі три варіанти.","Свої (живуть, працюють, обслуговують) і маршрутний транспорт — проїжджають."],
"o33-334":["Рух пішоходів із ручними візками забороняє знак, де людина котить візок, — знак 3. Інші знаки стосуються велосипедів, небезпечних вантажів і в’їзду, а синій знак 2 позначає місце для пішоходів.","Людина з візком у червоному колі — з візком сюди не можна."],
"o33-335":["Знак «Стоянку заборонено» дублює жовта переривчаста лінія біля краю дороги чи на бордюрі. Суцільна жовта лінія означає вже заборону зупинки.","Жовтий пунктир — без стоянки, жовта суцільна — без зупинки. Розрив = м’якша заборона."],
"o33-336":["За містом машини їдуть швидше, тож попереджувальний знак ставлять заздалегідь — за 150–300 м до небезпечного місця, щоб вистачило часу загальмувати.","За містом швидкість більша — і знак далі: 150–300 м."],
"o33-337":["У місті швидкість менша, а місця мало, тож попереджувальний знак ставлять ближче до небезпечного місця — за 50–100 м.","Місто тісне — знак близько: 50–100 м."],
"o33-338":["Синій прямокутний знак із велосипедом і стрілкою вгору позначає велосипедну смугу — частину дороги, виділену для велосипедистів.","Стрілка над велосипедом — як над смугою руху: це велосмуга."],
"o33-339":["Пішохід зі стрілками в усі чотири кути — це діагональний перехід: на ньому перехрестя можна переходити навскіс, з кута в кут.","Стрілки в чотири кути — переходиш навскіс, по діагоналі."],
"o33-340":["Синій знак із зображенням тунелю позначає початок ділянки, що йде через довгий тунель — 1000 м і більше. До населених пунктів він стосунку не має.","Темна арка на знаку — в’їзд у довгий тунель, від 1000 м."],
"o33-341":["Трикутник із чорною крапкою попереджає про місце, де часто стаються ДТП. Тут треба їхати особливо обережно.","Чорна крапка — як «чорна пляма» на карті аварій."],
"o33-342":["Знак із трактором і возом, розділеними червоною смугою, — це поєднаний знак: він забороняє рух саме тих видів транспорту, що на ньому намальовані.","Що намальовано на знаку — тому й зась."],
"o33-343":["Круглий синій знак, поділений вертикальною рискою на велосипед і пішоходів, позначає суміжні пішохідну та велосипедну доріжки: кожен рухається своєю половиною.","Риска посередині — дві доріжки поруч: велосипеду своя, пішоходам своя."],
"o33-344":["Синій круглий знак із колесом у ланцюгах наказує їхати лише з ланцюгами проти ковзання — і стосується всіх машин, а не тільки вантажівок.","Синє коло — наказ: колеса в ланцюгах, хоч би яке в тебе авто."],
"o33-345":["Синій круглий знак із легковиком над велосипедом позначає дорогу, де легковики й велосипедисти їдуть разом, однією проїзною частиною. Велосипедисти тут — повноправні сусіди.","Авто й велосипед в одному колі — їдуть разом по одній дорозі."],
"o33-346":["На знаку і загальна стрілка, і стрілка біля автобуса показують в один бік. Отже, смуга для маршрутного транспорту на дорозі, куди ти виїжджаєш, іде в тому ж напрямку, що й увесь потік.","Обидві стрілки в один бік — автобусна смуга іде попутно."],
"o33-347":["Числа в синіх колах над смугами — це мінімальна швидкість для кожної смуги: повільніше нею їхати не можна. Синій колір тут означає «не менше».","Синє коло — «підлога» швидкості, окремо для кожної смуги."],
"o33-348":["Числа в червоних колах над смугами — це максимальна швидкість для кожної смуги окремо. Червона облямівка означає «не більше».","Червоне коло — «стеля» швидкості, у кожної смуги своя."],
"o33-349":["Знак «P» з вантажівкою й людиною, що розвантажує, позначає місце, де фургон чи вантажівка можуть стати лише на час завантаження або розвантаження. Це не стоянка надовго.","Людина з візком біля кузова: стати, розвантажити — і поїхати."],
"o33-350":["Синій знак із якорем показує, що поруч морський чи річковий порт або вокзал. Якір — символ кораблів, а не автобусів.","Якір — значить, кораблі: порт або річковий вокзал."],
"o33-351":["Зелений знак автомагістралі з монетками внизу означає платну дорогу: за проїзд нею треба заплатити.","Монетки на знаку — за дорогу доведеться платити."],
"o33-352":["Синій знак із дорослим і дитиною та написом «ЗОНА» позначає пішохідну зону — територію, де головні пішоходи.","Дорослий з дитиною і слово «ЗОНА» — територія для пішоходів."],
"o33-353":["Знак показує дорогу, де машини їдуть в один бік (біла стрілка вгору), а велосипедисти — назустріч їм окремою, виділеною розміткою смугою (стрілка вниз під велосипедом).","Стрілки в різні боки — велосипед їде назустріч потоку своєю смугою."],
"o33-354":["Табличка з острівцем і стрілкою, що його оминає, попереджає: попереду острівець безпеки, і дорога звужується.","Острівець на табличці, стрілка його оминає — дорога вужчає."],
"o33-355":["Табличка з евакуатором, що піднімає легковик, попереджає: машину, залишену тут, можуть евакуювати без відома власника.","Евакуатор на табличці — машину можуть забрати, поки тебе немає."],
"o33-356":["Знак показує виїзд на дорогу з одностороннім рухом: машини їдуть праворуч (велика біла стрілка), а велосипеди мають свою зустрічну смугу (стрілка ліворуч біля велосипеда).","Велосипед «дивиться» в інший бік — у нього зустрічна смуга на односторонній дорозі."],
"o33-357":["Знак із помаранчевим прямокутником на машині забороняє рух транспорту з небезпечними вантажами. Табличка з годинами лише уточнює, коли діє заборона.","Помаранчевий прямокутник — позначка небезпечного вантажу."],
"o34-1":["Вигнуті стрілки на смузі попереджають, що попереду проїзна частина звужується і ця смуга скоро закінчиться. Перестроюватися треба заздалегідь — переваги ці стрілки не дають.","Стрілка «виштовхує» з твоєї смуги — попереду звуження."],
"o34-2":["Чорно-білі смуги на бордюрах — це вертикальна розмітка, що виділяє бордюри на небезпечних ділянках, щоб їх було добре видно. До зупинки чи стоянки вона стосунку не має.","«Зебра» на бордюрі — «обережно, бордюр!», а не заборона стояти."],
"o34-3":["Жовта переривчаста лінія біля бордюру означає заборону стоянки. Тож залишати тут машину не можна — ні на дорозі, ні з заїздом на тротуар.","Жовтий пунктир біля краю — «тут не паркуйся»."],
"o34-4":["Поперечні жовто-білі смуги попереджають про «лежачого поліцейського» попереду — пристрій, що змушує скинути швидкість. Пригальмовуй заздалегідь.","Жовто-білі смуги поперек дороги — зараз буде «лежачий поліцейський»."],
"o34-5":["Переривчасту лінію посередині дороги можна перетинати. Тож обгін, об’їзд і розворот вона не забороняє — виконуй їх за звичайними правилами.","Пунктир — «двері відчинені»: переїжджати можна."],
"o34-6":["Число в червоному колі, намальоване на асфальті, дублює знак обмеження максимальної швидкості. Це межа, а не порада — їхати швидше не можна.","Знак «ліг» на асфальт — правило те саме: не швидше, ніж написано."],
"o34-7":["Чорно-білі смуги на нижньому краї мосту чи тунелю показують, що він низький — 5 м над дорогою або менше. Так водії високих машин заздалегідь бачать небезпеку.","«Зебра» над головою — низька стеля: 5 м або менше."],
"o34-8":["Напис на асфальті з літерою й цифрами — це номер дороги чи маршруту. Він допомагає не загубитися, а не показує відстань.","Літера плюс цифри на асфальті — «паспорт» дороги, її номер."],
"o34-9":["Літера «А» позначає смугу для маршрутного транспорту. Нею можуть їхати також таксі, велосипедисти, мопеди й мотоцикли — крім мотоциклів із боковим причепом, мотоколясок і триколісних.","«А» — автобусна смуга з «гостями»: таксі, велосипеди, мопеди, мотоцикли."],
"o34-10":["Жовтий зигзаг біля краю дороги позначає місце зупинки маршрутного транспорту — тут автобуси й тролейбуси забирають пасажирів.","Зигзаг-змійка біля бордюру — місце для автобуса."],
"o34-11":["Якщо реверсивні світлофори вимкнулися, вже незрозуміло, чия зараз ця смуга. Тому треба негайно перестроїтися на праву смугу.","Реверс згас — одразу вправо, не чекаючи перехрестя."],
"o34-12":["На огорожі перешкоди знак зі стрілкою вниз ліворуч — «Об’їзд перешкоди ліворуч». Тож об’їжджати треба лише ліворуч, по траєкторії Б.","Куди показує синя стрілка — туди й об’їжджай."],
"o34-13":["Смугою «А» під знаком для маршрутного транспорту можуть їхати маршрутні автобуси, а також таксі, велосипеди, мопеди й мотоцикли — крім мотоциклів із боковим причепом, мотоколясок і триколісних.","Смуга «А» — для маршруток і «легких»: таксі, велосипед, мопед, мотоцикл."],
"o34-14":["Смугою для маршрутного транспорту дозволено їхати й велосипедистам. Тож велосипедист може рухатися нею.","Велосипед — бажаний гість на автобусній смузі."],
"o34-15":["Жовта переривчаста лінія біля бордюру забороняє лише стоянку. Коротко зупинитися, щоб висадити пасажира, тут можна.","Пунктир: стояти довго не можна, а висадити пасажира — будь ласка."],
"o34-16":["Стрілка ліворуч на смузі дозволяє не лише повернути ліворуч, а й розвернутися з цієї смуги.","Стрілка ліворуч — це і поворот, і розворот."],
"o34-17":["Жовтий зигзаг і знак зупинки автобуса позначають місце лише для маршрутного транспорту. Звичайній машині ставати тут не можна, навіть щоб посадити чи висадити пасажира.","Зигзаг — місце «зайняте» автобусом. Іншим — ні хвилинки."],
"o34-18":["Чорно-білі смуги на огорожі вздовж дороги — сигнал, що ти їдеш небезпечною ділянкою: крутий поворот, насип чи урвище. Тримай швидкість під контролем і будь уважнішим.","Смугаста огорожа = небезпечна ділянка. Бачиш «зебру» на відбійнику — пригальмуй."],
"o34-19":["Білий трикутник вершиною до тебе — це «Дати дорогу», намальований на асфальті. Він попереджає: попереду лінія, біля якої за потреби треба зупинитися й пропустити машини на дорозі, яку перетинаєш.","Трикутник на асфальті — той самий знак «Дати дорогу», тільки він лежить на дорозі."],
"o34-20":["Лінія тут комбінована: з твого боку вона переривчаста. Отже, тобі перетинати її можна, і обігнати трактор дозволено, якщо це безпечно.","Переривчаста з мого боку — мені можна. Суцільна з мого боку — не можна."],
"o34-21":["Чорно-білими смугами фарбують торці штучних споруд — опори мостів і шляхопроводів біля дороги. Так водій здалеку помічає перешкоду й не зачепить її.","Смугаста опора кричить: «Я тут стою, не зачепи!» Так позначають торці мостів і естакад."],
"o34-22":["Коли реверсивний світлофор вимкнений, реверсивна смуга закрита — треба триматися правіше від неї. Тому випереджати по ній заборонено.","Реверсивний світлофор спить — реверсивна смуга закрита."],
"o34-23":["Повертаючи ліворуч, ти пропускаєш машини на головній дорозі. Зупинятися треба перед перехрестям, біля лінії з трикутників 1.13 — вона показує, де стати, а не сам знак.","Знак попереджає, а лінія з трикутників показує, де саме стати."],
"o34-24":["Синє авто розвертається з того боку, де лінія переривчаста, — йому її перетинати можна. Біле авто виїжджає з двору з боку суцільної лінії, тож повертати ліворуч через неї не має права.","Перетинати можна лише з того боку, де лінія переривчаста."],
"o34-25":["Суцільну лінію краю дороги можна перетнути, щоб зупинитися на узбіччі праворуч, — це точка Б. Ліворуч, у точці А, за лінією розділювальна смуга, туди заїжджати й ставати не можна.","Стати можна на праве узбіччя — Б, а не ліворуч на розділювальну смугу."],
"o34-26":["Права смуга відділена суцільною лінією й позначена знаком з автобусом — вона для маршрутного транспорту. Легковим нею їхати не можна, тож рухатися далі цією смугою заборонено.","Знак з автобусом над смугою — смуга для автобусів, не для тебе."],
"o34-27":["Широкі короткі штрихи праворуч відділяють основну смугу від смуги гальмування — нею з’їжджають з дороги, скидаючи швидкість. Це не край дороги і не місце для зупинки.","Часті широкі штрихи біля з’їзду — «гальмівна доріжка»: зійди туди, тоді гальмуй."],
"o34-28":["Жовта суцільна лінія біля краю дороги означає, що тут не можна навіть зупинятися. А якщо зупинка заборонена, то стоянка й поготів.","Жовта суцільна вздовж бордюру — «жовта картка»: ні зупинки, ні стоянки."],
"o34-29":["Лінія тут комбінована, але з твого боку вона суцільна. Перетинати її не можна, тож обганяти трактор заборонено, хоч би як повільно він їхав.","Суцільна з мого боку — обгону нема. Швидкість трактора тут нічого не змінює."],
"o34-30":["Знак STOP вимагає обов’язково зупинитися, навіть якщо довкола нікого немає. Ставати треба біля стоп-лінії, звідки добре видно перехрестя, а не біля самого знака.","STOP — зупинка завжди, і саме на білій стоп-лінії."],
"o34-31":["Якщо знак і розмітка кажуть різне, слухайся знака. Знаки часто ставлять тимчасово, наприклад на час ремонту, а розмітку так швидко не перемалюєш.","Знак старший за розмітку: він стоїть вище — і на стовпі, і за важливістю."],
"o34-32":["Напис STOP на асфальті попереджає, що попереду стоп-лінія. Біля неї доведеться зупинитися, тож готуйся заздалегідь.","STOP на асфальті — анонс стоп-лінії: «Готуйся, скоро зупинка»."],
"o34-33":["Подвійну суцільну лінію перетинати не можна ніколи — ні для обгону, ні виїжджаючи з двору, ні в заторі. Це найсуворіша межа між зустрічними потоками.","Подвійна суцільна — подвійне «ні». Як бетонна стіна, тільки намальована."],
"o34-34":["Так, жовта сітка на перехресті позначає місце, куди не можна заїжджати, якщо попереду затор. Так ніхто не застрягне посеред перехрестя і не заблокує рух упоперек.","Жовта «вафля» — не ставай на неї, якщо далі нема куди їхати."],
"o34-35":["На жовту сітку не можна виїжджати, якщо попереду затор і ти не встигнеш з неї з’їхати. Інакше застрягнеш посеред перехрестя й заблокуєш тих, хто їде впоперек.","Затор попереду — на жовту клітинку ні колесом."],
"o35-1":["Чекаючи на зелений, тримай важіль у нейтралі, а не стій з вижатим зчепленням: так механізм менше зношується, а авто не смикнеться вперед, якщо нога зісковзне. Першу вмикай, коли загориться жовтий.","Червоний — нейтраль, жовтий — перша, зелений — поїхали."],
"o35-2":["Безпечна відстань на сухій дорозі — та, яку твоє авто проїде щонайменше за 2 секунди. Машина попереду минула стовп — порахуй до двох: якщо доїжджаєш до нього раніше, ти надто близько.","Правило двох секунд: сусід минув стовп — рахуй «раз-два», і тільки тоді ти біля стовпа."],
"o35-3":["Коли колеса заблоковані, авто ковзає юзом, гальмує гірше й не слухається керма. Якщо тиснути на гальмо переривчасто, тримаючи колеса на межі блокування, шини чіпляються за дорогу, і машина зупиняється швидше.","Колесо, що котиться, гальмує краще за колесо, що ковзає: тисни — відпускай."],
"o35-4":["У тумані чи під зливою їдь так, щоб устигнути зупинитися в межах того, що бачиш. Зупинний шлях має бути коротшим за відстань видимості, інакше перешкоду помітиш, коли гальмувати вже пізно.","Зупинитися маю раніше, ніж закінчується те, що бачу."],
"o35-5":["Час реакції — це мить від того, як ти помічаєш небезпеку, до того, як починаєш діяти: гальмувати чи кермувати. Сама зупинка авто сюди вже не входить.","Реакція — це шлях від «бачу» до «дію». Зупинка авто вже не рахується."],
"o35-6":["Ширший проміжок збоку потрібен, коли роз’їжджаєшся на великій швидкості, коли поруч довга фура чи автобус і коли дорога мокра, слизька або нерівна. Тож правильні всі варіанти.","Швидко, довго, слизько — відсунься збоку."],
"o35-7":["У глибокому снігу заздалегідь увімкни знижену передачу і їдь рівно, без різких поворотів і зупинок. Перемикання чи зупинка в заметі — найпростіший спосіб застрягти.","У снігу як у болоті: знижена передача, рівний хід і жодних зупинок."],
"o35-8":["ABS не дає колесам заблокуватися під час гальмування, але фізику не скасовує. Якщо в поворот заїхати надто швидко, авто все одно може знести чи занести.","ABS — помічник, а не чарівник: зайва швидкість у повороті все одно винесе."],
"o35-9":["На короткій слизькій ділянці краще нічого різко не робити: не гальмувати й не крутити кермо. Авто проскочить її по інерції, а гальмування на слизькому якраз і може спричинити занесення.","Слизька латка — тримай кермо рівно й нічого не чіпай, доки не проїдеш."],
"o35-10":["У хуртовину дальнє світло відбивається від сніжинок і засліплює тебе білою стіною. Протитуманні фари разом із ближнім світять низько, під снігову завісу, тож дорогу видно краще.","Дальнє в хуртовину — як ліхтарик у дзеркало. Ближнє з протитуманками світить під завісу."],
"o35-11":["Перед будь-яким гальмуванням глянь у дзеркало: позаду може бути машина, що їде надто близько. Так менше шансів отримати удар ззаду.","Ногу на гальмо — очі в дзеркало."],
"o35-12":["Коли зчеплення не вижате, ліву ногу тримай ліворуч від педалі — на підлозі чи спеціальному майданчику. Так нога відпочиває і випадково не натисне на зчеплення.","Ліва нога — на свою «лавочку» ліворуч від педалі, а не над нею."],
"o35-13":["Спершу підлаштуй сидіння, бо від нього залежить усе інше. Потім кермо під себе, далі дзеркала вже з правильного положення, а пасок — наостанок, щоб не заважав налаштовувати.","Сидіння, кермо, дзеркала, пасок: спершу сядь зручно, а пристебнись останнім."],
"o35-14":["Скільки може важити причіп з гальмами, залежить від конкретної машини, тому ці дані записані в її технічному паспорті. У Правилах чи страховому полісі цього немає.","Усе про можливості машини — в її «паспорті»."],
"o35-15":["Наближаючись до кінця затору в тунелі, увімкни аварійку — так ті, хто позаду, вчасно помітять, що потік стоїть. Розвертатися в тунелі не можна, а кидати машину без потреби не варто.","Хвіст затору в тунелі — мигай аварійкою, щоб у тебе не врізалися."],
"o35-16":["Скільки місця лишити збоку, залежить від того, як поводяться велосипедисти — вони можуть хитнутися чи об’їхати яму, — і від твоєї швидкості: що швидше їдеш, то більший потрібен проміжок.","Дивись на двох: як хитається велосипедист і як швидко їдеш сам."],
"o35-17":["Коли припарковані машини закривають огляд, виїжджай на перехрестя дуже обережно, потроху, доки не побачиш дорогу. Проскочити наосліп — найкоротший шлях до аварії.","Не бачиш — не мчиш: висувайся потроху, як з-за рогу."],
"o35-18":["На швидкості 50 км/год безпечна дистанція — не менше ніж 25 метрів, або 2 секунди руху. Двох метрів чи довжини авто не вистачить, щоб устигнути загальмувати.","Половина швидкості в метрах: 50 км/год — 25 метрів, або 2 секунди."],
"o35-19":["Після довгої їзди рівною трасою звикаєш до великої швидкості, і здається, що їдеш повільніше, ніж насправді. Тому частіше поглядай на спідометр.","Швидкість «приїдається»: довго мчиш — здається, що повзеш. Глянь на спідометр."],
"o35-20":["У передньопривідного авто передні колеса тягнуть машину за собою. Якщо занесло задню вісь, трохи газу допомагає «витягнути» авто й вирівняти його.","Передній привід тягне, як буксир: газ — і перед витягує зад."],
"o35-21":["Після води колодки мокрі й гальмують погано. Їдучи далі, кілька разів коротко натисни на гальмо — тертя швидко їх висушить.","Мокрі гальма сушать гальмуванням: натиснути-відпустити кілька разів."],
"o35-22":["Що крутіший спуск, то нижчу передачу вмикай. На низькій передачі двигун сильніше стримує авто, і гальма не перегріваються.","Крутіше вниз — нижча передача."],
"o35-23":["На «водяному клині» шини ковзають по воді, як лижі, і різке гальмування лише закрутить авто. Скидай швидкість плавно, відпустивши газ і гальмуючи двигуном, — колеса знову торкнуться асфальту.","Аквапланування — як серфінг: не гальмуй різко, просто відпусти газ."],
"o35-24":["Якщо довго спускатися, тримаючи авто самими гальмами, колодки й диски перегріваються, і гальма слабшають саме тоді, коли найбільше потрібні. Тому на спуску допомагай двигуном, не вимикаючи передачу.","Довгий спуск на самих гальмах — гальма «закипають» і перестають тримати."],
"o35-25":["У тумані предмети виглядають розмитими й блідими, тому здаються далі, ніж є насправді. Через це легко під’їхати впритул — тримай більшу дистанцію і знижуй швидкість.","Туман «відсуває» предмети: здається далеко, а насправді вже поруч."],
"o35-26":["Зупинний шлях — це вся відстань від миті, коли ти помічаєш небезпеку, до повної зупинки. Сюди входить і час реакції, і спрацювання гальм, і саме гальмування.","Зупинний шлях = побачити + зреагувати + загальмувати. Гальмівний — лише остання частина."],
"o35-27":["Що гірше видно дорогу, то повільніше треба їхати — і в місті, і за містом. Ти маєш устигнути зупинитися, щойно помітиш перешкоду.","Менше бачиш — повільніше їдеш."],
"o35-28":["Порожнє авто найстійкіше на повороті: центр ваги в нього найнижчий. Пасажири, а тим паче вантаж на даху, піднімають центр ваги, і машину легше перекинути.","Що вище вага — то легше перекинутися. Найстійкіше — порожнє авто."],
"o35-29":["Швидкість скидай ще до повороту, за потреби перейди на нижчу передачу. А в самому повороті їдь рівно: без різкого газу й гальмування і не котися накатом із вижатим зчепленням.","Гальмуй до повороту, а в повороті — рівний газ."],
"o35-30":["Рушаючи на підйомі, відпускай ручне гальмо саме тоді, коли авто починає рушати. Раніше — машина покотиться назад, пізніше — поїдеш із затиснутим гальмом.","Ручник відпускаєш тієї ж миті, як авто «потягнуло» вперед."],
"o35-31":["Найнебезпечніше — виїжджати з-за дерев чи будинків на відкрите місце: вітер б’є раптово, і авто може зсунути вбік. Тримай кермо міцніше, коли виїжджаєш на відкрите.","Ліс закінчився — чекай удару вітру збоку."],
"o35-32":["Так, що вища швидкість, то більший проміжок збоку треба лишати. На швидкості потік повітря сильніше хитає машини, а на виправлення помилки кермом лишається менше часу.","Швидше їдеш — ширше об’їжджаєш."],
"o35-33":["Що швидше їдеш, то вужче поле зору: погляд тягнеться вдалину, а те, що збоку, помічаєш гірше. Тому на швидкості легко прогледіти пішохода чи машину збоку.","Швидкість — як тунель: що швидше, то вужча «труба» огляду."],
"o35-34":["Найекономніше — розганятися плавно і так само плавно сповільнюватися, заздалегідь відпускаючи газ. Різкі ривки й гальмування спалюють пальне задарма.","Плавно рушати, плавно гальмувати — і бак тримає довше."],
"o35-35":["Причіп без власних гальм штовхає авто вперед, тож машині доводиться гальмувати за двох. Через це гальмівний шлях довшає, і дистанцію треба тримати більшу.","Причіп без гальм не допомагає зупинитися — тільки штовхає. Шлях довшає."],
"o35-36":["Перші краплі дощу змішуються з пилом і мастилом на асфальті, і дорога стає дуже слизькою. Тому одразу скидай швидкість і їдь особливо обережно.","Перший дощ — найслизькіший: крапає — пригальмуй."],
"o35-37":["Якщо авто занесло через гальмування, насамперед відпусти педаль гальма. Колеса знову закрутяться, зчепляться з дорогою, і машину вдасться вирівняти кермом.","Занесло від гальма — прибери ногу з гальма."],
"o35-38":["У темряві чи в похмуру погоду погано видно деталі, тож здається, що зустрічна машина їде повільніше, ніж насправді. Вона наближається швидше — закладай більший запас.","Уночі зустрічний «підкрадається»: здається повільним, а мчить швидше."],
"o35-39":["Гальмівний шлях рахують від миті, коли натискаєш на педаль гальма, до повної зупинки. Сліди шин на асфальті з’являються пізніше, тож за ними шлях вийде коротшим за справжній.","Гальмівний шлях починається з педалі, а не зі слідів на асфальті."],
"o35-40":["Так. На ожеледі різке гальмування блокує колеса, і авто ковзає, як на ковзанці, не слухаючись керма. Гальмуй плавно й заздалегідь.","Лід не любить різкості: різко гальмуєш — їдеш як на ковзанах."],
"o35-41":["Так. Сніг із даху під час гальмування з’їде на лобове скло й закриє огляд, а на ходу злетить на машини позаду. Тож очищай авто повністю, а не лише скло.","Снігова шапка на даху — «сюрприз» на лобовому склі під час першого гальмування."],
"o35-42":["У снігопад можна застрягнути чи довго стояти в заторі. Лопата допоможе відкопатися, ковдра — зігрітися, щітка зі скребком — очистити авто, а повний бак — довше гріти салон. Тож бери все.","Зимовий набір: копати, гріти, чистити, заправити — бери все."],
"o35-43":["Так. Уночі гірше видно дорогу, пішоходів і перешкоди, засліплюють фари зустрічних, та й утома дається взнаки. Тож уважність потрібна більша, ніж удень.","Уночі очі бачать менше — голова має працювати більше."],
"o35-44":["Ні. Стаж не дає жодної «пільги»: межа алкоголю в крові однакова для всіх водіїв, і 0,3 проміле — це вже більше, ніж дозволено.","Стаж не дає знижки на алкоголь: межа однакова і для новачка, і для ветерана."],
"o35-45":["Ні. На машині купа снігу — на даху, капоті й вікнах: огляд поганий, а сніг з даху може з’їхати на лобове скло під час гальмування. Перед поїздкою очищай усе авто.","Їдеш у «сніговій шапці» — ризикуєш і собою, і іншими. Чисть усе."],
"o35-46":["Ні. Машин уночі менше, але бачиш ти значно гірше, фари зустрічних засліплюють, а втома притуплює реакцію. Тож порожня нічна дорога — не привід розслаблятися.","Порожня дорога вночі не безпечна, а оманлива."],
"o35-47":["Так. У тумані зустрічні фари виглядають тьмяними й розмитими, тож здається, що машина далеко і їде повільно. Насправді вона ближче й швидше — тримай запас.","Туман бреше двічі: «далеко» і «повільно». Насправді — близько і швидко."],
"o35-48":["Уночі ти бачиш дорогу лише у світлі своїх фар, а інші помічають тебе за твоїми вогнями. Тож перед нічною поїздкою насамперед перевір, чи світять усі фари й ліхтарі.","Ніч = світло. Немає фар — немає дороги."],
"o35-49":["Ні. Самого лобового скла мало: бічні вікна, дзеркала, фари й дах теж мають бути чистими. Інакше не бачиш, що збоку й позаду, а сніг з даху з’їде на скло.","Віконце в снігу — це не огляд. Чисть авто цілком."],
"o35-50":["Так. На снігу й льоду шини тримаються за дорогу слабко, тож різкий газ, гальмо чи поворот керма легко зривають авто в занос. Усе роби плавно й завчасно.","Взимку керуй, ніби несеш повну чашку чаю: жодних ривків."],
"o35-51":["Ні. У населеному пункті сигналити можна лише тоді, коли без цього не вдасться запобігти аварії. Поквапити когось чи привітатися клаксоном не можна.","У місті клаксон — тільки на SOS: лише щоб відвернути аварію."],
"o35-52":["Ні. Покажчик повороту вимикають одразу після того, як маневр завершено, а не посеред повороту. Інакше інші можуть не зрозуміти, що ти робиш.","Поворот закінчено — тоді й поворотник геть."],
"o35-53":["Сніг з даху може зсунутися на твоє лобове скло й раптово закрити огляд, а може зірватися на ходу й полетіти на машини позаду. Тож правильні обидва варіанти.","Сніг на даху — загроза і тобі спереду, і сусідам ззаду."],
"o35-54":["Так. Що швидше їдеш, то довший шлях потрібен, щоб зупинитися, тож і відстань до машини попереду має бути більшою.","Більша швидкість — більше простору перед носом."],
"o35-55":["Так. Гальмівний шлях росте значно швидше за швидкість: їдеш удвічі швидше — гальмуєш приблизно вчетверо довше. Тому навіть невелике перевищення помітно віддаляє зупинку.","Удвічі швидше — вчетверо довше гальмуєш."],
"o35-56":["Так. Добрий водій думає на кілька кроків уперед: чи не вибіжить дитина з-за авто, чи не загальмує сусід. Обстановку ти не контролюєш, але передбачати її — твоя справа.","Їдь як шахіст: думай на хід уперед."],
"o35-57":["В Україні водієві дозволено щонайбільше дві десятих проміле алкоголю в крові, і ця межа однакова для всіх. Найнадійніше — не пити зовсім, якщо збираєшся за кермо.","Межа — «нуль, кома, два»: два — як дві руки на кермі."],
"o35-58":["Ні. Тримати телефон у руці під час руху не можна нікому, хоч який великий досвід. Говорити можна лише через гарнітуру чи гучний зв’язок.","Досвід не дає третьої руки: телефон — тільки без рук."],
"o35-59":["Якщо попереду хтось їде агресивно, не втягуйся в гру. Зберігай спокій, уважно стеж за дорогою і будь напоготові скинути швидкість чи зовсім зупинитися.","Агресор попереду — а в тебе холодна голова: спокій, увага, нога над гальмом."],
"o35-60":["Так. Білі вогні ззаду загоряються, коли вмикають задній хід. Бачиш їх — машина зараз рушить назад, тож тримайся подалі.","Білі вогні ззаду — «я їду назад»."],
"o35-61":["Коли на дорогу вискакує тварина, гальмуй і готуйся зупинитися повністю. Різкий рух кермом може викинути авто на зустрічну чи в кювет — це небезпечніше за саму тварину.","Тварина на дорозі — гальмо, а не кермо."],
"o35-62":["Якщо злива така, що далі їхати не можна, стань біля краю дороги й увімкни аварійку, щоб тебе помітили. Стояти посеред дороги з дальнім світлом — засліплювати інших і ризикувати отримати удар.","Злива стіною — до краю дороги й аварійку."],
"o35-63":["Ні. На мокрій дорозі шини тримаються гірше, і різкий газ легко зриває колеса в пробуксовку чи занос. Розганяйся плавно.","Дощ — і газ, і гальмо тільки плавно."],
"o35-64":["Знак «Дорожні роботи» попереджає, що попереду ремонт. Швидкість скидай ще до нього і не розганяйся одразу після: за знаком можуть бути робітники, техніка, ями чи звужена дорога.","Чоловічок з лопатою — тихо і до знака, і після: там працюють люди."],
"o35-65":["Наближаючись до перехрестя, будь напоготові: світлофор може перемкнутися, а зустрічний водій — помилитися й повернути просто перед тобою. Тож правильні обидва варіанти.","Перехрестя — зона сюрпризів: стеж і за світлофором, і за зустрічними."],
"o35-66":["Утома за кермом не минає від свіжого повітря — воно бадьорить лише на хвилину. Справді допомагає одне: з’їхати з дороги, зупинитися й відпочити, доки втома не мине.","Утому лікує лише зупинка, а не відчинене вікно."],
"o35-67":["Якщо сильно хочеться спати, гучне радіо чи холодне повітря лише ненадовго відволікають. Треба зупинитися, відпочити, а якщо є можливість — передати кермо іншому водієві.","Позіхаєш за кермом — шукай місце для зупинки, а не кнопку радіо."],
"o35-68":["Перед виїздом з узбіччя глянь у дзеркала й обернися через плече — так побачиш і те, що ховається в «сліпій зоні». Звуковий сигнал нічого тобі не покаже.","Дзеркала й погляд через плече — тоді рушай."],
"o35-69":["Якщо нічні поїздки лякають, спершу проїдь незнайомими вулицями вдень і запам’ятай їх. Потім уночі вони вже не здаватимуться чужими, і їхати буде спокійніше.","Спершу знайомся з вулицею вдень — тоді вночі не загубишся."],
"o35-70":["Від сонливості найкраще рятують регулярні зупинки: вийти, розім’ятися, випити води. Радіо чи повільніша їзда сон не проганяють.","Довга дорога — часті перерви: зупинка, вода, розминка."],
"o35-71":["Так. Ремінь утримує тебе на місці під час удару чи різкого гальмування, тож ти не б’єшся об кермо, скло чи інших людей у салоні. Це найдієвіший захист від травм.","Клац ременя — найкращий захист у машині."],
"o35-72":["У місті сигналити можна лише тоді, коли треба відвернути аварію. Дитина, що от-от вибіжить на дорогу, — саме такий випадок. Обгін чи гальмування сусіда — не причина сигналити.","Клаксон у місті — щоб урятувати, а не щоб поквапити."],
"o35-73":["Коли засліплюють зустрічні фари, не дивись на них — переведи погляд праворуч, на край своєї смуги. Так очі менше засліпить, а ти триматимеш напрямок.","Яскраві фари назустріч — очі на правий край дороги."],
"o35-74":["Так. Під час удару ззаду голову різко відкидає назад, і правильно виставлений підголівник береже шию від травми. Тому налаштовуй його під свій зріст.","Підголівник — подушка для шиї, коли б’ють ззаду."],
"o35-75":["Білі вогні ззаду вмикаються разом із задньою передачею. Бачиш їх — авто їде або от-от поїде назад, тож тримайся подалі.","Білий вогник ззаду — машина йде назад."],
"o35-76":["Так. Недокачана шина гірше тримає форму й слабше чіпляється за дорогу, тож авто гальмує довше. Тиск у шинах варто перевіряти регулярно.","М’яка шина — довге гальмування. Перевіряй тиск."],
"o35-77":["Ні, навпаки. Недокачана шина сильніше розплющується й більше опирається коченню, тож двигун витрачає більше пального.","Спущене колесо котиться, ніби по піску: опір більший — бак порожніє швидше."],
"o35-78":["У великих вантажівок і автобусів є великі «сліпі зони», де водій тебе просто не бачить, хоч дзеркала в нього є. Не затримуйся поруч із ними й не підрізай їх.","Не бачиш дзеркал фури — її водій не бачить тебе."],
"o35-79":["Якщо машина справа вже перестроюється у твою смугу, не влаштовуй перегони. Скинь швидкість і дай їй завершити маневр — так зіткнення не буде.","Хтось лізе у твою смугу — пропусти: гордість не варта аварії."],
"o35-80":["Біле авто різко перестроюється у твою смугу зліва. Не прискорюйся і не сигналь — скинь швидкість і дай йому завершити маневр, щоб не було зіткнення.","Різко підрізали — відпусти газ, а не нерви."],
"o35-81":["Дзеркало показує не все: у «сліпій зоні» може сховатися машина чи велосипедист. Тому глянь у дзеркало й обернися через плече — лише разом вони дають повну картину.","Дзеркало плюс погляд через плече — і сліпих зон немає."],
"o35-82":["Під час зіткнення тебе кидає вперед, і саме ремінь безпеки утримує голову й груди від удару об панель чи скло. Підголівник захищає шию, коли кидає назад.","Ремінь тримає спереду, підголівник ловить ззаду."],
"o35-83":["«Сліпу зону» варто перевіряти щоразу, коли зміщуєшся вбік: перестроюєшся, з’їжджаєш на узбіччя чи виїжджаєш з нього. Поруч може бути машина чи велосипедист, якого не видно в дзеркалі.","Зміщуєшся вбік — глянь через плече."],
"o35-84":["Так. Машина з увімкненим маячком поспішає на виклик, і їй мають поступитися всі — навіть пішоходи. Тож із переходом дороги треба зачекати, поки вона проїде.","Блимає маячок — дорога їй, а пішохід чекає на тротуарі."],
"o35-85":["Коли зустрічна машина засліплює дальнім світлом, не дивись на фари, а переведи погляд на правий край дороги. Так не втратиш напрямок, а очі менше засліпить.","Засліплюють — дивись праворуч на край, а не в «прожектор»."],
"o35-86":["Так. Якщо зустрічна машина опинилася на твоїй смузі, зіткнення може статися будь-якої миті. Сигнал у місті дозволено саме для того, щоб відвернути аварію, тож тут він доречний.","Зустрічний у твоїй смузі — сигналь: це той випадок, коли клаксон рятує."],
"o35-87":["Кондиціонер працює від двигуна і забирає частину його сили. Через це двигун спалює більше пального — от на що він впливає.","Холод у салоні оплачуєш пальним."],
"o35-88":["Так. Компресор кондиціонера крутить двигун, тож машина витрачає трохи більше пального.","Кондиціонер п’є з того ж бака, що й двигун."],
"o35-89":["Дивись далеко вперед, у точку А, де дорога продовжується і видно інші машини. Так раніше помітиш, що на тебе чекає, і встигнеш зреагувати. Узбіччя просто перед капотом мало що підкаже.","Погляд далеко вперед — і що буде на дорозі, видно заздалегідь."],
"o35-90":["Попереду пішохідний перехід і перехрестя зі світлофором — у таких місцях обганяти заборонено. Біле авто попереду може загальмувати перед пішоходами, а ти опинишся на зустрічній просто на переході.","Зебра попереду — обгін відкладається."],
"o35-91":["Дитину саджай у машину з боку тротуару: так вона не опиниться на дорозі поруч із машинами, що проїжджають. Це найбезпечніше місце, щоб посадити й пристебнути малюка.","Діти — з боку тротуару, подалі від потоку."],
"o35-92":["Так, у тумані треба скинути швидкість, навіть якщо інші не гальмують. Видимість погана, а зупинитися ти маєш у межах того, що бачиш, а не орієнтуючись на сусідів.","Туман — дивись не на інших, а на видимість, і скидай швидкість."],
"o35-93":["Ні. Водій сидить надто близько: тулуб нахилений уперед, руки сильно зігнуті, обличчя майже біля керма. Так важко повертати кермо, а подушка безпеки в аварії може травмувати.","Не обіймай кермо: спина на спинці, руки злегка зігнуті."],
"o35-94":["Ні. Водій згорбився й тягнеться до керма, спина не торкається спинки. У такій позі швидко втомлюєшся, гірше керуєш і більше ризикуєш травмуватися в аварії.","Згорблена посадка — швидка втома. Спина має спиратися на спинку."],
"o35-95":["Так. Коли випереджаєш вантажівку в дощ, з-під її коліс летить хмара бризок просто на твоє скло. Заздалегідь перемкни склоочисник на швидший режим, щоб не опинитися наосліп поруч із фурою.","Поруч фура в дощ — двірники на швидший режим."],
"o35-96":["Найнебезпечніша тут зона C — простір одразу за автобусом. Автобус ховає його від тебе, і звідти раптово може вийти пішохід чи виїхати машина.","Що ховає великий автобус — там і чекай сюрпризу."],
"o35-97":["Так. Ремінь потрібен і вагітним: правильно пристебнутий, він захищає і маму, і майбутню дитину. Нижню стрічку прокладай під животом, по стегнах.","Вагітність — не виняток: ремінь береже двох."],
"o35-98":["Якщо люди переходять дорогу не на переході, однаково негайно скидай швидкість і будь напоготові зупинитися. Сигналити чи викликати поліцію — не те, що вбереже їх просто зараз.","Бачиш людей на дорозі — нога на гальмо, де б вони не йшли."],
"o35-99":["Так. На мокрому асфальті шини гірше чіпляються за дорогу, тож авто гальмує довше. У дощ тримай більшу дистанцію і їдь повільніше.","Мокро — значить, слизько: зупинка далі, дистанція більша."],
"o35-100":["Вантажівка вже виїжджає на дорогу, хоч і не мала цього робити. Навіть якщо перевага за тобою, скинь швидкість або зупинись — правота не вбереже від зіткнення з важкою машиною.","Краще поступитися вантажівці, ніж бути правим у кюветі."],
"o35-101":["Так. Хоч ти й їдеш головною, вантажівка вже виїжджає тобі навперейми. Головна дорога не скасовує обов’язку уникнути аварії: скинь швидкість або зупинись.","Головна дорога — не броня. Бачиш небезпеку — гальмуй."],
"o35-102":["Навігацію в смартфоні можна використовувати, лише закріпивши телефон на панелі чи в тримачі. Тримати його в руці під час руху не можна — руки мають бути на кермі.","Телефон-навігатор — у тримач, руки — на кермо."],
"o35-103":["Пасажирів садять і висаджують біля краю дороги, а не з боку сусідньої смуги, де їдуть машини. А перш ніж хтось відчинить двері, глянь у дзеркала, чи безпечно виходити. Правильні обидва варіанти.","Висадка — біля бордюру й після погляду в дзеркало."],
"o35-104":["Ні. Плечова частина ременя тут не проходить через груди й плече, тож під час удару тулуб полетить уперед. Ремінь має лягати навскіс через плече й груди, а нижня стрічка — по стегнах.","Ремінь — через плече й груди, а не збоку чи за спиною."],
"o35-105":["Велосипедист уже перетинає перехрестя перед тобою. Пригальмуй і дай йому спокійно доїхати — об’їжджати його чи сигналити тому, хто позаду, не треба.","Велосипедист на перехресті — пригальмуй і дай доїхати."],
"o35-106":["Ні. Ремінь розрахований на людину, яка сидить рівно: тільки тоді він лягає на плече й стегна. Якщо пасажир лежить, під час удару він просто вислизне з-під ременя.","Ремінь тримає того, хто сидить. Хто лежить — той без захисту."],
"o35-107":["Новий водій може бути іншого зросту, тож під нього треба налаштувати і сидіння, і дзеркала. Інакше буде незручно діставати до педалей і не видно, що позаду.","Новий водій — нові налаштування: і сидіння, і дзеркала."],
"o35-108":["Якщо сонце засліпило, увімкни аварійку, не змінюй смуги, знижуй швидкість і зупинись. Звертати вбік наосліп небезпечно — можна зачепити того, кого не бачиш.","Засліпило сонце — аварійка, своя смуга, гальмо."],
"o35-109":["Ні. Ремінь у нього пропущено неправильно: плечова частина не лежить через плече й груди. В аварії такий ремінь не втримає тулуб і навіть може травмувати.","Ремінь «для вигляду» не рятує: тільки через плече й груди."],
"o35-110":["Так. Довга розмова, особливо коли пасажир нахиляється до водія, відволікає увагу від дороги. Навіть якщо огляд не закритий, думки вже не про рух.","Очі на дорозі, а думки в розмові — це вже неуважність."],
"o35-111":["Миготливий жовтий означає, що світлофор не регулює рух, і черговість доведеться визначати самому — за знаками й правилами. Тож скидай швидкість і будь напоготові зупинитися.","Жовтий мигає — світлофор «відпочиває», а ти пильнуєш."],
"o35-112":["Гальмівний шлях залежить і від швидкості, і від погоди: що швидше їдеш і що слизькіша дорога від дощу, снігу чи льоду, то довше авто зупиняється. Тож правильні обидва варіанти.","Швидко і мокро — гальмуєш довго."],
"o35-113":["Пального йде більше, коли їдеш швидше, коли машина важча і коли вона завантажена. Усе це змушує двигун працювати сильніше, тож правильні всі варіанти.","Швидше, важче, повніше — більше пального."],
"o35-114":["Так. Якщо тримаєш достатню відстань, то коли машина попереду різко загальмує, ти встигнеш просто зупинитися — без жодних об’їздів і перестроювань.","Дистанція — твій запас безпеки перед бампером сусіда."],
"o35-115":["Так. Зупинившись на вимогу поліцейського, увімкни аварійку — так інші водії бачать, що машина стоїть, і об’їжджають її обережніше.","Поліція просить стати — вмикай аварійку."],
"o35-116":["Навіть якщо цей водій раніше тобі заважав, не мсти й не прискорюйся. Перешкоджати обгону не можна: дорога — не місце для з’ясування стосунків.","Не перегони, а дорога: пропусти й забудь."],
"o35-117":["Ні. Учень їздить разом з інструктором, і окремо мати при собі медичну довідку Правила від нього не вимагають.","Учень за кермом — з інструктором поруч, а не з довідкою в кишені."],
"o35-118":["Так. У місті сигналити можна саме тоді, коли це допоможе відвернути аварію. Якщо водій попереду створив небезпеку, сигнал може його вчасно попередити.","Клаксон у місті — тільки щоб урятувати від ДТП."],
"o35-119":["Ні. Запаморочення й сильна втома небезпечні навіть на коротку поїздку — аварія може статися за мить. Краще відпочити або дістатися іншим способом.","Паморочиться в голові — ключі в кишеню, хоч би як близько їхати."],
"o35-120":["Якщо після ліків паморочиться в голові й важко зосередитися, керувати не можна взагалі. Ні порожня дорога, ні пасажири поруч цього не змінюють.","Ліки затуманили голову — за кермо не сідаєш."],
"o35-121":["Посвідчення категорії B дають лише з 18 років. Ні досвід, ні машина, отримана у спадок, віку не замінять.","Категорія B — тільки з 18, без жодних «але»."],
"o35-122":["Виходити можна лише тоді, коли транспорт повністю зупинився, — з автобуса, легковика чи мотоцикла однаково. На ходу легко впасти чи потрапити під колеса.","Колеса стали — тоді й виходиш."],
"o35-123":["Біля школи діти можуть раптово вибігти на дорогу, тому насамперед скинь швидкість. Так устигнеш зупинитися, а сигналити чи вмикати світло — не головне.","Школа поруч — нога з газу."],
"o35-124":["Навіть трохи алкоголю сповільнює реакцію й погіршує увагу, хоч сам водій цього може не відчувати. Тож сідати за кермо можна тільки на тверезу голову.","Ковток — і реакція вже не та."],
"o35-125":["П’яний водій пізніше реагує, їде швидше й гірше оцінює небезпеку, тож аварії з ним зазвичай важчі. Часто він навіть не встигає загальмувати перед ударом.","Алкоголь за кермом — удар сильніший, наслідки важчі."],
"o35-126":["Безпечно їхати — значить постійно стежити за всім довкола: попереду, збоку й позаду, тримаючи дистанцію та бокові проміжки. Пасажири цього за тебе не зроблять.","Голова «на шарнірах»: дивись усюди й тримай простір довкола авто."],
"o35-127":["Гравій на дорозі — як кульки під колесами: шини гірше тримаються за покриття. Перед крутим поворотом скинь швидкість, щоб авто не винесло.","Камінці під колесами — повільніше в поворот."],
"o35-128":["Кінь може злякатися шуму чи машини, що мчить поруч, і смикнутися вбік. Тому скинь швидкість і об’їжджай вершника якомога ширше, не сигналячи.","Кінь лякливий: тихо, повільно і подалі."],
"o35-129":["Категорія B розрахована на машини з меншою кількістю місць. Транспорт на десять місць разом із водієм — це вже невеликий автобус, і для нього потрібна інша категорія.","Десять місць — уже мікроавтобус, а не легковик: B не вистачить."],
"o35-130":["Не піддавайся тиску тих, хто сигналить позаду. Зберігай спокій і обганяй велосипедиста лише тоді, коли для цього буде досить місця й це безпечно.","Сигналять ззаду — хай сигналять: обганяєш, коли безпечно, а не коли квапять."],
"o35-131":["Перш ніж відчинити двері з боку дороги, переконайся, що позаду не їде машина чи велосипедист. Двері, відчинені навмання, — пастка для того, хто їде повз.","Спершу дзеркало й погляд назад — потім двері."],
"o35-132":["Діти, які граються біля дороги, можуть будь-якої миті вибігти за м’ячем чи один за одним. Тому скидай швидкість і будь напоготові повністю зупинитися — сигнал тут не допоможе.","Бачиш дітей біля дороги — нога над гальмом: діти непередбачувані, як м’ячик."],
"o35-133":["Дитина може вискочити на дорогу будь-якої секунди. Тож пильнуй, скидай швидкість і будь напоготові зупинитися повністю — «трохи пригальмувати» тут замало.","Діти поруч з дорогою = нога на гальмі. Готовність до повної зупинки, а не «мінус трохи»."],
"o35-134":["Де багато людей, як на фото з натовпом на переході, хтось обов’язково ступить на дорогу несподівано. Тому їдь повільніше, уважно дивись і будь напоготові зупинитися.","Натовп поруч — швидкість униз, увага вгору."],
"o35-135":["Літні люди ходять повільно, гірше чують і бачать, можуть не помітити машину чи раптом зупинитися. Тож пригальмуй, будь уважніше і напоготові зупинитися повністю.","Літня людина з паличкою на узбіччі — твоя нога вже над гальмом."],
"o35-136":["Нетвереза людина може раптово хитнутися чи вийти на дорогу, а сигнал її лише налякає. Тож максимум уваги, менша швидкість і будь напоготові зупинитися.","Пішохід хитається — ти гальмуєш, а не сигналиш."],
"o35-137":["Навіть якщо на переході порожньо, людина може з’явитися будь-якої миті — наприклад, з-за припаркованої червоної машини на фото. Під’їжджай уважно і будь напоготові пригальмувати чи зупинитися. Чекати пішоходів не треба.","Порожня зебра — ще не безпечна: око на тротуар, нога над гальмом."],
"o35-138":["З-за припаркованих машин може вибігти людина чи тварина, а хтось у салоні може раптом відчинити двері. Тож уздовж такого ряду авто їдь максимально обережно.","Ряд припаркованих машин — ряд схованок: за кожною хтось може бути."],
"o35-139":["Не втягуйся в перегони чи сварку з агресивним водієм. Зберігай спокій, за потреби пригальмуй і уважно стеж за тим, що відбувається на дорозі.","Агресор попереду — хай їде. Твоя зброя — спокій і гальмо."],
"o35-140":["Уночі гірше видно і складніше оцінити, що відбувається попереду. Тож тримай безпечну відстань до машини спереду — так устигнеш зреагувати, якщо вона різко загальмує.","Темніше — далі. Уночі дистанцію не скорочуй."],
"o35-141":["Безпечний водій не перекладає відповідальність на інших і не покладається на удачу: за кермом ти відповідаєш і за себе, і за всіх довкола.","Кермо в руках — відповідальність за всіх на дорозі."],
"o35-142":["Коли злива раптом закриває огляд, скидай швидкість і збільшуй відстань до машини попереду. Різко ставати посеред дороги небезпечно, а дальнє світло в дощ лише погіршить огляд.","Злива — повільніше і далі: менше швидкості, більше дистанції."],
"o35-143":["Удень краще видно і менше хочеться спати, а часті перерви знімають утому. Тому довгу поїздку плануй на світлий час доби з багатьма зупинками для відпочинку.","Далека дорога: їдь, поки світло, і зупиняйся частіше."],
"o35-144":["Безпечна відстань збоку від велосипедиста не одна на всі випадки: вона залежить і від того, як він їде (хитається, оглядається), і від твоєї швидкості — що швидше, то більший запас.","Інтервал до велосипеда рахуй за двома: як їде він і як швидко їдеш ти."],
"o35-145":["Після довгої їзди рівною трасою на високій швидкості до неї звикаєш, і вона здається меншою, ніж є насправді. Тому частіше поглядай на спідометр.","Довга траса обманює: здається, що повзеш, а насправді летиш."],
"o35-146":["Найменше пального йде, коли розганяєшся плавно і так само плавно сповільнюєшся: різкий газ «з’їдає» бензин, а різке гальмування марнує набрану швидкість.","Плавно рушай — плавно гальмуй: і бак, і нерви цілі."],
"o35-147":["У темряві чи в похмуру погоду важче оцінити відстань і швидкість, тому зустрічна машина здається повільнішою, ніж є насправді. Вона наблизиться швидше, ніж здається.","У сутінках зустрічна «повзе» лише на вигляд — насправді вона швидша."],
"o35-148":["Коли назустріч світять фари, на них дивитися не можна — засліплять. Тому орієнтуйся на праву лінію краю дороги: вона подалі від зустрічного світла і тримає тебе у своїй смузі.","Зустрічні фари сліплять — дивись праворуч, на лінію краю дороги."],
"o35-149":["Одразу після дощу вода на асфальті змішується з пилом і брудом, дорога стає слизькою, і машина гальмує довше. Тримай більшу відстань і пригальмовуй заздалегідь.","Мокро — гальмуєш довго. Дощ подовжує гальмівний шлях."],
"o35-150":["Навіть якщо тебе нахабно підрізали, не мстися: не блимай фарами, не підрізай у відповідь і не йди з’ясовувати стосунки. Просто спокійно тримай дистанцію і їдь далі.","Підрізали — видихни. Помста на дорозі = нова аварія."],
"o35-151":["Що гірше бачиш дорогу, як у тумані на фото, то повільніше треба їхати, щоб устигнути зупинитися перед тим, що раптом з’явиться попереду.","Бачиш менше — їдеш повільніше."],
"o35-152":["Навпаки: що гірше видно, як у густому тумані на фото, то повільніше треба їхати. Швидкість має бути такою, щоб устигнути зупинитися перед тим, що раптом з’явиться попереду.","Туман густішає — стрілка спідометра опускається, а не росте."],
"o35-153":["Двері відчиняють лише тоді, коли машина вже повністю стоїть. На ходу відчинені двері можуть зачепити пішохода, велосипедиста чи інше авто, а людина може випасти.","Спершу повна зупинка — потім двері. Ніколи навпаки."],
"o35-154":["Пасажирам теж не можна відчиняти двері, поки машина не зупинилася: на ходу двері можуть ударити когось поруч, а сама людина — травмуватися.","Колеса крутяться — двері зачинені. Для всіх у салоні."],
"o35-155":["Біля автобуса, в який сідають чи з якого виходять діти, хтось із малечі може раптом вибігти на дорогу. Тож скидай швидкість, пильнуй кожну дитину і за потреби зупинись. Сигнал лише налякає дітей.","Автобус і діти — нога на гальмі, рука подалі від сигналу."],
"o35-156":["Зона В — простір просто перед автобусом. З-за нього може раптово вийти пішохід, якого ти не бачиш, або сам автобус почне рух. Тому туди треба дивитися найуважніше.","Великий автобус — велика схованка: найбільша загроза там, де нічого не видно."],
"o35-157":["У зоні С людина стоїть між припаркованими машинами просто біля дороги: вона може раптом вийти на дорогу або відчинити двері. Тому найбільша небезпека саме там.","Людина між машинами на узбіччі — це або пішохід під колесами, або двері перед бампером."],
"o35-158":["Дальнє світло сліпить зустрічного водія, і він на мить перестає бачити дорогу. Тому щойно з’являється зустрічна машина, водій білого авто має перемкнутися на ближнє.","Бачиш зустрічні фари — «опусти» свої: з дальнього на ближнє."],
"o35-159":["Новачок реагує повільніше, а вміння швидко «читати» дорогу приходить лише з досвідом — після багатьох поїздок і розбору своїх рішень. Обидві причини правильні, тож новачкові варто їхати повільніше.","Новачок: реакція повільніша + досвіду менше = швидкість нижча."],
"o35-160":["Пішохід у зоні С стоїть між машинами біля самої дороги. Розраховувати, що він тебе пропустить, не можна: він може будь-якої миті рушити тобі під колеса.","Пішохід стоїть — не означає, що чекає. Він може рушити будь-якої миті."],
"o35-161":["Якщо велосипедист попереду постійно різко пригальмовує, не сигналь і не нервуй: зберігай спокій, за потреби пригальмуй, будь напоготові зупинитися й уважно стеж за дорогою.","Нервовий велосипедист попереду — спокійний ти позаду."],
"o35-162":["Перш ніж відчинити двері з боку дороги, подивись у дзеркало й озирнись, чи ніхто не їде. Відчиняй лише тоді, коли переконаєшся, що це нікому не загрожує.","Спершу дзеркало — потім ручка дверей."],
"o35-163":["Так, водій зі стажем менше двох років зобов’язаний розмістити на машині відповідний розпізнавальний знак. Він попереджає інших, що за кермом новачок, і вони стають уважнішими.","Менше двох років за кермом — розпізнавальний знак на авто обов’язково."],
"o35-164":["Зелений дозволяє їхати, але не гарантує, що шлях вільний: на фото перехрестя перетинає біле авто, а біля переходу стоять люди. Тож скинь швидкість і будь напоготові пригальмувати.","Зелений — дозвіл їхати, а не гарантія, що дорога порожня."],
"o35-165":["Якщо ні на переході, ні біля нього нікого немає, пропускати нікого не треба, тож можна проїхати, не скидаючи швидкості. Але все одно поглядай на тротуари обабіч.","Порожня зебра і порожні тротуари — проїжджай, але очі відкриті."],
"o35-166":["Сіре авто стоїть упритул до пішохідного переходу. Біля самого переходу зупинятися заборонено: машина закриває пішоходів від інших водіїв, а водіїв — від пішоходів.","Зебра — не парковка: біля переходу не стають."],
"o35-167":["Навіть коли перевага за тобою, а зустрічний водій усе одно повертає ліворуч тобі під колеса, треба гальмувати аж до зупинки. Перевага не захищає від удару.","Краще поступитися, ніж доводити свою правоту в аварії."],
"o35-168":["Вантажівка велика, може хитатися на дорозі й гнати сильний потік повітря, а її водій гірше тебе бачить. Тож, наближаючись до неї, тримайся збоку далі, ніж від легковика.","Більша машина — більший запас збоку."],
"o35-169":["Велосипедист на фото стоїть просто біля дороги серед натовпу. Він може будь-якої миті рушити й виїхати на дорогу, тому враховуй це і будь напоготові пригальмувати.","Велосипед стоїть — а за мить уже їде. Чекай руху від кожного біля дороги."],
"o35-170":["Літня людина з візком стоїть на самому краю дороги і може несподівано ступити на неї. Тому, проїжджаючи повз, обов’язково скидай швидкість.","Людина на краю дороги — швидкість менше, увага більше."],
"o35-171":["Засліплює саме світло — яскраві фари зустрічних машин, низьке сонце чи сильні відблиски. Сніг і злива погіршують огляд, але не сліплять.","Сліпить світло: фари, сонце, відблиск."],
"o36-1":["Якщо вважаєш затримання, огляд чи вилучення документів незаконним, скаржитися можна двома шляхами: до суду або до вищого керівництва органу, який це зробив. Обидва варіанти правильні.","Оскаржити можна двома дорогами: «нагору» начальству або до суду."],
"o36-2":["Огляд людини чи її речей обов’язково фіксують на папері: або окремим протоколом, або записом у протоколі про правопорушення чи про затримання. Підходить будь-який із цих способів.","Огляд без запису не рахується: окремий протокол або запис в іншому протоколі."],
"o36-3":["Виїзд на переїзд на червоне при закритому шлагбаумі — дуже небезпечне порушення, тож і кара серйозна: штраф або позбавлення права керувати.","Шлагбаум опущений — ризикуєш і життям, і посвідченням."],
"o36-4":["Поліцейський не може забрати що завгодно на свій розсуд. Вилучають лише те, чим скоєно порушення, або те, що є його безпосереднім предметом.","Забирають лише «докази»: знаряддя чи предмет порушення, а не все підряд."],
"o36-5":["Якщо є підстави вважати водія нетверезим, його не лише перевіряють на сп’яніння, а й відсторонюють від керування, щоб він більше нікуди не поїхав.","Підозра на сп’яніння: геть від керма і на перевірку."],
"o36-6":["Так, поліція має право адміністративно затримати водія, який порушив правила дорожнього руху.","Порушення правил — законна підстава для затримання поліцією."],
"o36-7":["Адміністративне затримання людини, яка вчинила правопорушення, може тривати не більше трьох годин — довше тримати її так не можна.","Три години — стеля для адмінзатримання."],
"o36-8":["Втеча з місця ДТП, до якої маєш стосунок, карається суворо: штрафом, громадськими роботами або навіть адміністративним арештом.","Втеча з ДТП б’є і по гаманцю, і по часу, і по волі: штраф, роботи чи арешт."],
"o37-1":["Кістку, що стирчить, не чіпають і не вправляють: рану закривають стерильною пов’язкою, ногу фіксують так, щоб не рухалися суглоби вище й нижче перелому, і везуть у зручному для людини положенні.","Відкритий перелом: закрий рану, зафіксуй суглоби вище й нижче, не вправляй."],
"o37-2":["При переламаній ключиці в пахву кладуть валик із бинта чи вати, а руку, зігнуту в лікті, прибинтовують до тулуба. Так уламки менше рухаються і менше болить.","Ключиця: валик під пахву, лікоть зігнутий, рука притиснута до тіла."],
"o37-3":["Спершу зупиняють сильну кровотечу — від неї людина може загинути за лічені хвилини. Далі звільняють дихальні шляхи, а потім забезпечують нормальне дихання.","Спершу кров, потім шлях для повітря, потім саме дихання."],
"o37-4":["У базовому алгоритмі реанімації не шукають пульс і не дивляться на зіниці: якщо людина не дихає, вважають, що серце зупинилося, і одразу починають реанімацію.","Не дихає — значить, серце стоїть: починай натискати."],
"o37-5":["На грудну клітку тиснуть у чіткому темпі — 100 разів за хвилину, тобто майже двічі на секунду. Повільніше — кров погано рухається тілом.","Тисни під ритм пісні «Stayin’ Alive» — якраз близько 100 ударів за хвилину."],
"o37-6":["Реанімацію проводять циклами: 30 натискань на грудну клітку, потім 2 вдихи, і знову по колу.","30 і 2: тридцять разів тиснеш — двічі вдихаєш."],
"o37-7":["Пухирі від опіку не проколюють — вони захищають рану від інфекції. На опік накладають чисту пов’язку і фіксують її легенько, без тиску.","Пухир — природний пластир: не чіпай його, лише прикрий чистим."],
"o37-8":["Спершу треба припинити горіння, потім охолодити опік прохолодною водою і накрити чистою марлевою пов’язкою. Лід, спирт, йод чи зеленка лише ще більше пошкодять шкіру.","Опік: загасити — охолодити водою — накрити. Ні льоду, ні зеленки."],
"o37-9":["Реанімацію не припиняють за годинником. Зупиняються тоді, коли з’являються ознаки життя: людина починає дихати чи приходить до тями.","Зупиняй натискання, коли людина «ожила», а не коли минуло стільки-то хвилин."],
"o37-10":["Реанімацію не кидають через певний час: її продовжують, доки не приїде бригада екстреної допомоги й не візьме все на себе.","Тиснеш, поки не передаси естафету медикам."],
"o37-11":["Коли точно видно, звідки б’є сильна кровотеча, джгут накладають трохи вище рани — на 5-7 см, не впритул до неї і не надто далеко.","Джгут — на 5-7 см вище рани: не впритул і не далеко."],
"o37-12":["Стороннє тіло з рани не витягують: воно може затуляти пошкоджену судину, і після виймання почнеться сильна кровотеча. Пов’язку накладають навколо нього.","Застрягло в рані — хай там і лишається до лікарів."],
"o37-13":["Коли мотоцикліст перелітає через перешкоду, він часто падає на голову, і найбільше страждає шия. Тому першою підозрюй травму шийного відділу хребта і не рухай йому голову без потреби.","Політ через перешкоду — бережи шию: голову не крутити."],
"o37-14":["Джгут затягують рівно настільки, щоб кровотеча зупинилася. Слабше — кров тектиме далі, а «скільки є сили» — зайве травмує руку чи ногу.","Кров зупинилась — досить тягнути."],
"o37-15":["Людину без свідомості, але без травм, кладуть у стабільне положення на бік. Так язик не западе, а блювота не потрапить у дихальні шляхи.","Без свідомості й без травм — на бік, щоб дихати було чим."],
"o37-16":["При сильній артеріальній кровотечі людина втрачає кров за лічені хвилини, тому спершу накладають джгут і записують час, а вже потім телефонують на 103.","Спершу зупини кров, потім дзвони: джгут — час — 103."],
"o37-17":["Перш ніж допомагати, переконайся, що тобі й постраждалому нічого не загрожує: машини, вогонь, струм. Якщо постраждаєш сам, допомогти вже не зможеш.","Спершу безпека — потім допомога."],
"o37-18":["Джгут чи тугий бинт на шиї можуть перекрити дихання і кровопостачання мозку. Тому рану на шиї щільно притискають пальцями.","Шия — не кінцівка: ні джгута, ні тугого бинта, лише пальці на рану."],
"o37-19":["Якщо рани не видно (наприклад, під одягом), а кров тече сильно, джгут накладають якомога вище на руку чи ногу — так він точно опиниться вище пошкодження.","Не бачиш рани — став джгут якомога вище, щоб точно перекрити."],
"o37-20":["Від випарів бензину людині бракує свіжого повітря, тому її виносять на свіже повітря, зігрівають, а якщо не дихає — роблять штучне дихання. Промивати шлунок не треба: отрута потрапила через дихання.","Отруєння парою лікують повітрям: винести, зігріти, допомогти дихати."],
"o37-21":["Електроліт з акумулятора — їдка рідина, і найкраще її просто змити великою кількістю води. Йод чи перекис лише додатково подразнять шкіру.","Електроліт на шкірі — під воду, і багато."],
"o37-22":["При харчовому отруєнні треба позбутися отрути: зупинитися, випити багато рідини, викликати блювання і прийняти активоване вугілля. Кава чи валеріанка тут не допоможуть.","Харчове отруєння — «промий» шлунок: вода, блювання, вугілля."],
"o37-23":["Забитий живіт не розтирають і не гріють — так можна посилити кровотечу всередині. Людині дають повний спокій, а на забите місце кладуть холод.","Удар у живіт: спокій і холод, ніякого тепла й масажу."],
"o37-24":["Якщо людина не дихає, не гай часу на пошук пульсу чи нашатир — одразу починай серцево-легеневу реанімацію. Кожна хвилина зволікання зменшує шанси.","Не дихає — одразу тисни на груди."],
"o37-25":["Людину виводять подалі від жару і накривають опік сухою стерильною пов’язкою або чистою бавовняною тканиною. Пухирі не проколюють, олією й вазеліном не мажуть.","Опік — тільки чисте й сухе: ні олії, ні проколів."],
"o37-26":["При болю в серці людині дають більше свіжого повітря (розстебнути комір, відчинити вікно) і таблетку нітрогліцерину чи валідолу під язик. Холодна вода й нашатир тут не допоможуть.","Болить серце — повітря і таблетку під язик."],
"o37-27":["Зламану руку чи ногу треба знерухомити шиною або тим, що її замінить: дошкою, палицею, згорнутим журналом. Тоді уламки не рухаються і не ранять тканини.","Перелом — шина: що нерухоміше, то менше шкоди."],
"o37-28":["Алкоголь гальмує мозок, тому водій реагує повільніше — час реакції збільшується, і машина встигає проїхати більше, перш ніж почнеться гальмування.","Чарка в крові — гальма в голові: реакція довшає."],
"o37-29":["Найнебезпечніша — артеріальна кровотеча: кров іде під тиском, поштовхами, і людина може втратити її дуже швидко.","Артерія — «магістраль» під тиском: з неї кров витікає найшвидше."],
"o37-30":["Сильну артеріальну кровотечу звичайна пов’язка не втримає, і сама вона не спиниться, тому накладають кровоспинний джгут.","Артерія б’є фонтаном — потрібен джгут."],
"o37-31":["Венозна кров тече спокійніше, без поштовхів, тому її зазвичай зупиняють пов’язкою, що тисне на рану. Джгут тут, як правило, не потрібен.","Вена — тиснуча пов’язка, артерія — джгут."],
"o37-32":["Артеріальна кров яскраво-червона, тече швидко і б’є поштовхами в такт серцю. Темна кров, що повільно витікає, — це вже венозна кровотеча.","Артерія — яскраво і поштовхами, вена — темно і спокійно."],
"o37-33":["Венозна кров темна і витікає з рани повільно, рівномірно, без поштовхів. Яскрава кров, що б’є поштовхами, — це вже артерія.","Вена — темна й повільна, артерія — яскрава й швидка."],
"o37-34":["Коли кров ллється сильно, а звідки саме — не видно, шукати рану ніколи. Джгут ставлять якомога вище на руці чи нозі, щоб він гарантовано був вище пошкодження.","Рани не видно, а кров ллється — джгут якомога вище, без пошуків."],
"o37-35":["При травмі грудей людині важко дихати, тож її не вкладають силоміць, а допомагають зайняти те положення, у якому дихати найлегше.","Травма грудей — хай людина сама обере позу, в якій легше дихати."],
"o37-36":["Спершу телефонуй у швидку — бригада вже їхатиме, а диспетчер підкаже, що робити, — і одразу починай серцево-легеневу реанімацію. Чекати, поки людина задихає, щоб подзвонити, не можна.","Дзвінок і руки на груди: швидка вже їде, а ти тиснеш."],
"o37-37":["Пухирі не проколюють: вони захищають рану від інфекції. Місце опіку охолоджують і накривають чистою стерильною сухою пов’язкою, яка не тисне.","Пухирі цілі, опік охолоджений, пов’язка суха й вільна."],
"o37-38":["Головне, від чого залежить допомога при опіку, — наскільки сильно й глибоко пошкоджені шкіра та тканини. Вік, зріст чи місце, де людина обпеклася, тут другорядні.","Опік оцінюють за глибиною ушкодження шкіри."],
"o37-39":["Пошкодження шкіри й тканин від високої температури — це термічний опік. Тепловий удар — це перегрів усього тіла, а не рана на шкірі.","Термічний = від жару, опік = рана шкіри."],
"o37-40":["Якщо пухирі вже прорвалися, рана відкрита, тож її просто накривають чистою стерильною сухою пов’язкою, яка не тисне. Дезінфікувальними засобами опік не обробляють.","Пухир лопнув — просто прикрий чистим і сухим, без тиску."],
"o37-41":["Предмет, що застряг у животі, витягати не можна: він може затуляти пошкоджені судини, і почнеться сильна кровотеча. Його надійно закріплюють і доглядають за людиною до приїзду швидкої.","Застрягло — не тягни: закріпи й чекай медиків."],
"o37-42":["Якщо кров швидко й рясно витікає з рани назовні — це масивна зовнішня кровотеча. Внутрішньої кровотечі не видно, бо кров лишається всередині тіла.","Видно, як ллється, — зовнішня; не видно — внутрішня."],
"o37-43":["Відкритий перелом видно одразу: на місці перелому є рана, з неї тече кров, а в рані можуть проглядати уламки кістки.","Відкритий — бо кістку «відкрито» назовні: рана, кров, уламки."],
"o37-44":["Під раною на голові може бути пошкоджена кістка черепа, тож рану не мацають, на неї не тиснуть і не заливають антисептиками. Усі три заборони правильні.","Рана на голові: не мацати, не тиснути, не заливати."],
"o37-45":["Якщо кістка зламана, а шкіра над нею ціла, — перелом закритий: кістку не видно, вона «закрита» шкірою.","Шкіра ціла — перелом закритий."],
"o37-46":["Якщо разом із кісткою пошкоджена й шкіра над місцем перелому, — це відкритий перелом: рана «відкриває» його назовні.","Шкіра порвана — перелом відкритий."],
"o37-47":["При закритому переломі допомагають людині влаштуватися так, щоб боліло найменше, і знерухомлюють пошкоджену кінцівку шиною або підручними засобами. Обидві дії правильні.","Закритий перелом: зручна поза + шина."],
"o37-48":["Спершу переконайся, що небезпеки немає ні тобі, ні людям довкола, ні постраждалому, — і лише тоді допомагай. Інакше постраждалих може стати більше.","Спершу оглянься, потім рятуй."],
"o37-49":["Шок — це стан, коли органам бракує крові. До нього може призвести і сильна зовнішня кровотеча, і внутрішня, і серцевий напад, тож правильні всі варіанти.","Шок — «голод» органів на кров: хоч рана, хоч кровотеча всередині, хоч серце."],
"o37-50":["При підозрі на шок спершу викликають швидку й слухають диспетчера, потім, якщо можна, усувають причину (наприклад, зупиняють кровотечу) і вкладають людину в протишокове положення. Заспокійливого не дають.","Шок: дзвінок — причина — протишокова поза. Ніяких пігулок."],
"o37-51":["Коли в аварії є потерпілі, найперше — рятувати людей: надати домедичну допомогу і викликати швидку. Якщо самотужки не можеш, попроси присутніх і відправ потерпілих до лікарні.","Спершу люди, потім поліція і сліди."],
"o37-52":["Коли бачиш, звідки б’є кров, найшвидше її спинить сильний тиск: щосили притисни рану руками і наклади пов’язку, що тисне. Промивати рану зараз — марнувати дорогоцінні секунди.","Бачиш, звідки ллється, — тисни щосили і бинтуй туго."],
"o37-53":["Якщо після джгута кров і далі тече, його затягують сильніше або накладають другий вище першого. Ще можна щільно затиснути рану руками до приїзду швидкої чи туго заповнити її бинтом. Обидва варіанти правильні.","Джгут не впорався — тисни сильніше: другий джгут, руки чи тампон."],
"o37-54":["На основу шиї джгут не накладеш, а кров звідти витікає дуже швидко. Тому найперше — щосили притиснути рану. Заспокоювати й влаштовувати людину зручніше будеш уже потім.","Шия кровить — тисни щосили, розмови потім."],
"o37-55":["У пахві джгут не накладеш, а кровотеча звідти небезпечна, тож найперше — якомога сильніше притиснути рану. Усе інше — після того, як кров зупинено.","Пахва кровить — спершу тиск на рану, потім усе інше."],
"o37-56":["Реанімацію до приїзду швидкої зупиняють, якщо людина ожила (сама дихає, рухається), якщо з’явилася загроза життю тобі чи їй, або якщо фізично вже не можеш продовжувати. Правильні всі варіанти.","Три причини зупинитися: людина ожила, стало небезпечно, сил більше немає."],
"o37-57":["При травмі голови часто страждає і шия. Тому найперше — обмежити рухи в шийному відділі: тримати голову рівно, не крутити і не трусити людину.","Травма голови — тримай шию нерухомо."],
"o37-58":["Рану на голові накривають марлевою пов’язкою і фіксують її без сильного тиску — під раною може бути пошкоджена кістка черепа. Антисептики й тугі пов’язки тут не потрібні.","Голова: пов’язка є, тиску немає."],
"o37-59":["Про тупу травму живота свідчать і синці чи гематоми на передній або боковій стінці живота, і біль у животі. Тому правильні обидва варіанти.","Синець + біль у животі = підозра на травму органів усередині."],
"o37-60":["Інсульт видно за раптовими змінами: обличчя перекошується, рука чи нога з одного боку слабне або німіє, людина погано говорить чи не розуміє простих запитань. Усі ці ознаки правильні.","Обличчя, рука, мова: раптова зміна будь-чого — підозра на інсульт."],
"o38-1":["Хто кого пропускає, визначають правила, але чи справді водій вантажівки їх дотримається, видно лише з його дій. Тож їдь за правилами і водночас стеж, що робить вантажівка.","Правила кажуть, хто перший, а очі перевіряють, чи інший це знає."],
"o38-2":["На вузькому мосту перевага за тобою — це показує синій знак праворуч. Але якщо вантажівка не скидає швидкість і заїжджає на міст, починай гальмувати: краще поступитися, ніж зіткнутися.","Перевага на знаку не зупинить вантажівку — зупиняєшся ти."],
"o38-3":["Якщо водій вантажівки кілька разів блимає дальнім, незрозуміло, що він має на увазі. Тож пригальмуй і подивись, що він робитиме далі. Блимати чи сигналити у відповідь — не вихід.","Незрозумілий сигнал — пригальмуй і з’ясуй, а не сперечайся фарами."],
"o38-4":["Коли машина попереду коротко блимає стоп-сигналами в щільному потоці, вона або просить тебе відстати, або попереджає, що зараз гальмуватиме. Обидва значення можливі.","Блимнули стопи попереду — відпусти газ: або «відстань», або «гальмую»."],
"o38-5":["Поки обгінна машина позаду, твоє дальнє освітлює їй дорогу, а коли ви порівнялися на сусідніх смугах, воно вже б’є їй у дзеркала. Тож саме в цю мить перемикайся на ближнє.","Порівнялися боками — дальнє вимикай."],
"o38-6":["Перш ніж вийти з машини на дорозі, зроби все: убезпеч авто від самовільного руху, переконайся через дзеркало чи озирнувшись, що вихід безпечний, а вночі на неосвітленій ділянці ввімкни габарити.","Перед виходом: машина стоїть надійно, позаду чисто, вночі — габарити."],
"o38-7":["Під час перестроювання можна не помітити машину в «мертвій» зоні, а ще зненацька може загальмувати той, хто попереду, чи різко розігнатися сусід позаду. Усі ці дії здатні спричинити аварію.","Мертва зона, різке гальмо, різкий газ — три пастки перестроювання."],
"o38-8":["Коротким увімкненням лівого покажчика водій вантажівки, який бачить дорогу далі за тебе, підказує: обганяти зараз небезпечно, попереду щось є.","Вантажівка блимнула лівим — «не обганяй»: їй видно далі."],
"o38-9":["Якщо машина попереду вночі різко стала, причини ти не знаєш — на дорозі може бути перешкода чи людина. Зупинись у своїй смузі з аварійкою і об’їжджай, лише переконавшись, що це безпечно.","Попереду різко стали — стань і ти, аварійка, і спершу розберися."],
"o38-10":["Щоб зустрічні фари не засліпили, не дивись прямо на них — переведи погляд праворуч, на узбіччя, і орієнтуйся за правим краєм дороги.","Сліплять зліва — дивись направо."],
"o38-11":["Уночі під час роз’їзду дивитися в бік зустрічних фар — означає засліпнути. Найбезпечніше стежити за лінією правого краю дороги: так тримаєш свою смугу і не дивишся на світло.","Зустрічна світить — тримайся правої лінії."],
"o38-12":["Що швидше їдеш, то більше погляд зосереджується далеко попереду, а те, що збоку, «розмивається». Поле зору звужується — і пішохода біля дороги можна не помітити.","Більша швидкість — вужчий «тунель» перед очима."],
"o38-13":["Після дощу асфальт мокрий, а вода з пилом утворює слизьку плівку, тому шини гірше тримають дорогу і машина зупиняється довше. Гальмуй раніше і тримай більшу дистанцію.","Мокра дорога — довге гальмо."],
"o38-14":["Підрізали — не відповідай тим самим: блимання фарами, «помста» гальмуванням чи розбірки на світлофорі лише створять нову небезпеку. Просто пропусти й спокійно їдь далі.","На хамство на дорозі найкраща відповідь — жодної."],
"o39-1":["Європротокол можна скласти лише тоді, коли в обох водіїв є чинні поліси обов’язкового автострахування (або «Зелена картка»). Одного поліса на двох замало.","Європротокол — це дует: два водії, два чинні поліси."],
"o39-2":["Європротокол — тільки для випадків, коли постраждали самі машини. Якщо пошкоджено щось інше — паркан, стовп, чуже майно, — скласти його не можна.","Європротокол — лише про машини: зачепили стовп — уже не він."],
"o39-3":["Європротокол складають лише двоє учасників ДТП. Якщо постраждала ще й третя машина, байдуже, наскільки сильно, — цей спосіб уже не підходить.","Європротокол — розмова на двох: третій зайвий."],
"o39-4":["Європротокол заповнюють самі водії машин, які потрапили в ДТП, без поліції. У цьому й суть: оформити все на місці самостійно.","Європротокол — «зроби сам»: заповнюють водії-учасники."],
"o39-5":["Літера «А» в бланку — просто позначка, а не «винуватець» чи «потерпілий». Тож частину «Транспортний засіб А» може заповнити будь-хто з двох водіїв.","«А» — не «агресор»: цю частину заповнює будь-хто з водіїв."],
"o39-6":["Якщо в ДТП хтось травмувався чи загинув, європротокол не складають — навіть коли шкода здається незначною. Він лише для аварій, де постраждали тільки машини.","Є постраждалі люди — європротоколу немає."],
"o44-1":["Узбіччя не для їзди: обминати ним вантажівку, як на малюнку, не можна. А от зупинитися чи поставити там машину дозволено.","Узбіччя — щоб стати, а не щоб їхати."],
"o44-2":["Права категорії В, тобто на звичайну легкову машину, як на фото, видають з 18 років.","Повноліття — і за кермо легковика: категорія В з 18."],
"o44-3":["Білий знак з назвою міста, як «Одеса» на малюнку, означає початок населеного пункту. Тут діє обмеження швидкості 50 км/год.","Біла табличка з назвою міста — тримай 50."],
"o44-4":["Під час практичного навчання на категорію В кожен має відпрацювати керування на майданчику, зокрема в темряві, і навчитися їздити заднім ходом за дзеркалами. Усе це обов’язково.","Майданчик, ніч, задній хід — повний набір для категорії В."],
"o44-5":["У темну пору доби, навіть на добре освітленій вулиці, вмикають фари — ближнє або дальнє світло. Самих габаритів замало, а протитуманки — для туману.","Темно — фари обов’язково, навіть під ліхтарями."],
"o44-6":["Зупинятися й ставити машину на дорозі можна в спеціально відведених для цього місцях, а також на узбіччі. Обидві відповіді правильні.","Стати можна там, де для цього є місце, або на узбіччі."],
"o44-7":["Безпечна дистанція й відстань збоку залежать від багатьох речей одразу: швидкості, ситуації на дорозі, вантажу, який везеш, і стану самої машини. Тому правильні всі варіанти.","Дистанцію рахуй за чотирма: швидкість, дорога, вантаж, машина."],
"o44-8":["Навіть якщо в кожному напрямку кілька вільних смуг, без потреби в маневрах тримайся якомога правіше. Ліві смуги лишай тим, кому треба обганяти чи повертати.","Нічого не обганяєш — тримайся правіше."],
"o44-9":["Якщо їдеш по колу і не змінюєш смугу, покажчики повороту вмикати не треба: ти нікуди не перестроюєшся, тож і попереджати нема про що.","Не змінюєш смугу — «поворотник» мовчить."],
"o44-10":["Удень за містом вмикають денні ходові вогні, а якщо їх у машині немає, — ближнє світло. Дальнє вдень лише сліпитиме зустрічних.","Удень за містом: денні вогні, а як їх нема — ближнє."],
"o44-11":["Сигналити заборонено в населених пунктах, а за їх межами — там, де стоїть знак заборони звукового сигналу. Виняток один: коли без сигналу не уникнути аварії.","Клаксон — лише щоб уникнути аварії: у місті й під знаком мовчи."],
"o44-12":["Якщо покажчики повороту не працюють, поворот праворуч показують лівою рукою: висувають її у вікно і згинають у лікті під прямим кутом угору.","Праворуч — ліва рука «гачком» угору у вікні."],
"o44-13":["Учасник руху має бути уважним, не смітити на дорозі, не створювати небезпеки своїми діями і повідомляти дорожні служби про виявлені перешкоди. Усе це — його обов’язки.","Уважний, охайний, безпечний і небайдужий — чотири обов’язки на дорозі."],
"o44-14":["Водій завжди має мати при собі реєстраційний документ на машину, посвідчення водія потрібної категорії та поліс автоцивілки (крім тих, кого від неї звільнено). Генеральна довіреність не потрібна.","Три папери під рукою: техпаспорт, права, страховка."],
"o44-15":["З категорією В пасажирів у машині має бути менше дев’яти. Щоб возити більше людей, потрібна вже інша категорія.","Легковик — не автобус: пасажирів менше дев’яти."],
"o44-16":["Що вивчати і скільки годин їздити з інструктором, вирішує не автошкола і не сам інструктор, а єдина для всіх Типова навчальна програма підготовки водіїв.","Програма одна на всіх — типова, а не «як інструктор захоче»."],
"o45-1":["Недостатня видимість — це коли через сутінки, туман, дощ чи снігопад дорогу попереду видно менш ніж на 300 м, як у тумані на малюнку. Якщо огляд закриває поворот дороги — це вже обмежена оглядовість.","Недостатня видимість — винна погода, обмежена оглядовість — винна дорога."],
"o45-2":["«Дати дорогу» не означає обов’язково зупинитися. Це означає не рушати, не продовжувати рух і не маневрувати, якщо через тебе той, хто має перевагу, змушений буде змінити швидкість чи напрямок.","Дати дорогу = не змусити іншого гальмувати чи кермувати. Зупинка — лише за потреби."],
"o45-3":["Перехрестя — це місце, де дороги перетинаються, примикають чи розгалужуються на одному рівні, як на малюнку. Межа — уявні лінії між початками заокруглень країв дороги. Виїзд із двору чи міст над дорогою — не перехрестя.","Перехрестя — дороги зустрічаються на одному рівні. Міст над дорогою чи виїзд із двору не рахуються."],
"o45-4":["Видимість у напрямку руху — це найбільша відстань, на якій з-за керма чітко видно межі дороги та її елементів і всіх, хто на ній, тож можна впевнено орієнтуватися.","Видимість — наскільки далеко ти чітко бачиш дорогу і тих, хто на ній."],
"o45-5":["Склопідйомник, що не працює, не заважає безпечно їхати, тож з ним їздити можна. Решта несправностей з переліку — серед тих, з якими машину експлуатувати заборонено.","Вікно не опускається — не біда, їхати можна."],
"o45-6":["З категорією В максимум — 9 місць, і місце водія теж входить у це число. Тобто рахуй усіх у салоні разом із тим, хто за кермом.","9 — це разом із водієм: рахуй і себе."],
"o45-7":["Протитуманні фари — не обов’язкове обладнання, тож без них їздити можна. А от збите регулювання фар чи невідповідні розсіювачі сліплять інших і погано світять — із цим не можна.","Протитуманок немає — не страшно; фари світять криво — страшно."],
"o45-8":["У легковику обов’язково мають бути аптечка, вогнегасник і знак аварійної зупинки. А противідкатні упори для легкового авто не обов’язкові.","Аптечка, вогнегасник, знак — обов’язкова трійка. Упори — ні."],
"o45-9":["Якщо робочі гальма не можуть зупинити машину навіть на мінімальній швидкості, своїм ходом їхати не можна взагалі — навіть до сервісу чи стоянки. Інші несправності з переліку не настільки критичні.","Немає гальм — немає руху. Зовсім."],
"o45-10":["Балансування вирівнює вагу колеса по колу, щоб воно не било і не вібрувало під час руху. Тоді й кермо не тремтить.","Баланс — щоб колесо крутилося рівно, а не «гупало»."],
"o45-11":["В автоматі з позиції P (паркування) важіль не зрушить, поки не натиснеш педаль гальма. Це захист, щоб машина не рушила несподівано.","Хочеш вийти з P — спершу нога на гальмо, потім важіль."],
"o45-12":["Індикатор 4 — червоний акумулятор із «плюсом» і «мінусом». Якщо він загорівся в дорозі, щось не так з акумулятором.","Батарейка з плюсом і мінусом — проблема з акумулятором."],
"o45-13":["Індикатор 1 — червона маслянка з краплею. Він означає, що в двигуні впав тиск масла або масла замало.","Маслянка з краплею — двигуну бракує масла."],
"o45-14":["Ближнє світло показує зелений значок фари з променями, нахиленими донизу, — це індикатор D. Синій С — дальнє світло, а А і В — протитуманні.","Ближнє — зелене й «дивиться» вниз, дальнє — синє й прямо."],
"o45-15":["Червона маслянка з краплею, як на фото, попереджає: у двигуні впав тиск масла або його замало. Варто зупинитися й перевірити.","Червона маслянка — масло в біді."],
"o45-16":["Червоний значок машини з відчиненими дверцятами, як на фото, означає, що якісь двері не зачинені. Перевір їх, перш ніж їхати далі.","Машинка з «крильцями» — десь відчинені двері."],
"o45-17":["Жовта бензоколонка на панелі приладів, як на фото, загоряється, коли пального в баку лишилося мало. Час шукати заправку.","Засвітилася колонка — їдь до колонки."],
"o45-18":["Коли блимають обидві зелені стрілки одночасно, як на фото, — увімкнена аварійна сигналізація. Одна стрілка — це звичайний покажчик повороту.","Дві стрілки блимають разом — аварійка ввімкнена."],
"o45-19":["Індикатор 3 — людина з ременем через груди. Він загоряється після запуску двигуна і світиться, доки ремінь не пристебнеш.","Чоловічок із ременем — пристебнися, і він згасне."],
"o45-20":["Червоне коло зі знаком оклику в дужках, як на малюнку, — це про гальма: або увімкнене стоянкове гальмо, або можлива проблема з гальмовою системою.","Знак оклику в «дужках» — перевір гальма і ручник."],
"o45-21":["Зелений значок фари, промені якої перетинає хвиляста лінія — ніби світло пробивається крізь туман, — означає, що ввімкнено протитуманні фари.","Хвиляста лінія на променях — це «туман»: горять протитуманки."],
"o45-22":["Жовтий значок, схожий на шину в розрізі зі знаком оклику всередині, як на малюнку, попереджає, що в шинах низький тиск. Перевір і підкачай колеса.","Підкова з протектором і знаком оклику — шина просить повітря."],
"o45-23":["Червоний чоловічок із ременем через груди нагадує: треба пристебнутися.","Бачиш ремінь на чоловічку — пристебни свій."],
"o45-24":["На значку відкрита задня частина машини — це кришка багажника. Тож індикатор попереджає, що багажник не зачинений.","Кришка піднята ззаду — багажник відчинений."],
"o45-25":["Жовтий значок із літерами ABS сигналізує про несправність антиблокувальної системи — тієї, що не дає колесам заблокуватися під час різкого гальмування.","Бачиш ABS — проблема з антиблокуванням."],
"o45-26":["Дальнє світло позначає блакитний значок фари з прямими горизонтальними променями. Зелений індикатор на малюнку означає інше.","Дальнє — блакитне, як далеке небо."],
"o45-27":["Ближнє світло показує зелений значок фари з променями, нахиленими донизу. Блакитний значок із прямими променями — це дальнє.","Ближнє — зелене, промені «дивляться» вниз, на дорогу."],
"o45-28":["Червоний термометр над хвилями означає, що рідина в системі охолодження занадто гаряча, тобто двигун перегрівається. Варто зупинитися й дати йому охолонути.","Термометр у хвилях почервонів — мотор «закипає»."],
"o45-29":["Про проблеми з гальмами попереджає індикатор 1 — червоне коло зі знаком оклику в дужках. Інші значки — пальне, двері й температура двигуна.","Знак оклику в колі з дужками — гальма."],
"o45-30":["Низький рівень пального показує індикатор 2 — жовта бензоколонка. Пора на заправку.","Колонка на панелі — колонка на дорозі."],
"o45-31":["Індикатор 3 — машина з відчиненими дверцятами. Він загоряється, якщо якісь двері зачинені неправильно, і гасне, щойно їх щільно зачиниш.","Машинка з розкритими «крилами» — дочини двері."],
"o45-32":["Перегрів двигуна показує індикатор 4 — червоний термометр над хвилями охолоджувальної рідини.","Термометр — це температура: червоний означає «гаряче»."],
"o45-33":["Блакитний значок фари з прямими горизонтальними променями означає, що ввімкнено дальнє світло. Коли хтось їде назустріч, його треба перемкнути на ближнє.","Блакитне й прямо вдалечінь — дальнє."],
"o46-1":["Відступити від вимог закону водій може лише у двох випадках: коли діє непереборна сила (наприклад, стихія) або коли інакше не відвернути загибелі чи каліцтва людей. Обидва варіанти правильні.","Відступ від закону — лише у форс-мажорі або щоб урятувати життя."],
"o46-2":["Перевірку на алкоголь прямо на місці зупинки проводять у присутності двох свідків. Вони підтверджують, що все відбувалося чесно.","Алкотест на дорозі — при двох свідках."],
"o46-3":["Огляд твого автомобіля проводять у присутності двох понятих — сторонніх людей, які засвідчують, що нічого не підкинули й не приховали.","Огляд авто — двоє понятих поруч."],
"o46-4":["Особистий огляд і огляд речей проводять обов’язково при двох понятих, які стежать, щоб усе було законно.","Огляд тебе чи твоєї сумки — теж двоє понятих."],
"o46-5":["Позбавити прав можуть за керування напідпитку чи під дією наркотиків, за виїзд на переїзд, коли рух через нього заборонено, і за порушення правил, через яке пошкоджено машини, дороги чи інше майно.","Позбавлення прав: сп’яніння, закритий переїзд, аварія з пошкодженнями."],
"o46-6":["Із цього переліку позбавлення права керування загрожує саме за виїзд на залізничний переїзд, коли рух через нього заборонений. Решта порушень карається інакше.","Переїзд закритий — права під загрозою."],
"o46-7":["Поліція може адміністративно затримати і за дрібне хуліганство, і за порушення правил дорожнього руху. В обох випадках обов’язково складають протокол про затримання.","Є затримання — є й протокол про нього."],
"o46-8":["Якщо даєш кермо людині, яка не має права керувати цією машиною, відповідальність несеш і ти. Це адміністративне порушення, а не кримінальне.","Дати кермо тому, хто без прав, — адмінвідповідальність для тебе."],
"o46-9":["На стан сп’яніння перевіряє або поліцейський просто на місці зупинки при двох свідках, або лікар медичного закладу, який має право на такий огляд. Будь-який лікар не підходить.","Перевіряють двоє: поліцейський при свідках або лікар із правом на огляд."],
"o47-1":["Щоб машина завжди була під контролем, тримай безпечну дистанцію й відстань збоку, пристебнися і не вези непристебнутих пасажирів, а також обирай безпечну швидкість. Потрібно все разом.","Дистанція, ремінь, швидкість — три опори безпечного керування."],
"o47-2":["Якщо хтось «висить» у тебе на хвості, збільш відстань до машини попереду, трохи відпустивши газ. Тоді гальмувати доведеться плавно, і той, хто позаду, встигне зреагувати.","Тиснуть ззаду — дай більше місця спереду."],
"o47-3":["Якщо з-під капота дим, перш ніж його відкрити, заглуши двигун (і вимкни «масу», якщо вона є), приготуй вогнегасник і захисти руки рукавичками чи ганчіркою. Потрібно все разом.","Дим з-під капота: заглуши, вогнегасник у руку, руки в рукавички."],
"o47-4":["Найбезпечніше їхати з тією самою швидкістю, що й потік: тоді тобі не треба нікого обганяти і тебе не обганяють, тож менше маневрів і ризику.","У потоці пливи разом з усіма — не швидше й не повільніше."],
"o47-5":["Миготливий зелений попереджає, що скоро ввімкнеться заборонний сигнал. Тож завчасно скинь швидкість, щоб за потреби спокійно зупинитися перед стоп-лінією без різкого гальмування.","Зелений замиготів — нога з газу, а не в підлогу."],
"o47-6":["Швидкість реакції залежить від віку, часу доби, утоми від довгої їзди і навіть температури в салоні. А от освіта на неї не впливає: диплом не робить реакцію швидшою.","Диплом гальмувати не допоможе: освіта на реакцію не впливає."],
"o47-7":["Дитяче автокрісло найбезпечніше ставити на заднє сидіння: там дитина далі від місця найчастіших ударів — спереду.","Дитина — позаду: найцінніше подалі від удару."]
};
